static int m11_is_dm1_source_kind(M11_GameSourceKind kind)
{
    return kind == M11_GAME_SOURCE_BUILTIN_CATALOG ||
           kind == M11_GAME_SOURCE_CUSTOM_DUNGEON ||
           kind == M11_GAME_SOURCE_DIRECT_DUNGEON;
}

static int m11_is_stock_dm1_hall_map0(const M11_GameViewState* state)
{
    return state &&
           state->sourceId[0] != '\0' &&
           strcmp(state->sourceId, "dm1") == 0 &&
           state->world.party.mapIndex == 0;
}

static int m11_apply_dm1_startup_launch_path_receipt(
    M11_GameViewState* state,
    DM1_V1_StartupLaunchPath_PC34 launch_path) {
    DM1_V1_StartupLaunchPathFacts_PC34 facts;
    DM1_V1_StartupLaunchPathReceipt_PC34 receipt;

    if (!state) {
        return 0;
    }
    memset(&facts, 0, sizeof(facts));
    memset(&receipt, 0, sizeof(receipt));
    facts.source_id = state->sourceId;
    facts.launch_path = launch_path;
    if (!dm1_v1_startup_launch_path_receipt_pc34(&facts, &receipt)) {
        return 0;
    }
    if (receipt.handled) {
        state->dm1StartupIntroBypassed = receipt.intro_bypassed;
        state->startedFromLauncher = receipt.started_from_launcher;
    }
    return 1;
}

static int m11_apply_dm1_startup_runtime_start_receipt(
    M11_GameViewState* state,
    const DM1_V1_StartupRuntimeStartReceipt_PC34* receipt) {
    if (!state || !receipt || !receipt->handled) {
        return 0;
    }
    state->active = receipt->active;
    state->startedFromLauncher = receipt->started_from_launcher;
    state->sourceKind = (M11_GameSourceKind)receipt->source_kind;
    snprintf(state->bootAssetMd5,
             sizeof(state->bootAssetMd5),
             "%s",
             receipt->boot_asset_md5);
    state->presentationMode = receipt->presentation_mode;
    state->presentationWidth = receipt->presentation_width;
    state->presentationHeight = receipt->presentation_height;
    state->fontScale = receipt->font_scale;
    snprintf(state->title, sizeof(state->title), "%s", receipt->title);
    snprintf(state->sourceId,
             sizeof(state->sourceId),
             "%s",
             receipt->source_id);
    if (receipt->launch_path_receipt.handled) {
        state->dm1StartupIntroBypassed =
            receipt->launch_path_receipt.intro_bypassed;
    }
    snprintf(state->dungeonPath,
             sizeof(state->dungeonPath),
             "%s",
             receipt->dungeon_path);
    m11_set_status(state, receipt->status_title, receipt->status_detail);
    m11_set_inspect_readout(state,
                            receipt->inspect_title,
                            receipt->inspect_detail);
    return 1;
}

static int m11_dm1_load_object_names_m564(M11_GameViewState* state);

static int m11_dm1_companion_song_path(const char *graphics_path,
                                       char *song_path,
                                       size_t song_path_size)
{
    static const char graphics_name[] = "GRAPHICS.DAT";
    static const char song_name[] = "SONG.DAT";
    size_t graphics_path_length;
    size_t graphics_name_length = sizeof(graphics_name) - 1U;
    size_t prefix_length;

    if (!graphics_path || !song_path || song_path_size == 0U) return 0;
    graphics_path_length = strlen(graphics_path);
    if (graphics_path_length <= graphics_name_length ||
        strcmp(graphics_path + graphics_path_length - graphics_name_length,
               graphics_name) != 0) return 0;
    prefix_length = graphics_path_length - graphics_name_length;
    if (prefix_length + sizeof(song_name) > song_path_size) return 0;
    memcpy(song_path, graphics_path, prefix_length);
    memcpy(song_path + prefix_length, song_name, sizeof(song_name));
    return 1;
}

static void m11_dm1_rebind_source_song(M11_GameViewState *state,
                                       const char *graphics_path)
{
    char song_path[M11_GAME_VIEW_PATH_CAPACITY];

    if (!state) return;
    state->dm1MusicSourceBound = 0;
    memset(&state->dm1MusicSource, 0, sizeof(state->dm1MusicSource));
    if (!m11_dm1_companion_song_path(graphics_path, song_path,
                                     sizeof(song_path)) ||
        !M11_Audio_BindOriginalSongPath(&state->audioState, song_path) ||
        !state->audioState.originalSongAvailable) return;
    state->dm1MusicSourceBound = dm1_v1_f0740_f0743_bind_song_dat_pc34(
        state->audioState.originalSongDatPath, &state->dm1MusicSource);
}

static int m11_dm1_bind_original_font(M11_GameViewState *state) {
    unsigned char raw[M11_FONT_BITMAP_BYTES];
    size_t length = 0;
    M11_Font_Init(&state->originalFont);
    state->originalFontAvailable = 0;
    /* TEXT.C:2013-2022 loads M653 with NOT_EXPANDED. The legacy and
     * Atari asset owners retain original bytes without a PC34 fileState. */
    if (state->assetLoader.atariStDm1) {
        DM1_V1_AtariStGraphicsDat dat;
        int count;
        if (!dm1_v1_atari_st_graphics_open(state->assetLoader.atariStData,
                (size_t)state->assetLoader.atariStDataSize, &dat)) return 0;
        count = dm1_v1_atari_st_graphics_read(&dat, 557, raw, sizeof(raw));
        if (count != M11_FONT_BITMAP_BYTES) return 0;
        length = (size_t)count;
    } else if (state->assetLoader.legacyDm1) {
        if (!dm1_v1_legacy_graphics_read_raw(state->assetLoader.legacyData,
                (size_t)state->assetLoader.legacyDataSize,
                state->assetLoader.legacyBigEndian, 557, raw, sizeof(raw), &length))
            return 0;
    } else {
        state->originalFontAvailable = M11_Font_LoadFromGraphicsDat(
            &state->originalFont, state->assetLoader.fileState,
            state->assetLoader.runtimeState);
        return state->originalFontAvailable;
    }
    state->originalFontAvailable = M11_Font_LoadFromRawBitmap(
        &state->originalFont, M11_FONT_GRAPHIC_INDEX_LEGACY, raw, length);
    return state->originalFontAvailable;
}

static int m11_apply_dm1_startup_graphics_bind_receipt(
    M11_GameViewState* state,
    const DM1_V1_StartupGraphicsBindReceipt_PC34* receipt) {
    if (!state || !receipt || !receipt->handled) {
        return 0;
    }
    if (!receipt->bind_graphics_dat) {
        return 1;
    }
    /* The virtual path has already bound its authenticated member in RAM.
     * Do not reopen it, but still bind every source-owned post-load surface
     * from the retained virtual identity. */
    if (strstr(receipt->graphics_dat_path, "::") != NULL &&
        state->assetLoader.initialized) {
        state->assetsAvailable = 1;
        (void)M11_Audio_BindOriginalSnd3Path(
            &state->audioState,
            state->assetLoader.atariStDm1 || state->assetLoader.legacyDm1
                ? NULL : state->assetLoader.graphicsDatPath);
        m11_dm1_rebind_source_song(state, state->assetLoader.graphicsDatPath);
        (void)m11_dm1_load_object_names_m564(state);
        (void)m11_dm1_bind_original_font(state);
        return 1;
    }
    /* FM Towns and Amiga DM1 keep the original legacy IMAGE2 container;
     * recognise that source format before trying the PC34 IMG3 loader.
     * Otherwise a permissive PC34 header match can hide the legacy binding
     * and prevent the native title/menu owner from starting. */
    {
        int legacyLoaded =
            M11_AssetLoader_InitDm1LegacyFromFile(
                &state->assetLoader, receipt->graphics_dat_path, 0) ||
            M11_AssetLoader_InitDm1LegacyFromFile(
                &state->assetLoader, receipt->graphics_dat_path, 1) ||
            M11_AssetLoader_InitDm1AtariStFromFile(
                &state->assetLoader, receipt->graphics_dat_path);
        /* A packed FM Towns source has no filesystem pathname that the
         * legacy loader can open.  Prefer the authenticated legacy parser
         * over the generic IMG3 probe: both formats may accept a loose
         * prefix, but only the legacy binding supplies the FM Towns title
         * and menu graphics contract. */
        if (!legacyLoaded && state->fmtownsGraphicsDat &&
            state->fmtownsGraphicsDatSize > 0) {
            legacyLoaded =
                M11_AssetLoader_InitDm1LegacyFromBuffer(
                    &state->assetLoader,
                    state->fmtownsGraphicsDat,
                    (long)state->fmtownsGraphicsDatSize,
                    0);
        }
        if (!legacyLoaded &&
            !M11_AssetLoader_Init(&state->assetLoader,
                                   receipt->graphics_dat_path)) {
            if (state->fmtownsGraphicsDat && state->fmtownsGraphicsDatSize > 0) {
                if (!M11_AssetLoader_InitFromBuffer(&state->assetLoader,
                        state->fmtownsGraphicsDat,
                        (long)state->fmtownsGraphicsDatSize) &&
                    !M11_AssetLoader_InitDm1LegacyFromBuffer(
                        &state->assetLoader, state->fmtownsGraphicsDat,
                        (long)state->fmtownsGraphicsDatSize, 0)) {
                    return 0;
                }
            } else {
                return 0;
            }
        }
    }
    state->assetsAvailable = 1;
    /* ReDMCSB F0060 reads the SND3 bank from the same verified PC34
     * GRAPHICS.DAT installation as the visual assets. M11_Audio_Init runs
     * before this startup receipt is applied, so explicitly bind the audio
     * bank here instead of allowing a different default search root to win. */
    (void)M11_Audio_BindOriginalSnd3Path(
        &state->audioState,
        state->assetLoader.atariStDm1 || state->assetLoader.legacyDm1
            ? NULL : state->assetLoader.graphicsDatPath);
    m11_dm1_rebind_source_song(state, state->assetLoader.graphicsDatPath);
    (void)m11_dm1_load_object_names_m564(state);
    (void)m11_dm1_bind_original_font(state);
    return 1;
}

static int m11_apply_dm1_save_resume_receipt(
    M11_GameViewState* state,
    const struct DM1SaveResumeReceipt* receipt) {
    if (!state || !receipt || !receipt->allowed || !receipt->loadSucceeded) {
        return 0;
    }
    state->loadGameTick = receipt->loadGameTick;
    state->lastSaveTick = receipt->lastSaveTick;
    (void)M11_GameView_SetMusicEnabled(state, receipt->musicOn);
    m11_set_status(state, receipt->statusTitle, receipt->statusDetail);
    snprintf(state->inspectTitle,
             sizeof(state->inspectTitle),
             "%s",
             receipt->inspectTitle);
    snprintf(state->inspectDetail,
             sizeof(state->inspectDetail),
             "%s",
             receipt->inspectDetail);
    return 1;
}

enum {
    M11_QUICKSAVE_EXPLORED_BITS_COUNT = 32,
};

