    s_m11_dm1_f0115_c2900_capture_request;
static M11_Dm1F0115FloorItemRuntimeCaptureReceipt
    s_m11_dm1_f0115_floor_item_runtime_capture_receipt;
static M11_Dm1F0115C15RuntimeCaptureReceipt
    s_m11_dm1_f0115_c15_runtime_capture_receipt;
static M11_Dm1F0115C2900RuntimeCaptureReceipt
    s_m11_dm1_f0115_c2900_runtime_capture_receipt;

static void m11_dm1_runtime_capture_frame_begin(const M11_GameViewState* state)
{
    memset(&s_m11_dm1_runtime_capture_routes, 0,
           sizeof(s_m11_dm1_runtime_capture_routes));
    memset(&s_m11_dm1_runtime_capture_receipt, 0,
           sizeof(s_m11_dm1_runtime_capture_receipt));
    memset(&s_m11_dm1_f0115_floor_item_capture_request, 0,
           sizeof(s_m11_dm1_f0115_floor_item_capture_request));
    memset(&s_m11_dm1_f0115_c15_capture_request, 0,
           sizeof(s_m11_dm1_f0115_c15_capture_request));
    memset(&s_m11_dm1_f0115_c2900_capture_request, 0,
           sizeof(s_m11_dm1_f0115_c2900_capture_request));
    memset(&s_m11_dm1_f0115_floor_item_runtime_capture_receipt, 0,
           sizeof(s_m11_dm1_f0115_floor_item_runtime_capture_receipt));
    memset(&s_m11_dm1_f0115_c15_runtime_capture_receipt, 0,
           sizeof(s_m11_dm1_f0115_c15_runtime_capture_receipt));
    memset(&s_m11_dm1_f0115_c2900_runtime_capture_receipt, 0,
           sizeof(s_m11_dm1_f0115_c2900_runtime_capture_receipt));
    if (!state || !m11_is_dm1_source_kind(state->sourceKind) ||
        state->showDebugHUD) {
        return;
    }
    if (s_m11_dm1_runtime_capture_evidence_bridge.owner != state) {
        memset(&s_m11_dm1_runtime_capture_evidence_bridge, 0,
               sizeof(s_m11_dm1_runtime_capture_evidence_bridge));
        s_m11_dm1_runtime_capture_evidence_bridge.owner = state;
    }
    s_m11_dm1_runtime_capture_routes.owner = state;
    s_m11_dm1_runtime_capture_routes.gameTick = state->world.gameTick;
    s_m11_dm1_f0115_floor_item_capture_request.owner = state;
    s_m11_dm1_f0115_floor_item_capture_request.runtimeTick =
        state->world.gameTick;
    s_m11_dm1_f0115_c15_capture_request.owner = state;
    s_m11_dm1_f0115_c15_capture_request.runtimeTick = state->world.gameTick;
    s_m11_dm1_f0115_c2900_capture_request.owner = state;
    s_m11_dm1_f0115_c2900_capture_request.runtimeTick = state->world.gameTick;
}

static int m11_dm1_runtime_capture_route_index(unsigned int route)
{
    switch (route) {
        case M11_DM1_RUNTIME_CAPTURE_C13: return 0;
        case M11_DM1_RUNTIME_CAPTURE_HOC: return 1;
        case M11_DM1_RUNTIME_CAPTURE_TOP_ROW: return 2;
        case M11_DM1_RUNTIME_CAPTURE_ACTION_SPELL: return 3;
        case M11_DM1_RUNTIME_CAPTURE_F0115_FLOOR_ITEM: return 4;
        case M11_DM1_RUNTIME_CAPTURE_F0115_C15: return 5;
        case M11_DM1_RUNTIME_CAPTURE_F0115_C2900: return 6;
        default: return -1;
    }
}

static void m11_dm1_runtime_capture_route_evidence(
    const M11_GameViewState* state,
    unsigned int route,
    int accepted,
    int sourceOwned,
    int suppressSyntheticFallback,
    unsigned int sourceTick,
    unsigned int serial,
    unsigned int materialFNV1a)
{
    M11_Dm1RuntimeCaptureFrameRoutes* routes =
        &s_m11_dm1_runtime_capture_routes;
    int index;

    if (!state || routes->owner != state ||
        routes->gameTick != state->world.gameTick || route == 0u) {
        return;
    }
    index = m11_dm1_runtime_capture_route_index(route);
    if (index < 0) {
        return;
    }
    routes->requiredRoutes |= route;
    if (accepted && sourceOwned && suppressSyntheticFallback &&
        sourceTick != 0u && materialFNV1a != 0u) {
        const M11_Dm1RuntimeCaptureEvidenceBridge* bridge =
            &s_m11_dm1_runtime_capture_evidence_bridge;
        if (bridge->owner != state ||
            (bridge->lastRuntimeTick[index] != 0u &&
             state->world.gameTick <= bridge->lastRuntimeTick[index]) ||
            (bridge->lastSourceTick[index] != 0u &&
             sourceTick < bridge->lastSourceTick[index])) {
            return;
        }
        routes->acceptedRoutes |= route;
        routes->evidence[index].runtimeTick = state->world.gameTick;
        routes->evidence[index].sourceOwned = 1;
        routes->evidence[index].suppressSyntheticFallback = 1;
        routes->evidence[index].sourceTick = sourceTick;
        routes->evidence[index].serial = serial;
        routes->evidence[index].materialFNV1a = materialFNV1a;
    }
}

static unsigned int m11_dm1_runtime_capture_fnv1a(
    const unsigned char* bytes,
    size_t count)
{
    unsigned int hash = 2166136261u;
    size_t index;

    if (!bytes || count == 0u) {
        return 0u;
    }
    for (index = 0u; index < count; ++index) {
        hash ^= (unsigned int)bytes[index];
        hash *= 16777619u;
    }
    return hash;
}

static unsigned int m11_framebuffer_rect_fnv1a(const unsigned char* framebuffer,
                                                int framebufferWidth,
                                                int framebufferHeight,
                                                int x,
                                                int y,
                                                int width,
                                                int height)
{
    unsigned int hash = 2166136261u;
    int row;

    if (!framebuffer || framebufferWidth <= 0 || framebufferHeight <= 0 ||
        width <= 0 || height <= 0) {
        return 0u;
    }
    if (x < 0) {
        width += x;
        x = 0;
    }
    if (y < 0) {
        height += y;
        y = 0;
    }
    if (x >= framebufferWidth || y >= framebufferHeight) {
        return 0u;
    }
    if (x + width > framebufferWidth) width = framebufferWidth - x;
    if (y + height > framebufferHeight) height = framebufferHeight - y;
    if (width <= 0 || height <= 0) return 0u;

    for (row = 0; row < height; ++row) {
        const unsigned char* pixels = framebuffer + (y + row) * framebufferWidth + x;
        int column;
        for (column = 0; column < width; ++column) {
            hash ^= (unsigned int)pixels[column];
            hash *= 16777619u;
        }
    }
    return hash;
}

static int m11_dm1_f0444_endgame_graphic_pc34(
    const M11_AssetSlot* slot,
    int graphic_index,
    DM1_V1_F0444EndgameGraphicPc34* out_graphic)
{
    if (!slot || !out_graphic || !slot->loaded ||
        slot->graphicIndex != (unsigned int)graphic_index || !slot->pixels ||
        slot->width == 0u || slot->height == 0u) {
        return 0;
    }
    memset(out_graphic, 0, sizeof(*out_graphic));
    out_graphic->graphic_index = graphic_index;
    out_graphic->indexed_pixels = slot->pixels;
    out_graphic->indexed_pixel_byte_count =
        (size_t)slot->width * (size_t)slot->height;
    out_graphic->graphics_dat_record_fingerprint =
        m11_dm1_runtime_capture_fnv1a(slot->pixels,
                                      out_graphic->indexed_pixel_byte_count);
    out_graphic->decoded_from_original_graphics_dat = 1;
    out_graphic->raw_record_verified = 1;
    out_graphic->no_synthetic_surface = 1;
    return out_graphic->graphics_dat_record_fingerprint != 0u;
}

/* ENDGAME.C F0444 may only paint decoded PC34 endgame records.  The
 * admission receipt is shared by draw and final-state reporting so an
 * asset-ready boolean alone can never authorize a host-built ending. */
static int m11_dm1_f0444_endgame_material_bound(
    const M11_GameViewState* state,
    const M11_AssetSlot** out_the_end,
    const M11_AssetSlot** out_mirror,
    const M11_AssetSlot** out_portraits,
    const M11_AssetSlot** out_credits)
{
    const M11_AssetSlot* the_end;
    const M11_AssetSlot* mirror;
    const M11_AssetSlot* portraits;
    const M11_AssetSlot* credits;
    DM1_V1_F0444EndgameGraphicPc34 the_end_graphic;
    DM1_V1_F0444EndgameGraphicPc34 mirror_graphic;
    DM1_V1_F0444EndgameGraphicPc34 portraits_graphic;
    DM1_V1_F0444EndgameGraphicPc34 credits_graphic;
    DM1_V1_F0444EndgameMaterialRequestPc34 request;
    uint8_t palette_rgb6[DM1_V1_F0444_CREDITS_PALETTE_BYTE_COUNT_PC34];
    int index;

    if (out_the_end) *out_the_end = NULL;
    if (out_mirror) *out_mirror = NULL;
    if (out_portraits) *out_portraits = NULL;
    if (out_credits) *out_credits = NULL;
    if (!state || !state->assetsAvailable || !state->assetLoader.initialized ||
        !state->assetLoader.fileState || !state->assetLoader.runtimeState) {
        return 0;
    }
    the_end = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                   (unsigned int)dm1_v1_graphic_the_end_pc34());
    mirror = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                  (unsigned int)dm1_v1_graphic_endgame_champion_mirror_pc34());
    portraits = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                     (unsigned int)dm1_v1_graphic_champion_portraits_pc34());
    credits = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 5u);
    if (!m11_dm1_f0444_endgame_graphic_pc34(the_end,
                                             dm1_v1_graphic_the_end_pc34(),
                                             &the_end_graphic) ||
        !m11_dm1_f0444_endgame_graphic_pc34(mirror,
                                             dm1_v1_graphic_endgame_champion_mirror_pc34(),
                                             &mirror_graphic) ||
        !m11_dm1_f0444_endgame_graphic_pc34(portraits,
                                             dm1_v1_graphic_champion_portraits_pc34(),
                                             &portraits_graphic) ||
        !m11_dm1_f0444_endgame_graphic_pc34(credits, 5, &credits_graphic)) {
        return 0;
    }
    for (index = 0; index < 16; ++index) {
        const unsigned int rgb12 = (unsigned int)dm1_v1_palette_credits_pc34(index);
        palette_rgb6[index * 3] = (uint8_t)(((rgb12 >> 8) & 0x0fu) << 2);
        palette_rgb6[index * 3 + 1] = (uint8_t)(((rgb12 >> 4) & 0x0fu) << 2);
        palette_rgb6[index * 3 + 2] = (uint8_t)((rgb12 & 0x0fu) << 2);
    }
    memset(&request, 0, sizeof(request));
    request.the_end = &the_end_graphic;
    request.champion_portraits = &portraits_graphic;
    request.champion_mirror = &mirror_graphic;
    request.credits = &credits_graphic;
    request.credits_palette_rgb6 = palette_rgb6;
    request.credits_palette_byte_count = sizeof(palette_rgb6);
    request.credits_palette_fingerprint =
        m11_dm1_runtime_capture_fnv1a(palette_rgb6, sizeof(palette_rgb6));
    request.original_credits_palette_verified = 1;
    request.no_host_font = 1;
    request.no_synthetic_credits = 1;
    if (!dm1_v1_f0444_endgame_material_admission_pc34(&request, NULL)) {
        return 0;
    }
    if (out_the_end) *out_the_end = the_end;
    if (out_mirror) *out_mirror = mirror;
    if (out_portraits) *out_portraits = portraits;
    if (out_credits) *out_credits = credits;
    return 1;
}

static void m11_dm1_runtime_capture_publish(
    const M11_GameViewState* state,
    const unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    const M11_Dm1RuntimeCaptureFrameRoutes* routes =
        &s_m11_dm1_runtime_capture_routes;
    M11_Dm1RuntimeCaptureReceipt* receipt =
        &s_m11_dm1_runtime_capture_receipt;
    size_t pixelCount;

    if (!state || !framebuffer || framebufferWidth <= 0 ||
        framebufferHeight <= 0 || state->showDebugHUD ||
        !m11_is_dm1_source_kind(state->sourceKind) ||
        routes->owner != state || routes->gameTick != state->world.gameTick ||
        routes->requiredRoutes != routes->acceptedRoutes) {
        return;
    }
    {
        int index;
        for (index = 0; index < M11_DM1_RUNTIME_CAPTURE_ROUTE_COUNT; ++index) {
            if ((routes->acceptedRoutes & (1u << index)) != 0u &&
                (routes->evidence[index].runtimeTick != state->world.gameTick ||
                 !routes->evidence[index].sourceOwned ||
                 !routes->evidence[index].suppressSyntheticFallback ||
                 routes->evidence[index].sourceTick == 0u ||
                 routes->evidence[index].materialFNV1a == 0u)) {
                return;
            }
        }
    }
    pixelCount = (size_t)framebufferWidth * (size_t)framebufferHeight;
    receipt->indexedFrameFNV1a = m11_dm1_runtime_capture_fnv1a(
        framebuffer, pixelCount);
    if (receipt->indexedFrameFNV1a == 0u) {
        return;
    }
    receipt->owner = state;
    receipt->valid = 1;
    receipt->gameTick = state->world.gameTick;
    receipt->routeMask = routes->acceptedRoutes;
    receipt->framebufferWidth = framebufferWidth;
    receipt->framebufferHeight = framebufferHeight;
    memcpy(receipt->evidence, routes->evidence, sizeof(receipt->evidence));
    {
        int index;
        for (index = 0; index < M11_DM1_RUNTIME_CAPTURE_ROUTE_COUNT; ++index) {
            if ((routes->acceptedRoutes & (1u << index)) != 0u) {
                s_m11_dm1_runtime_capture_evidence_bridge.lastRuntimeTick[index] =
                    routes->evidence[index].runtimeTick;
                s_m11_dm1_runtime_capture_evidence_bridge.lastSourceTick[index] =
                    routes->evidence[index].sourceTick;
                s_m11_dm1_runtime_capture_evidence_bridge.lastSerial[index] =
                    routes->evidence[index].serial;
                s_m11_dm1_runtime_capture_evidence_bridge.lastMaterialFNV1a[index] =
                    routes->evidence[index].materialFNV1a;
            }
        }
    }
}

static unsigned int m11_dm1_f0115_floor_item_material_fnv1a(
    const M11_GameViewState* state,
    const M11_Dm1FloorItemHostPresentationReceipt* presentation)
{
    const M11_AssetSlot* slot;
    unsigned int hash;

    if (!state || !presentation || !presentation->valid ||
        !presentation->floorItemLane || presentation->graphicsId <= 0 ||
        presentation->assetWidth <= 0 || presentation->assetHeight <= 0) {
        return 0u;
    }
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                (unsigned int)presentation->graphicsId);
    if (!slot || !slot->loaded || !slot->pixels ||
        (int)slot->width != presentation->assetWidth ||
        (int)slot->height != presentation->assetHeight) {
        return 0u;
    }
    hash = m11_dm1_runtime_capture_fnv1a(
        slot->pixels, (size_t)slot->width * (size_t)slot->height);
    if (hash == 0u) {
        return 0u;
    }
    hash ^= (unsigned int)presentation->graphicsId;
    hash *= 16777619u;
    hash ^= (unsigned int)presentation->sourceZoneRow;
    hash *= 16777619u;
    hash ^= (unsigned int)presentation->destinationX;
    hash *= 16777619u;
    hash ^= (unsigned int)presentation->destinationY;
    hash *= 16777619u;
    hash ^= (unsigned int)presentation->destinationW;
    hash *= 16777619u;
    hash ^= (unsigned int)presentation->destinationH;
    hash *= 16777619u;
    return hash;
}

static void m11_dm1_f0115_floor_item_runtime_capture_consume(
    const M11_GameViewState* state)
{
    const M11_Dm1F0115FloorItemCaptureRequest* request =
        &s_m11_dm1_f0115_floor_item_capture_request;
    const M11_Dm1FloorItemHostPresentationReceipt* presentation =
        &s_m11_dm1_floor_item_host_presentation_receipt;
    unsigned int materialFNV1a = 0u;
    int accepted = 0;

    if (!state || !m11_is_dm1_source_kind(state->sourceKind) ||
        request->owner != state ||
        request->runtimeTick != state->world.gameTick || !request->requested) {
        return;
    }
    materialFNV1a = m11_dm1_f0115_floor_item_material_fnv1a(
        state, presentation);
    accepted = presentation->valid && presentation->floorItemLane &&
        presentation->usesF0791Blit && materialFNV1a != 0u;
    m11_dm1_runtime_capture_route_evidence(
        state, M11_DM1_RUNTIME_CAPTURE_F0115_FLOOR_ITEM, accepted,
        accepted, accepted, state->world.gameTick,
        materialFNV1a, materialFNV1a);
    if (!accepted) {
        return;
    }
    s_m11_dm1_f0115_floor_item_runtime_capture_receipt.valid = 1;
    s_m11_dm1_f0115_floor_item_runtime_capture_receipt.runtimeTick =
        state->world.gameTick;
    s_m11_dm1_f0115_floor_item_runtime_capture_receipt.sourceTick =
        state->world.gameTick;
    s_m11_dm1_f0115_floor_item_runtime_capture_receipt.serial = materialFNV1a;
    s_m11_dm1_f0115_floor_item_runtime_capture_receipt.materialFNV1a =
        materialFNV1a;
    s_m11_dm1_f0115_floor_item_runtime_capture_receipt.presentation =
        *presentation;
}

