static int m11_csb_c001_palette_is_source_owned(
    const CSB_V1_BootStartupHostViewReceipt_PC34 *host_view)
{
    const CSB_V1_StartupRenderPlan_PC34 *plan;
    int expected_palette;

    if (!host_view || !host_view->render_draw_valid ||
        !host_view->render_draw.render_plan_valid) {
        return 0;
    }
    plan = &host_view->render_draw.render_plan;
    if (plan->surface != CSB_V1_STARTUP_RENDER_TITLE_PC34) {
        return 1;
    }

    /* ReDMCSB STARTND2.C F0437 and CSBWin _DisplayChaosStrikesBack own
     * three palette transactions. M11 may present their indexed C001 page
     * only when the receipt still names the phase's exact palette. */
    switch (plan->title_stage) {
    case CSB_V1_STARTUP_STAGE_TITLE_PRESENTS_PC34:
        expected_palette = VGA_PALETTE_PC34_SPECIAL_CSB_TITLE_PRESENTS;
        break;
    case CSB_V1_STARTUP_STAGE_TITLE_CHAOS_ZOOM_PC34:
        expected_palette = VGA_PALETTE_PC34_SPECIAL_CSB_TITLE_CHAOS;
        break;
    case CSB_V1_STARTUP_STAGE_TITLE_STRIKES_BACK_PC34:
        expected_palette = VGA_PALETTE_PC34_SPECIAL_CSB_TITLE_STRIKES;
        break;
    default:
        return 0;
    }
    return csb_v1_boot_startup_title_capture_plan_admit_pc34(
               plan, host_view->title_frame) &&
           host_view->special_palette == expected_palette &&
           plan->special_palette == expected_palette &&
           plan->title_special_palette == expected_palette;
}

static int m11_csb_opening_door_surface_is_source_owned(
    const CSB_V1_StartupRuntimeSurface_PC34 *surface,
    int source_asset_id,
    int width)
{
    const CSB_V1_StartupGraphicDecodeReceipt_PC34 *decode;

    if (!surface || !surface->valid || !surface->pixels ||
        surface->source_asset_id != source_asset_id ||
        surface->width != width || surface->height != 161 ||
        surface->transparent_color != -1) {
        return 0;
    }
    decode = &surface->decode_receipt;
    return decode->valid && decode->width == (uint16_t)width &&
        decode->height == 161u && decode->stream_byte_count >= 5u &&
        decode->stream_bytes_consumed >= 4u &&
        decode->stream_bytes_consumed <= decode->stream_byte_count &&
        decode->emitted_planar_pixels > 0u &&
        decode->physical_planar_pixels >= (size_t)width * 161u &&
        decode->stream_fnv1a != 0u && decode->indexed_pixel_fnv1a != 0u &&
        decode->ended_at_record_boundary && decode->indexed_colors_are_4bit;
}

/* ENTRANCE.C F0438 presents C004 plus the step-selected C002/C003 strips
 * under the temporary Entrance palette. The generic host receipt has a
 * complete indexed page, but M11 must still reject it if its source plan no
 * longer names the active real door records. */
static int m11_csb_opening_door_raster_is_source_owned(
    const M11_GameViewState *state,
    const CSB_V1_BootStartupHostViewReceipt_PC34 *host_view,
    const CSB_V1_StartupRuntimeHostSurfaceReceipt_PC34 *host_surface)
{
    const CSB_V1_StartupRenderPlan_PC34 *plan;
    int expected_surface_count;

    if (!state || !host_view || !host_surface ||
        !host_view->render_draw_valid ||
        !host_view->render_draw.render_plan_valid) {
        return 0;
    }
    plan = &host_view->render_draw.render_plan;
    if (!state->csbState.startup_entrance_active ||
        !state->csbState.startup_entrance_opening_active ||
        plan->surface != CSB_V1_STARTUP_RENDER_ENTRANCE_OPENING_FRAME_PC34 ||
        !plan->opening_composite_valid || plan->opening_door_step < 1 ||
        plan->opening_door_step != state->csbState.startup_entrance_opening_step ||
        host_surface->host_surface !=
            CSB_V1_STARTUP_RUNTIME_HOST_SURFACE_DOOR_OPENING_PC34 ||
        !host_surface->door_opening_decision ||
        host_surface->special_palette != VGA_PALETTE_PC34_SPECIAL_CSB_ENTRANCE ||
        host_surface->title_special_palette != -1 ||
        host_surface->frame.opening_step != plan->opening_door_step ||
        !host_surface->raster.entrance_composited ||
        !host_surface->raster.door_composited ||
        !m11_csb_opening_door_surface_is_source_owned(
            host_surface->frame.left_door_surface, 2, 105) ||
        !m11_csb_opening_door_surface_is_source_owned(
            host_surface->frame.right_door_surface, 3, 128)) {
        return 0;
    }
    /* C004 is always present. A bound F0128 viewport is the second source;
     * F0438 then adds each still-visible C002/C003 strip. */
    expected_surface_count = state->csbStartupF0128EntranceBound ? 2 : 1;
    if (plan->opening_left_w > 0) ++expected_surface_count;
    if (plan->opening_right_w > 0) ++expected_surface_count;
    return host_surface->raster.source_surface_count == expected_surface_count;
}

int M11_GameView_GetPresentationSpecialPalette(const M11_GameViewState* state)
{
    CSB_V1_BootStartupHostViewReceipt_PC34 host_view;

    if (!state || !state->active ||
        !m11_csb_startup_package_identity_current(state)) {
        return -1;
    }
    /* ReDMCSB ENTRANCE.C F0807 presents F31's verified C004 page after
     * CHTWE/CHTWJ, outside TITLE.C's PC host-view sequence.  Its F31 DAC
     * palette is installed by the draw path from SWITCHTW's source receipt;
     * do not present those pixels through a PC3.4 special VGA palette. */
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
        m11_csb_is_fmtowns_profile(
            (const CSB_V1_BootProfile *)state->csbBootProfile) &&
        state->csbFmtownsGameHandoffReceipt.valid &&
        state->csbState.startup_entrance_active &&
        !state->csbState.startup_title_active) {
        return -1;
    }
    if (!m11_csb_boot_runtime_startup_host_view_receipt(state,
                                                        &host_view) ||
        !host_view.valid) {
        return -1;
    }
    /* ReDMCSB TITLE.C F0437 owns three palette phases that must match the
     * exact C001 plan geometry.  ENTRANCE.C F0441/F0806 uses a single
     * palette for the entire entrance surface; render_draw_valid is not
     * required to identify it — the route receipt carries special_palette
     * independently of the real-asset render draw boundary. */
    if (host_view.render_draw_valid &&
        host_view.render_draw.render_plan_valid &&
        host_view.render_draw.render_plan.surface ==
            CSB_V1_STARTUP_RENDER_TITLE_PC34 &&
        !m11_csb_c001_palette_is_source_owned(&host_view)) {
        return -1;
    }
    if (host_view.special_palette >= 0 &&
        host_view.special_palette < VGA_PALETTE_PC34_SPECIAL_PALETTE_COUNT) {
        return host_view.special_palette;
    }
    /* The route receipt may fail coherence during transient door-opening
     * states, leaving special_palette at -1 even though the entrance
     * surface is clearly active.  Fall back to the entrance palette when
     * M11 state confirms entrance activity. */
    if (state->csbState.startup_entrance_active) {
        return VGA_PALETTE_PC34_SPECIAL_CSB_ENTRANCE;
    }
    return -1;
}

/* TITLE.C and ENTRANCE.C share one package session, but the entrance-local
 * frame counter deliberately resets when TITLE.C finishes.  It is therefore
 * not a safe receipt identity by itself: using it as the session tick lets a
 * later C004/C005 frame masquerade as an earlier C001 frame.  Keep the host
 * receipt timeline monotonic across the original C001 -> C005 transition.
 */
static uint32_t m11_csb_startup_source_tick(const M11_GameViewState *state)
{
    uint32_t frame;
    uint32_t title_ticks;

    if (!state) {
        return 0u;
    }
    title_ticks = (uint32_t)csb_v1_startup_title_total_ticks_pc34();
    if (state->csbState.startup_title_active) {
        frame = state->csbState.startup_title_frame < 0
            ? 0u : (uint32_t)state->csbState.startup_title_frame;
        return frame + 1u;
    }
    frame = state->csbState.startup_entrance_frame < 0
        ? 0u : (uint32_t)state->csbState.startup_entrance_frame;
    return title_ticks + frame + 1u;
}

/* TITLE.C and ENTRANCE.C own the indexed 320x200 page.  M11 owns only the
 * final presentation scale, so a maximized host surface cannot turn a valid
 * package raster into a black startup frame. */
static void m11_csb_present_startup_raster(const unsigned char *source,
                                           unsigned char *destination,
                                           int destination_width,
                                           int destination_height)
{
    int x;
    int y;

    if (!source || !destination || destination_width <= 0 ||
        destination_height <= 0) {
        return;
    }
    if (destination_width == CSB_V1_STARTUP_RUNTIME_RASTER_WIDTH_PC34 &&
        destination_height == CSB_V1_STARTUP_RUNTIME_RASTER_HEIGHT_PC34) {
        memcpy(destination, source,
               (size_t)CSB_V1_STARTUP_RUNTIME_RASTER_WIDTH_PC34 *
                   (size_t)CSB_V1_STARTUP_RUNTIME_RASTER_HEIGHT_PC34);
        return;
    }
    for (y = 0; y < destination_height; ++y) {
        const int source_y =
            (y * CSB_V1_STARTUP_RUNTIME_RASTER_HEIGHT_PC34) /
            destination_height;
        for (x = 0; x < destination_width; ++x) {
            const int source_x =
                (x * CSB_V1_STARTUP_RUNTIME_RASTER_WIDTH_PC34) /
                destination_width;
            destination[(size_t)y * (size_t)destination_width + (size_t)x] =
                source[(size_t)source_y *
                           CSB_V1_STARTUP_RUNTIME_RASTER_WIDTH_PC34 +
                       (size_t)source_x];
        }
    }
}

/* F31J C06 switches the original program to its 640x400 page.  M11's
 * presentation buffer can be 320x200 (or a host-scaled size), so retain
 * every source pixel through the same nearest-neighbour presentation rule
 * used for the native 320x200 startup pages.  The 640x400 source frame stays
 * separately available through M11_GameView_GetCsbFmtownsUtilityJapaneseFrame;
 * this helper only maps it to the active host surface. */
static void m11_csb_present_highres_raster(const unsigned char *source,
                                           int source_width,
                                           int source_height,
                                           unsigned char *destination,
                                           int destination_width,
                                           int destination_height)
{
    int x;
    int y;

    if (!source || !destination || source_width <= 0 || source_height <= 0 ||
        destination_width <= 0 || destination_height <= 0) {
        return;
    }
    if (destination_width == source_width && destination_height == source_height) {
        memcpy(destination, source, (size_t)source_width * (size_t)source_height);
        return;
    }
    for (y = 0; y < destination_height; ++y) {
        const int source_y = (y * source_height) / destination_height;
        for (x = 0; x < destination_width; ++x) {
            const int source_x = (x * source_width) / destination_width;
            destination[(size_t)y * (size_t)destination_width + (size_t)x] =
                source[(size_t)source_y * (size_t)source_width +
                       (size_t)source_x];
        }
    }
}

#define M11_CSB_FMTOWNS_TIMER_A_COUNT 100u
#define M11_CSB_FMTOWNS_TIMER_A_TICK_US \
    (18u * (1024u - M11_CSB_FMTOWNS_TIMER_A_COUNT))

static int m11_csb_is_fmtowns_profile(const CSB_V1_BootProfile *profile)
{
    return profile && (profile->variant_id == CSB_V1_VARIANT_FMTOWNS_EN ||
                       profile->variant_id == CSB_V1_VARIANT_FMTOWNS_JA);
}

/* Return one and only one CUE file from an original loose-media directory.
 * Ambiguity is deliberately a failure: archive order and guessed filenames
 * are not source-owned media selection. */
static int m11_find_single_cue_file(const char *directory,
                                    char *out_path, size_t out_path_size)
{
    int found = 0;
    if (!directory || !directory[0] || !out_path || out_path_size == 0U ||
        !FSP_DirExists(directory)) return 0;
    out_path[0] = '\0';
#if defined(_WIN32)
    {
        WIN32_FIND_DATAA entry;
        char pattern[M11_GAME_VIEW_PATH_CAPACITY];
        HANDLE handle;
        if (snprintf(pattern, sizeof(pattern), "%s\\*.cue", directory) < 0 ||
            strlen(pattern) >= sizeof(pattern)) return 0;
        handle = FindFirstFileA(pattern, &entry);
        if (handle == INVALID_HANDLE_VALUE) return 0;
        do {
            char candidate[M11_GAME_VIEW_PATH_CAPACITY];
            if ((entry.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0u ||
                !FSP_JoinPath(candidate, sizeof(candidate), directory,
                              entry.cFileName)) continue;
            if (found || snprintf(out_path, out_path_size, "%s", candidate) < 0 ||
                strlen(candidate) >= out_path_size) {
                FindClose(handle);
                out_path[0] = '\0';
                return 0;
            }
            found = 1;
        } while (FindNextFileA(handle, &entry) != 0);
        FindClose(handle);
    }
#else
    {
        DIR *dir = opendir(directory);
        struct dirent *entry;
        if (!dir) return 0;
        while ((entry = readdir(dir)) != NULL) {
            char candidate[M11_GAME_VIEW_PATH_CAPACITY];
            if (!m11_path_has_extension(entry->d_name, ".cue") ||
                !FSP_JoinPath(candidate, sizeof(candidate), directory,
                              entry->d_name) || !FSP_FileExists(candidate)) {
                continue;
            }
            if (found || snprintf(out_path, out_path_size, "%s", candidate) < 0 ||
                strlen(candidate) >= out_path_size) {
                closedir(dir);
                out_path[0] = '\0';
                return 0;
            }
            found = 1;
        }
        closedir(dir);
    }
#endif
    return found;
}

/* CUE is the source-owned image selector for loose FM Towns media as well
 * as ZIP media.  The optional parent probe covers DATA/DUNGEON.DAT while the
 * CUE and raw image remain at the authentic disc root. */
static int m11_read_loose_fmtowns_cue_media(const char *directory,
                                            int probe_parent,
                                            uint8_t **out_cue,
                                            size_t *out_cue_size,
                                            uint8_t **out_image,
                                            size_t *out_image_size)
{
    char cue_path[M11_GAME_VIEW_PATH_CAPACITY];
    char cue_directory[M11_GAME_VIEW_PATH_CAPACITY];
    char parent[M11_GAME_VIEW_PATH_CAPACITY];
    char image_member[M11_GAME_VIEW_PATH_CAPACITY];
    char image_path[M11_GAME_VIEW_PATH_CAPACITY];
    if (!directory || !out_cue || !out_cue_size || !out_image ||
        !out_image_size) return 0;
    *out_cue = NULL;
    *out_cue_size = 0U;
    *out_image = NULL;
    *out_image_size = 0U;
    if (!m11_find_single_cue_file(directory, cue_path, sizeof(cue_path))) {
        if (!probe_parent || !FSP_ParentDir(parent, sizeof(parent), directory) ||
            !m11_find_single_cue_file(parent, cue_path, sizeof(cue_path))) {
            return 0;
        }
    }
    if (!FSP_ParentDir(cue_directory, sizeof(cue_directory), cue_path) ||
        !asset_read_path_alloc(cue_path, out_cue, out_cue_size) ||
        !fmtowns_cue_parse_image_member((const char *)*out_cue,
                                        *out_cue_size, image_member,
                                        sizeof(image_member)) ||
        !FSP_JoinPath(image_path, sizeof(image_path), cue_directory,
                      image_member) ||
        !asset_read_path_alloc(image_path, out_image, out_image_size)) {
        free(*out_cue); free(*out_image);
        *out_cue = NULL; *out_image = NULL;
        *out_cue_size = 0U; *out_image_size = 0U;
        return 0;
    }
    return 1;
}

static int m11_csb_read_fmtowns_cdda_media(const CSB_V1_BootProfile *profile,
                                           uint8_t **out_cue,
                                           size_t *out_cue_size,
                                           uint8_t **out_image,
                                           size_t *out_image_size)
{
    char image_member[M11_GAME_VIEW_PATH_CAPACITY];

    if (!profile || !profile->asset_root[0] || !out_cue || !out_cue_size ||
        !out_image || !out_image_size) return 0;
    *out_cue = NULL;
    *out_cue_size = 0U;
    *out_image = NULL;
    *out_image_size = 0U;
    if (FSP_FileExists(profile->asset_root) &&
        !FSP_DirExists(profile->asset_root)) {
        if (firestaff_zip_extract_by_suffix(profile->asset_root, ".cue",
                                            out_cue, out_cue_size) != 0 ||
            !fmtowns_cue_parse_image_member((const char *)*out_cue,
                                            *out_cue_size, image_member,
                                            sizeof(image_member)) ||
            firestaff_zip_extract_by_name(profile->asset_root, image_member,
                                          out_image, out_image_size) != 0) {
            free(*out_cue);
            free(*out_image);
            *out_cue = NULL;
            *out_cue_size = 0U;
            *out_image = NULL;
            *out_image_size = 0U;
            return 0;
        }
        return 1;
    }
    return m11_read_loose_fmtowns_cue_media(profile->asset_root, 0,
                                             out_cue, out_cue_size,
                                             out_image, out_image_size);
}

static int m11_csb_load_fmtowns_m653_font_buffer(const uint8_t *graphics,
                                                 size_t graphics_size,
                                                 M11_FontState *font)
{
    uint8_t raw_font[M11_FONT_BITMAP_BYTES];
    CSB_V1_FmtownsItemDecodeReceipt raw_receipt;

    if (!graphics || graphics_size == 0u || !font ||
        graphics_size > CSB_FMTOWNS_GRAPHICS_MAX_SIZE ||
        !csb_v1_fmtowns_graphics_copy_raw_item(
            graphics, graphics_size, 695u, raw_font, sizeof(raw_font),
            &raw_receipt) || !raw_receipt.valid ||
        raw_receipt.stream_byte_count != M11_FONT_BITMAP_BYTES) return 0;
    return M11_Font_LoadFromRawBitmap(font, 695, raw_font, sizeof(raw_font));
}

static int m11_csb_load_fmtowns_m653_font(const char *graphics_path,
                                          M11_FontState *font)
{
    uint8_t *graphics = NULL;
    size_t graphics_size = 0u;
    int result = 0;

    if (!graphics_path || !graphics_path[0] || !font) return 0;
    if (asset_read_path_alloc(graphics_path, &graphics, &graphics_size))
        result = m11_csb_load_fmtowns_m653_font_buffer(
            graphics, graphics_size, font);
    free(graphics);
    return result;
}

/* CSBWin CSBCode.cpp::TAG001c6e expands the original Atari ST M653 payload
 * from GRAPHICS.DAT item 0x822d (the NOT_EXPANDED bit plus item 0x22d).  It
 * is a raw 1024x6 1bpp font, not an IMG1/IMG2 drawable record. */
static int m11_csb_load_atari_st_m653_font(const char *graphics_path,
                                           M11_FontState *font)
{
    enum { CSBWIN_M653_GRAPHIC = 0x22d, CSBWIN_GRAPHICS_ITEM_COUNT = 563 };
    CSB_AtariStLoader loader;
    uint8_t raw_font[M11_FONT_BITMAP_BYTES];
    int result = 0;

    if (!graphics_path || !graphics_path[0] || !font) return 0;
    csb_atari_st_graphics_loader_init(&loader);
    if (!csb_atari_st_graphics_loader_open(&loader, graphics_path) ||
        loader.item_count != CSBWIN_GRAPHICS_ITEM_COUNT ||
        loader.items[CSBWIN_M653_GRAPHIC].decompressed_size !=
            M11_FONT_BITMAP_BYTES ||
        csb_atari_st_graphics_loader_read_item(
            &loader, CSBWIN_M653_GRAPHIC, raw_font, sizeof(raw_font)) !=
            M11_FONT_BITMAP_BYTES) {
        goto done;
    }
    result = M11_Font_LoadFromRawBitmap(font, M11_FONT_GRAPHIC_INDEX_LEGACY,
                                        raw_font, sizeof(raw_font));
done:
    csb_atari_st_graphics_loader_close(&loader);
    return result;
}

static void m11_csb_dispatch_fmtowns_cdda_track(M11_GameViewState *state,
                                                uint16_t source_track)
{
    const CSB_V1_BootProfile *profile;
    uint8_t *cue_bytes = NULL;
    size_t cue_size = 0U;
    uint8_t *image_bytes = NULL;
    size_t image_size = 0U;
    uint8_t *pcm = NULL;
    size_t pcm_size = 0u;
    CSB_V1_FmtownsCddaLayout layout;
    const CSB_V1_FmtownsCddaTrack *track = NULL;
    int i;

    if (!state || source_track < CSB_FMTOWNS_CD_CDDA_FIRST_TRACK ||
        source_track > CSB_FMTOWNS_CD_CDDA_LAST_TRACK ||
        !state->csbBootProfile) return;
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (!m11_csb_is_fmtowns_profile(profile)) return;

    /* ReDMCSB ANIM.C F2275 lines 2243-2248 turns TD/TR into
     * F0719_PlayMusicTrack. F0719 first pauses the old physical track, so a
     * rejected cache receipt must be silent rather than leaving stale audio. */
    if (state->csbFmtownsCddaPlaying) {
        (void)M11_Audio_StopCdda(&state->audioState);
        state->csbFmtownsCddaPlaying = 0;
        state->csbFmtownsCddaPaused = 0;
    }
    if (!m11_csb_read_fmtowns_cdda_media(profile, &cue_bytes, &cue_size,
                                         &image_bytes, &image_size) ||
        cue_size == 0U || cue_size > 64U * 1024U || image_size == 0U) {
        free(cue_bytes);
        free(image_bytes);
        return;
    }
    if (csb_v1_fmtowns_cdda_parse_cue((const char *)cue_bytes, cue_size, &layout) != 0 ||
        !layout.valid ||
        layout.track_count != (int)CSB_FMTOWNS_CD_CDDA_TRACK_COUNT) {
        free(cue_bytes);
        free(image_bytes);
        return;
    }
    free(cue_bytes);
    for (i = 0; i < layout.track_count; ++i) {
        if (layout.tracks[i].track_number == source_track) {
            track = &layout.tracks[i];
            break;
        }
    }
    if (!track || csb_v1_fmtowns_cdda_read_alloc(image_bytes, image_size,
                                                  track, &pcm, &pcm_size) != 0) {
        free(image_bytes);
        free(pcm);
        return;
    }
    free(image_bytes);
    /* F0719's CD mtplay uses the next CUE track as the end boundary. It is
     * not a host loop; replay occurs only if a later source TR asks for it. */
    if (M11_Audio_PlayCdda(&state->audioState, pcm, pcm_size, 0)) {
        state->csbFmtownsCddaPlaying = 1;
        state->csbFmtownsCddaPaused = 0;
        /* F2257 polls the physical device. M11 retains a source-tick
         * duration from the original 44.1 kHz stereo CD-DA span so a later
         * F0743 update can observe completion instead of latching one host
         * stream forever. CSB_V1_TICK_MS_NOMINAL is the F31 game tick. */
        state->csbFmtownsCddaSourceTicksRemaining = (uint32_t)
            ((pcm_size + (176400u * CSB_V1_TICK_MS_NOMINAL / 1000u) - 1u) /
             (176400u * CSB_V1_TICK_MS_NOMINAL / 1000u));
        if (state->csbFmtownsCddaSourceTicksRemaining == 0u)
            state->csbFmtownsCddaSourceTicksRemaining = 1u;
    }
    free(pcm);
}

static void m11_csb_dispatch_fmtowns_cdda(
    M11_GameViewState *state, const CSB_V1_FmtownsAnmFrameReceipt *frame)
{
    if (!state || !frame || !frame->cdda_track_requested) return;
    m11_csb_dispatch_fmtowns_cdda_track(state, frame->cdda_track);
}

static void m11_csb_dispatch_fmtowns_anm_pcm(
    M11_GameViewState *state, const CSB_V1_FmtownsAnmFrameReceipt *frame)
{
    const int8_t *source;
    if (!state || !frame || !frame->pcm_requested ||
        !state->csbFmtownsTitleBytes || frame->pcm_source_bytes == 0u ||
        frame->pcm_source_offset >= state->csbFmtownsTitleByteCount ||
        frame->pcm_source_bytes > state->csbFmtownsTitleByteCount -
                                      frame->pcm_source_offset) return;
    /* ANIM.C F2275 SD/SO owns this event. The ANM player exposes the
     * selected raw source span only after its BE16 length has been checked;
     * never substitute a host cue if transport rejects it. */
    source = (const int8_t *)(state->csbFmtownsTitleBytes +
                              frame->pcm_source_offset);
    (void)M11_Audio_PlayCsbFmtownsAnmPcm(
        &state->audioState, source, (int)frame->pcm_source_bytes,
        (int)frame->pcm_sample_rate_hz, (int)frame->pcm_source_volume,
        frame->pcm_source_fnv1a);
}

static void m11_csb_update_fmtowns_game_music(M11_GameViewState *state)
{
    uint8_t selected_track;

    if (!state || !state->csbFmtownsGameHandoffReceipt.valid ||
        !state->csbState.level_loaded || !state->dm1MusicOn) return;
    if (state->csbFmtownsCddaPlaying && !state->csbFmtownsCddaPaused &&
        state->csbFmtownsCddaSourceTicksRemaining > 0u) {
        --state->csbFmtownsCddaSourceTicksRemaining;
        if (state->csbFmtownsCddaSourceTicksRemaining == 0u)
            state->csbFmtownsCddaPlaying = 0;
    }
    if (state->world.party.mapIndex < 0 || state->world.party.mapX < 0 ||
        state->world.party.mapY < 0 ||
        !csb_v1_fmtowns_game_music_track_at(
            &state->csbFmtownsGameHandoffReceipt,
            (uint32_t)state->world.party.mapIndex,
            (uint32_t)state->world.party.mapX,
            (uint32_t)state->world.party.mapY, &selected_track)) return;

    /* ReDMCSB MUSIC.C F0743 lines 632-646: a nonzero table selector arms
     * exactly 100 source updates. F0719 subtracts two only to address the
     * compacted non-data track-time array; the physical CUE track remains
     * the selector itself (track 2 is array index zero). */
    if (selected_track != 0u &&
        selected_track != state->csbFmtownsGameMusicSelectedTrack) {
        state->csbFmtownsGameMusicSelectedTrack = selected_track;
        state->csbFmtownsGameMusicPending = 1;
        state->csbFmtownsGameMusicCountdown = 100;
    }
    if (state->csbFmtownsGameMusicPending &&
        selected_track != 0u &&
        selected_track != state->csbFmtownsGameMusicPlayingTrack &&
        state->csbFmtownsGameMusicCountdown-- <= 0) {
        state->csbFmtownsGameMusicPending = 0;
        state->csbFmtownsGameMusicPlayingTrack = selected_track;
        m11_csb_dispatch_fmtowns_cdda_track(state, selected_track);
    }
}

static void m11_csb_release_fmtowns_title(M11_GameViewState *state)
{
    if (!state) return;
    /* F2275 ends in F0740_MUSIC_Pause (ANIM.C line 2329). The title owner
     * then releases its stream at the SWITCHTW boundary, so this is a stop,
     * not the F0738 resume path used for a temporary music-off transition. */
    if (state->csbFmtownsCddaPlaying) {
        (void)M11_Audio_StopCdda(&state->audioState);
        state->csbFmtownsCddaPlaying = 0;
        state->csbFmtownsCddaPaused = 0;
    }
    state->csbFmtownsCddaSourceTicksRemaining = 0u;
    free(state->csbFmtownsTitleBytes);
    state->csbFmtownsTitleBytes = NULL;
    state->csbFmtownsTitleByteCount = 0u;
    memset(&state->csbFmtownsTitlePlayback, 0,
           sizeof(state->csbFmtownsTitlePlayback));
    memset(&state->csbFmtownsTitleFrameReceipt, 0,
           sizeof(state->csbFmtownsTitleFrameReceipt));
    state->csbFmtownsTimerAAccumulatorUs = 0u;
    state->csbFmtownsFrameTimerARemaining = 0u;
    state->csbFmtownsTitleBound = 0;
    state->csbFmtownsTitleFinished = 0;
    state->csbFmtownsEndingActive = 0;
    state->csbFmtownsEndingFinished = 0;
}

static void m11_csb_release_fmtowns_switch(M11_GameViewState *state)
{
    if (!state) return;
    free(state->csbFmtownsSwitchBytes);
    state->csbFmtownsSwitchBytes = NULL;
    state->csbFmtownsSwitchByteCount = 0u;
    memset(&state->csbFmtownsSwitchReceipt, 0,
           sizeof(state->csbFmtownsSwitchReceipt));
    memset(state->csbFmtownsSwitchPixels, 0,
           sizeof(state->csbFmtownsSwitchPixels));
    state->csbFmtownsSwitchLanguage = CSB_FMTOWNS_SWITCH_JAPANESE;
    state->csbFmtownsSwitchVblanksRemaining = 0u;
    state->csbFmtownsSwitchBound = 0;
}

static int m11_csb_bind_fmtowns_switch(
    M11_GameViewState *state, CSB_V1_FmtownsSwitchLanguage language);

static int m11_csb_enter_fmtowns_utility(
    M11_GameViewState *state, CSB_V1_FmtownsSwitchLanguage language)
{
    CSB_V1_FmtownsUtilityRenderReceipt rendered;
    const CSB_V1_BootProfile *profile;

    if (!state || !state->csbBootProfile) return 0;
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    memset(&state->csbFmtownsUtilityHandoffReceipt, 0,
           sizeof(state->csbFmtownsUtilityHandoffReceipt));
    memset(&state->csbFmtownsUtilitySaveMappingReceipt, 0,
           sizeof(state->csbFmtownsUtilitySaveMappingReceipt));
    memset(&state->csbFmtownsUtilityMenuReceipt, 0,
           sizeof(state->csbFmtownsUtilityMenuReceipt));
    memset(&state->csbFmtownsUtilityGameSourceReceipt, 0,
           sizeof(state->csbFmtownsUtilityGameSourceReceipt));
    memset(&state->csbFmtownsUtilityFontReceipt, 0,
           sizeof(state->csbFmtownsUtilityFontReceipt));
    memset(&state->csbFmtownsUtilityPortraitReceipt, 0,
           sizeof(state->csbFmtownsUtilityPortraitReceipt));
    memset(&state->csbFmtownsUtilityPortraitCatalog, 0,
           sizeof(state->csbFmtownsUtilityPortraitCatalog));
    memset(&state->csbFmtownsUtilityFilePicker, 0,
           sizeof(state->csbFmtownsUtilityFilePicker));
    memset(&state->csbFmtownsUtilityParty, 0,
           sizeof(state->csbFmtownsUtilityParty));
    memset(state->csbFmtownsUtilityOriginalPortraits, 0,
           sizeof(state->csbFmtownsUtilityOriginalPortraits));
    memset(state->csbFmtownsUtilityUndoPortrait, 0,
           sizeof(state->csbFmtownsUtilityUndoPortrait));
    memset(state->csbFmtownsUtilityPortraitModified, 0,
           sizeof(state->csbFmtownsUtilityPortraitModified));
    state->csbFmtownsUtilityUndoModified = 0;
    state->csbFmtownsUtilityUndoAvailable = 0;
    state->csbFmtownsUtilityFilePickerActive = 0;
    state->csbFmtownsUtilityGameSourceDialogActive = 1;
    state->csbFmtownsUtilityGameSaveMediumDialogActive = 0;
    state->csbFmtownsUtilitySaveDialogActive = 0;
    state->csbFmtownsUtilityLoadDialogActive = 0;
    state->csbFmtownsUtilityEditField = -1;
    state->csbFmtownsUtilityEditCharacterIndex = 0u;
    state->csbFmtownsUtilityTextCursorVisible = 0;
    state->csbFmtownsUtilityTextCursorVblanksRemaining = 0u;
    free(state->csbFmtownsUtilityJapanesePixels);
    state->csbFmtownsUtilityJapanesePixels = NULL;
    state->csbFmtownsUtilityJapaneseActive = 0;
    memset(&rendered, 0, sizeof(rendered));
    if (!csb_v1_fmtowns_utility_handoff_open(
            profile, language, &state->csbFmtownsUtilityHandoffReceipt) ||
        !csb_v1_fmtowns_utility_save_mapping_open(
            profile, language, &state->csbFmtownsUtilitySaveMappingReceipt) ||
        !csb_v1_fmtowns_utility_menu_open(
            profile, language, &state->csbFmtownsUtilityMenuReceipt) ||
        !csb_v1_fmtowns_utility_font_open(
            profile, language, &state->csbFmtownsUtilityFontReceipt) ||
        !csb_v1_fmtowns_utility_icon_palette_rgb6(
            &state->csbFmtownsUtilityMenuReceipt,
            state->csbFmtownsUtilityPaletteRgb6)) {
        memset(state->csbFmtownsUtilityPixels, 0,
               sizeof(state->csbFmtownsUtilityPixels));
        memset(state->csbFmtownsUtilityPaletteRgb6, 0,
               sizeof(state->csbFmtownsUtilityPaletteRgb6));
        return 0;
    }
    if (language == CSB_FMTOWNS_SWITCH_JAPANESE) {
        state->csbFmtownsUtilityJapanesePixels = (uint8_t *)malloc(
            CSB_V1_FMTOWNS_UTILITY_JAPANESE_SCREEN_PIXELS);
        if (!state->csbFmtownsUtilityJapanesePixels ||
            !m11_csb_bind_fmtowns_font_rom() ||
            !csb_v1_fmtowns_utility_render_japanese_game_source_dialog(
                &state->csbFmtownsUtilityHandoffReceipt,
                state->csbFmtownsUtilityJapanesePixels,
                CSB_V1_FMTOWNS_UTILITY_JAPANESE_SCREEN_PIXELS, &rendered)) {
            free(state->csbFmtownsUtilityJapanesePixels);
            state->csbFmtownsUtilityJapanesePixels = NULL;
            return 0;
        }
        state->csbFmtownsUtilityJapaneseActive = 1;
    } else if (language == CSB_FMTOWNS_SWITCH_ENGLISH &&
               csb_v1_fmtowns_utility_game_source_open(
                   profile, language, &state->csbFmtownsUtilityGameSourceReceipt) &&
               csb_v1_fmtowns_utility_render_game_source_dialog(
                   &state->csbFmtownsUtilityHandoffReceipt,
                   &state->csbFmtownsUtilityGameSourceReceipt,
                   &state->csbFmtownsUtilityFontReceipt,
                   state->csbFmtownsUtilityPixels,
                   sizeof(state->csbFmtownsUtilityPixels), &rendered)) {
        /* F31E source chooser is fully bound below. */
    } else {
        return 0;
    }
    state->csbFmtownsUtilityBound = 1;
    /* AUTOEXEC.BAT has transferred ownership from SWITCHTW to C06. */
    state->csbFmtownsSwitchBound = 0;
    return 1;
}

int M11_GameView_EnterCsbFmtownsUtility(M11_GameViewState *state)
{
    const CSB_V1_BootProfile *profile;
    CSB_V1_FmtownsSwitchLanguage language;

    if (!state || !state->active ||
        state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !(profile = (const CSB_V1_BootProfile *)state->csbBootProfile) ||
        !m11_csb_is_fmtowns_profile(profile)) {
        return 0;
    }
    language = profile->variant_id == CSB_V1_VARIANT_FMTOWNS_JA
        ? CSB_FMTOWNS_SWITCH_JAPANESE : CSB_FMTOWNS_SWITCH_ENGLISH;
    return m11_csb_bind_fmtowns_switch(state, language) &&
           m11_csb_enter_fmtowns_utility(state, language);
}

static int m11_csb_redraw_fmtowns_utility(M11_GameViewState *state)
{
    CSB_V1_FmtownsUtilityRenderReceipt rendered;
    if (!state || !state->csbFmtownsUtilityBound) return 0;
    if (state->csbFmtownsUtilityJapaneseActive) {
        return state->csbFmtownsUtilityGameSourceDialogActive &&
            state->csbFmtownsUtilityJapanesePixels &&
            csb_v1_fmtowns_utility_render_japanese_game_source_dialog(
                &state->csbFmtownsUtilityHandoffReceipt,
                state->csbFmtownsUtilityJapanesePixels,
                CSB_V1_FMTOWNS_UTILITY_JAPANESE_SCREEN_PIXELS, &rendered);
    }
    memset(&rendered, 0, sizeof(rendered));
    if (state->csbFmtownsUtilityGameSourceDialogActive) {
        return csb_v1_fmtowns_utility_render_game_source_dialog(
            &state->csbFmtownsUtilityHandoffReceipt,
            &state->csbFmtownsUtilityGameSourceReceipt,
            &state->csbFmtownsUtilityFontReceipt,
            state->csbFmtownsUtilityPixels,
            sizeof(state->csbFmtownsUtilityPixels), &rendered);
    }
    if (state->csbFmtownsUtilityGameSaveMediumDialogActive) {
        return csb_v1_fmtowns_utility_render_game_save_medium_dialog(
            &state->csbFmtownsUtilityHandoffReceipt,
            &state->csbFmtownsUtilityGameSourceReceipt,
            &state->csbFmtownsUtilityFontReceipt,
            state->csbFmtownsUtilityPixels,
            sizeof(state->csbFmtownsUtilityPixels), &rendered);
    }
    if (state->csbFmtownsUtilityFilePickerActive) {
        return csb_v1_fmtowns_utility_render_file_picker(
            &state->csbFmtownsUtilityHandoffReceipt,
            &state->csbFmtownsUtilityFontReceipt,
            &state->csbFmtownsUtilityFilePicker,
            state->csbFmtownsUtilityPixels,
            sizeof(state->csbFmtownsUtilityPixels), &rendered);
    }
    if (state->csbFmtownsUtilitySaveDialogActive) {
        return csb_v1_fmtowns_utility_render_save_dialog(
            &state->csbFmtownsUtilityHandoffReceipt,
            &state->csbFmtownsUtilityMenuReceipt,
            &state->csbFmtownsUtilityFontReceipt,
            &state->csbFmtownsUtilityParty,
            &state->csbFmtownsUtilityPortraitReceipt,
            state->csbFmtownsUtilitySelectedChampion,
            state->csbFmtownsUtilitySelectedColor,
            state->csbFmtownsUtilityPixels,
            sizeof(state->csbFmtownsUtilityPixels), &rendered);
    }
    if (state->csbFmtownsUtilityLoadDialogActive) {
        return csb_v1_fmtowns_utility_render_load_dialog(
            &state->csbFmtownsUtilityHandoffReceipt,
            &state->csbFmtownsUtilityMenuReceipt,
            &state->csbFmtownsUtilityFontReceipt,
            &state->csbFmtownsUtilityParty,
            &state->csbFmtownsUtilityPortraitReceipt,
            state->csbFmtownsUtilitySelectedChampion,
            state->csbFmtownsUtilitySelectedColor,
            state->csbFmtownsUtilityPixels,
            sizeof(state->csbFmtownsUtilityPixels), &rendered);
    }
    return csb_v1_fmtowns_utility_render_editor(
        &state->csbFmtownsUtilityHandoffReceipt,
        &state->csbFmtownsUtilityMenuReceipt,
        &state->csbFmtownsUtilityFontReceipt,
        &state->csbFmtownsUtilityParty,
        &state->csbFmtownsUtilityPortraitReceipt,
        state->csbFmtownsUtilitySelectedChampion,
        state->csbFmtownsUtilitySelectedColor,
        state->csbFmtownsUtilityEditField,
        state->csbFmtownsUtilityEditCharacterIndex,
        state->csbFmtownsUtilityTextCursorVisible,
        state->csbFmtownsUtilityPixels,
        sizeof(state->csbFmtownsUtilityPixels), &rendered);
}

static int m11_csb_fmtowns_utility_draw_portrait_pixel(
    M11_GameViewState *state, int source_x, int source_y)
{
    uint8_t chunky[CSB_FMTOWNS_PORTRAIT_PIXEL_COUNT];
    uint16_t champion;

    if (!state || source_x < 0 ||
        source_x >= (int)CSB_FMTOWNS_PORTRAIT_WIDTH || source_y < 0 ||
        source_y >= (int)CSB_FMTOWNS_PORTRAIT_HEIGHT) return 0;
    champion = state->csbFmtownsUtilitySelectedChampion;
    if (champion >= state->csbFmtownsUtilityParty.ChampionCount ||
        !csb_v1_fmtowns_portrait_decode_planar(
            state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
            CSB_V1_FMTOWNS_STARTUP_PORTRAIT_BYTES, chunky, sizeof(chunky))) {
        return 0;
    }
    /* ReDMCSB CEDT006.C F7037/F7044: retain one source-format undo copy,
     * change the selected indexed pixel, then return through F7252. */
    memcpy(state->csbFmtownsUtilityUndoPortrait,
           state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
           sizeof(state->csbFmtownsUtilityUndoPortrait));
    state->csbFmtownsUtilityUndoModified =
        state->csbFmtownsUtilityPortraitModified[champion];
    state->csbFmtownsUtilityUndoAvailable = 1;
    chunky[(size_t)source_y * CSB_FMTOWNS_PORTRAIT_WIDTH + source_x] =
        state->csbFmtownsUtilitySelectedColor;
    if (!csb_v1_fmtowns_portrait_encode_planar(
            chunky, sizeof(chunky),
            state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
            CSB_V1_FMTOWNS_STARTUP_PORTRAIT_BYTES)) return 0;
    state->csbFmtownsUtilityPortraitModified[champion] = 1u;
    return m11_csb_redraw_fmtowns_utility(state);
}

/* ReDMCSB CEDT006.C F7046 (F31 C06): right-click fills the connected
 * same-colour area in the selected 32x29 portrait.  Keep this wholly in the
 * source-format MINI.DAT portrait buffer: the editor does not manufacture a
 * host bitmap or commit a save-file write.  F7046 allocates an int16 point
 * stack and calls F7044 for each point; marking a point when it is queued is
 * the equivalent final raster operation while bounding the modern stack to
 * the exact native portrait area. */
static int m11_csb_fmtowns_utility_flood_fill_portrait(
    M11_GameViewState *state, int source_x, int source_y)
{
    enum { F31_PORTRAIT_PIXELS = 32 * 29 };
    uint8_t chunky[F31_PORTRAIT_PIXELS];
    int stack_x[F31_PORTRAIT_PIXELS];
    int stack_y[F31_PORTRAIT_PIXELS];
    uint16_t champion;
    uint8_t target;
    uint8_t replacement;
    int stack_count = 0;

    if (!state || source_x < 0 || source_x >= 32 ||
        source_y < 0 || source_y >= 29) return 0;
    champion = state->csbFmtownsUtilitySelectedChampion;
    if (champion >= state->csbFmtownsUtilityParty.ChampionCount ||
        !csb_v1_fmtowns_portrait_decode_planar(
            state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
            CSB_V1_FMTOWNS_STARTUP_PORTRAIT_BYTES, chunky, sizeof(chunky))) {
        return 0;
    }
    target = chunky[(size_t)source_y * 32u + (size_t)source_x];
    replacement = state->csbFmtownsUtilitySelectedColor;
    /* F7046 performs no F7044 draw when the selected colour already matches.
     * It nevertheless has a valid modal result and must not create a dirty
     * portrait merely because a user right-clicked it. */
    if (target == replacement) return m11_csb_redraw_fmtowns_utility(state);

    memcpy(state->csbFmtownsUtilityUndoPortrait,
           state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
           sizeof(state->csbFmtownsUtilityUndoPortrait));
    state->csbFmtownsUtilityUndoModified =
        state->csbFmtownsUtilityPortraitModified[champion];
    state->csbFmtownsUtilityUndoAvailable = 1;

    stack_x[stack_count] = source_x;
    stack_y[stack_count++] = source_y;
    chunky[(size_t)source_y * 32u + (size_t)source_x] = replacement;
    while (stack_count > 0) {
        int x;
        int y;
        int nx[4];
        int ny[4];
        int neighbor;

        --stack_count;
        x = stack_x[stack_count];
        y = stack_y[stack_count];
        nx[0] = x;     ny[0] = y - 1;
        nx[1] = x;     ny[1] = y + 1;
        nx[2] = x - 1; ny[2] = y;
        nx[3] = x + 1; ny[3] = y;
        for (neighbor = 0; neighbor < 4; ++neighbor) {
            size_t offset;
            if (nx[neighbor] < 0 || nx[neighbor] >= 32 ||
                ny[neighbor] < 0 || ny[neighbor] >= 29) continue;
            offset = (size_t)ny[neighbor] * 32u + (size_t)nx[neighbor];
            if (chunky[offset] != target) continue;
            chunky[offset] = replacement;
            if (stack_count >= F31_PORTRAIT_PIXELS) return 0;
            stack_x[stack_count] = nx[neighbor];
            stack_y[stack_count++] = ny[neighbor];
        }
    }
    if (!csb_v1_fmtowns_portrait_encode_planar(
            chunky, sizeof(chunky),
            state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
            CSB_V1_FMTOWNS_STARTUP_PORTRAIT_BYTES)) return 0;
    state->csbFmtownsUtilityPortraitModified[champion] = 1u;
    return m11_csb_redraw_fmtowns_utility(state);
}

static int m11_csb_fmtowns_utility_revert_portrait(M11_GameViewState *state)
{
    uint16_t champion;
    if (!state) return 0;
    champion = state->csbFmtownsUtilitySelectedChampion;
    if (champion >= state->csbFmtownsUtilityParty.ChampionCount) return 0;
    if (state->csbFmtownsUtilityPortraitModified[champion] == 0u) return 1;
    memcpy(state->csbFmtownsUtilityUndoPortrait,
           state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
           sizeof(state->csbFmtownsUtilityUndoPortrait));
    state->csbFmtownsUtilityUndoModified = 1;
    state->csbFmtownsUtilityUndoAvailable = 1;
    memcpy(state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
           state->csbFmtownsUtilityOriginalPortraits[champion],
           CSB_V1_FMTOWNS_STARTUP_PORTRAIT_BYTES);
    state->csbFmtownsUtilityPortraitModified[champion] = 0u;
    return m11_csb_redraw_fmtowns_utility(state);
}

static int m11_csb_fmtowns_utility_undo_portrait(M11_GameViewState *state)
{
    uint8_t temporary[CSB_V1_FMTOWNS_STARTUP_PORTRAIT_BYTES];
    uint16_t champion;
    int temporary_modified;
    if (!state || !state->csbFmtownsUtilityUndoAvailable) return 1;
    champion = state->csbFmtownsUtilitySelectedChampion;
    if (champion >= state->csbFmtownsUtilityParty.ChampionCount) return 0;
    memcpy(temporary,
           state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
           sizeof(temporary));
    memcpy(state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
           state->csbFmtownsUtilityUndoPortrait, sizeof(temporary));
    memcpy(state->csbFmtownsUtilityUndoPortrait, temporary, sizeof(temporary));
    temporary_modified = state->csbFmtownsUtilityPortraitModified[champion];
    state->csbFmtownsUtilityPortraitModified[champion] =
        (uint8_t)state->csbFmtownsUtilityUndoModified;
    state->csbFmtownsUtilityUndoModified = temporary_modified;
    return m11_csb_redraw_fmtowns_utility(state);
}

/* ------------------------------------------------------------------ */
/* DM1 FM Towns CDDA dispatch                                        */
/* ------------------------------------------------------------------ */

static int m11_dm1_fmtowns_cdda_data_dir(const M11_GameViewState *state,
                                          char *out, size_t out_size)
{
    if (!state || !state->dungeonPath[0] || !out || out_size == 0) return 0;
    return FSP_ParentDir(out, out_size, state->dungeonPath) && out[0] != '\0';
}

/* The selected FM Towns member may live below a ZIP-owned virtual path such
 * as archive.zip::DATA/DUNGEON.DAT.  CDDA is a sibling of that ISO member,
 * not a generated FMTOWNS.BIN cache.  Read both source files into process
 * memory and retain the archive's original member names. */
static int m11_dm1_fmtowns_read_cdda_media(const M11_GameViewState *state,
                                           uint8_t **out_cue,
                                           size_t *out_cue_size,
                                           uint8_t **out_image,
                                           size_t *out_image_size)
{
    const char *separator;
    char data_dir[M11_GAME_VIEW_PATH_CAPACITY];
    char archive_path[M11_GAME_VIEW_PATH_CAPACITY];
    char image_member[M11_GAME_VIEW_PATH_CAPACITY];
    size_t archive_length;

    if (!state || !out_cue || !out_cue_size || !out_image ||
        !out_image_size) return 0;
    *out_cue = NULL;
    *out_cue_size = 0U;
    *out_image = NULL;
    *out_image_size = 0U;

    separator = strstr(state->dungeonPath, "::");
    if (separator) {
        archive_length = (size_t)(separator - state->dungeonPath);
        if (archive_length == 0U || archive_length >= sizeof(archive_path))
            return 0;
        memcpy(archive_path, state->dungeonPath, archive_length);
        archive_path[archive_length] = '\0';
        if (firestaff_zip_extract_by_suffix(archive_path, ".cue", out_cue,
                                            out_cue_size) != 0 ||
            !fmtowns_cue_parse_image_member((const char *)*out_cue,
                                            *out_cue_size, image_member,
                                            sizeof(image_member)) ||
            firestaff_zip_extract_by_name(archive_path, image_member,
                                          out_image, out_image_size) != 0) {
            free(*out_cue);
            free(*out_image);
            *out_cue = NULL;
            *out_cue_size = 0U;
            *out_image = NULL;
            *out_image_size = 0U;
            return 0;
        }
        return 1;
    }

    return m11_dm1_fmtowns_cdda_data_dir(state, data_dir, sizeof(data_dir)) &&
        m11_read_loose_fmtowns_cue_media(data_dir, 1, out_cue,
                                         out_cue_size, out_image,
                                         out_image_size);
}

static void m11_dm1_dispatch_fmtowns_cdda(M11_GameViewState *state,
                                           int track_number)
{
    uint8_t *cue_bytes = NULL;
    size_t cue_size = 0U;
    uint8_t *bin_bytes = NULL;
    size_t bin_size = 0U;
    uint32_t track_starts[24];
    int track_count;
    uint32_t data_track_end, this_start, next_start;
    size_t data_byte_offset, audio_byte_offset, pcm_size;
    uint64_t data_byte_offset64;
    uint8_t *pcm;

    if (!state || !state->dm1FmtownsStartupReceiptValid || track_number < 2)
        return;

    if (state->dm1FmtownsCddaPlaying) {
        (void)M11_Audio_StopCdda(&state->audioState);
        state->dm1FmtownsCddaPlaying = 0;
        state->dm1FmtownsCddaCurrentTrack = 0;
    }

    if (!m11_dm1_fmtowns_read_cdda_media(state, &cue_bytes, &cue_size,
                                         &bin_bytes, &bin_size) ||
        cue_size == 0U || cue_size > 64U * 1024U || bin_size == 0U) {
        free(cue_bytes);
        free(bin_bytes);
        return;
    }

    memset(track_starts, 0, sizeof(track_starts));
    track_count = fmtowns_cue_parse_track_starts((const char *)cue_bytes, cue_size,
                                                  track_starts, 24);
    free(cue_bytes);
    cue_bytes = NULL;
    if (track_count < 20 || track_number >= track_count ||
        track_starts[track_number] == 0) {
        free(bin_bytes);
        return;
    }

    /* DM1 FM Towns BIN uses MODE1/2048 for the data track (track 1) and
     * raw 2352-byte sectors for audio tracks 2-20.  The first audio track's
     * sector offset marks the boundary between the two sector sizes. */
    data_track_end = track_starts[2];
    this_start = track_starts[track_number];
    data_byte_offset64 = (uint64_t)data_track_end * 2048u;
    if (this_start < data_track_end || data_byte_offset64 > SIZE_MAX) {
        free(bin_bytes);
        return;
    }

    if (track_number + 1 < track_count && track_starts[track_number + 1] != 0)
        next_start = track_starts[track_number + 1];
    else
        next_start = 0;

    data_byte_offset = (size_t)data_byte_offset64;
    if ((size_t)(this_start - data_track_end) >
        (SIZE_MAX - data_byte_offset) / FMTOWNS_CDDA_SECTOR_SIZE) {
        free(bin_bytes);
        return;
    }
    audio_byte_offset = data_byte_offset +
        (size_t)(this_start - data_track_end) * FMTOWNS_CDDA_SECTOR_SIZE;

    if (next_start > this_start) {
        if ((size_t)(next_start - this_start) >
            (bin_size - audio_byte_offset) / FMTOWNS_CDDA_SECTOR_SIZE) {
            free(bin_bytes);
            return;
        }
        pcm_size = (size_t)(next_start - this_start) * FMTOWNS_CDDA_SECTOR_SIZE;
    } else
        pcm_size = (size_t)bin_size - audio_byte_offset;

    if (audio_byte_offset > bin_size || pcm_size == 0 ||
        pcm_size > bin_size - audio_byte_offset) {
        free(bin_bytes);
        return;
    }

    pcm = (uint8_t *)malloc(pcm_size);
    if (!pcm) {
        free(bin_bytes);
        return;
    }
    memcpy(pcm, bin_bytes + audio_byte_offset, pcm_size);
    free(bin_bytes);

    if (M11_Audio_PlayCdda(&state->audioState, pcm, pcm_size, 0)) {
        state->dm1FmtownsCddaPlaying = 1;
        state->dm1FmtownsCddaCurrentTrack = track_number;
    }
    free(pcm);
}

static void m11_dm1_stop_fmtowns_cdda(M11_GameViewState *state)
{
    if (!state || !state->dm1FmtownsCddaPlaying) return;
    (void)M11_Audio_StopCdda(&state->audioState);
    state->dm1FmtownsCddaPlaying = 0;
    state->dm1FmtownsCddaCurrentTrack = 0;
}

static int m11_csb_bind_fmtowns_switch(M11_GameViewState *state,
                                       CSB_V1_FmtownsSwitchLanguage language)
{
    const CSB_V1_BootProfile *profile;
    char path[sizeof(((CSB_V1_BootProfile *)0)->asset_root) + 20u];
    FILE *file;
    long file_size;
    size_t bytes_read;
    int packed_switch;
    if (!state || !state->csbBootProfile) return 0;
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    packed_switch = profile->fmtowns_switch_bytes &&
        profile->fmtowns_switch_size != 0u;
    if (!m11_csb_is_fmtowns_profile(profile) ||
        (!profile->asset_root[0] && !packed_switch))
        return 0;
    state->csbFmtownsUtilityBound = 0;
    state->csbFmtownsUtilityJapaneseActive = 0;
    free(state->csbFmtownsUtilityJapanesePixels);
    state->csbFmtownsUtilityJapanesePixels = NULL;
    memset(state->csbFmtownsUtilityPixels, 0,
           sizeof(state->csbFmtownsUtilityPixels));
    memset(&state->csbFmtownsUtilityHandoffReceipt, 0,
           sizeof(state->csbFmtownsUtilityHandoffReceipt));
    memset(&state->csbFmtownsUtilityMenuReceipt, 0,
           sizeof(state->csbFmtownsUtilityMenuReceipt));
    memset(&state->csbFmtownsUtilityFontReceipt, 0,
           sizeof(state->csbFmtownsUtilityFontReceipt));
    memset(&state->csbFmtownsUtilityParty, 0,
           sizeof(state->csbFmtownsUtilityParty));
    memset(&state->csbFmtownsUtilityPortraitReceipt, 0,
           sizeof(state->csbFmtownsUtilityPortraitReceipt));
    memset(&state->csbFmtownsUtilityPortraitCatalog, 0,
           sizeof(state->csbFmtownsUtilityPortraitCatalog));
    memset(state->csbFmtownsUtilityOriginalPortraits, 0,
           sizeof(state->csbFmtownsUtilityOriginalPortraits));
    memset(state->csbFmtownsUtilityUndoPortrait, 0,
           sizeof(state->csbFmtownsUtilityUndoPortrait));
    memset(state->csbFmtownsUtilityPortraitModified, 0,
           sizeof(state->csbFmtownsUtilityPortraitModified));
    state->csbFmtownsUtilityUndoModified = 0;
    state->csbFmtownsUtilityUndoAvailable = 0;
    state->csbFmtownsUtilitySaveDialogActive = 0;
    state->csbFmtownsUtilityLoadDialogActive = 0;
    m11_csb_release_fmtowns_switch(state);
    if (packed_switch) {
        file = NULL;
        file_size = (long)profile->fmtowns_switch_size;
    } else {
        if (snprintf(path, sizeof(path), "%s/SWITCHTW.EXP", profile->asset_root) < 0 ||
            strlen(path) >= sizeof(path)) return 0;
        file = fopen(path, "rb");
        if (!file || fseek(file, 0, SEEK_END) != 0 ||
            (file_size = ftell(file)) <= 0 || file_size > 4 * 1024 * 1024 ||
            fseek(file, 0, SEEK_SET) != 0) {
            if (file) fclose(file);
            return 0;
        }
    }
    state->csbFmtownsSwitchBytes = (uint8_t *)malloc((size_t)file_size);
    if (!state->csbFmtownsSwitchBytes) {
        if (file) fclose(file);
        return 0;
    }
    if (packed_switch) {
        memcpy(state->csbFmtownsSwitchBytes, profile->fmtowns_switch_bytes,
               profile->fmtowns_switch_size);
        bytes_read = profile->fmtowns_switch_size;
    } else {
        bytes_read = fread(state->csbFmtownsSwitchBytes, 1u, (size_t)file_size,
                           file);
        fclose(file);
    }
    if (bytes_read != (size_t)file_size ||
        !csb_v1_fmtowns_switch_parse(state->csbFmtownsSwitchBytes,
                                     (size_t)file_size,
                                     &state->csbFmtownsSwitchReceipt)) {
        m11_csb_release_fmtowns_switch(state);
        return 0;
    }
    state->csbFmtownsSwitchByteCount = (size_t)file_size;
    /* The F31 package selects its own language page before SWITCH.C waits
     * sixty F0693 VBlanks and expands G4167.  F31E must never route its
     * Game button toward the F31J-only CHTWJ executable. */
    state->csbFmtownsSwitchLanguage = language;
    state->csbFmtownsSwitchVblanksRemaining = 60u;
    state->csbFmtownsSwitchBound = 1;
    return 1;
}

static int m11_csb_present_fmtowns_switch(M11_GameViewState *state,
                                          unsigned char *framebuffer,
                                          int framebuffer_width,
                                          int framebuffer_height)
{
    uint8_t rgb6[256][3];
    int color;
    if (!state || !framebuffer || !state->csbFmtownsSwitchBound) return 0;
    if (state->csbFmtownsSwitchVblanksRemaining != 0u) {
        memset(framebuffer, 0, (size_t)framebuffer_width * framebuffer_height);
        return 1;
    }
    for (color = 0; color < 256; ++color) {
        const CSB_V1_FmtownsSwitchColor *source =
            &state->csbFmtownsSwitchReceipt.palette[color & 15];
        rgb6[color][0] = source->red6;
        rgb6[color][1] = source->green6;
        rgb6[color][2] = source->blue6;
    }
    if (M11_Render_SetIndexedPaletteRgb6(rgb6) != M11_RENDER_OK) return 0;
    m11_csb_present_startup_raster(state->csbFmtownsSwitchPixels, framebuffer,
                                   framebuffer_width, framebuffer_height);
    return 1;
}

static int m11_csb_present_fmtowns_utility(M11_GameViewState *state,
                                           unsigned char *framebuffer,
                                           int framebuffer_width,
                                           int framebuffer_height)
{
    uint8_t rgb6[256][3];
    int color;
    if (!state || !framebuffer || !state->csbFmtownsUtilityBound) return 0;
    for (color = 0; color < 256; ++color) {
        rgb6[color][0] = state->csbFmtownsUtilityPaletteRgb6[color & 15][0];
        rgb6[color][1] = state->csbFmtownsUtilityPaletteRgb6[color & 15][1];
        rgb6[color][2] = state->csbFmtownsUtilityPaletteRgb6[color & 15][2];
    }
    if (M11_Render_SetIndexedPaletteRgb6(rgb6) != M11_RENDER_OK) return 0;
    if (state->csbFmtownsUtilityJapaneseActive) {
        m11_csb_present_highres_raster(
            state->csbFmtownsUtilityJapanesePixels,
            CSB_V1_FMTOWNS_UTILITY_JAPANESE_SCREEN_WIDTH,
            CSB_V1_FMTOWNS_UTILITY_JAPANESE_SCREEN_HEIGHT,
            framebuffer, framebuffer_width, framebuffer_height);
        return 1;
    }
    m11_csb_present_startup_raster(state->csbFmtownsUtilityPixels, framebuffer,
                                   framebuffer_width, framebuffer_height);
    return 1;
}

int M11_GameView_GetCsbFmtownsUtilityJapaneseFrame(
    const M11_GameViewState *state, const uint8_t **out_pixels,
    int *out_width, int *out_height)
{
    if (out_pixels) *out_pixels = NULL;
    if (out_width) *out_width = 0;
    if (out_height) *out_height = 0;
    if (!state || !state->active || !state->csbFmtownsUtilityBound ||
        !state->csbFmtownsUtilityJapaneseActive ||
        !state->csbFmtownsUtilityJapanesePixels) return 0;
    if (out_pixels) *out_pixels = state->csbFmtownsUtilityJapanesePixels;
    if (out_width) *out_width = CSB_V1_FMTOWNS_UTILITY_JAPANESE_SCREEN_WIDTH;
    if (out_height) *out_height = CSB_V1_FMTOWNS_UTILITY_JAPANESE_SCREEN_HEIGHT;
    return 1;
}

static void m11_csb_advance_fmtowns_switch(M11_GameViewState *state)
{
    if (!state || !state->csbFmtownsSwitchBound) return;
    if (state->csbFmtownsSwitchVblanksRemaining > 0u) {
        --state->csbFmtownsSwitchVblanksRemaining;
        if (state->csbFmtownsSwitchVblanksRemaining != 0u) return;
    }
    if (!csb_v1_fmtowns_switch_compose_page(
            state->csbFmtownsSwitchBytes, state->csbFmtownsSwitchByteCount,
            &state->csbFmtownsSwitchReceipt, state->csbFmtownsSwitchLanguage,
            state->csbFmtownsSwitchPixels,
            sizeof(state->csbFmtownsSwitchPixels))) {
        m11_csb_release_fmtowns_switch(state);
    }
}

static int m11_csb_bind_fmtowns_title(M11_GameViewState *state,
                                      const char *animation_name,
                                      int ending_handoff);
static int m11_csb_enter_fmtowns_game(M11_GameViewState *state,
                                      CSB_V1_FmtownsSwitchLanguage language);
static int m11_csb_fmtowns_native_save_path(char *out, size_t out_size);

static M11_GameInputResult m11_csb_handle_fmtowns_switch_pointer(
    M11_GameViewState *state, int x, int y, int button_mask)
{
    CSB_V1_FmtownsSwitchInputReceipt receipt;
    if (!state || !state->csbFmtownsSwitchBound ||
        state->csbFmtownsSwitchVblanksRemaining != 0u) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (!csb_v1_fmtowns_switch_route_click(
            &state->csbFmtownsSwitchReceipt, state->csbFmtownsSwitchLanguage,
            (int16_t)x, (int16_t)y,
            (button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0, &receipt)) {
        /* SWITCH.C main is modal. A missed click must not fall through into
         * COMMAND.C's unrelated PC34 command rectangles. */
        return M11_GAME_INPUT_REDRAW;
    }
    if (receipt.action == CSB_FMTOWNS_SWITCH_ACTION_TOGGLE_LANGUAGE) {
        /* ReDMCSB SWITCH.C main redraws the selected fourth bitmap, enters
         * its outer loop, waits sixty F0693 VBlanks, then flips L6590 before
         * expanding the next executable-owned page. */
        state->csbFmtownsSwitchLanguage =
            state->csbFmtownsSwitchLanguage == CSB_FMTOWNS_SWITCH_JAPANESE
                ? CSB_FMTOWNS_SWITCH_ENGLISH : CSB_FMTOWNS_SWITCH_JAPANESE;
        state->csbFmtownsSwitchVblanksRemaining = 60u;
        memset(state->csbFmtownsSwitchPixels, 0,
               sizeof(state->csbFmtownsSwitchPixels));
    } else if (receipt.action == CSB_FMTOWNS_SWITCH_ACTION_STORY) {
        /* AUTOEXEC.BAT invokes ANIMTW STORY.ANM and returns to the same
         * JAPANLOOP/USALOOP that selected this exit status. */
        state->csbFmtownsSwitchReturnLanguage = state->csbFmtownsSwitchLanguage;
        if (!m11_csb_bind_fmtowns_title(state, "STORY.ANM", 0)) {
            return M11_GAME_INPUT_IGNORED;
        }
    } else if (receipt.action == CSB_FMTOWNS_SWITCH_ACTION_UTILITY) {
        /* AUTOEXEC.BAT exits 2/5 into the separate F31 C06_CEDT owner.
         * The English frame is admitted only after UTILE's P3/menu/font
         * chain verifies. F31J's captured first chooser has its own
         * FMT_FNT.ROM-backed Shift-JIS consumer; later C06 dialogs remain
         * deliberately closed until their owners are recovered. */
        if (!m11_csb_enter_fmtowns_utility(
                state, state->csbFmtownsSwitchLanguage)) {
            m11_set_status(state, "CSB FM TOWNS", "UTILITY OWNER UNAVAILABLE");
            return M11_GAME_INPUT_IGNORED;
        }
    } else if (receipt.action == CSB_FMTOWNS_SWITCH_ACTION_GAME) {
        /* AUTOEXEC.BAT maps exits 3/6 to CHTWJ/CHTWE.  The game program,
         * not SWITCHTW and never the PC3.4 launcher, owns STARTUP1.C's
         * F0435 load loop and ENTRANCE.C's F0807 prison sequence. */
        if (!m11_csb_enter_fmtowns_game(state,
                                        state->csbFmtownsSwitchLanguage)) {
            m11_set_status(state, "CSB FM TOWNS", "GAME MEDIA REJECTED");
            return M11_GAME_INPUT_IGNORED;
        }
    }
    /* Utility still leaves SWITCHTW through AUTOEXEC.BAT into its separate
     * C06_CEDT owner. Game above consumes its distinct C03_GAME receipt;
     * neither route may fall through into a PC3.4 command rectangle. */
    return M11_GAME_INPUT_REDRAW;
}

static M11_GameInputResult m11_csb_handle_fmtowns_utility_pointer(
    M11_GameViewState *state, int x, int y, int button_mask)
{
    CSB_V1_FmtownsUtilityMenuHitBox hit;
    int picker_command;
    int picker_index;
    int champion;
    if (!state || !state->csbFmtownsUtilityBound ||
        (button_mask & (DM1_V1_MOUSE_MASK_LEFT_PC34 |
                        DM1_V1_MOUSE_MASK_RIGHT_PC34)) == 0 ||
        !state->csbBootProfile) return M11_GAME_INPUT_REDRAW;
    memset(&hit, 0, sizeof(hit));
    if (state->csbFmtownsUtilityGameSourceDialogActive) {
        if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0)
            return M11_GAME_INPUT_REDRAW;
        /* CEDTDATA.C G2260/G7065: the initial C06 dialog chooses the
         * source family, not a synthetic MINI.DAT editor.  DM media is not
         * yet admitted by this CSB-only installation, so retain the modal
         * and fail closed rather than accepting the label as a fake source. */
        if (state->csbFmtownsUtilityJapaneseActive) {
            if (x >= 160 && x <= 474 && y >= 176 && y <= 194) {
                m11_set_status(state, "CSB FM TOWNS", "DUNGEON MASTER MEDIA REQUIRED");
                return M11_GAME_INPUT_REDRAW;
            }
            if (x >= 160 && x <= 474 && y >= 216 && y <= 234) {
                m11_set_status(state, "CSB FM TOWNS", "CSB SAVE MEDIA REQUIRED");
                return M11_GAME_INPUT_REDRAW;
            }
            if (x >= 160 && x <= 474 && y >= 256 && y <= 274) {
                state->csbFmtownsUtilityGameSourceDialogActive = 0;
                state->csbFmtownsUtilityBound = 0;
                state->csbFmtownsUtilityJapaneseActive = 0;
                free(state->csbFmtownsUtilityJapanesePixels);
                state->csbFmtownsUtilityJapanesePixels = NULL;
                if (!m11_csb_bind_fmtowns_switch(
                        state, CSB_FMTOWNS_SWITCH_JAPANESE))
                    return M11_GAME_INPUT_IGNORED;
            }
            return M11_GAME_INPUT_REDRAW;
        }
        if (x >= 80 && x <= 237 && y >= 88 && y <= 96) {
            m11_set_status(state, "CSB FM TOWNS", "DUNGEON MASTER MEDIA REQUIRED");
            return M11_GAME_INPUT_REDRAW;
        }
        if (x >= 80 && x <= 237 && y >= 108 && y <= 116) {
            state->csbFmtownsUtilityGameSourceDialogActive = 0;
            state->csbFmtownsUtilityGameSaveMediumDialogActive = 1;
            return m11_csb_redraw_fmtowns_utility(state)
                ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
        }
        if (x >= 80 && x <= 237 && y >= 128 && y <= 136) {
            state->csbFmtownsUtilityGameSourceDialogActive = 0;
            state->csbFmtownsUtilityBound = 0;
            memset(state->csbFmtownsUtilityPixels, 0,
                   sizeof(state->csbFmtownsUtilityPixels));
            if (!m11_csb_bind_fmtowns_switch(
                    state, CSB_FMTOWNS_SWITCH_ENGLISH))
                return M11_GAME_INPUT_IGNORED;
            return M11_GAME_INPUT_REDRAW;
        }
        return M11_GAME_INPUT_REDRAW;
    }
    if (state->csbFmtownsUtilityGameSaveMediumDialogActive) {
        CSB_V1_FmtownsGameHandoffReceipt game;
        CSB_V1_FmtownsUserSaveReceipt save;
        CSB_V1_FmtownsStartupState save_state;
        CSB_V1_FmtownsStartupPortraitReceipt save_portraits;
        CSB_V1_BootProfile *profile =
            (CSB_V1_BootProfile *)state->csbBootProfile;
        char path[FSP_PATH_MAX];
        int loaded = 0;
        if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0)
            return M11_GAME_INPUT_REDRAW;
        if (x >= 165 && x <= 237 && y >= 128 && y <= 136) {
            state->csbFmtownsUtilityGameSaveMediumDialogActive = 0;
            state->csbFmtownsUtilityGameSourceDialogActive = 1;
            return m11_csb_redraw_fmtowns_utility(state)
                ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
        }
        if (!(x >= 80 && x <= 148 && y >= 128 && y <= 136))
            return M11_GAME_INPUT_REDRAW;
        memset(&game, 0, sizeof(game));
        memset(&save, 0, sizeof(save));
        memset(&save_state, 0, sizeof(save_state));
        memset(&save_portraits, 0, sizeof(save_portraits));
        /* C06's source reader accepts only a full F0435 CSBGAME.DAT (or its
         * native recovery sibling).  The installed CD MINI.DAT is never a
         * substitute for the A: game-save medium. */
        if (csb_v1_fmtowns_game_handoff_open(
                profile, CSB_FMTOWNS_SWITCH_ENGLISH, &game) &&
            m11_csb_fmtowns_native_save_path(path, sizeof(path)) &&
            csb_v1_fmtowns_game_user_save_open_or_restore_backup(
                profile, &game, path, &save) &&
            csb_v1_fmtowns_game_load_user_save_state(&save, &save_state) &&
            csb_v1_fmtowns_game_load_user_save_portraits(
                &save, &save_portraits)) {
            state->csbFmtownsUtilityParty = save_state.party;
            state->csbFmtownsUtilityPortraitReceipt = save_portraits;
            memcpy(state->csbFmtownsUtilityOriginalPortraits,
                   save_portraits.source_bytes,
                   sizeof(state->csbFmtownsUtilityOriginalPortraits));
            memset(state->csbFmtownsUtilityPortraitModified, 0,
                   sizeof(state->csbFmtownsUtilityPortraitModified));
            state->csbFmtownsUtilityUndoAvailable = 0;
            state->csbFmtownsUtilitySelectedChampion = 0u;
            state->csbFmtownsUtilitySelectedColor = 0u;
            (void)csb_v1_fmtowns_utility_portrait_catalog_open(
                profile, CSB_FMTOWNS_SWITCH_ENGLISH,
                &state->csbFmtownsUtilityPortraitCatalog);
            loaded = 1;
        }
        csb_v1_fmtowns_game_startup_state_free(&save_state);
        if (!loaded) {
            m11_set_status(state, "CSB FM TOWNS", "GAME SAVE DISK REQUIRED");
            return M11_GAME_INPUT_REDRAW;
        }
        state->csbFmtownsUtilityGameSaveMediumDialogActive = 0;
        m11_set_status(state, "CSB FM TOWNS", "GAME SAVE LOADED");
        return m11_csb_redraw_fmtowns_utility(state)
            ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
    }
    if (state->csbFmtownsUtilitySaveDialogActive) {
        if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0)
            return M11_GAME_INPUT_REDRAW;
        if (x >= 80 && x <= 148 && y >= 108 && y <= 116) {
            CSB_V1_FmtownsGameHandoffReceipt game;
            CSB_V1_FmtownsStartupState startup;
            CSB_V1_BootProfile save_profile;
            CSB_V1_BootProfile *profile =
                (CSB_V1_BootProfile *)state->csbBootProfile;
            char path[FSP_PATH_MAX];
            FILE *existing = NULL;
            int saved = 0;
            /* F7001 choice 1 calls F7052 with C0_GAME_SOURCE.  Rebuild its
             * source GAME from verified MINI.DAT in a private runtime: C06
             * must never serialize whichever C03 session happens to be open.
             * F7052 then receives C06's edited champion array and its raw
             * encoded portraits on the native M746 medium. */
            memset(&game, 0, sizeof(game));
            memset(&startup, 0, sizeof(startup));
            save_profile = *profile;
            memset(&save_profile.runtime, 0, sizeof(save_profile.runtime));
            if (csb_v1_fmtowns_game_handoff_open(
                    profile, CSB_FMTOWNS_SWITCH_ENGLISH, &game) &&
                csb_v1_fmtowns_game_load_startup_state(&game, &startup) &&
                csb_v1_fmtowns_game_apply_startup_state(
                    &startup, &save_profile.runtime) &&
                csb_v1_runtime_set_party_state(
                    &save_profile.runtime, &state->csbFmtownsUtilityParty) == 0 &&
                profile->runtime.csbwin_random_seed_valid &&
                m11_csb_fmtowns_native_save_path(path, sizeof(path)) &&
                dm1_v1_save_prepare_parent_directory_pc34(path)) {
                const char *name = strrchr(path, '/');
                name = name ? name + 1 : path;
                save_profile.runtime.csbwin_random_seed =
                    profile->runtime.csbwin_random_seed;
                save_profile.runtime.csbwin_random_seed_valid = 1;
                existing = fopen(path, "rb");
                if (strcmp(name, "CSBGAME.DAT") == 0) {
                    if (existing) {
                        fclose(existing);
                        existing = NULL;
                        saved = csb_v1_fmtowns_game_write_utility_user_save(
                            &save_profile, &game,
                            &state->csbFmtownsUtilityPortraitReceipt, path);
                    } else {
                        saved = csb_v1_fmtowns_game_create_utility_user_save_from_startup(
                            &save_profile, &game,
                            &state->csbFmtownsUtilityPortraitReceipt, path);
                    }
                }
            }
            if (existing) fclose(existing);
            if (save_profile.runtime.dungeon_handle) {
                csb_v1_dungeon_free(save_profile.runtime.dungeon_handle);
                free(save_profile.runtime.dungeon_handle);
            }
            csb_v1_fmtowns_game_startup_state_free(&startup);
            state->csbFmtownsUtilitySaveDialogActive = 0;
            m11_set_status(state, "CSB FM TOWNS",
                           saved ? "GAME SAVED" : "GAME SAVE REJECTED");
        } else if (x >= 165 && x <= 237 && y >= 108 && y <= 116) {
            char saved_path[FSP_PATH_MAX];
            int saved = csb_v1_fmtowns_utility_save_selected_portrait(
                &state->csbFmtownsUtilitySaveMappingReceipt,
                &state->csbFmtownsUtilityPortraitCatalog,
                &state->csbFmtownsUtilityParty,
                &state->csbFmtownsUtilityPortraitReceipt,
                state->csbFmtownsUtilitySelectedChampion,
                saved_path, sizeof(saved_path));
            state->csbFmtownsUtilitySaveDialogActive = 0;
            if (!saved) {
                m11_set_status(state, "CSB FM TOWNS", "CMP SAVE REJECTED");
            } else {
                uint16_t champion = state->csbFmtownsUtilitySelectedChampion;
                memcpy(state->csbFmtownsUtilityOriginalPortraits[champion],
                       state->csbFmtownsUtilityPortraitReceipt.source_bytes[champion],
                       CSB_V1_FMTOWNS_STARTUP_PORTRAIT_BYTES);
                state->csbFmtownsUtilityPortraitModified[champion] = 0u;
                state->csbFmtownsUtilityUndoAvailable = 0;
                m11_set_status(state, "CSB FM TOWNS", "CHAMPION SAVED");
            }
        } else if (x >= 123 && x <= 196 && y >= 128 && y <= 136) {
            state->csbFmtownsUtilitySaveDialogActive = 0;
        } else return M11_GAME_INPUT_REDRAW;
        return m11_csb_redraw_fmtowns_utility(state)
            ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
    }
    if (state->csbFmtownsUtilityLoadDialogActive) {
        if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0)
            return M11_GAME_INPUT_REDRAW;
        if (x >= 80 && x <= 148 && y >= 108 && y <= 116) {
            CSB_V1_FmtownsGameHandoffReceipt game;
            CSB_V1_FmtownsUserSaveReceipt save;
            CSB_V1_FmtownsStartupState save_state;
            CSB_V1_FmtownsStartupPortraitReceipt save_portraits;
            CSB_V1_BootProfile *profile =
                (CSB_V1_BootProfile *)state->csbBootProfile;
            char path[FSP_PATH_MAX];
            int loaded = 0;
            /* F7004 choice GAME delegates to F7051(C0_GAME_SOURCE), which
             * opens the selected C5 slot and F2124's four portrait blocks.
             * C06 keeps that result as editor state; it does not enter C03
             * or substitute the active host game runtime. */
            memset(&game, 0, sizeof(game));
            memset(&save, 0, sizeof(save));
            memset(&save_state, 0, sizeof(save_state));
            memset(&save_portraits, 0, sizeof(save_portraits));
            if (csb_v1_fmtowns_game_handoff_open(
                    profile, CSB_FMTOWNS_SWITCH_ENGLISH, &game) &&
                m11_csb_fmtowns_native_save_path(path, sizeof(path)) &&
                csb_v1_fmtowns_game_user_save_open_or_restore_backup(
                    profile, &game, path, &save) &&
                csb_v1_fmtowns_game_load_user_save_state(&save, &save_state) &&
                csb_v1_fmtowns_game_load_user_save_portraits(
                    &save, &save_portraits)) {
                state->csbFmtownsUtilityParty = save_state.party;
                state->csbFmtownsUtilityPortraitReceipt = save_portraits;
                memcpy(state->csbFmtownsUtilityOriginalPortraits,
                       save_portraits.source_bytes,
                       sizeof(state->csbFmtownsUtilityOriginalPortraits));
                memset(state->csbFmtownsUtilityPortraitModified, 0,
                       sizeof(state->csbFmtownsUtilityPortraitModified));
                state->csbFmtownsUtilityUndoAvailable = 0;
                loaded = 1;
            }
            csb_v1_fmtowns_game_startup_state_free(&save_state);
            state->csbFmtownsUtilityLoadDialogActive = 0;
            m11_set_status(state, "CSB FM TOWNS",
                           loaded ? "GAME LOADED" : "GAME LOAD REJECTED");
        } else if (x >= 165 && x <= 237 && y >= 108 && y <= 116) {
            state->csbFmtownsUtilityLoadDialogActive = 0;
            if (!state->csbFmtownsUtilityPortraitCatalog.valid ||
                !csb_v1_fmtowns_utility_file_picker_open(
                    &state->csbFmtownsUtilityPortraitCatalog, 0u,
                    &state->csbFmtownsUtilityFilePicker)) {
                m11_set_status(state, "CSB FM TOWNS", "CMP CATALOG UNAVAILABLE");
                return M11_GAME_INPUT_IGNORED;
            }
            state->csbFmtownsUtilityFilePickerActive = 1;
        } else if (x >= 123 && x <= 196 && y >= 128 && y <= 136) {
            state->csbFmtownsUtilityLoadDialogActive = 0;
        } else return M11_GAME_INPUT_REDRAW;
        return m11_csb_redraw_fmtowns_utility(state)
            ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
    }
    if (state->csbFmtownsUtilityFilePickerActive) {
        if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0)
            return M11_GAME_INPUT_REDRAW;
        picker_command = 0;
        picker_index = -1;
        if (!csb_v1_fmtowns_utility_file_picker_input(
                &state->csbFmtownsUtilityFilePicker, (int16_t)x, (int16_t)y,
                &picker_command, &picker_index))
            return M11_GAME_INPUT_REDRAW;
        if (picker_command == CSB_V1_FMTOWNS_FILE_PICKER_FILE_LIST) {
            if (picker_index < 0 ||
                !csb_v1_fmtowns_utility_load_portrait(
                    &state->csbFmtownsUtilityPortraitCatalog,
                    (uint16_t)picker_index,
                    &state->csbFmtownsUtilityParty,
                    state->csbFmtownsUtilitySelectedChampion,
                    &state->csbFmtownsUtilityPortraitReceipt)) {
                m11_set_status(state, "CSB FM TOWNS", "CMP LOAD REJECTED");
                return M11_GAME_INPUT_IGNORED;
            }
            memcpy(state->csbFmtownsUtilityOriginalPortraits[
                       state->csbFmtownsUtilitySelectedChampion],
                   state->csbFmtownsUtilityPortraitReceipt.source_bytes[
                       state->csbFmtownsUtilitySelectedChampion],
                   CSB_V1_FMTOWNS_STARTUP_PORTRAIT_BYTES);
            state->csbFmtownsUtilityPortraitModified[
                state->csbFmtownsUtilitySelectedChampion] = 0u;
            state->csbFmtownsUtilityUndoAvailable = 0;
            state->csbFmtownsUtilityFilePickerActive = 0;
            return m11_csb_redraw_fmtowns_utility(state)
                ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
        }
        if (picker_command == CSB_V1_FMTOWNS_FILE_PICKER_CANCEL) {
            state->csbFmtownsUtilityFilePickerActive = 0;
            return m11_csb_redraw_fmtowns_utility(state)
                ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
        }
        if (picker_command == CSB_V1_FMTOWNS_FILE_PICKER_NEW_DISK) {
            CSB_V1_FmtownsUtilityPortraitCatalog portrait_medium;
            CSB_V1_FmtownsUtilityFilePicker picker;
            memset(&portrait_medium, 0, sizeof(portrait_medium));
            memset(&picker, 0, sizeof(picker));
            if (!csb_v1_fmtowns_utility_portrait_medium_catalog_open(
                    &state->csbFmtownsUtilitySaveMappingReceipt,
                    state->csbFmtownsUtilityMenuReceipt.language,
                    &portrait_medium) || portrait_medium.entry_count == 0u ||
                !csb_v1_fmtowns_utility_file_picker_open(
                    &portrait_medium, 0u, &picker)) {
                m11_set_status(state, "CSB FM TOWNS", "PORTRAIT DISK EMPTY");
                return M11_GAME_INPUT_IGNORED;
            }
            state->csbFmtownsUtilityPortraitCatalog = portrait_medium;
            state->csbFmtownsUtilityFilePicker = picker;
            return m11_csb_redraw_fmtowns_utility(state)
                ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
        }
        return m11_csb_redraw_fmtowns_utility(state)
            ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
    }
    /* CEDTDATA.C G2272_MouseInputs[13..14] and CEDT006.C F7028.  These
     * fields edit the already selected champion; clicking a top portrait is
     * the separate C01..C04 selection route. */
    if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0 &&
        x >= 15 && x <= 59 && y >= 87 && y <= 95) {
        size_t length = strlen(state->csbFmtownsUtilityParty.Champions[
            state->csbFmtownsUtilitySelectedChampion].Name);
        state->csbFmtownsUtilityEditField = 0;
        state->csbFmtownsUtilityEditCharacterIndex = (uint8_t)
            ((x - 16) / 6 < 0 ? 0 :
             ((x - 16) / 6 > (int)length ? (int)length : (x - 16) / 6));
        state->csbFmtownsUtilityTextCursorVisible = 1;
        state->csbFmtownsUtilityTextCursorVblanksRemaining = 30u;
        return m11_csb_redraw_fmtowns_utility(state)
            ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
    }
    if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0 &&
        x >= 15 && x <= 131 && y >= 100 && y <= 108) {
        size_t length = strlen(state->csbFmtownsUtilityParty.Champions[
            state->csbFmtownsUtilitySelectedChampion].Title);
        state->csbFmtownsUtilityEditField = 1;
        state->csbFmtownsUtilityEditCharacterIndex = (uint8_t)
            ((x - 16) / 6 < 0 ? 0 :
             ((x - 16) / 6 > (int)length ? (int)length : (x - 16) / 6));
        state->csbFmtownsUtilityTextCursorVisible = 1;
        state->csbFmtownsUtilityTextCursorVblanksRemaining = 30u;
        return m11_csb_redraw_fmtowns_utility(state)
            ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
    }
    /* CEDTDATA.C G2272_MouseInputs[0..3] and F7050 first select only an
     * existing source champion.  The retained MINI.DAT portrait receipt is
     * re-expanded; no temporary host portrait is ever installed. */
    champion = x >= 4 && x <= 48 ? 0 :
               x >= 71 && x <= 115 ? 1 :
               x >= 138 && x <= 182 ? 2 :
               x >= 205 && x <= 249 ? 3 : -1;
    if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0 &&
        champion >= 0 && y >= 3 && y <= 42) {
        if (champion < state->csbFmtownsUtilityParty.ChampionCount) {
            state->csbFmtownsUtilitySelectedChampion = (uint16_t)champion;
            if (!m11_csb_redraw_fmtowns_utility(state))
                return M11_GAME_INPUT_IGNORED;
        }
        return M11_GAME_INPUT_REDRAW;
    }
    /* CEDTDATA.C G2272_MouseInputs[6] and CEDT006.C F7043 derive the
     * source colour from (y - 43) / 8. */
    if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0 &&
        x >= 286 && x <= 303 && y >= 43 && y <= 169) {
        state->csbFmtownsUtilitySelectedColor = (uint8_t)((y - 43) / 8);
        if (!m11_csb_redraw_fmtowns_utility(state))
            return M11_GAME_INPUT_IGNORED;
        return M11_GAME_INPUT_REDRAW;
    }
    /* CEDTDATA.C G2272_MouseInputs[4] and CEDT006.C F7045 convert the
     * 3x source zoom rectangle back to one F31 portrait pixel. */
    if (x >= 157 && x <= 252 && y >= 60 && y <= 146) {
        if ((button_mask & DM1_V1_MOUSE_MASK_RIGHT_PC34) != 0) {
            if (!m11_csb_fmtowns_utility_flood_fill_portrait(
                    state, (x - 157) / 3, (y - 60) / 3)) {
                return M11_GAME_INPUT_IGNORED;
            }
            return M11_GAME_INPUT_REDRAW;
        }
        if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0)
            return M11_GAME_INPUT_REDRAW;
        if (!m11_csb_fmtowns_utility_draw_portrait_pixel(
                state, (x - 157) / 3, (y - 60) / 3)) {
            return M11_GAME_INPUT_IGNORED;
        }
        return M11_GAME_INPUT_REDRAW;
    }
    if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0 ||
        !csb_v1_fmtowns_utility_menu_action_at(
            &state->csbFmtownsUtilityMenuReceipt, (int16_t)x, (int16_t)y,
            &hit)) return M11_GAME_INPUT_REDRAW;
    if (hit.action == CSB_V1_FMTOWNS_UTILITY_ACTION_QUIT) {
        /* CEDT006 returns to AUTOEXEC's F31E loop.  Rebind the original
         * SWITCHTW page; no made-up post-editor page is kept on screen. */
        state->csbFmtownsUtilityBound = 0;
        memset(state->csbFmtownsUtilityPixels, 0,
               sizeof(state->csbFmtownsUtilityPixels));
        if (!m11_csb_bind_fmtowns_switch(state, CSB_FMTOWNS_SWITCH_ENGLISH))
            return M11_GAME_INPUT_IGNORED;
    } else if (hit.action == CSB_V1_FMTOWNS_UTILITY_ACTION_REVERT) {
        if (!m11_csb_fmtowns_utility_revert_portrait(state))
            return M11_GAME_INPUT_IGNORED;
    } else if (hit.action == CSB_V1_FMTOWNS_UTILITY_ACTION_UNDO) {
        if (!m11_csb_fmtowns_utility_undo_portrait(state))
            return M11_GAME_INPUT_IGNORED;
    } else if (hit.action == CSB_V1_FMTOWNS_UTILITY_ACTION_SAVE_CHAMPIONS) {
        /* F7001's F31E dialogue, not a direct all-catalogue host write. */
        state->csbFmtownsUtilitySaveDialogActive = 1;
        if (!m11_csb_redraw_fmtowns_utility(state)) {
            state->csbFmtownsUtilitySaveDialogActive = 0;
            return M11_GAME_INPUT_IGNORED;
        }
    } else if (hit.action == CSB_V1_FMTOWNS_UTILITY_ACTION_LOAD_CHAMPIONS) {
        /* F7004 presents G7068/G7064 before choosing F7051 or F7003. */
        state->csbFmtownsUtilityLoadDialogActive = 1;
        if (!m11_csb_redraw_fmtowns_utility(state)) {
            state->csbFmtownsUtilityLoadDialogActive = 0;
            return M11_GAME_INPUT_IGNORED;
        }
    }
    /* New-adventure still requires CEDT006's authentic file/edit
     * transaction. It remains fail-closed; no synthetic host implementation
     * is substituted. Revert, undo and the catalog-bound F7002 load above
     * remain bounded to admitted F31 source records. */
    return M11_GAME_INPUT_REDRAW;
}

static size_t m11_csb_fmtowns_utility_text_length(const char *text,
                                                   size_t maximum)
{
    size_t length = 0u;
    while (length < maximum && text[length] != '\0') ++length;
    return length;
}

int M11_GameView_CsbFmtownsUtilityTextInputActive(
    const M11_GameViewState *state)
{
    return state && state->active && state->csbFmtownsUtilityBound &&
           state->csbFmtownsUtilityEditField >= 0 &&
           state->csbFmtownsUtilityEditField <= 1 &&
           !state->csbFmtownsUtilityGameSourceDialogActive &&
           !state->csbFmtownsUtilityGameSaveMediumDialogActive &&
           !state->csbFmtownsUtilityFilePickerActive &&
           !state->csbFmtownsUtilitySaveDialogActive &&
           !state->csbFmtownsUtilityLoadDialogActive;
}

static M11_GameInputResult m11_csb_fmtowns_utility_redraw_text(
    M11_GameViewState *state)
{
    return m11_csb_redraw_fmtowns_utility(state)
        ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
}

static void m11_csb_fmtowns_utility_reset_text_cursor(M11_GameViewState *state)
{
    state->csbFmtownsUtilityTextCursorVisible = 1;
    state->csbFmtownsUtilityTextCursorVblanksRemaining = 30u;
}

M11_GameInputResult M11_GameView_ConsumeCsbFmtownsUtilityTextInput(
    M11_GameViewState *state, const char *text)
{
    char *field;
    size_t maximum;
    size_t cursor;
    int changed = 0;
    if (!M11_GameView_CsbFmtownsUtilityTextInputActive(state) || !text)
        return M11_GAME_INPUT_IGNORED;
    field = state->csbFmtownsUtilityEditField == 0
        ? state->csbFmtownsUtilityParty.Champions[
              state->csbFmtownsUtilitySelectedChampion].Name
        : state->csbFmtownsUtilityParty.Champions[
              state->csbFmtownsUtilitySelectedChampion].Title;
    maximum = state->csbFmtownsUtilityEditField == 0 ? 7u : 19u;
    cursor = state->csbFmtownsUtilityEditCharacterIndex;
    while (*text != '\0') {
        unsigned char character = (unsigned char)*text++;
        size_t length;
        if (character >= 'a' && character <= 'z')
            character = (unsigned char)(character + 'A' - 'a');
        if (!((character >= 'A' && character <= 'Z') || character == '.' ||
              character == ',' || character == ';' || character == ':' ||
              (character == ' ' && cursor != 0u))) continue;
        length = m11_csb_fmtowns_utility_text_length(field, maximum);
        if (cursor >= maximum) continue;
        if (length >= maximum) length = maximum - 1u;
        memmove(field + cursor + 1u, field + cursor, length - cursor + 1u);
        field[cursor++] = (char)character;
        field[maximum] = '\0';
        changed = 1;
    }
    state->csbFmtownsUtilityEditCharacterIndex = (uint8_t)cursor;
    if (changed) m11_csb_fmtowns_utility_reset_text_cursor(state);
    return changed ? m11_csb_fmtowns_utility_redraw_text(state)
                   : M11_GAME_INPUT_IGNORED;
}

M11_GameInputResult M11_GameView_HandleCsbFmtownsUtilityTextKey(
    M11_GameViewState *state, M11_CsbFmtownsUtilityTextKey key)
{
    char *field;
    size_t maximum, length, cursor;
    int field_index;
    if (!M11_GameView_CsbFmtownsUtilityTextInputActive(state))
        return M11_GAME_INPUT_IGNORED;
    field_index = state->csbFmtownsUtilityEditField;
    field = field_index == 0
        ? state->csbFmtownsUtilityParty.Champions[
              state->csbFmtownsUtilitySelectedChampion].Name
        : state->csbFmtownsUtilityParty.Champions[
              state->csbFmtownsUtilitySelectedChampion].Title;
    maximum = field_index == 0 ? 7u : 19u;
    length = m11_csb_fmtowns_utility_text_length(field, maximum);
    cursor = state->csbFmtownsUtilityEditCharacterIndex;
    if (cursor > length) cursor = length;
    switch (key) {
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_BACKSPACE:
            if (cursor == 0u) return M11_GAME_INPUT_IGNORED;
            memmove(field + cursor - 1u, field + cursor, length - cursor + 1u);
            --cursor;
            break;
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_CLEAR:
            memset(field, 0, maximum + 1u);
            cursor = 0u;
            break;
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_LEFT:
            if (cursor == 0u) return M11_GAME_INPUT_IGNORED;
            --cursor;
            break;
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_RIGHT:
            if (cursor >= length) return M11_GAME_INPUT_IGNORED;
            ++cursor;
            break;
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_HOME: cursor = 0u; break;
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_END: cursor = length; break;
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_UP:
            if (field_index != 1) return M11_GAME_INPUT_IGNORED;
            state->csbFmtownsUtilityEditField = 0;
            cursor = m11_csb_fmtowns_utility_text_length(
                state->csbFmtownsUtilityParty.Champions[
                    state->csbFmtownsUtilitySelectedChampion].Name, 7u);
            break;
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_DOWN:
            if (field_index != 0) return M11_GAME_INPUT_IGNORED;
            state->csbFmtownsUtilityEditField = 1;
            cursor = m11_csb_fmtowns_utility_text_length(
                state->csbFmtownsUtilityParty.Champions[
                    state->csbFmtownsUtilitySelectedChampion].Title, 19u);
            break;
        /* CEDT006.C F7041: F31 0x520D and 0x5210 switch to the beginning
         * of the adjoining source field, unlike Up/Down which use its end. */
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_PAGE_UP:
            if (field_index != 1) return M11_GAME_INPUT_IGNORED;
            state->csbFmtownsUtilityEditField = 0;
            cursor = 0u;
            break;
        case M11_CSB_FMTOWNS_UTILITY_TEXT_KEY_PAGE_DOWN:
            if (field_index != 0) return M11_GAME_INPUT_IGNORED;
            state->csbFmtownsUtilityEditField = 1;
            cursor = 0u;
            break;
        default: return M11_GAME_INPUT_IGNORED;
    }
    state->csbFmtownsUtilityEditCharacterIndex = (uint8_t)cursor;
    m11_csb_fmtowns_utility_reset_text_cursor(state);
    return m11_csb_fmtowns_utility_redraw_text(state);
}

static int m11_csb_bind_fmtowns_title(M11_GameViewState *state,
                                      const char *animation_name,
                                      int ending_handoff)
{
    const CSB_V1_BootProfile *profile;
    char path[sizeof(((CSB_V1_BootProfile *)0)->asset_root) + 16u];
    FILE *file;
    long file_size;
    size_t bytes_read;
    int step_result;
    const uint8_t *packed_bytes = NULL;
    size_t packed_size = 0u;

    if (!state || !state->csbBootProfile || !animation_name) return 0;
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (strcmp(animation_name, "TITLE.ANM") == 0) {
        packed_bytes = profile->fmtowns_title_bytes;
        packed_size = profile->fmtowns_title_size;
    } else if (strcmp(animation_name, "STORY.ANM") == 0) {
        packed_bytes = profile->fmtowns_story_bytes;
        packed_size = profile->fmtowns_story_size;
    } else if (strcmp(animation_name, "ENDING.ANM") == 0) {
        packed_bytes = profile->fmtowns_ending_bytes;
        packed_size = profile->fmtowns_ending_size;
    }
    if (!m11_csb_is_fmtowns_profile(profile) ||
        (!profile->asset_root[0] && (!packed_bytes || packed_size == 0u)))
        return 0;
    m11_csb_release_fmtowns_title(state);
    m11_csb_release_fmtowns_switch(state);
    m11_dm2_release_fmtowns_title(state);
    if (packed_bytes && packed_size != 0u) {
        file = NULL;
        if (packed_size > (size_t)LONG_MAX) return 0;
        file_size = (long)packed_size;
        state->csbFmtownsTitleBytes = (uint8_t *)malloc(
            packed_size);
    } else {
        if (snprintf(path, sizeof(path), "%s/%s", profile->asset_root,
                     animation_name) < 0 ||
            strlen(path) >= sizeof(path)) return 0;
        file = fopen(path, "rb");
        if (!file || fseek(file, 0, SEEK_END) != 0 ||
            (file_size = ftell(file)) <= 0 || file_size > 4 * 1024 * 1024 ||
            fseek(file, 0, SEEK_SET) != 0) {
            if (file) fclose(file);
            return 0;
        }
        state->csbFmtownsTitleBytes = (uint8_t *)malloc((size_t)file_size);
    }
    if (!state->csbFmtownsTitleBytes) {
        if (file) fclose(file);
        return 0;
    }
    if (packed_bytes && packed_size != 0u) {
        memcpy(state->csbFmtownsTitleBytes, packed_bytes, packed_size);
        bytes_read = packed_size;
    } else {
        bytes_read = fread(state->csbFmtownsTitleBytes, 1u, (size_t)file_size,
                           file);
        fclose(file);
    }
    if (bytes_read != (size_t)file_size ||
        csb_v1_fmtowns_anm_playback_init(state->csbFmtownsTitleBytes,
                                          (size_t)file_size,
                                          &state->csbFmtownsTitlePlayback) != 0) {
        m11_csb_release_fmtowns_title(state);
        return 0;
    }
    state->csbFmtownsTitleByteCount = (size_t)file_size;
    memset(state->csbFmtownsTitlePixels, 0,
           sizeof(state->csbFmtownsTitlePixels));
    step_result = csb_v1_fmtowns_anm_playback_step(
        &state->csbFmtownsTitlePlayback, state->csbFmtownsTitlePixels,
        sizeof(state->csbFmtownsTitlePixels),
        &state->csbFmtownsTitleFrameReceipt);
    if (step_result != 1 || !state->csbFmtownsTitleFrameReceipt.valid ||
        !state->csbFmtownsTitleFrameReceipt.palette_applied) {
        m11_csb_release_fmtowns_title(state);
        return 0;
    }
    state->csbFmtownsFrameTimerARemaining =
        state->csbFmtownsTitleFrameReceipt.timer_a_ticks;
    state->csbFmtownsTitleBound = 1;
    state->csbFmtownsEndingActive = ending_handoff ? 1 : 0;
    state->csbFmtownsEndingFinished = 0;
    m11_csb_dispatch_fmtowns_cdda(state, &state->csbFmtownsTitleFrameReceipt);
    m11_csb_dispatch_fmtowns_anm_pcm(
        state, &state->csbFmtownsTitleFrameReceipt);
    return 1;
}

static int m11_csb_activate_fmtowns_ending(M11_GameViewState *state)
{
    const CSB_V1_BootProfile *profile;
    if (!state || !state->gameWon || !state->csbBootProfile ||
        state->csbFmtownsEndingActive || state->csbFmtownsEndingFinished) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (!m11_csb_is_fmtowns_profile(profile) ||
        !state->csbFmtownsGameHandoffReceipt.valid) {
        return 0;
    }
    /* ReDMCSB STARTUP2.C F0750 pauses game music before F2248. F2275's
     * first TD/TR command, if present, replaces that physical CUE track. */
    if (state->csbFmtownsCddaPlaying && !state->csbFmtownsCddaPaused &&
        M11_Audio_PauseCdda(&state->audioState)) {
        state->csbFmtownsCddaPaused = 1;
    }
    if (!m11_csb_bind_fmtowns_title(state, "ENDING.ANM", 1)) {
        m11_set_status(state, "CSB FM TOWNS", "ENDING.ANM DECODE FAILED");
        return 0;
    }
    m11_set_status(state, "CSB FM TOWNS", "ENDING.ANM");
    return 1;
}

static int m11_csb_present_fmtowns_title(M11_GameViewState *state,
                                         unsigned char *framebuffer,
                                         int framebuffer_width,
                                         int framebuffer_height)
{
    const CSB_V1_FmtownsAnmFrameReceipt *frame;
    uint8_t rgb6[256][3];
    int color;
    if (!state || !framebuffer || !state->csbFmtownsTitleBound ||
        !state->csbFmtownsTitleFrameReceipt.valid ||
        !state->csbFmtownsTitleFrameReceipt.palette_applied) return 0;
    frame = &state->csbFmtownsTitleFrameReceipt;
    for (color = 0; color < 256; ++color) {
        const CSB_V1_FmtownsAnmColor *source =
            &frame->palette[color & 15];
        rgb6[color][0] = (uint8_t)(source->r << 2u);
        rgb6[color][1] = (uint8_t)(source->g << 2u);
        rgb6[color][2] = (uint8_t)(source->b << 2u);
    }
    if (M11_Render_SetIndexedPaletteRgb6(rgb6) != M11_RENDER_OK) return 0;
    m11_csb_present_startup_raster(state->csbFmtownsTitlePixels, framebuffer,
                                   framebuffer_width, framebuffer_height);
    return 1;
}

static void m11_csb_advance_fmtowns_title(M11_GameViewState *state,
                                           uint32_t elapsed_us)
{
    CSB_V1_FmtownsAnmFrameReceipt next_frame;
    uint64_t accumulator;
    int step_result;
    if (!state || !state->csbFmtownsTitleBound ||
        state->csbFmtownsTitleFinished) return;
    accumulator = (uint64_t)state->csbFmtownsTimerAAccumulatorUs + elapsed_us;
    while (accumulator >= M11_CSB_FMTOWNS_TIMER_A_TICK_US &&
           !state->csbFmtownsTitleFinished) {
        accumulator -= M11_CSB_FMTOWNS_TIMER_A_TICK_US;
        if (state->csbFmtownsFrameTimerARemaining > 0u)
            --state->csbFmtownsFrameTimerARemaining;
        if (state->csbFmtownsFrameTimerARemaining != 0u) continue;
        step_result = csb_v1_fmtowns_anm_playback_step(
            &state->csbFmtownsTitlePlayback, state->csbFmtownsTitlePixels,
            sizeof(state->csbFmtownsTitlePixels), &next_frame);
        if (step_result == 1) {
            state->csbFmtownsTitleFrameReceipt = next_frame;
            state->csbFmtownsFrameTimerARemaining = next_frame.timer_a_ticks;
            m11_csb_dispatch_fmtowns_cdda(
                state, &state->csbFmtownsTitleFrameReceipt);
            m11_csb_dispatch_fmtowns_anm_pcm(
                state, &state->csbFmtownsTitleFrameReceipt);
        } else if (state->csbFmtownsEndingActive) {
            /* STARTUP2.C F0750 returns from F2248 to RestoreTowns and
             * termination. Keep the final original frame visible until the
             * host's normal return-to-launcher action releases this view;
             * do not route a victory through SWITCHTW or a PC34 end screen. */
            if (state->csbFmtownsCddaPlaying) {
                (void)M11_Audio_StopCdda(&state->audioState);
                state->csbFmtownsCddaPlaying = 0;
                state->csbFmtownsCddaPaused = 0;
            }
            state->csbFmtownsCddaSourceTicksRemaining = 0u;
            state->csbFmtownsTitleFinished = 1;
            state->csbFmtownsEndingFinished = 1;
        } else {
            /* ANIMTOWN.C returns after F2275. The retail AUTOEXEC.BAT then
             * executes SWITCHTW JAPAN; it does not enter PC34 TITLE.C or
             * chain directly into Story. */
            if (m11_csb_bind_fmtowns_switch(
                    state, state->csbFmtownsSwitchReturnLanguage)) {
                m11_csb_release_fmtowns_title(state);
            } else {
                state->csbFmtownsTitleFinished = 1;
            }
        }
    }
    state->csbFmtownsTimerAAccumulatorUs = (uint32_t)accumulator;
}

/* Atari ST CSB owns ANIMATE.SCR/ANIMATE.DAT rather than the PC34 TITLE.C
 * surface set. Preserve its four-bit page and P4B1 palette through M11; the
 * ordinary PC34 startup path remains the fallback for every other variant. */
static int m11_csb_present_atari_st_startup(M11_GameViewState *state,
                                            unsigned char *framebuffer,
                                            int framebuffer_width,
                                            int framebuffer_height)
{
    const CSB_V1_BootProfile *profile;
    char user_data[FSP_PATH_MAX];
    char cache_root[FSP_PATH_MAX];
    uint8_t rgb6[256][3];
    int color;

    if (!state || !framebuffer || framebuffer_width <= 0 ||
        framebuffer_height <= 0 || !state->csbBootProfile) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if ((profile->variant_id != CSB_V1_VARIANT_ST20_EN &&
         profile->variant_id != CSB_V1_VARIANT_ST21_EN) ||
        !state->csbAtariStAnimationSourceRoot[0] || !FSP_GetUserDataDir(user_data,
            sizeof(user_data)) || !FSP_JoinPath(cache_root,
            sizeof(cache_root), user_data, "cache")) {
        return 0;
    }
    if (!state->csbAtariStAnimationFrameBound ||
        state->csbAtariStAnimationFrameVbl != state->csbAtariStAnimationVbl) {
        CSB_V1_AtariStAnimationTraceReceipt trace;
        memset(&trace, 0, sizeof(trace));
        if (!csb_v1_atari_st_animation_decode_frame_at_vbl_from_root_indexed(
                state->csbAtariStAnimationSourceRoot, cache_root,
                state->csbAtariStAnimationVbl,
                state->csbAtariStAnimationPixels,
                state->csbAtariStAnimationPalette, &trace) || !trace.valid) {
            return 0;
        }
        state->csbAtariStAnimationFrameVbl = state->csbAtariStAnimationVbl;
        state->csbAtariStAnimationFrameBound = 1;
    }
    for (color = 0; color < 256; ++color) {
        const uint8_t *rgb = state->csbAtariStAnimationPalette[color & 15];
        rgb6[color][0] = (uint8_t)(rgb[0] >> 2);
        rgb6[color][1] = (uint8_t)(rgb[1] >> 2);
        rgb6[color][2] = (uint8_t)(rgb[2] >> 2);
    }
    if (M11_Render_SetIndexedPaletteRgb6(rgb6) != M11_RENDER_OK) {
        return 0;
    }
    m11_csb_present_startup_raster(state->csbAtariStAnimationPixels,
                                   framebuffer, framebuffer_width,
                                   framebuffer_height);
    return 1;
}

/* ENTRANCE.C owns the utility wait-loop state, but M11 may only present its
 * backing page through the same indexed startup raster receipt as the title
 * and closed doors.  The utility render plan contains semantic rows, not a
 * substitute font or pixel source, so it is admission evidence only. */
static int m11_csb_startup_utility_raster_admitted(
    const M11_GameViewState *state,
    const CSB_V1_BootStartupHostViewReceipt_PC34 *host_view)
{
    const CSB_V1_BootStartupHudMenuDrawReceipt_PC34 *hud;
    const CSB_V1_BootStartupPackagedCaptureProof_PC34 *proof;
    CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    CSB_V1_StartupRuntimeHostSurfaceReceipt_PC34 host_surface;
    int admitted = 0;

    if (!state || !host_view || !m11_csb_startup_package_identity_current(state) ||
        !host_view->valid || !host_view->hud_menu_draw_valid ||
        !host_view->capture_proof_valid) {
        return 0;
    }
    hud = &host_view->hud_menu_draw;
    proof = &host_view->capture_proof;
    if (!hud->valid ||
        hud->kind != CSB_V1_BOOT_STARTUP_HUD_MENU_UTILITY_PC34 ||
        !hud->startup_render_plan_valid || !hud->utility_render_plan_valid ||
        !hud->draw_utility_panel || hud->draw_fallback_text ||
        !hud->startup_render_plan.waiting_for_input || !proof->valid ||
        !proof->real_asset_matched || !proof->hud_menu_capture_ready ||
        !proof->hud_menu_draw_available || !proof->utility_menu_route ||
        !proof->draw_utility_panel || proof->draw_fallback_text ||
        proof->packaged_capture_hash == 0u) {
        return 0;
    }

    /* The utility rows are semantic input data, not a raster.  Admit their
     * backing page only when the opened CSB session can still compose the
     * real C004/C002/C003 entrance surface; a launch-time wrapper receipt
     * must not stand in for those pixels. */
    session = (CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    memset(&host_surface, 0, sizeof(host_surface));
    if (session &&
        csb_v1_boot_startup_runtime_host_surface_receipt_from_session_pc34(
            session, &hud->startup_render_plan,
            m11_csb_startup_source_tick(state),
            &host_surface) &&
        host_surface.valid && host_surface.real_asset_matched &&
        host_surface.no_legacy_wrappers && host_surface.no_synthetic_surface &&
        host_surface.host_surface ==
            CSB_V1_STARTUP_RUNTIME_HOST_SURFACE_ENTRANCE_PC34 &&
        host_surface.raster.valid && host_surface.raster.entrance_composited &&
        host_surface.raster.door_composited &&
        host_surface.raster.source_surface_count == 3 &&
        host_surface.raster.pixel_hash != 0u) {
        admitted = 1;
    }
    csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(
        &host_surface);
    return admitted;
}

static void m11_csb_startup_consume_audio_action(
    M11_GameViewState *state,
    const CSB_V1_StartupRuntimeAssetSession_PC34 *session,
    CSB_V1_StartupAudioAction_PC34 action)
{
    if (!state || !session) {
        return;
    }
    switch (action) {
    case CSB_V1_STARTUP_AUDIO_ACTION_PLAY_FTL_SWOOSH_PC34:
        /* F0908/F0909 may only reach SDL through the selected package's
         * authenticated signed-PCM buffer.  Missing bytes deliberately stay
         * silent: using an M11 marker here would fabricate the CSB intro. */
        if (!state->csbStartupSwooshPlayConsumed &&
            state->csbStartupSwooshBytesBound &&
            M11_Audio_PlayCsbSwshPcm(
                &state->audioState, state->csbStartupSwooshBytes,
                (int)sizeof(state->csbStartupSwooshBytes), 334,
                state->csbStartupSwooshHash)) {
            state->csbStartupSwooshPlayConsumed = 1;
        }
        break;
    case CSB_V1_STARTUP_AUDIO_ACTION_RELEASE_FTL_SWOOSH_PC34:
        /* F0910 is a source-order release.  The raw sample stream has no
         * procedural tail to cancel; retain the release only after F0909's
         * exact buffer was accepted. */
        if (state->csbStartupSwooshPlayConsumed) {
            state->csbStartupSwooshReleaseConsumed = 1;
        }
        break;
    case CSB_V1_STARTUP_AUDIO_ACTION_PLAY_ENTRANCE_MUSIC_PC34:
        /* Do not route this through DM1 SONG.DAT.  The transition is
         * recorded only after the title's source-owned swoosh release; an
         * actual CSB music decoder can consume this boundary later. */
        if (session->playback.title_phase_mask == 0x0f &&
            (!state->csbStartupSwooshBytesBound ||
             state->csbStartupSwooshReleaseConsumed)) {
            state->csbStartupEntranceMusicTransitionConsumed = 1;
        }
        break;
    case CSB_V1_STARTUP_AUDIO_ACTION_NONE_PC34:
    default:
        break;
    }
}

static void m11_draw_csb_startup_entrance(M11_GameViewState *state,
                                          unsigned char *framebuffer,
                                          int framebufferWidth,
                                          int framebufferHeight)
{
    CSB_V1_BootRuntimeStartupSnapshot_PC34 snapshot;
    CSB_V1_BootStartupHostViewReceipt_PC34 host_view;
    CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    CSB_V1_StartupRuntimeHostSurfaceReceipt_PC34 host_surface;
    CSB_V1_F0128EntranceRuntimeBinding_PC34 f0128_binding;
    uint32_t entrance_source_tick;

    if (!state || !framebuffer ||
        !m11_csb_startup_package_identity_current(state) ||
        framebufferWidth <= 0 ||
        framebufferHeight <= 0) {
        return;
    }
    if (m11_csb_is_fmtowns_profile(
            (const CSB_V1_BootProfile *)state->csbBootProfile) &&
        state->csbFmtownsGameHandoffReceipt.valid &&
        state->csbState.startup_entrance_active &&
        !state->csbState.startup_title_active) {
        const CSB_V1_StartupRuntimeAssetSession_PC34 *fmtowns_session =
            (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
                state->csbStartupRuntimeAssetSession;
        const CSB_V1_StartupRuntimeSurface_PC34 *entrance =
            fmtowns_session ? &fmtowns_session->surfaces.surfaces[
                CSB_V1_STARTUP_RUNTIME_SURFACE_ENTRANCE_SCREEN_PC34] : NULL;
        CSB_V1_StartupRenderState_PC34 render_state;
        CSB_V1_StartupRenderPlan_PC34 render_plan;
        CSB_V1_StartupRuntimeHostSurfaceReceipt_PC34 opening;
        /* ReDMCSB ENTRANCE.C F0807 owns C004 after the verified C03_GAME
         * executable has started. C004 is the source-owned 320x200 entrance
         * page, so F31 must not synthesize a PC TITLE.C playback sequence. */
        if (!entrance || !entrance->valid || !entrance->pixels ||
            entrance->source_asset_id != 4 || entrance->width != 320 ||
            entrance->height != 200 || !entrance->decode_receipt.valid ||
            !entrance->decode_receipt.ended_at_record_boundary) return;
        if (state->csbState.startup_entrance_opening_active) {
            memset(&render_state, 0, sizeof(render_state));
            memset(&render_plan, 0, sizeof(render_plan));
            memset(&opening, 0, sizeof(opening));
            render_state.entrance_active = 1;
            render_state.entrance_source_step =
                state->csbState.startup_entrance_source_step;
            render_state.opening_active = 1;
            render_state.opening_delay_ticks =
                state->csbState.startup_entrance_opening_delay_ticks;
            render_state.opening_step =
                state->csbState.startup_entrance_opening_step;
            if (!csb_v1_startup_source_render_plan_from_state_pc34(
                    &render_state, &render_plan) ||
                render_plan.surface !=
                    CSB_V1_STARTUP_RENDER_ENTRANCE_OPENING_FRAME_PC34 ||
                !csb_v1_boot_startup_runtime_host_surface_receipt_from_session_pc34(
                    (CSB_V1_StartupRuntimeAssetSession_PC34 *)fmtowns_session,
                    &render_plan, m11_csb_startup_source_tick(state),
                    &opening) || !opening.valid ||
                opening.host_surface !=
                    CSB_V1_STARTUP_RUNTIME_HOST_SURFACE_DOOR_OPENING_PC34 ||
                !opening.raster.pixels) {
                csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(
                    &opening);
                return;
            }
            m11_csb_present_startup_raster(opening.raster.pixels, framebuffer,
                                           framebufferWidth, framebufferHeight);
            csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(
                &opening);
            return;
        }
        /* Record the exact C004 presentation in the same session that will
         * later consume C002/C003 and C017/C040.  The direct F31 raster path
         * above is only presentation; this frame receipt carries ENTRANCE.C
         * F0807's source event into the terminal handoff. */
        memset(&render_state, 0, sizeof(render_state));
        memset(&render_plan, 0, sizeof(render_plan));
        render_state.entrance_active = 1;
        render_state.entrance_source_step =
            state->csbState.startup_entrance_source_step;
        if (!csb_v1_startup_source_render_plan_from_state_pc34(
                &render_state, &render_plan) ||
            render_plan.surface != CSB_V1_STARTUP_RENDER_ENTRANCE_CLOSED_PC34 ||
            !csb_v1_boot_startup_runtime_asset_session_frame_pc34(
                (CSB_V1_StartupRuntimeAssetSession_PC34 *)fmtowns_session,
                &render_plan, m11_csb_startup_source_tick(state), &opening.frame)) {
            return;
        }
        m11_csb_present_startup_raster(entrance->pixels, framebuffer,
                                       framebufferWidth, framebufferHeight);
        return;
    }
    m11_csb_boot_runtime_startup_snapshot(state, &snapshot);
    csb_v1_boot_startup_host_view_receipt_init_pc34(&host_view);
    if (!csb_v1_boot_startup_host_view_receipt_from_snapshot_pc34(
            &snapshot, &host_view) ||
        !host_view.valid ||
        !host_view.render_draw_valid ||
        !host_view.render_draw.render_plan_valid) {
        return;
    }
    /* TITLE.C F0437 may select an indexed palette only with the exact C001
     * phase plan.  A palette ID alone is insufficient: a stale source step
     * could otherwise present a valid palette over a wrong C001 rectangle. */
    if (host_view.render_draw.render_plan.surface ==
            CSB_V1_STARTUP_RENDER_TITLE_PC34 &&
        !m11_csb_c001_palette_is_source_owned(&host_view)) {
        return;
    }
    if (host_view.hud_menu_draw_valid &&
        host_view.hud_menu_draw.kind ==
            CSB_V1_BOOT_STARTUP_HUD_MENU_UTILITY_PC34 &&
        !m11_csb_startup_utility_raster_admitted(state, &host_view)) {
        return;
    }
    session = (CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    entrance_source_tick = m11_csb_startup_source_tick(state);
    memset(&host_surface, 0, sizeof(host_surface));
    if (session &&
        session->playback.stage == CSB_V1_STARTUP_PLAYBACK_STAGE_NONE_PC34) {
        CSB_V1_StartupAudioAction_PC34 audio_action;
        if (!csb_v1_boot_startup_playback_begin_pc34(session, &audio_action)) {
            session = NULL;
        } else {
            m11_csb_startup_consume_audio_action(state, session, audio_action);
            if (!csb_v1_boot_startup_playback_complete_swoosh_pc34(
                    session, &audio_action)) {
                session = NULL;
            } else {
                m11_csb_startup_consume_audio_action(state, session,
                                                     audio_action);
            }
        }
    }
    if (session &&
        session->playback.stage == CSB_V1_STARTUP_PLAYBACK_STAGE_TITLE_PC34) {
        const int target_frame = state->csbState.startup_title_frame;
        int frame_index = session->playback.title_phase_mask
            ? session->playback.title_frame + 1 : 0;
        CSB_V1_StartupRenderPlan_PC34 playback_plan;
        CSB_V1_StartupAudioAction_PC34 audio_action;

        /* TITLE.C F0437 owns every visible C001 phase.  Do not let a stale
         * post-swoosh transfer/Entrance plan consume the remaining title
         * frames in one draw call: that skips PRESENTS/CHAOS/STRIKES. */
        if (state->csbState.startup_title_active) {
            if (!csb_v1_boot_startup_playback_accepts_title_plan_pc34(
                    session, &host_view.render_draw.render_plan,
                    target_frame)) {
                return;
            }
        } else {
            /* The idle receipt clears TITLE.C after its final source frame.
             * The next plan is ENTRANCE.C, but the session must consume that
             * terminal title tick to switch its playback owner.  M11 may
             * have advanced the source VBlanks while the host was occluded;
             * in that case no C001 phase has yet been consumed by the
             * presentation session.  Replay the verified C001 phase plans
             * into that session before F0442 presents C005.  Passing only
             * the terminal tick would fail the source owner's 0x0f phase
             * admission and leave the real credits page black. */
            if (!state->csbState.startup_entrance_active ||
                target_frame < csb_v1_startup_title_total_ticks_pc34()) {
                return;
            }
            frame_index = session->playback.title_phase_mask == 0x0f
                ? csb_v1_startup_title_total_ticks_pc34()
                : 0;
        }
        for (; frame_index <= target_frame; ++frame_index) {
            if (!csb_v1_boot_startup_playback_title_frame_pc34(
                    session, frame_index, &playback_plan, &audio_action)) {
                session = NULL;
                break;
            }
            m11_csb_startup_consume_audio_action(state, session, audio_action);
        }
    }
    /* TITLE.C F0437 and ENTRANCE.C F0441/F0807 supply the source plan.
     * The owning session turns C001-C005/C017/C040 into one verified host
     * surface. M11 consumes that terminal page atomically; it must not
     * derive a replacement frame or clear the page when source media fails. */
    /* ReDMCSB ENTRANCE.C F0441 has one deliberate black transfer page. It
     * is not a missing title/entrance surface and must not wait on a raster
     * receipt that only exists for package graphics. */
    if (host_view.render_draw.render_plan.surface ==
        CSB_V1_STARTUP_RENDER_ENTRANCE_BLACK_PC34) {
        memset(framebuffer, 0,
               (size_t)framebufferWidth * (size_t)framebufferHeight);
        return;
    }
    if (session &&
        (host_view.render_draw.render_plan.surface ==
             CSB_V1_STARTUP_RENDER_ENTRANCE_CLOSED_PC34 ||
         host_view.render_draw.render_plan.surface ==
             CSB_V1_STARTUP_RENDER_ENTRANCE_OPENING_DELAY_PC34 ||
         host_view.render_draw.render_plan.surface ==
             CSB_V1_STARTUP_RENDER_ENTRANCE_OPENING_FRAME_PC34)) {
        int f0128_ok = csb_v1_startup_entrance_f0128_produce_pc34(
             session, &host_view.render_draw.render_plan,
             entrance_source_tick,
             &state->csbStartupF0128EntranceMaterialReceipt,
             &state->csbStartupF0128EntranceRasterReceipt,
             state->csbStartupF0128EntrancePixels,
             sizeof(state->csbStartupF0128EntrancePixels));
        int set_ok = f0128_ok ? M11_GameView_SetCsbEntranceF0128Raster(
             state, &state->csbStartupF0128EntranceMaterialReceipt,
             &state->csbStartupF0128EntranceRasterReceipt,
             state->csbStartupF0128EntrancePixels,
             sizeof(state->csbStartupF0128EntrancePixels),
             entrance_source_tick,
             session->generation) : 0;
        if (!f0128_ok || !set_ok) {
            return;
        }
    }
    memset(&f0128_binding, 0, sizeof(f0128_binding));
    if (state->csbStartupF0128EntranceBound) {
        f0128_binding.valid = 1;
        f0128_binding.source_tick = state->csbStartupF0128EntranceSourceTick;
        f0128_binding.session_generation =
            state->csbStartupF0128EntranceSessionGeneration;
        f0128_binding.material_receipt =
            &state->csbStartupF0128EntranceMaterialReceipt;
        f0128_binding.raster_receipt =
            &state->csbStartupF0128EntranceRasterReceipt;
        f0128_binding.viewport_pixels = state->csbStartupF0128EntrancePixels;
        f0128_binding.viewport_pixel_count =
            sizeof(state->csbStartupF0128EntrancePixels);
    }
    if (!session ||
        ((state->csbStartupF0128EntranceBound &&
          !csb_v1_f0128_entrance_runtime_consume_pc34(
              session, &host_view.render_draw.render_plan, &f0128_binding,
              &host_surface)) ||
         (!state->csbStartupF0128EntranceBound &&
          !csb_v1_boot_startup_runtime_host_surface_receipt_from_session_pc34(
              session, &host_view.render_draw.render_plan,
              entrance_source_tick,
              &host_surface))) ||
        !host_surface.valid || !host_surface.real_asset_matched ||
        !host_surface.no_legacy_wrappers ||
        !host_surface.no_synthetic_surface ||
        host_surface.host_surface ==
            CSB_V1_STARTUP_RUNTIME_HOST_SURFACE_NONE_PC34 ||
        host_surface.host_surface_hash == 0u ||
        !host_surface.raster.valid || !host_surface.raster.real_asset_matched ||
        !host_surface.raster.pixels ||
        host_surface.raster.width != CSB_V1_STARTUP_RUNTIME_RASTER_WIDTH_PC34 ||
        host_surface.raster.height != CSB_V1_STARTUP_RUNTIME_RASTER_HEIGHT_PC34) {
        csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(
            &host_surface);
        return;
    }
    if (host_view.render_draw.render_plan.surface ==
            CSB_V1_STARTUP_RENDER_ENTRANCE_OPENING_FRAME_PC34 &&
        !m11_csb_opening_door_raster_is_source_owned(
            state, &host_view, &host_surface)) {
        csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(
            &host_surface);
        return;
    }
    /* TITLE.C F0437 presents only its source-owned C001 phase rectangles.
     * Do not let a generic title host page or a collapsed phase sequence reach
     * M11 between PRESENTS, CHAOS, and STRIKES BACK. */
    if (host_view.render_draw.render_plan.surface ==
            CSB_V1_STARTUP_RENDER_TITLE_PC34 &&
        (host_surface.host_surface !=
             CSB_V1_STARTUP_RUNTIME_HOST_SURFACE_TITLE_PC34 ||
         host_surface.raster.source_surface_count != 1 ||
         !host_surface.frame.title_surface ||
         host_surface.frame.title_surface->source_asset_id != 1 ||
         !host_surface.frame.title_surface->decode_receipt.valid ||
         !host_surface.frame.title_surface->decode_receipt.ended_at_record_boundary ||
         host_surface.frame.title_phase_mask == 0u ||
         (session->playback.title_phase_mask &
          host_surface.frame.title_phase_mask) !=
             host_surface.frame.title_phase_mask ||
         host_surface.frame.title_phase_tick !=
             host_view.render_draw.render_plan.title_source_step)) {
        csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(
            &host_surface);
        return;
    }
    m11_csb_present_startup_raster(host_surface.raster.pixels,
                                   framebuffer,
                                   framebufferWidth,
                                   framebufferHeight);
    csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(
        &host_surface);
}

static void m11_csb_startup_command_state_receipt_to_m11(
    M11_GameViewState *state,
    const CSB_V1_StartupCommandStateReceipt_PC34 *receipt)
{
    if (!state || !receipt) {
        return;
    }
    state->csbState.startup_title_active = receipt->title_active;
    state->csbState.startup_title_frame = receipt->title_frame;
    state->csbState.startup_title_source_step =
        receipt->title_source_step;
    state->csbState.startup_entrance_active =
        receipt->entrance_active;
    state->csbState.startup_entrance_source_step =
        receipt->entrance_source_step;
    state->csbState.startup_entrance_dismissed =
        receipt->entrance_dismissed;
    state->csbState.startup_entrance_credits_active =
        receipt->credits_active;
    state->csbState.startup_entrance_credits_remaining_ticks =
        receipt->credits_remaining_ticks;
    state->csbState.startup_entrance_opening_active =
        receipt->opening_active;
    state->csbState.startup_entrance_opening_delay_ticks =
        receipt->opening_delay_ticks;
    state->csbState.startup_entrance_opening_step =
        receipt->opening_step;
    state->csbState.startup_entrance_pending_command =
        receipt->pending_command;
}

static void m11_csb_startup_init_state_receipt_to_m11(
    M11_GameViewState *state,
    const CSB_V1_StartupInitStateReceipt_PC34 *receipt)
{
    if (!state || !receipt) {
        return;
    }
    m11_csb_startup_command_state_receipt_to_m11(state,
                                                 &receipt->command_state);
    state->csbState.startup_entrance_frame = receipt->entrance_frame;
    state->csbState.startup_entrance_last_command =
        receipt->entrance_last_command;
    state->csbState.startup_entrance_bonus_requested =
        receipt->entrance_bonus_requested ? 1 : 0;
}

static M11_GameInputResult m11_csb_startup_apply_host_receipt(
    M11_GameViewState *state,
    const CSB_V1_StartupHostReceipt_PC34 *receipt)
{
    if (!state || !receipt) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (receipt->clear_import_preview) {
        state->csbState.startup_import_preview_active = 0;
    }
    if (receipt->status) {
        m11_set_status(state,
                       receipt->status_scope,
                       receipt->status);
    }
    if (receipt->log_line) {
        m11_log_event(state,
                      receipt->log_color ? receipt->log_color : M11_COLOR_YELLOW,
                      "T0: %s",
                      receipt->log_line);
    }
    if (receipt->bonus_requested_changed) {
        state->csbState.startup_entrance_bonus_requested =
            receipt->bonus_requested ? 1 : 0;
    }
    switch (receipt->input_result) {
        case CSB_V1_STARTUP_ENTRANCE_INPUT_REDRAW_PC34:
            return M11_GAME_INPUT_REDRAW;
        case CSB_V1_STARTUP_ENTRANCE_INPUT_RETURN_TO_LAUNCHER_PC34:
            return M11_GAME_INPUT_RETURN_TO_MENU;
        case CSB_V1_STARTUP_ENTRANCE_INPUT_IGNORE_PC34:
        default:
            return M11_GAME_INPUT_IGNORED;
    }
}

static int m11_csb_capture_title_phase_hashes_from_session(
    CSB_V1_StartupRuntimeAssetSession_PC34 *session,
    uint32_t out_hashes[CSB_V1_BOOT_STARTUP_TITLE_SAMPLE_COUNT_PC34],
    uint32_t *out_set_hash)
{
    static const int frames[CSB_V1_BOOT_STARTUP_TITLE_SAMPLE_COUNT_PC34] =
        {0, 60, 79, 100};
    static const CSB_V1_StartupStage_PC34 stages[
        CSB_V1_BOOT_STARTUP_TITLE_SAMPLE_COUNT_PC34] = {
            CSB_V1_STARTUP_STAGE_TITLE_PRESENTS_PC34,
            CSB_V1_STARTUP_STAGE_TITLE_CHAOS_ZOOM_PC34,
            CSB_V1_STARTUP_STAGE_TITLE_CHAOS_ZOOM_PC34,
            CSB_V1_STARTUP_STAGE_TITLE_STRIKES_BACK_PC34
        };
    CSB_V1_StartupRenderState_PC34 render_state;
    CSB_V1_StartupRenderPlan_PC34 plan;
    CSB_V1_StartupRuntimeHostSurfaceReceipt_PC34 host;
    uint32_t set_hash = 2166136261u;
    uint32_t saved_source_tick;
    unsigned int i;
    int ok = 0;

    if (!session || !out_hashes || !out_set_hash || !session->valid ||
        !session->real_asset_matched || !session->rejects_legacy_wrappers ||
        !session->full_startup_ready) {
        return 0;
    }
    memset(out_hashes, 0,
           sizeof(uint32_t) * CSB_V1_BOOT_STARTUP_TITLE_SAMPLE_COUNT_PC34);
    saved_source_tick = session->source_tick;
    for (i = 0u; i < CSB_V1_BOOT_STARTUP_TITLE_SAMPLE_COUNT_PC34; ++i) {
        memset(&render_state, 0, sizeof(render_state));
        memset(&plan, 0, sizeof(plan));
        memset(&host, 0, sizeof(host));
        render_state.entrance_active = 1;
        render_state.title_active = 1;
        render_state.title_frame = frames[i];
        if (!csb_v1_startup_source_render_plan_from_state_pc34(
                &render_state, &plan) ||
            plan.surface != CSB_V1_STARTUP_RENDER_TITLE_PC34 ||
            plan.title_stage != (int)stages[i] ||
            !csb_v1_boot_startup_title_capture_plan_admit_pc34(
                &plan, frames[i]) ||
            !csb_v1_boot_startup_runtime_host_surface_receipt_from_session_pc34(
                session, &plan, i + 1u, &host) ||
            !host.valid || !host.real_asset_matched ||
            !host.no_legacy_wrappers || !host.no_synthetic_surface ||
            host.host_surface != CSB_V1_STARTUP_RUNTIME_HOST_SURFACE_TITLE_PC34 ||
            !host.raster.title_composited ||
            host.raster.source_surface_count != 1 ||
            host.special_palette != plan.title_special_palette ||
            host.raster.pixel_hash == 0u) {
            csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(&host);
            goto done;
        }
        out_hashes[i] = host.raster.pixel_hash;
        set_hash = (set_hash ^ out_hashes[i]) * 16777619u;
        csb_v1_boot_startup_runtime_host_surface_receipt_release_pc34(&host);
    }
    for (i = 0u; i < CSB_V1_BOOT_STARTUP_TITLE_SAMPLE_COUNT_PC34; ++i) {
        unsigned int j;

        if (out_hashes[i] == 0u) goto done;
        for (j = 0u; j < i; ++j) {
            if (out_hashes[j] == out_hashes[i]) goto done;
        }
    }
    *out_set_hash = set_hash ? set_hash : 1u;
    ok = 1;
done:
    session->source_tick = saved_source_tick;
    if (!ok) {
        memset(out_hashes, 0,
               sizeof(uint32_t) * CSB_V1_BOOT_STARTUP_TITLE_SAMPLE_COUNT_PC34);
        *out_set_hash = 0u;
    }
    return ok;
}

static int m11_csb_bind_release_app_capture_receipt(
    M11_GameViewState *state,
    const CSB_V1_BootStartupRuntimeAssetGateReceipt_PC34 *boot_gate)
{
    CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    CSB_V1_StartupFullRuntimeReceipt_PC34 full_runtime;
    CSB_V1_StartupCompleteSupportReceipt_PC34 complete_support;

    if (!state || !state->csbBootProfile ||
        !state->csbStartupRuntimeAssetSession || !boot_gate ||
        !boot_gate->valid || !boot_gate->real_asset_matched ||
        !boot_gate->rejects_fallback_sources) {
        return 0;
    }
    session = (CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    memset(&state->csbStartupReleaseAppCaptureReceipt, 0,
           sizeof(state->csbStartupReleaseAppCaptureReceipt));
    memset(&state->csbStartupReleaseLifecycleReceipt, 0,
           sizeof(state->csbStartupReleaseLifecycleReceipt));
    memset(&full_runtime, 0, sizeof(full_runtime));
    memset(&complete_support, 0, sizeof(complete_support));
    if (!csb_v1_boot_startup_full_runtime_receipt_from_session_pc34(
            session, &full_runtime)) {
        return 0;
    }
    /* The launch handoff is the boot-owned provenance boundary available to
     * M11. Bind its already verified asset gate to the opened source session;
     * per-frame delivery is still rejected unless the runtime lifecycle below
     * names the same generation and source tick. */
    state->csbStartupReleaseAppCaptureReceipt.valid = 1;
    state->csbStartupReleaseAppCaptureReceipt.complete_support_valid = 1;
    state->csbStartupReleaseAppCaptureReceipt.release_app_capture_ready = 1;
    state->csbStartupReleaseAppCaptureReceipt.title_phase_route_complete = 1;
    state->csbStartupReleaseAppCaptureReceipt.runtime_host_routes_ready = 1;
    state->csbStartupReleaseAppCaptureReceipt.draw_consumes_receipt_only = 1;
    state->csbStartupReleaseAppCaptureReceipt.input_consumes_receipt_only = 1;
    state->csbStartupReleaseAppCaptureReceipt.no_fallback_callbacks = 1;
    state->csbStartupReleaseAppCaptureReceipt.no_wrapper_fallback_routes = 1;
    state->csbStartupReleaseAppCaptureReceipt.real_startup_assets_bound = 1;
    complete_support.valid = 1;
    complete_support.real_asset_matched = 1;
    complete_support.no_legacy_wrappers = 1;
    complete_support.no_fallback_callbacks = 1;
    complete_support.no_wrapper_fallback_routes = 1;
    complete_support.real_startup_assets_bound = 1;
    complete_support.session_generation = full_runtime.session_generation;
    complete_support.title_runtime_phase_mask =
        CSB_V1_STARTUP_RUNTIME_TITLE_ALL_PHASES_PC34;
    complete_support.title_runtime_expected_phase_mask =
        CSB_V1_STARTUP_RUNTIME_TITLE_ALL_PHASES_PC34;
    complete_support.title_runtime_phase_hash_count =
        CSB_V1_STARTUP_RUNTIME_TITLE_SAMPLE_COUNT_PC34;
    if (!m11_csb_capture_title_phase_hashes_from_session(
            session, complete_support.title_runtime_phase_hashes,
            &complete_support.title_runtime_phase_hash)) {
        return 0;
    }
    /* Retire the old route-hash-derived title samples. M11 records the four
     * canonical C001 rasters through the verified session, leaving no legacy
     * wrapper or readiness flag able to impersonate PRESENTS/CHAOS/STRIKES. */
    state->csbStartupReleaseAppCaptureReceipt.title_runtime_phase_hash_count =
        CSB_V1_STARTUP_RUNTIME_TITLE_SAMPLE_COUNT_PC34;
    state->csbStartupReleaseAppCaptureReceipt.complete_support =
        complete_support;
    state->csbStartupReleaseAppCaptureReceipt.complete_support_hash =
        (uint32_t)boot_gate->real_asset_receipt_hash ?: 1u;
    state->csbStartupReleaseAppCaptureReceipt.runtime_host_gate_hash =
        full_runtime.playback_route_hash;
    state->csbStartupReleaseAppCaptureReceipt.title_runtime_phase_hash =
        complete_support.title_runtime_phase_hash;
    state->csbStartupReleaseAppCaptureReceipt.release_app_capture_hash =
        state->csbStartupReleaseAppCaptureReceipt.complete_support_hash ^
        state->csbStartupReleaseAppCaptureReceipt.title_runtime_phase_hash;
    for (int i = 0; i < CSB_V1_STARTUP_RUNTIME_TITLE_SAMPLE_COUNT_PC34; ++i) {
        state->csbStartupReleaseAppCaptureReceipt.title_runtime_phase_hashes[i] =
            complete_support.title_runtime_phase_hashes[i];
    }
    return state->csbStartupReleaseAppCaptureReceipt.release_app_capture_hash != 0u &&
           csb_v1_startup_release_lifecycle_advance_pc34(
               &state->csbStartupReleaseAppCaptureReceipt, 1u, NULL,
               &state->csbStartupReleaseLifecycleReceipt);
}

static int m11_csb_enter_fmtowns_game(M11_GameViewState *state,
                                      CSB_V1_FmtownsSwitchLanguage language)
{
    CSB_V1_FmtownsGameHandoffReceipt handoff;
    CSB_V1_FmtownsStartupState startup_state;
    CSB_V1_BootProfile *profile;
    CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    CSB_V1_BootStartupRuntimeAssetGateReceipt_PC34 gate;
    uint8_t entrance_track = 0u;

    if (!state || !state->csbBootProfile ||
        state->csbStartupRuntimeAssetSession ||
        !m11_csb_is_fmtowns_profile(
            (const CSB_V1_BootProfile *)state->csbBootProfile) ||
        !csb_v1_fmtowns_game_handoff_open(
            (const CSB_V1_BootProfile *)state->csbBootProfile, language,
            &handoff)) return 0;

    /* F31 CHTWE/CHTWJ reaches STARTUP1.C's F0435 load before ENTRANCE.C.
     * Bind the authenticated little-endian MINI.DAT party at that same
     * boundary.  This is not an Atari/Amiga GAMEBLOCK fallback: F0435 copies
     * the F7057-validated 4*319-byte M516_CHAMPIONS array directly, then
     * ENTRANCE.C F0806/F0807 opens the Prison doors around that live state. */
    profile = (CSB_V1_BootProfile *)state->csbBootProfile;
    memset(&startup_state, 0, sizeof(startup_state));
    if (!csb_v1_fmtowns_game_load_startup_state(&handoff, &startup_state) ||
        !csb_v1_fmtowns_game_apply_startup_state(&startup_state,
                                                  &profile->runtime)) {
        csb_v1_fmtowns_game_startup_state_free(&startup_state);
        return 0;
    }
    /* The candidate now owns every F0435 save part and C04 active-group
     * identity, so its dungeon pose is committed atomically instead of being
     * mixed with the bootstrap DUNGEON.DAT runtime. */

    session = (CSB_V1_StartupRuntimeAssetSession_PC34 *)calloc(1u,
        sizeof(*session));
    if (!session || !csb_v1_boot_startup_runtime_asset_session_open_pc34(
            (const CSB_V1_BootProfile *)state->csbBootProfile, session)) {
        free(session);
        return 0;
    }
    session->csbStartupPackageIdentity =
        state->csbStartupExpectedPackageIdentity;
    if (!state->csbFmtownsSwitchReceipt.valid) {
        csb_v1_boot_startup_runtime_asset_session_release_pc34(session);
        free(session);
        return 0;
    }
    session->fmtowns_standalone_title_handoff_verified = 1;
    session->fmtowns_standalone_title_handoff_hash =
        handoff.executable_fnv1a ^ state->csbFmtownsSwitchReceipt.executable_fnv1a ^
        session->generation;
    if (session->fmtowns_standalone_title_handoff_hash == 0u)
        session->fmtowns_standalone_title_handoff_hash = 1u;
    session->playback.stage = CSB_V1_STARTUP_PLAYBACK_STAGE_ENTRANCE_PC34;
    session->playback.entrance_music_active = 1;
    session->playback.no_fallback_routes = 1;
    state->csbStartupRuntimeAssetSession = session;
    gate = state->csbStartupAssetGateReceipt;
    /* The F31 title is owned by ANIMTW rather than TITLE.C, so the launch
     * gate intentionally has no PC title-session receipt. CHTWE/CHTWJ is the
     * authoritative C03_GAME transition: combine its exact executable
     * identity with the just-opened C001--C005/C017/C040 session instead of
     * manufacturing a PC34 receipt. */
    if ((!gate.valid || !gate.real_asset_matched ||
         !gate.rejects_fallback_sources) &&
        session->valid && session->real_asset_matched &&
        session->full_startup_ready && handoff.valid &&
        handoff.executable_verified && handoff.language_matches_profile &&
        handoff.game_program_is_c03_game) {
        memset(&gate, 0, sizeof(gate));
        gate.valid = 1;
        gate.real_asset_matched = 1;
        gate.asset_ownership_valid = 1;
        gate.session_state_valid = 1;
        gate.title_assets_owned = 1;
        gate.entrance_assets_owned = 1;
        gate.hud_assets_owned = session->hud_assets_bound;
        gate.rejects_fallback_sources = 1;
        gate.real_asset_receipt_hash = handoff.executable_fnv1a ^
            session->generation;
        gate.source_evidence = handoff.source_evidence;
    }
    if (!m11_csb_bind_release_app_capture_receipt(state, &gate)) {
        csb_v1_boot_startup_runtime_asset_session_release_pc34(session);
        free(session);
        state->csbStartupRuntimeAssetSession = NULL;
        return 0;
    }
    state->csbFmtownsGameHandoffReceipt = handoff;
    /* SWITCHTW exits before CHTWE/CHTWJ enters F0806. ENTRANCE.C:440 then
     * replaces C26_SWITCH with the Game executable's C28_ENTRANCE_CSB.
     * Keeping C26 made C004 predominantly red. */
    if (handoff.entrance_palette_verified) {
        int color;
        for (color = 0; color < 16; ++color) {
            state->csbFmtownsEntrancePaletteRgb6[color][0] =
                handoff.entrance_palette_rgb6[color][0];
            state->csbFmtownsEntrancePaletteRgb6[color][1] =
                handoff.entrance_palette_rgb6[color][1];
            state->csbFmtownsEntrancePaletteRgb6[color][2] =
                handoff.entrance_palette_rgb6[color][2];
        }
        state->csbFmtownsEntrancePaletteValid = 1;
    } else {
        state->csbFmtownsEntrancePaletteValid = 0;
        memset(state->csbFmtownsEntrancePaletteRgb6, 0,
               sizeof(state->csbFmtownsEntrancePaletteRgb6));
    }
    if (handoff.dungeon_palettes_verified) {
        memcpy(state->csbFmtownsDungeonPaletteRgb6,
               handoff.dungeon_palette_rgb6,
               sizeof(state->csbFmtownsDungeonPaletteRgb6));
        state->csbFmtownsDungeonPalettesValid = 1;
    } else {
        state->csbFmtownsDungeonPalettesValid = 0;
        memset(state->csbFmtownsDungeonPaletteRgb6, 0,
               sizeof(state->csbFmtownsDungeonPaletteRgb6));
    }
    state->csbFmtownsGameMusicSelectedTrack = -1;
    state->csbFmtownsGameMusicPlayingTrack = -1;
    state->csbFmtownsGameMusicCountdown = -1;
    state->csbFmtownsGameMusicPending = 0;
    /* F31 does not inherit the standalone TITLE.ANM soundtrack. After
     * CHTWE/CHTWJ's F0435 load, ENTRANCE.C F0806/F0807 calls
     * F0741(C0_MUSIC_ENTRANCE); the admitted Game executable maps that to
     * physical CD-DA track 02. Dispatch only that F31-owned Red Book span;
     * a missing or malformed CUE/IMG remains silent rather than borrowing
     * another platform's music. */
    if (state->dm1MusicOn &&
        csb_v1_fmtowns_game_entrance_music_track(&handoff, &entrance_track)) {
        m11_csb_dispatch_fmtowns_cdda_track(state, entrance_track);
    }
    m11_csb_release_fmtowns_switch(state);
    /* ReDMCSB STARTUP1.C enters F0441 before its F0435 loop. The FM Towns
     * game executable therefore starts on the closed C004 entrance page;
     * it must not replay the standalone TITLE.ANM or PC TITLE.C timeline. */
    state->csbState.startup_title_active = 0;
    state->csbState.startup_title_frame = 0;
    state->csbState.startup_title_source_step = 0;
    state->csbState.startup_entrance_active = 1;
    /* CHTWE/CHTWJ reaches ENTRANCE.C F0807's interactive C004 wait after
     * the separate ANIMTW/SWITCHTW programs have returned. It is not the
     * PC TITLE.C pre-Entrance phase, so make only the source wait stage
     * eligible for the first Prison command. */
    state->csbState.startup_entrance_source_step =
        csb_v1_startup_entrance_wait_stage_pc34();
    state->csbState.startup_entrance_dismissed = 0;
    state->csbState.startup_entrance_credits_active = 0;
    state->csbState.startup_entrance_credits_remaining_ticks = 0;
    state->csbState.startup_entrance_opening_active = 0;
    state->csbState.startup_entrance_opening_delay_ticks = 0;
    state->csbState.startup_entrance_opening_step = 0;
    state->csbState.startup_entrance_pending_command = 0;
    state->csbState.startup_entrance_frame = 0;
    return 1;
}

static int m11_csb_release_delivery_receipt_current(
    const M11_GameViewState *state)
{
    const CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    const CSB_V1_StartupReleaseAppCaptureReceipt_PC34 *release;
    const CSB_V1_StartupReleaseLifecycleReceipt_PC34 *lifecycle;

    if (!state || !state->csbStartupRuntimeAssetSession) {
        return 0;
    }
    session = (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    release = &state->csbStartupReleaseAppCaptureReceipt;
    lifecycle = &state->csbStartupReleaseLifecycleReceipt;
    return session->valid && release->valid && lifecycle->valid &&
           release->complete_support.session_generation == session->generation &&
           lifecycle->session_generation == session->generation &&
           lifecycle->complete_support_hash == release->complete_support_hash &&
           lifecycle->title_phase_hash == release->title_runtime_phase_hash &&
           lifecycle->runtime_route_hash == release->runtime_host_gate_hash &&
           lifecycle->release_capture_hash == release->release_app_capture_hash;
}

/* CSBWin can supply the canonical Atari GRAPHICS.DAT/DUNGEON.DAT pair without
 * ANIMATE.SCR/DAT. C001-C005 are still original startup records, while item
 * 40 has no image height and cannot satisfy the separate PC3.4 C040 HUD
 * contract. Admit only this source-owned title/Entrance session. The normal
 * release receipt and the dungeon handoff remain unavailable until a real
 * CSBWin runtime HUD owner has been recovered. */
static int m11_csb_csbwin_graphics_startup_only_eligible(
    const CSB_V1_BootProfile *profile,
    const CSB_V1_StartupRuntimeAssetSession_PC34 *session)
{
    if (!profile || !session ||
        (profile->variant_id != CSB_V1_VARIANT_ST20_EN &&
         profile->variant_id != CSB_V1_VARIANT_ST21_EN) ||
        !session->valid || !session->real_asset_matched ||
        !session->full_startup_ready || !session->title_presents_ready ||
        !session->title_chaos_ready || !session->title_strikes_back_ready ||
        !session->entrance_assets_ready || !session->door_assets_ready ||
        session->hud_assets_bound || session->surfaces.hud_surfaces_ready) {
        return 0;
    }
    return session->surfaces.surfaces[
               CSB_V1_STARTUP_RUNTIME_SURFACE_TITLE_PC34].valid &&
        session->surfaces.surfaces[
               CSB_V1_STARTUP_RUNTIME_SURFACE_OPENING_LEFT_PC34].valid &&
        session->surfaces.surfaces[
               CSB_V1_STARTUP_RUNTIME_SURFACE_OPENING_RIGHT_PC34].valid &&
        session->surfaces.surfaces[
               CSB_V1_STARTUP_RUNTIME_SURFACE_ENTRANCE_SCREEN_PC34].valid &&
        session->surfaces.surfaces[
               CSB_V1_STARTUP_RUNTIME_SURFACE_ENTRANCE_CREDITS_PC34].valid;
}

static int m11_csb_dsa_save_runtime_viewport_current(
    const M11_GameViewState *state)
{
    const CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    const CSB_V1_CSBWinDSASaveRuntimeHandoffReceipt_PC34 *receipt;
    const CSB_V1_BootProfile *profile;

    if (!state || !state->csbDsaSaveRuntimeRouteRequired) {
        return state != NULL;
    }
    if (state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !m11_csb_startup_package_identity_current(state) ||
        !state->csbBootProfile || !state->csbStartupRuntimeAssetSession) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    session = (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    receipt = &state->csbDsaSaveRuntimeReceipt;
    /* A real LOADSAVE.C F0435 resume has no startup terminal transaction.
     * Its current dungeon identity and loaded GAMEBLOCK are the source-owned
     * admission boundary; do not demand a title-generated DSA receipt. */
    if (session->direct_resume_loaded) {
        return profile->assets_verified && profile->graphics_verified &&
            profile->dungeon_verified && profile->runtime.dungeon_handle &&
            strlen(profile->dungeon_md5) == 32u && session->valid &&
            session->real_asset_matched && session->hud_assets_bound &&
            session->csbStartupPackageIdentity != 0u;
    }
    return receipt->valid && receipt->source_admission_consumed &&
           receipt->save_handoff_consumed &&
           receipt->dungeon_identity_current &&
           receipt->startup_session_consumed &&
           receipt->runtime_chain_consumed &&
           receipt->save_fnv1a != 0u && receipt->gameblock_fnv1a != 0u &&
           receipt->source_admission_hash != 0u && receipt->handoff_hash != 0u &&
           receipt->imported_action_count > 0 &&
           profile->assets_verified && profile->dungeon_verified &&
           strlen(profile->dungeon_md5) == 32u && session->valid &&
           session->real_asset_matched && session->full_startup_ready &&
           session->rejects_legacy_wrappers &&
           receipt->startup_session_generation == session->generation &&
           receipt->startup_source_tick == session->source_tick &&
           receipt->runtime_game_time == profile->runtime.game_time &&
           strcmp(receipt->dungeon_md5, profile->dungeon_md5) == 0;
}

static int m11_csb_dsa_restored_timer_transaction_current(
    const M11_GameViewState *state)
{
    const CSB_V1_BootProfile *profile;
    const CSB_V1_StartupRuntimeAssetSession_PC34 *session;

    if (!state || !state->csbDsaRestoredTimerTransactionRequired) {
        return state != NULL;
    }
    if (!m11_csb_dsa_save_runtime_viewport_current(state) ||
        !state->csbBootProfile || !state->csbStartupRuntimeAssetSession) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    session = (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    return csb_v1_csbwin_dsa_restored_timer_receipt_current_pc34(
        profile, &state->csbDsaSaveRuntimeReceipt, session,
        &state->csbDsaRestoredTimerTransactionReceipt);
}

static int m11_csb_dsa_overlay_material_current(
    const M11_GameViewState *state)
{
    const CSB_V1_StartupRuntimeAssetSession_PC34 *session;
    const CSB_V1_BootProfile *profile;

    if (!state || !state->csbDsaSaveRuntimeRouteRequired) {
        return 1;
    }
    if (!m11_csb_dsa_save_runtime_viewport_current(state)) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    session = (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    return profile->graphics_verified && profile->graphics_path[0] != '\0' &&
           session->csbgraphics_palette_receipt_ready &&
           session->csbgraphics_palette_receipt_hash != 0u;
}

static int m11_csb_original_save_runtime_receipt_current(
    const M11_GameViewState *state)
{
    if (!state || !state->csbOriginalSaveRuntimeReceiptRequired) {
        return state != NULL;
    }
    if (state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !state->csbBootProfile) {
        return 0;
    }
    return csb_v1_boot_original_save_runtime_receipt_current_pc34(
        (const CSB_V1_BootProfile *)state->csbBootProfile,
        &state->csbOriginalSaveRuntimeReceipt);
}

int M11_GameView_BindCSBDSASaveRuntimeHandoff(
    M11_GameViewState *state,
    const CSB_V1_CSBWinDSASaveRuntimeHandoffReceipt_PC34 *receipt)
{
    if (!state) {
        return 0;
    }
    state->csbDsaSaveRuntimeRouteRequired = 1;
    memset(&state->csbDsaSaveRuntimeReceipt, 0,
           sizeof(state->csbDsaSaveRuntimeReceipt));
    state->csbDsaRestoredTimerTransactionRequired = 0;
    memset(&state->csbDsaRestoredTimerTransactionReceipt, 0,
           sizeof(state->csbDsaRestoredTimerTransactionReceipt));
    if (!receipt) {
        return 0;
    }
    state->csbDsaSaveRuntimeReceipt = *receipt;
    if (!m11_csb_dsa_save_runtime_viewport_current(state)) {
        memset(&state->csbDsaSaveRuntimeReceipt, 0,
               sizeof(state->csbDsaSaveRuntimeReceipt));
        return 0;
    }
    return 1;
}

int M11_GameView_CommitCSBDSARestoredTimerOutcome(
    M11_GameViewState *state,
    const CSB_V1_CSBWinDSARestoredTimerExecutionReceipt_PC34 *receipt)
{
    CSB_V1_CSBWinDSARestoredTimerExecutionReceipt_PC34 candidate;

    if (!state || !receipt || !state->csbBootProfile ||
        !state->csbStartupRuntimeAssetSession ||
        !m11_csb_dsa_save_runtime_viewport_current(state)) {
        return 0;
    }
    candidate = *receipt;
    state->csbDsaRestoredTimerTransactionRequired = 1;
    state->csbDsaRestoredTimerTransactionReceipt = candidate;
    if (!m11_csb_dsa_restored_timer_transaction_current(state)) {
        state->csbDsaRestoredTimerTransactionRequired = 0;
        memset(&state->csbDsaRestoredTimerTransactionReceipt, 0,
               sizeof(state->csbDsaRestoredTimerTransactionReceipt));
        return 0;
    }
    return 1;
}

int M11_GameView_ExecuteCSBDSARestoredTimer(
    M11_GameViewState *state,
    const CSB_V1_DSAFilterLocation *location,
    uint16_t queue_slot)
{
    CSB_V1_CSBWinDSARestoredTimerExecutionReceipt_PC34 receipt;
    CSB_V1_BootProfile *profile;
    CSB_V1_StartupRuntimeAssetSession_PC34 *session;

    if (!state || !location || !state->active ||
        !m11_csb_dsa_save_runtime_viewport_current(state)) {
        return 0;
    }
    profile = (CSB_V1_BootProfile *)state->csbBootProfile;
    session = (CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession;
    memset(&receipt, 0, sizeof(receipt));
    /* CSBWin owns TimerQueue ordering and DSA action selection.  M11 only
     * transports the caller-named due slot into that authenticated runner. */
    if (!csb_v1_csbwin_dsa_execute_restored_timer_pc34(
            profile, &state->csbDsaSaveRuntimeReceipt, session, location,
            queue_slot, &receipt) ||
        !M11_GameView_CommitCSBDSARestoredTimerOutcome(state, &receipt)) {
        return 0;
    }
    return 1;
}

/* M11's ordinary DM1 launch path creates its query model while it reads the
 * selected DUNGEON.DAT.  CSB correctly bypasses that path: F0435 has already
 * made the verified CSB image live in profile->runtime.dungeon_handle before
 * this M11 receipt is applied.  The bypass used to leave state->world and the
 * mirror catalogue empty, which in turn made native Atari/Amiga C127 mirrors
 * unreachable even though their C03 runtime was live.
 *
 * Build a second, read-only M11 query model from that *same materialized and
 * hash-verified DUNGEON.DAT*.  It is deliberately not an alternate CSB
 * runtime: movement, save/load, Thing mutations, timing, and graphics remain
 * owned by profile->runtime and the platform-specific render route.  M11
 * consumes this model solely for static dungeon queries such as the original
 * mirror-text catalogue and front-wall hit testing.  Fresh CSB launch only:
 * a save image may own later mutable dungeon state and must not be projected
 * onto the base-package model as though it were current.
 *
 * ReDMCSB LOADSAVE.C F0435 lines 1929-1944 loads G0278/G0277 before C03 can
 * consume them; DUNGEON.C F0173/F0174 selects the current map from that live
 * source image. */
static int m11_csb_bind_verified_dungeon_world_snapshot(
    M11_GameViewState *state, const CSB_V1_BootProfile *profile,
    int direct_save_requested)
{
    const CSB_V1_DungeonData *source;
    struct ChampionMirrorCatalog_Compat catalogue;
    struct GameWorld_Compat world;
    uint32_t seed;
    int world_loaded;

    if (!state || !profile || direct_save_requested ||
        state->world.dungeon || state->world.things ||
        !profile->dungeon_verified || !profile->dungeon_path[0] ||
        !profile->runtime.dungeon_handle ||
        profile->runtime.dungeon_handle != csb_v1_dungeon_get_current()) {
        return 0;
    }
    source = profile->runtime.dungeon_handle;
    if (!source->raw_data || source->raw_size <= 0 ||
        source->raw_size > INT_MAX || source->level_count <= 0) {
        return 0;
    }

    /* The source header's ornament seed is the only seed admitted to this
     * non-authoritative query model.  Its RNG is never advanced by CSB input. */
    seed = (uint32_t)source->ornament_random_seed;
    memset(&world, 0, sizeof(world));
    /* CSB's boot reader has already authenticated and decoded the dungeon
     * bytes into this source-owned handle.  Re-open neither a package image
     * (STX/ADF) nor an archive virtual path here: the generic file loader
     * understands DUNGEON.DAT, not the container.  Building the query mirror
     * from these exact bytes keeps the handoff source-faithful and entirely
     * in memory for every supported CSB platform. */
    world_loaded = F0882_WORLD_InitFromDungeonDatBuffer_Compat(
        source->raw_data, source->raw_size, seed, &world);
    if (!world_loaded) {
        /* F0882 releases its local allocations on a failed parse.  Its
         * caller-visible struct can still contain those retired addresses,
         * so never route this branch through F0883 a second time. */
        return 0;
    }
    if (!world.dungeon || !world.things || !world.ownsDungeon ||
        world.dungeon->header.mapCount != (uint8_t)source->level_count) {
        F0883_WORLD_Free_Compat(&world);
        return 0;
    }

    memset(&catalogue, 0, sizeof(catalogue));
    if (F0652_CHAMPION_BuildMirrorCatalog_Compat(world.things,
                                                  &catalogue) <= 0) {
        F0883_WORLD_Free_Compat(&world);
        return 0;
    }
    state->world = world;
    state->mirrorCatalog = catalogue;
    state->mirrorCatalogAvailable = 1;
    return 1;
}

static int m11_csb_fmtowns_load_user_save_path(M11_GameViewState *state,
                                               const char *path);

static int m11_csb_apply_boot_runtime_receipt(
    M11_GameViewState *state,
    const M11_GameLaunchSpec *spec,
    const CSB_V1_BootStartupRuntimeReceipt_PC34 *receipt)
{
    uint32_t package_identity = 2166136261u;
    const char *identity_text;
    int resolved_presentation_mode;
    if (!state || !spec || !receipt || !receipt->profile) {
        return 0;
    }
    for (identity_text = receipt->profile->graphics_md5;
         identity_text && *identity_text; ++identity_text) {
        package_identity = (package_identity ^ (unsigned char)*identity_text) * 16777619u;
    }
    for (identity_text = receipt->profile->dungeon_md5;
         identity_text && *identity_text; ++identity_text) {
        package_identity = (package_identity ^ (unsigned char)*identity_text) * 16777619u;
    }
    /* Keep this in sync with the CSB V2.2 material admission decision. A
     * requested V2.2 mode resolves to V2.1 until original-CSB material is
     * decoded and pixel-verified; M11 must not restore the raw request. */
    csb_v2_presentation_mode_set_m12(spec->presentationMode);
    switch (csb_v2_presentation_mode_get()) {
        case CSB_V2_PM_V20_FILTERED:
            resolved_presentation_mode = M12_PRESENTATION_V20_FILTERED;
            break;
        case CSB_V2_PM_V21_UPSCALED:
            resolved_presentation_mode = M12_PRESENTATION_V21_UPSCALED;
            break;
        case CSB_V2_PM_V22_MODERN:
            resolved_presentation_mode = M12_PRESENTATION_V22_MODERN;
            break;
        default:
            resolved_presentation_mode = M12_PRESENTATION_V1_ORIGINAL;
            break;
    }
    /* V2.0 is a source-preserving filter route.  Its indexed and RGBA
     * filters are applied to presentation copies in main_loop_m11.c; it must
     * not initialise the smooth camera/runtime because that would alter the
     * source-owned 320x200 page before capture.  The V2 runtime therefore
     * starts with V2.1, whose upscale/smooth presentation contract owns it. */
    csb_v2_runtime_cleanup();
    if (resolved_presentation_mode == M12_PRESENTATION_V21_UPSCALED ||
        resolved_presentation_mode == M12_PRESENTATION_V22_MODERN) {
        csb_v2_runtime_init(
            resolved_presentation_mode == M12_PRESENTATION_V22_MODERN ? 4 : 2);
        csb_v2_runtime_bind_to_v1(&receipt->profile->runtime);
    }
    state->active = 1;
    state->startedFromLauncher = 1;
    state->sourceKind = M11_GAME_SOURCE_CSB_BOOT;
    snprintf(state->bootAssetMd5,
             sizeof(state->bootAssetMd5),
             "%s",
             receipt->boot_asset_md5);
    state->presentationMode = resolved_presentation_mode;
    state->presentationWidth = spec->presentationWidth;
    state->presentationHeight = spec->presentationHeight;
    snprintf(state->title,
             sizeof(state->title),
             "%s",
             receipt->title[0]
                 ? receipt->title
                 : (spec->title ? spec->title : "CHAOS STRIKES BACK"));
    snprintf(state->sourceId,
             sizeof(state->sourceId),
             "%s",
             receipt->source_id[0]
                 ? receipt->source_id
                 : (spec->sourceId ? spec->sourceId : "csb"));
    snprintf(state->dungeonPath,
             sizeof(state->dungeonPath),
             "%s",
             receipt->dungeon_path);
    /* ReDMCSB ENTRANCE.C F0806 hands dungeon and graphics globals to the
     * CSB runtime before the first dungeon frame. M11's shared V1 chrome and
     * font paths still use the asset loader, so bind them from the verified
     * CSB boot receipt. */
    /* Amiga CSB is DMCSB2/IMG1, not PC3.4's GRAPHICS.DAT container.  It has
     * its own authenticated direct decoder in m11_csb_present_amiga_runtime_surface.
     * Do not let the shared PC loader claim the file first: an apparently
     * successful PC34 header bind would make unrelated HUD/font consumers
     * treat a native Amiga session as PC material. */
    if (receipt->bind_graphics_to_runtime_asset_loader &&
        receipt->graphics_path[0] != '\0' &&
        m11_csb_is_fmtowns_profile(receipt->profile) &&
        ((receipt->profile->fmtowns_graphics_bytes &&
          receipt->profile->fmtowns_graphics_size <= (size_t)LONG_MAX)
             ? M11_AssetLoader_InitCsbFmtownsFromBuffer(
                   &state->assetLoader,
                   receipt->profile->fmtowns_graphics_bytes,
                   (long)receipt->profile->fmtowns_graphics_size,
                   receipt->graphics_path)
             : M11_AssetLoader_InitCsbFmtownsFromFile(
                   &state->assetLoader, receipt->graphics_path))) {
        /* F31 GRAPHICS.DAT has the PC-style 0x8001 table envelope but IMG2
         * record streams. ReDMCSB IMAGE2.C F0689 is its decoder; do not let
         * the shared PC IMG3 loader claim the matching header. */
        state->assetsAvailable = 1;
    } else if (receipt->bind_graphics_to_runtime_asset_loader &&
        receipt->graphics_path[0] != '\0' &&
        !m11_csb_is_amiga_profile(receipt->profile) &&
        M11_AssetLoader_Init(&state->assetLoader, receipt->graphics_path)) {
        state->assetsAvailable = 1;
        if (receipt->load_original_font_from_graphics) {
            M11_Font_Init(&state->originalFont);
            if (M11_Font_LoadFromGraphicsDat(
                    &state->originalFont,
                    state->assetLoader.fileState,
                    state->assetLoader.runtimeState)) {
                state->originalFontAvailable = 1;
            }
        }
    }
    if (!state->assetsAvailable && m11_csb_is_amiga_profile(receipt->profile) &&
        M11_AssetLoader_InitCsbAmigaFromFile(&state->assetLoader,
                                             receipt->graphics_path)) {
        /* Native CSB Amiga IMG1 records are now cached by their own decoder.
         * The loader has no PC34 file/runtime state, so later consumers can
         * use only these authenticated Amiga pixels. */
        state->assetsAvailable = 1;
    }
    if (!state->assetsAvailable &&
        (receipt->profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
         receipt->profile->variant_id == CSB_V1_VARIANT_ST21_EN) &&
        M11_AssetLoader_InitDecodedOnly(&state->assetLoader,
                                        receipt->graphics_path)) {
        /* Atari ST GRAPHICS.DAT has a separate C232/022e consumer. */
        state->assetsAvailable = 1;
        /* CSBWin's TAG001c6e always binds raw M653 item 0x822d before
         * TextToViewport can draw the selected-inventory labels or values.
         * A malformed/missing source payload leaves that text undrawn; do
         * not inherit the PC3.4 font or use Firestaff's diagnostic glyphs. */
        state->originalFontAvailable = m11_csb_load_atari_st_m653_font(
            receipt->graphics_path, &state->originalFont);
    }
    /* Some ST package revisions happen to pass the shared table-envelope
     * probe before their native decoder is selected.  M653 is nevertheless
     * CSBWin's raw C822D record, so resolve it independently of that drawable
     * loader choice and never retain a foreign PC font. */
    if ((receipt->profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
         receipt->profile->variant_id == CSB_V1_VARIANT_ST21_EN) &&
        !state->originalFontAvailable) {
        state->originalFontAvailable = m11_csb_load_atari_st_m653_font(
            receipt->graphics_path, &state->originalFont);
    }
    state->csbBootProfile = receipt->profile;
    state->csbStartupAssetGateReceipt = receipt->startup_asset_gate;
    /* Bind the query-only dungeon/mirror model before a native title or
     * APPB route reaches C03.  A supplied save retains F0435 ownership and
     * intentionally has no base-package projection here. */
    if (!spec->savePath || !spec->savePath[0]) {
        (void)m11_csb_bind_verified_dungeon_world_snapshot(
            state, receipt->profile, 0);
    }
    if (spec->savePath && spec->savePath[0] != '\0') {
        CSB_V1_BootOriginalSaveRuntimeReceipt_PC34 original_save_receipt;

        if (m11_csb_is_fmtowns_profile(receipt->profile)) {
            CSB_V1_FmtownsSwitchLanguage language =
                receipt->profile->variant_id == CSB_V1_VARIANT_FMTOWNS_EN
                    ? CSB_FMTOWNS_SWITCH_ENGLISH
                    : CSB_FMTOWNS_SWITCH_JAPANESE;

            /* The boot layer has already applied F31's complete native
             * F0435 transaction.  Bind the source Game program's receipt
             * and then reload the same verified slot through M11's F31
             * handoff so its retained game/portrait state owns the live
             * view.  This intentionally bypasses TITLE.ANM/SWITCHTW's UI,
             * matching direct LOAD's CHTWE/CHTWJ -> F0435 -> GAMELOOP path.
             * ReDMCSB STARTUP1.C:163; LOADSAVE.C F0435. */
            state->csbStartupExpectedPackageIdentity =
                package_identity ? package_identity : 1u;
            if (!m11_csb_bind_fmtowns_switch(state, language) ||
                !m11_csb_enter_fmtowns_game(state, language) ||
                !m11_csb_fmtowns_load_user_save_path(state, spec->savePath)) {
                m11_set_status(state, "CSB FM TOWNS", "SAVE HANDOFF FAILED");
                return 0;
            }
            state->csbState.startup_title_active = 0;
            state->csbState.startup_entrance_active = 0;
            state->csbState.startup_entrance_dismissed = 1;
            state->csbState.startup_entrance_credits_active = 0;
            state->csbState.startup_entrance_opening_active = 0;
            return 1;
        }

        /* The boot handoff has already admitted this path through the
         * original-container gate. Bind its F0435 provenance to the M11
         * session as well, so an Atari/Amiga direct resume has the same
         * stale-file protection as an F9 resume. This second source-owned
         * F0435 read also captures a CSBGAMEx.BAK recovery after it has
         * replaced the damaged selected slot. */
        memset(&original_save_receipt, 0, sizeof(original_save_receipt));
        if (!csb_v1_boot_runtime_load_original_save_receipt_pc34(
                receipt->profile, spec->savePath,
                &original_save_receipt)) {
            return 0;
        }
        state->csbOriginalSaveRuntimeReceipt = original_save_receipt;
        state->csbOriginalSaveRuntimeReceiptRequired = 1;

        /* CSBWin's stock Game/CSB package carries the original Atari ST
         * MEDIA332 pair.  F0435 has already restored its live world above;
         * it must enter the native ST viewport handoff directly, not try to
         * open the unrelated PC3.4 C040 HUD session below.  The latter has
         * no owner in the ST package and used to reject an otherwise fully
         * authenticated CSBWin resume from both the menu and --game csb.
         *
         * ReDMCSB LOADSAVE.C F0435 returns to GAMELOOP after a successful
         * load; ANIM.C's title path is bypassed for the same reason. */
        if (receipt->receipts.handoff.direct_resume_loaded &&
            (receipt->profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
             receipt->profile->variant_id == CSB_V1_VARIANT_ST21_EN)) {
            ((CSB_V1_BootProfile *)state->csbBootProfile)->runtime.state =
                CSB_STATE_GAME;
            state->csbStartupExpectedPackageIdentity =
                package_identity ? package_identity : 1u;
            m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
            state->csbState.startup_title_active = 0;
            state->csbState.startup_entrance_active = 0;
            state->csbState.startup_entrance_dismissed = 1;
            state->csbState.startup_entrance_credits_active = 0;
            state->csbState.startup_entrance_opening_active = 0;
            state->csbAtariStRuntimeHandoffComplete = 1;
            return 1;
        }

        /* ReDMCSB LOADSAVE.C F0435 restores the GAMEBLOCK and enters the
         * live loop.  A valid original resume must not be routed back through
         * the selected platform's title program: on ST that used to replay
         * ANIMATE.SCR despite MINI.DAT already being live.  The same rule
         * applies to the Amiga and FM Towns native title paths. */
        if (receipt->receipts.handoff.direct_resume_loaded) {
            /* F0435 returns to the live GAMELOOP, rather than leaving the
             * boot profile in its title-program state.  The platform-native
             * C232/C0128 consumers below require that same post-load state
             * as a normal ANIMATE.SCR -> GAME hand-off. */
            ((CSB_V1_BootProfile *)state->csbBootProfile)->runtime.state =
                CSB_STATE_GAME;
            /* Dynamic C232/F0128 records are package-scoped just like the
             * normal Atari hand-off below.  A direct F0435 load bypasses
             * ANIMATE.SCR, not GRAPHICS.DAT provenance. */
            state->csbStartupExpectedPackageIdentity =
                package_identity ? package_identity : 1u;
            m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
            state->csbState.startup_title_active = 0;
            state->csbState.startup_entrance_active = 0;
            state->csbState.startup_entrance_dismissed = 1;
            state->csbState.startup_entrance_credits_active = 0;
            state->csbState.startup_entrance_opening_active = 0;
            if (receipt->profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
                receipt->profile->variant_id == CSB_V1_VARIANT_ST21_EN) {
                state->csbAtariStRuntimeHandoffComplete = 1;
            }
            return 1;
        }
    }
    if (receipt->load_original_font_from_graphics) {
        unsigned char *font_pixels = NULL;
        int font_width = 0;
        int font_height = 0;
        CSB_V1_StartupGraphicDecodeReceipt_PC34 font_receipt;

        memset(&font_receipt, 0, sizeof(font_receipt));
        if (m11_csb_is_fmtowns_profile(receipt->profile)) {
            /* ReDMCSB TEXT.C:2019-2022 reads F31 M653 with
             * NOT_EXPANDED. Its 768 source bytes must never be sent through
             * IMG2, which is reserved for drawable F31 records. */
            state->originalFontAvailable =
                receipt->profile->fmtowns_graphics_bytes &&
                receipt->profile->fmtowns_graphics_size != 0u
                    ? m11_csb_load_fmtowns_m653_font_buffer(
                          receipt->profile->fmtowns_graphics_bytes,
                          receipt->profile->fmtowns_graphics_size,
                          &state->originalFont)
                    : m11_csb_load_fmtowns_m653_font(
                          receipt->profile->graphics_path,
                          &state->originalFont);
        }
        /* ReDMCSB DEFS.H M653 resolves to C695 for the PC3.4 CSB media.
         * Do not let the DM1-oriented generic loader define CSB glyphs. */
        if (!state->originalFontAvailable &&
            !m11_csb_is_amiga_profile(receipt->profile) &&
            csb_v1_boot_decode_graphics_dat_asset_pc34(
                receipt->profile->graphics_path, 695u, &font_pixels,
                &font_width, &font_height, &font_receipt) &&
            font_receipt.valid &&
            M11_Font_LoadFromIndexedPixels(&state->originalFont, 695,
                                            font_pixels, font_width,
                                            font_height)) {
            state->originalFontAvailable = 1;
        }
        free(font_pixels);
    }
    if (receipt->profile->swoosh_source_bound) {
        (void)M11_GameView_SetCsbStartupSwooshSource(
            state, receipt->profile->swoosh_source_bytes,
            (int)sizeof(receipt->profile->swoosh_source_bytes),
            receipt->profile->swoosh_source_fnv1a);
    } else {
        /* A new package without authenticated audio must not inherit an
         * earlier package's intro buffer. */
        (void)M11_GameView_SetCsbStartupSwooshSource(state, NULL, 0, 0u);
    }
    if (receipt->profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
        receipt->profile->variant_id == CSB_V1_VARIANT_ST21_EN) {
        /* The Atari package has an original ANIMATE.SCR/DAT startup program,
         * not PC34 TITLE.C assets.  Do not attempt to open the PC34 surface
         * session: it rejects the verified ST GRAPHICS.DAT before M11 gets a
         * chance to show the real animation.  ANIM.C crosses into the
         * separately-bound C232/Viewport runtime only at its final source
         * VBlank (m11_csb_complete_atari_st_runtime_handoff). */
        state->csbStartupExpectedPackageIdentity =
            package_identity ? package_identity : 1u;
        m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
        m11_csb_startup_init_state_receipt_to_m11(
            state, &receipt->receipts.init_state);
        state->csbState.startup_title_active = 1;
        state->csbState.startup_entrance_active = 0;
        state->csbAtariStAnimationVbl = 0u;
        state->csbAtariStAnimationVblRemainder = 0u;
        csb_v1_atari_st_vblank_init(&state->csbAtariStVBlank,
            m11_csb_atari_st_vblank_palette_start,
            m11_csb_atari_st_vblank_original_handler, state);
        state->csbAtariStAnimationClockStarted = 0;
        state->csbAtariStAnimationFrameBound = 0;
        state->csbAtariStAnimationEndVbl = 0u;
        state->csbAtariStRuntimeHandoffComplete = 0;
        if (m11_csb_prepare_atari_st_animation_handoff(state)) {
            return 1;
        }
        /* CSBWin's standard package can retain the authentic ST
         * GRAPHICS.DAT/DUNGEON.DAT pair while omitting the optional Atari
         * ANIMATE.SCR/DAT program.  Continue below through the verified
         * GRAPHICS.DAT startup records; do not fake an Atari animation. */
    }
    if (m11_csb_is_amiga_a35m_profile(receipt->profile)) {
        state->csbStartupExpectedPackageIdentity =
            package_identity ? package_identity : 1u;
        m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
        m11_csb_startup_init_state_receipt_to_m11(
            state, &receipt->receipts.init_state);
        state->csbState.startup_title_active = 1;
        state->csbState.startup_entrance_active = 0;
        if (m11_csb_prepare_amiga_a35m_appb_selection(state)) return 1;
        m11_set_status(state, "CSB AMIGA", "A35M APPB DECODE FAILED");
        return 0;
    }
    if (m11_csb_is_amiga_a35e_profile(receipt->profile)) {
        state->csbStartupExpectedPackageIdentity =
            package_identity ? package_identity : 1u;
        m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
        m11_csb_startup_init_state_receipt_to_m11(
            state, &receipt->receipts.init_state);
        if (m11_csb_complete_amiga_a35e_direct_handoff(state)) return 1;
        m11_set_status(state, "CSB AMIGA", "A35E C03 HANDOFF FAILED");
        return 0;
    }
    if (m11_csb_is_amiga_a31e_profile(receipt->profile)) {
        state->csbStartupExpectedPackageIdentity =
            package_identity ? package_identity : 1u;
        m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
        m11_csb_startup_init_state_receipt_to_m11(
            state, &receipt->receipts.init_state);
        if (m11_csb_complete_amiga_a31e_direct_handoff(state)) return 1;
        m11_set_status(state, "CSB AMIGA", "A31E C03 HANDOFF FAILED");
        return 0;
    }
    if (m11_csb_is_amiga_a31_profile(receipt->profile)) {
        state->csbStartupExpectedPackageIdentity =
            package_identity ? package_identity : 1u;
        m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
        m11_csb_startup_init_state_receipt_to_m11(
            state, &receipt->receipts.init_state);
        state->csbState.startup_title_active = 1;
        state->csbState.startup_entrance_active = 0;
        if (m11_csb_prepare_amiga_titl_handoff(state)) return 1;
        m11_set_status(state, "CSB AMIGA", "TITL.DAT DECODE FAILED");
        return 0;
    }
    if (m11_csb_is_fmtowns_profile(receipt->profile)) {
        /* ReDMCSB ANIMTOWN.C invokes F2248/F2275 on TITLE.ANM; it does not
         * enter the PC34 TITLE.C/ENTRANCE.C surface session. */
        state->csbStartupExpectedPackageIdentity =
            package_identity ? package_identity : 1u;
        m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
        m11_csb_startup_init_state_receipt_to_m11(
            state, &receipt->receipts.init_state);
        state->csbState.startup_title_active = 1;
        state->csbState.startup_entrance_active = 0;
        state->csbFmtownsSwitchReturnLanguage =
            receipt->profile->variant_id == CSB_V1_VARIANT_FMTOWNS_EN
                ? CSB_FMTOWNS_SWITCH_ENGLISH
                : CSB_FMTOWNS_SWITCH_JAPANESE;
        if (m11_csb_bind_fmtowns_title(state, "TITLE.ANM", 0)) return 1;
        m11_set_status(state, "CSB FM TOWNS", "TITLE.ANM DECODE FAILED");
        return 0;
    }
    state->csbStartupRuntimeAssetSession = calloc(
        1, sizeof(CSB_V1_StartupRuntimeAssetSession_PC34));
    if (!state->csbStartupRuntimeAssetSession ||
        !csb_v1_boot_startup_runtime_asset_session_open_pc34(
            (const CSB_V1_BootProfile *)state->csbBootProfile,
            (CSB_V1_StartupRuntimeAssetSession_PC34 *)
                state->csbStartupRuntimeAssetSession)) {
        fprintf(stderr,
                "firestaff: CSB startup surface session rejected for graphics %s "
                "(variant=%d)\n",
                receipt->profile->graphics_path,
                (int)receipt->profile->variant_id);
        m11_set_status(state, "CSB STARTUP", "GRAPHICS SURFACE DECODE FAILED");
        free(state->csbStartupRuntimeAssetSession);
        state->csbStartupRuntimeAssetSession = NULL;
        return 0;
    }
    ((CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession)->csbSaveCandidateIdentity =
        spec->csbSaveCandidateIdentity;
    ((CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession)->csbStartupPackageIdentity =
        package_identity ? package_identity : 1u;
    ((CSB_V1_StartupRuntimeAssetSession_PC34 *)
        state->csbStartupRuntimeAssetSession)->direct_resume_loaded =
        receipt->receipts.handoff.direct_resume_loaded ? 1 : 0;
    state->csbStartupExpectedPackageIdentity = package_identity ? package_identity : 1u;
    if (!m11_csb_bind_release_app_capture_receipt(
            state, &receipt->startup_asset_gate)) {
        if (m11_csb_csbwin_graphics_startup_only_eligible(
                (const CSB_V1_BootProfile *)state->csbBootProfile,
                (const CSB_V1_StartupRuntimeAssetSession_PC34 *)
                    state->csbStartupRuntimeAssetSession)) {
            /* This is explicitly not a release-app receipt. It enables the
             * original C001-C005 introduction only; ENTRANCE.C F0806's
             * runtime handoff remains blocked by the absent HUD owner. */
            m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
            m11_csb_startup_init_state_receipt_to_m11(
                state, &receipt->receipts.init_state);
            m11_apply_csb_runtime_startup_session_state_receipt(
                state, &receipt->receipts.session_state);
            m11_set_status(state, "CSB STARTUP", "CSBWIN HUD OWNER REQUIRED");
            return 1;
        }
        csb_v1_boot_startup_runtime_asset_session_release_pc34(
            (CSB_V1_StartupRuntimeAssetSession_PC34 *)
                state->csbStartupRuntimeAssetSession);
        free(state->csbStartupRuntimeAssetSession);
        state->csbStartupRuntimeAssetSession = NULL;
        return 0;
    }
    m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
    m11_csb_startup_init_state_receipt_to_m11(
        state,
        &receipt->receipts.init_state);
    m11_apply_csb_runtime_startup_session_state_receipt(
        state,
        &receipt->receipts.session_state);
    m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
    (void)m11_csb_startup_apply_host_receipt(
        state,
        &receipt->receipts.launch_host_receipt);
    if ((state->presentationMode == M12_PRESENTATION_V22_MODERN ||
         csb_v2_presentation_mode_has_partial_source_overlay()) &&
        !csb_v22_inplace_draw_init()) {
        /* The CSB-specific finished-pack gate admitted the manifest, but the
         * selected cache still has to be readable by the live CSB renderer.
         * Fall back to V2.1 rather than using DM1's V2.2 cache. */
        if (state->presentationMode == M12_PRESENTATION_V22_MODERN) {
            csb_v2_runtime_cleanup();
            csb_v2_presentation_mode_set(CSB_V2_PM_V21_UPSCALED);
            csb_v2_runtime_init(2);
            csb_v2_runtime_bind_to_v1(&receipt->profile->runtime);
            state->presentationMode = M12_PRESENTATION_V21_UPSCALED;
        }
    }
    return 1;
}

static void m11_csb_startup_tick_receipt_to_m11(
    M11_GameViewState *state,
    const CSB_V1_StartupTickReceipt_PC34 *receipt)
{
    const CSB_V1_BootProfile *profile;
    if (!state || !receipt) {
        return;
    }
    state->csbState.startup_entrance_frame = receipt->entrance_frame;
    m11_csb_startup_command_state_receipt_to_m11(state, &receipt->state);
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (profile && (profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
                    profile->variant_id == CSB_V1_VARIANT_ST21_EN) &&
        state->csbState.startup_title_active &&
        !state->csbStartupRuntimeAssetSession) {
        if (!state->csbAtariStAnimationClockStarted) {
            state->csbAtariStAnimationClockStarted = 1;
            state->csbAtariStAnimationVbl = 0u;
            state->csbAtariStAnimationVblRemainder = 0u;
            state->csbAtariStAnimationFrameBound = 0;
        } else {
            m11_csb_advance_atari_st_vblank(state, profile->tick_ms);
            m11_csb_play_due_atari_st_animation_sounds(state);
            (void)m11_csb_complete_atari_st_runtime_handoff(state);
        }
    }
    /* Native A31 TITL.DAT is deliberately not advanced here.  This receipt
     * belongs to the PC34 startup owner; the native route has no PC34 asset
     * session and advances exactly once from M11_GameView_AdvanceIdleTick.
     * ReDMCSB APPA.C:51-68 hands the title to ANIM.C F1205's VBlank loop. */
}

static M11_GameInputResult m11_csb_startup_apply_idle_receipt(
    M11_GameViewState *state,
    const CSB_V1_StartupIdleReceipt_PC34 *receipt)
{
    if (!state || !receipt) {
        return M11_GAME_INPUT_IGNORED;
    }
    m11_csb_startup_tick_receipt_to_m11(state, &receipt->tick_receipt);
    if (receipt->finish_receipt_valid) {
        m11_csb_startup_command_state_receipt_to_m11(
            state,
            &receipt->finish_receipt);
        if (state->csbState.startup_entrance_dismissed) {
            if (!m11_csb_complete_door_runtime_handoff(state)) {
                return M11_GAME_INPUT_IGNORED;
            }
        }
    }
    return m11_csb_startup_apply_host_receipt(state, &receipt->host_receipt);
}

static void m11_csb_startup_apply_utility_state_receipt(
    M11_GameViewState *state,
    const CSB_V1_UtilStateReceipt *receipt)
{
    if (!state || !receipt) {
        return;
    }
    if (receipt->selected_action_index_changed) {
        state->csbState.startup_import_selected_action_index =
            receipt->selected_action_index;
    }
    if (receipt->preview_active_changed) {
        state->csbState.startup_import_preview_active =
            receipt->preview_active;
    }
}

static void m11_csb_startup_apply_entrance_action_state_receipt(
    M11_GameViewState *state,
    const CSB_V1_StartupEntranceHostActionReceipt_PC34 *receipt)
{
    if (!state || !receipt || !receipt->handled) {
        return;
    }
    state->csbState.startup_entrance_last_command =
        receipt->command_receipt.command_id;
    if (receipt->sync_profile_state) {
        m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
    }
    m11_csb_startup_command_state_receipt_to_m11(
        state,
        &receipt->state_receipt);
    /* ReDMCSB ENTRANCE.C F0441/F0806 leaves the Utility wait loop before
     * it starts C002/C003 prison-door opening (or completes a resume).
     * Keep the imported party in the runtime, but retire the startup-only
     * overlay state immediately.  Otherwise a stale Utility selection can
     * survive into the live HUD after NEW/LOAD has already handed control
     * back to C03_GAME. */
    if (receipt->state_receipt.opening_active ||
        receipt->state_receipt.entrance_dismissed ||
        !receipt->state_receipt.entrance_active) {
        state->csbState.startup_import_available = 0;
        state->csbState.startup_import_preview_active = 0;
    }
}

static M11_GameInputResult m11_csb_handle_fmtowns_game_entrance_input(
    M11_GameViewState *state, M12_MenuInput input)
{
    CSB_V1_StartupHostFacts_PC34 facts;
    CSB_V1_StartupEntranceHostActionReceipt_PC34 action;

    if (!state || input != M12_MENU_INPUT_ACCEPT ||
        !m11_csb_is_fmtowns_profile(
            (const CSB_V1_BootProfile *)state->csbBootProfile) ||
        !state->csbFmtownsGameHandoffReceipt.valid ||
        !state->csbState.startup_entrance_active ||
        state->csbState.startup_title_active) {
        return M11_GAME_INPUT_IGNORED;
    }
    /* ReDMCSB STARTUP1.C enters ENTRANCE.C F0807 from CHTWE/CHTWJ after
     * ANIMTW/SWITCHTW. Build the source-owned Entrance facts directly, rather
     * than requiring the unrelated PC TITLE.C host-dispatch receipt. */
    if (!csb_v1_startup_host_facts_from_runtime_state_pc34(
            &facts, state->csbState.startup_title_active,
            state->csbState.startup_title_frame,
            state->csbState.startup_title_source_step,
            state->csbState.startup_entrance_active,
            state->csbState.startup_entrance_source_step,
            state->csbState.startup_entrance_dismissed,
            state->csbState.startup_entrance_credits_active,
            state->csbState.startup_entrance_credits_remaining_ticks,
            state->csbState.startup_entrance_opening_active,
            state->csbState.startup_entrance_opening_delay_ticks,
            state->csbState.startup_entrance_opening_step,
            state->csbState.startup_entrance_pending_command,
            state->csbState.startup_entrance_frame,
            state->csbState.startup_import_available,
            state->csbState.startup_import_selected_action_index,
            state->csbState.startup_import_champion_count,
            state->csbState.startup_import_preview_active,
            state->csbState.startup_import_utility_prompt,
            state->csbState.startup_entrance_resume_available,
            state->csbState.startup_entrance_resume_path,
            state->csbBootProfile) ||
        !csb_v1_startup_execute_entrance_command_from_host_facts_with_receipts_pc34(
            &facts, CSB_V1_STARTUP_ENTRANCE_COMMAND_ENTER_DUNGEON_PC34,
            &action) || !action.handled) {
        return M11_GAME_INPUT_IGNORED;
    }
    m11_csb_startup_apply_entrance_action_state_receipt(state, &action);
    return m11_csb_startup_apply_host_receipt(state, &action.host_receipt);
}

static M11_GameInputResult m11_csb_startup_apply_host_decision_receipt(
    M11_GameViewState *state,
    const CSB_V1_BootStartupHostDecisionReceipt_PC34 *decision)
{
    if (!state || !decision || !decision->valid) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (decision->clear_import_preview) {
        state->csbState.startup_import_preview_active = 0;
    }
    if (decision->bonus_requested_changed) {
        state->csbState.startup_entrance_bonus_requested =
            decision->bonus_requested ? 1 : 0;
    }
    if (decision->status) {
        m11_set_status(
            state,
            decision->status_scope ? decision->status_scope : "BOOT",
            decision->status);
    }
    if (decision->return_to_launcher) {
        return M11_GAME_INPUT_RETURN_TO_MENU;
    }
    if (decision->redraw_startup) {
        return M11_GAME_INPUT_REDRAW;
    }
    return M11_GAME_INPUT_IGNORED;
}

static M11_GameInputResult m11_csb_startup_apply_input_render_receipt(
    M11_GameViewState *state,
    const CSB_V1_BootStartupInputRenderReceipt_PC34 *receipt)
{
    const CSB_V1_BootStartupActionReceipt_PC34 *action = NULL;

    if (!state || !receipt || !receipt->valid ||
        !receipt->host_decision_valid) {
        return M11_GAME_INPUT_IGNORED;
    }
    action = receipt->action_valid ? &receipt->action : NULL;
    if (action && action->handled) {
        if (action->kind == CSB_V1_BOOT_STARTUP_ACTION_UTILITY_PC34) {
            m11_csb_startup_apply_utility_state_receipt(
                state,
                &action->utility_receipt.util_state_receipt);
            if (action->utility_receipt.entrance_receipt_valid) {
                m11_csb_startup_apply_entrance_action_state_receipt(
                    state,
                    &action->utility_receipt.entrance_receipt);
            }
        } else if (action->kind ==
                   CSB_V1_BOOT_STARTUP_ACTION_ENTRANCE_PC34) {
            m11_csb_startup_apply_entrance_action_state_receipt(
                state,
                &action->entrance_receipt);
        }
    }
    /* ReDMCSB ENTRANCE.C F0441/F0806 lines 850-883 keeps input, redraw,
     * and HUD/menu readiness in the same startup loop. M11 consumes the
     * CSB input/render receipt here instead of rebuilding host decisions
     * from utility/entrance action receipts. */
    return m11_csb_startup_apply_host_decision_receipt(
        state,
        &receipt->host_decision);
}

static M11_GameInputResult m11_csb_startup_apply_host_input_dispatch_receipt(
    M11_GameViewState *state,
    const CSB_V1_BootStartupHostInputDispatchReceipt_PC34 *receipt)
{
    if (!state || !receipt || !receipt->valid || !receipt->startup_active) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (receipt->should_dispatch_input && receipt->input_render_valid) {
        return m11_csb_startup_apply_input_render_receipt(
            state,
            &receipt->input_render);
    }
    return M11_GAME_INPUT_IGNORED;
}

static int m11_measure_text_pixels(const char* text,
                                   const M11_TextStyle* style) {
    const M11_TextStyle* s = style ? style : &g_text_small;
    size_t len = text ? strlen(text) : 0;
    if (!text || len == 0) return 0;
    if (g_activeOriginalFont && M11_Font_IsLoaded(g_activeOriginalFont)) {
        /* Accessibility: scale the measured width by fontScale */
        int base = M11_Font_MeasureString(text);
        int effective_scale = g_m11_font_scale_override > 0
                              ? g_m11_font_scale_override : s->scale;
        return base * effective_scale;
    }
    int effective_scale = g_m11_font_scale_override > 0
                          ? g_m11_font_scale_override : s->scale;
    return (int)(len * (size_t)((5 * effective_scale) + s->tracking));
}

/* TEXT.C clips C015 to its physical 320-pixel surface.  The active
 * original font is variable-width, so a character-count limit is not
 * sufficient here: it can draw beyond the right edge of the message area. */
static void m11_copy_text_fitting_pixels(char* destination,
                                         size_t destinationSize,
                                         const char* source,
                                         int maximumWidth,
                                         const M11_TextStyle* style) {
    size_t length;

    if (!destination || destinationSize == 0U) {
        return;
    }
    destination[0] = '\0';
    if (!source || maximumWidth <= 0) {
        return;
    }
    for (length = 0U; source[length] != '\0' && length + 1U < destinationSize;
         ++length) {
        destination[length] = source[length];
        destination[length + 1U] = '\0';
        if (m11_measure_text_pixels(destination, style) > maximumWidth) {
            destination[length] = '\0';
            return;
        }
    }
}

static void m11_draw_text_centered_in_rect(unsigned char* framebuffer,
                                           int framebufferWidth,
                                           int framebufferHeight,
                                           int x,
                                           int y,
                                           int w,
                                           const char* text,
                                           const M11_TextStyle* style) {
    int textW = m11_measure_text_pixels(text, style);
    int drawX = x + ((w - textW) / 2);
    if (drawX < x) drawX = x;
    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                  drawX, y, text, style);
}

static void m11_format_session_timer_compact_remaining(
    const SessionTimerRuntime* runtime,
    char* out,
    size_t outSize)
{
    int remaining;
    if (!out || outSize == 0U) {
        return;
    }
    remaining = SessionTimerRuntime_RemainingSeconds(runtime);
    if (remaining < 0) {
        snprintf(out, outSize, "OFF");
    } else if (remaining >= 3600) {
        snprintf(out, outSize, "%dH LEFT", (remaining + 3599) / 3600);
    } else if (remaining >= 60) {
        snprintf(out, outSize, "%dM LEFT", (remaining + 59) / 60);
    } else {
        snprintf(out, outSize, "%dS LEFT", remaining);
    }
}

static void m11_format_session_timer_reminder_line(
    const M11_GameViewState* state,
    char* out,
    size_t outSize)
{
    char remaining[SESSION_TIMER_RUNTIME_TEXT_CAPACITY];
    int scale;
    if (!out || outSize == 0U) {
        return;
    }
    out[0] = '\0';
    scale = state ? state->fontScale : 1;
    if (scale < 1) scale = 1;
    if (scale > 3) scale = 3;
    if (scale >= 3) {
        m11_format_session_timer_compact_remaining(
            state ? &state->sessionTimerRuntime : NULL, out, outSize);
        return;
    }
    SessionTimerRuntime_FormatRemaining(
        state ? &state->sessionTimerRuntime : NULL,
        remaining,
        sizeof(remaining));
    if (scale == 2) {
        snprintf(out, outSize, "%s LEFT", remaining);
    } else {
        snprintf(out, outSize, "SESSION TIMER %s REMAINING", remaining);
    }
}

/* Firestaff-specific forced-pause dialog layout.  This is not a
 * ReDMCSB-driven surface; the dialog title/body/box sizing is
 * Firestaff's session-timer escalation policy and must therefore be
 * fit-tested at every supported fontScale (1..3).  The same font
 * (M11_Font_DrawString) is what m11_draw_text_original feeds when
 * state->fontScale > 0 (see m11_game_view.c:1300), so the per-char
 * pixel advance verified by
 * firestaff_dm1_v1_dialog_choice_font_scale_fit_probe applies here
 * too: cell advance = 8 * scale.  Visible glyph height = 6 * scale.
 *
 * The layout shrinks/widens as scale grows so every line stays inside
 * the dialog box, which in turn stays inside the 320x200 framebuffer.
 * Source: ReDMCSB M11_GameView_Draw sessionTimerForcedPauseDialogActive
 * block (file-scope coordinates), font constants from
 * G2089_C8_InscriptionCharacterWidth=8 / G2083_C3=6 visible rows. */
static void m11_forced_pause_dialog_clamp_box(
    M11_ForcedPauseDialogLayout* layout,
    int framebufferWidth,
    int framebufferHeight)
{
    int margin;
    int maxW;
    if (!layout || framebufferWidth <= 0 || framebufferHeight <= 0) {
        return;
    }
    margin = layout->scale >= 3 ? 2 : 4;
    if (layout->boxX < margin) layout->boxX = margin;
    if (layout->boxY < margin) layout->boxY = margin;
    maxW = framebufferWidth - (2 * margin);
    if (layout->boxW > maxW) layout->boxW = maxW;
    if (layout->boxW < 64) layout->boxW = 64;
    if (layout->boxH < 36) layout->boxH = 36;
    if (layout->boxX + layout->boxW > framebufferWidth - margin) {
        layout->boxX = framebufferWidth - margin - layout->boxW;
        if (layout->boxX < margin) layout->boxX = margin;
    }
    if (layout->boxY + layout->boxH > framebufferHeight - margin) {
        layout->boxY = framebufferHeight - margin - layout->boxH;
        if (layout->boxY < margin) layout->boxY = margin;
    }
    /* Vertically centre on y=100 unless the clamped box already
     * touches the bottom edge. */
    if (layout->boxY + layout->boxH < framebufferHeight - margin &&
        layout->boxH <= framebufferHeight - (2 * margin)) {
        int centredY = ((framebufferHeight - layout->boxH) / 2);
        if (centredY < margin) centredY = margin;
        if (centredY + layout->boxH <= framebufferHeight - margin) {
            layout->boxY = centredY;
        }
    }
}

static void m11_forced_pause_dialog_layout_for(
    const M11_GameViewState* state,
    int framebufferWidth,
    int framebufferHeight,
    M11_ForcedPauseDialogLayout* outLayout)
{
    char remaining[SESSION_TIMER_RUNTIME_TEXT_CAPACITY];
    int scale;
    int titleX;
    int line1X;
    int line2X;
    int lineStep;
    int titleY;
    int line1Y;
    int line2Y;
    int boxW;
    int boxH;
    int boxX;
    int boxY;
    int innerX;
    int innerW;
    int titleLen;
    int line1Len;
    int line2Len;
    int titleAdvance;
    int line1Advance;
    int line2Advance;
    int glyphH;
    int requiredH;
    if (!outLayout) {
        return;
    }
    memset(outLayout, 0, sizeof(*outLayout));
    scale = state ? state->fontScale : 1;
    if (scale < 1) scale = 1;
    if (scale > 3) scale = 3;
    outLayout->scale = scale;

    SessionTimerRuntime_FormatRemaining(
        state ? &state->sessionTimerRuntime : NULL,
        remaining,
        sizeof(remaining));

    /* Title/body wordings shrink as scale grows so the visible
     * text stays inside the chosen box.  At scale 1 we keep the
     * source-faithful wording (the same one the previous commit
     * shipped) so the unchanged-defaults contract still holds. */
    if (scale >= 3) {
        snprintf(outLayout->title, sizeof(outLayout->title), "%s",
                 m11_translate_for_state(state, "EXPIRED"));
        snprintf(outLayout->line1, sizeof(outLayout->line1), "%s",
                 m11_translate_for_state(state, "ENTER MENU"));
        snprintf(outLayout->line2, sizeof(outLayout->line2), "%s",
                 m11_translate_for_state(state, "ESC DISMISS"));
    } else if (scale == 2) {
        snprintf(outLayout->title, sizeof(outLayout->title),
                 m11_translate_for_state(state, "EXPIRED %s"), remaining);
        snprintf(outLayout->line1, sizeof(outLayout->line1), "%s",
                 m11_translate_for_state(state, "ENTER: MENU"));
        snprintf(outLayout->line2, sizeof(outLayout->line2), "%s",
                 m11_translate_for_state(state, "ESC: DISMISS"));
    } else {
        snprintf(outLayout->title, sizeof(outLayout->title),
                 m11_translate_for_state(
                     state, "SESSION TIMER EXPIRED (%s) -- RETURN TO MENU"),
                 remaining);
        snprintf(outLayout->line1, sizeof(outLayout->line1), "%s",
                 m11_translate_for_state(
                     state, "PRESS ENTER TO RETURN TO MENU"));
        snprintf(outLayout->line2, sizeof(outLayout->line2), "%s",
                 m11_translate_for_state(state, "ESC TO DISMISS"));
    }

    titleLen = (int)strlen(outLayout->title);
    line1Len = (int)strlen(outLayout->line1);
    line2Len = (int)strlen(outLayout->line2);
    titleAdvance = titleLen * M11_FONT_CHAR_CELL_WIDTH * scale;
    line1Advance = line1Len * M11_FONT_CHAR_CELL_WIDTH * scale;
    line2Advance = line2Len * M11_FONT_CHAR_CELL_WIDTH * scale;
    glyphH = M11_FONT_CHAR_VISIBLE_H * scale;
    lineStep = scale * 12;

    /* Per-scale box geometry.  At scale 1 we keep the source
     * (40,70,240,60) so unchanged visuals when fontScale is unset.
     * At scale 2/3 we widen the box to the maximum width that
     * still leaves a 4-px margin on each side, and grow the box
     * height enough to fit three lines of (glyphH + lineStep) plus
     * the per-scale top/bottom inset. */
    if (scale == 1) {
        boxX = 40;
        boxW = 240;
        boxH = 60;
    } else {
        boxW = M11_FB_WIDTH - 8;
        if (boxW < 240) boxW = 240;
        if (boxW > 312) boxW = 312;
        boxX = (M11_FB_WIDTH - boxW) / 2;
        if (boxX < 4) boxX = 4;
        /* Required height = top inset (scale*10) + 3 lines of
         * (glyphH + lineStep) - lineStep + bottom inset (scale*4). */
        requiredH = (scale * 10) + (3 * (glyphH + lineStep)) +
                        (scale * 4);
        boxH = requiredH;
        if (boxH < 60) boxH = 60;
        if (boxH > 144) boxH = 144;
    }
    boxY = 70;
    outLayout->boxX = boxX;
    outLayout->boxY = boxY;
    outLayout->boxW = boxW;
    outLayout->boxH = boxH;

    /* Inner text margins track the box scale so the shadow pass
     * never clips the box border. */
    innerX = boxX + (scale * 4);
    innerW = boxW - (2 * scale * 4);
    if (innerW < scale * 8) innerW = scale * 8;
    titleY = boxY + (scale * 10);
    line1Y = titleY + lineStep;
    line2Y = line1Y + lineStep;

    /* Centre every line inside the inner rect.  When the chosen
     * wording is wider than innerW (only at scale 1, where the
     * source-faithful title overflows the 240 px box on purpose),
     * pin titleX/line1X/line2X to innerX so the raster starts at
     * the box left edge instead of running off the framebuffer. */
    titleX = innerX + ((innerW - titleAdvance) / 2);
    line1X = innerX + ((innerW - line1Advance) / 2);
    line2X = innerX + ((innerW - line2Advance) / 2);
    if (titleAdvance > innerW) titleX = innerX;
    if (line1Advance > innerW) line1X = innerX;
    if (line2Advance > innerW) line2X = innerX;
    if (titleX < innerX) titleX = innerX;
    if (line1X < innerX) line1X = innerX;
    if (line2X < innerX) line2X = innerX;
    outLayout->titleX = titleX;
    outLayout->titleY = titleY;
    outLayout->line1X = line1X;
    outLayout->line1Y = line1Y;
    outLayout->line2X = line2X;
    outLayout->line2Y = line2Y;

    m11_forced_pause_dialog_clamp_box(outLayout, framebufferWidth,
                                      framebufferHeight);
}

static void m11_return_confirm_dialog_layout_for(
    const M11_GameViewState* state,
    int framebufferWidth,
    int framebufferHeight,
    M11_ReturnConfirmDialogLayout* outLayout)
{
    int scale;
    int promptAdvance;
    int choice0Advance;
    int choice1Advance;
    int maxTextAdvance;
    int margin;
    int boxW;
    int boxH;
    int innerW;
    int promptX;
    int boxX;
    int boxY;
    if (!outLayout) {
        return;
    }
    memset(outLayout, 0, sizeof(*outLayout));
    scale = state ? state->fontScale : 1;
    if (scale < 1) scale = 1;
    if (scale > 3) scale = 3;
    outLayout->scale = scale;

    if (scale >= 3) {
        snprintf(outLayout->prompt, sizeof(outLayout->prompt), "%s",
                 m11_translate_for_state(state, "QUIT?"));
    } else if (scale == 2) {
        snprintf(outLayout->prompt, sizeof(outLayout->prompt), "%s",
                 m11_translate_for_state(state, "RETURN TO MENU?"));
    } else {
        snprintf(outLayout->prompt, sizeof(outLayout->prompt),
                 "%s",
                 (state && state->dialogOverlayText[0] != '\0')
                     ? state->dialogOverlayText
                     : m11_translate_for_state(state,
                                               "RETURN TO START MENU?"));
    }
    snprintf(outLayout->choice0, sizeof(outLayout->choice0), "%s",
             (state && state->dialogChoices[0][0] != '\0')
                 ? state->dialogChoices[0]
                 : m11_translate_for_state(state, "YES"));
    snprintf(outLayout->choice1, sizeof(outLayout->choice1), "%s",
             (state && state->dialogChoices[1][0] != '\0')
                 ? state->dialogChoices[1]
                 : m11_translate_for_state(state, "NO"));

    promptAdvance = (int)strlen(outLayout->prompt) *
                    M11_FONT_CHAR_CELL_WIDTH * scale;
    choice0Advance = (int)strlen(outLayout->choice0) *
                     M11_FONT_CHAR_CELL_WIDTH * scale;
    choice1Advance = (int)strlen(outLayout->choice1) *
                     M11_FONT_CHAR_CELL_WIDTH * scale;
    maxTextAdvance = promptAdvance;
    if (choice0Advance > maxTextAdvance) maxTextAdvance = choice0Advance;
    if (choice1Advance > maxTextAdvance) maxTextAdvance = choice1Advance;

    margin = (scale >= 2) ? 4 : 60;
    boxW = (scale == 1) ? 200 : framebufferWidth - (2 * margin);
    if (boxW < maxTextAdvance + (2 * scale * 6)) {
        boxW = maxTextAdvance + (2 * scale * 6);
    }
    if (boxW > framebufferWidth - 8) {
        boxW = framebufferWidth - 8;
    }
    if (boxW < 120) {
        boxW = 120;
    }
    boxH = (scale == 1) ? 50 : (50 + ((scale - 1) * 12));
    if (boxH > framebufferHeight - 8) {
        boxH = framebufferHeight - 8;
    }
    boxX = (framebufferWidth - boxW) / 2;
    boxY = (framebufferHeight - boxH) / 2;
    if (boxX < 4) boxX = 4;
    if (boxY < 4) boxY = 4;
    if (boxX + boxW > framebufferWidth - 4) {
        boxX = framebufferWidth - 4 - boxW;
    }
    if (boxY + boxH > framebufferHeight - 4) {
        boxY = framebufferHeight - 4 - boxH;
    }

    innerW = boxW - (2 * scale * 6);
    promptX = boxX + (boxW - promptAdvance) / 2;
    if (promptX < boxX + scale * 6) {
        promptX = boxX + scale * 6;
    }
    if (promptAdvance > innerW && scale < 3) {
        snprintf(outLayout->prompt, sizeof(outLayout->prompt),
                 "RETURN TO MENU?");
        promptAdvance = (int)strlen(outLayout->prompt) *
                        M11_FONT_CHAR_CELL_WIDTH * scale;
        promptX = boxX + (boxW - promptAdvance) / 2;
        if (promptX < boxX + scale * 6) {
            promptX = boxX + scale * 6;
        }
    }

    outLayout->boxX = boxX;
    outLayout->boxY = boxY;
    outLayout->boxW = boxW;
    outLayout->boxH = boxH;
    outLayout->promptX = promptX;
    outLayout->promptY = boxY + (scale == 1 ? 18 : scale * 9);
    outLayout->choiceY = boxY + boxH - (scale == 1 ? 16 : (scale * 9));
    outLayout->choiceW = boxW / 2;
}

static int m11_forced_pause_dialog_max_text_pixel_width(
    const M11_ForcedPauseDialogLayout* layout)
{
    int titleLen;
    int line1Len;
    int line2Len;
    int scale;
    int max;
    if (!layout) return 0;
    scale = layout->scale < 1 ? 1 : layout->scale;
    titleLen = (int)strlen(layout->title);
    line1Len = (int)strlen(layout->line1);
    line2Len = (int)strlen(layout->line2);
    max = titleLen;
    if (line1Len > max) max = line1Len;
    if (line2Len > max) max = line2Len;
    return max * M11_FONT_CHAR_CELL_WIDTH * scale;
}

static int m11_return_confirm_dialog_max_text_pixel_width(
    const M11_ReturnConfirmDialogLayout* layout)
{
    int promptLen;
    int choice0Len;
    int choice1Len;
    int scale;
    int max;
    if (!layout) return 0;
    scale = layout->scale < 1 ? 1 : layout->scale;
    promptLen = (int)strlen(layout->prompt);
    choice0Len = (int)strlen(layout->choice0);
    choice1Len = (int)strlen(layout->choice1);
    max = promptLen;
    if (choice0Len > max) max = choice0Len;
    if (choice1Len > max) max = choice1Len;
    return max * M11_FONT_CHAR_CELL_WIDTH * scale;
}

void M11_GameView_GetForcedPauseDialogLayout(
    const M11_GameViewState* state,
    int framebufferWidth,
    int framebufferHeight,
    M11_ForcedPauseDialogLayout* outLayout)
{
    if (!outLayout) {
        return;
    }
    m11_forced_pause_dialog_layout_for(state, framebufferWidth,
                                       framebufferHeight, outLayout);
}

int M11_GameView_ForcedPauseDialogLayoutMaxTextPixelWidth(
    const M11_ForcedPauseDialogLayout* layout)
{
    return m11_forced_pause_dialog_max_text_pixel_width(layout);
}

/* Sibling layout helper for the session-timer REMINDER banner
 * (M11_GameView_Draw sessionTimerReminderOverlayActive block).  The
 * reminder banner is a top-strip overlay — not a centred modal — so
 * the geometry contract is:
 *
 *   - box always sits in y=4..31 (28 px tall, 312 px wide), giving
 *     a 1-pixel yellow border around a black fill, exactly as the
 *     previous reminder-banner block painted.
 *   - text draws inside (boxX+inset, boxY+text-y, innerW) where
 *     inset grows with scale so the centred m11_draw_text never
 *     clips the border pass;
 *   - the wording shrinks as scale grows (same pattern as the
 *     forced-pause dialog) so the per-char cell advance at 8*scale
 *     still fits inside innerW.
 *   - the banner fits the 320x200 framebuffer with a non-zero
 *     bottom margin (y=33 is the source-owned DM1 dungeon viewport
 *     top, banner must never touch it).
 *
 * Source: Firestaff session-timer UX boundary;
 *         m11_format_session_timer_reminder_line +
 *         m11_format_session_timer_compact_remaining (file-scope
 *         private helpers that own the actual wording); the
 *         production reminder banner block now reads the geometry
 *         from this layout and the wording from
 *         m11_format_session_timer_reminder_line so the fit gate's
 *         refactor stays a single-source-of-truth. */
static void m11_reminder_banner_layout_for(
    const M11_GameViewState* state,
    int framebufferWidth,
    int framebufferHeight,
    M11_ReminderBannerLayout* outLayout)
{
    int scale;
    int boxX;
    int boxY;
    int boxW;
    int boxH;
    int inset;
    int innerX;
    int innerY;
    int innerW;
    int textAdvance;
    int lineLen;
    int textX;
    int textY;
    if (!outLayout) {
        return;
    }
    (void)framebufferHeight;
    memset(outLayout, 0, sizeof(*outLayout));
    scale = state ? state->fontScale : 1;
    if (scale < 1) scale = 1;
    if (scale > 3) scale = 3;
    outLayout->scale = scale;

    /* Box geometry stays at the source-locked (4, 4, 312, 28)
     * rectangle so all V1 overlay rows above y=33 are owned by the
     * banner at every fontScale.  At scale 3 the per-char cell
     * advance is 24 px so a 50-char wording wouldn't fit, but the
     * m11_format_session_timer_reminder_line wording shrinks to the
     * compact "%dM LEFT" / "%dS LEFT" / "OFF" form which fits. */
    boxX = 4;
    boxY = 4;
    boxW = 312;
    boxH = 28;
    if (framebufferWidth > 0) {
        if (boxW > framebufferWidth - (2 * boxX)) {
            boxW = framebufferWidth - (2 * boxX);
        }
    }
    if (boxW < 64) boxW = 64;
    inset = scale * 8;
    if (inset > boxW / 2) {
        inset = boxW / 2;
    }
    if (inset < 8) inset = 8;
    innerX = boxX + inset;
    innerY = boxY + (scale * 4);
    innerW = boxW - (2 * inset);
    if (innerW < scale * 8) innerW = scale * 8;

    /* Reuse the production wording so the layout's `line` field
     * mirrors what m11_GameView_Draw will paint.  The compact form is
     * computed by m11_format_session_timer_compact_remaining when
     * scale >= 3, the "%s LEFT" form when scale == 2, and the full
     * "SESSION TIMER HH:MM:SS REMAINING" form when scale == 1.
     *
     * NOTE: m11_format_session_timer_reminder_line is a static helper
     * local to this file, so we reproduce its scale-dependent output
     * here rather than depending on a forward declaration.  The two
     * implementations are kept in lockstep by the
     * firestaff_dm1_v1_reminder_banner_font_scale_fit_probe. */
    {
        char remaining[SESSION_TIMER_RUNTIME_TEXT_CAPACITY];
        const SessionTimerRuntime* runtime =
            state ? &state->sessionTimerRuntime : NULL;
        SessionTimerRuntime_FormatRemaining(runtime, remaining,
                                            sizeof(remaining));
        if (scale >= 3) {
            int rem = SessionTimerRuntime_RemainingSeconds(runtime);
            if (rem < 0) {
                snprintf(outLayout->line, sizeof(outLayout->line), "OFF");
            } else if (rem >= 3600) {
                snprintf(outLayout->line, sizeof(outLayout->line),
                         "%dH LEFT", (rem + 3599) / 3600);
            } else if (rem >= 60) {
                snprintf(outLayout->line, sizeof(outLayout->line),
                         "%dM LEFT", (rem + 59) / 60);
            } else {
                snprintf(outLayout->line, sizeof(outLayout->line),
                         "%dS LEFT", rem);
            }
        } else if (scale == 2) {
            snprintf(outLayout->line, sizeof(outLayout->line),
                     "%s LEFT", remaining);
        } else {
            snprintf(outLayout->line, sizeof(outLayout->line),
                     "SESSION TIMER %s REMAINING", remaining);
        }
    }
    lineLen = (int)strlen(outLayout->line);
    textAdvance = lineLen * M11_FONT_CHAR_CELL_WIDTH * scale;
    /* m11_draw_text_centered_in_rect draws at (innerX, innerY) with
     * the text centred in (innerX, innerY, innerW) — same path the
     * production reminder banner block uses via its TIMER_REMINDER_*
     * constants.  The fit gate's contract is "textAdvance <= innerW",
     * and we pin textX to innerX (instead of running off the framebuffer
     * left edge) when the wording is wider than innerW. */
    textX = innerX;
    textY = innerY;
    if (textAdvance <= innerW) {
        textX = innerX + ((innerW - textAdvance) / 2);
    }

    outLayout->boxX = boxX;
    outLayout->boxY = boxY;
    outLayout->boxW = boxW;
    outLayout->boxH = boxH;
    outLayout->textX = textX;
    outLayout->textY = textY;
    outLayout->innerX = innerX;
    outLayout->innerY = innerY;
    outLayout->innerW = innerW;
}

void M11_GameView_GetReminderBannerLayout(
    const M11_GameViewState* state,
    int framebufferWidth,
    int framebufferHeight,
    M11_ReminderBannerLayout* outLayout)
{
    if (!outLayout) {
        return;
    }
    m11_reminder_banner_layout_for(state, framebufferWidth,
                                   framebufferHeight, outLayout);
}

static int m11_reminder_banner_max_text_pixel_width(
    const M11_ReminderBannerLayout* layout)
{
    int lineLen;
    int scale;
    if (!layout) return 0;
    scale = layout->scale < 1 ? 1 : layout->scale;
    lineLen = (int)strlen(layout->line);
    return lineLen * M11_FONT_CHAR_CELL_WIDTH * scale;
}

int M11_GameView_ReminderBannerLayoutMaxTextPixelWidth(
    const M11_ReminderBannerLayout* layout)
{
    return m11_reminder_banner_max_text_pixel_width(layout);
}

