static int m11_group_visible_party_distance_f0200(
    M11_GameViewState* state,
    unsigned short groupThing,
    const struct DungeonGroup_Compat* group,
    int groupX,
    int groupY,
    int* outDistance) {
    struct DM1GroupBehaviorContext_Compat ctx;
    struct DM1ActiveGroup_Compat activeGroup;
    struct M11GroupSightRouteSource sight;
    struct DM1CreatureInfo_Compat sourceInfo;
    int distance;
    int i;

    if (!state || !group || !outDistance ||
        !m11_creature_source_info_i34(group->creatureType, &sourceInfo)) {
        return 0;
    }
    distance = abs(state->world.party.mapX - groupX) +
               abs(state->world.party.mapY - groupY);
    if (distance <= 0) {
        *outDistance = 0;
        return 1;
    }
    memset(&ctx, 0, sizeof(ctx));
    memset(&activeGroup, 0, sizeof(activeGroup));
    memset(&sight, 0, sizeof(sight));
    sight.world = &state->world;
    sight.mapIndex = state->world.party.mapIndex;
    ctx.currentGroupMapX = groupX;
    ctx.currentGroupMapY = groupY;
    ctx.currentGroupDistanceToParty = distance;
    ctx.partyMapX = state->world.party.mapX;
    ctx.partyMapY = state->world.party.mapY;
    ctx.partyMapIndex = state->world.party.mapIndex;
    ctx.currentMapIndex = state->world.party.mapIndex;
    ctx.partyChampionCount = state->world.party.championCount;
    ctx.dungeonViewPaletteIndex = m11_compute_dungeon_palette_index(state);
    ctx.isViewSquareBlocked = m11_group_sight_route_square_blocked;
    ctx.viewBlockerContext = &sight;
    ctx.creatureInfo = sourceInfo;
    ctx.creatureType = group->creatureType;
    ctx.groupBehavior = group->behavior;
    ctx.creatureCount = group->count;
    ctx.creatureSize = sourceInfo.attributes & DM1_ATTR_SIZE_MASK;
    activeGroup.groupThingIndex = THING_GET_INDEX(groupThing);
    activeGroup.directions = group->direction;
    activeGroup.cells = group->cells;

    for (i = 0; i < state->world.timeline.count; ++i) {
        if (state->world.timeline.events[i].aux2 == DM1_EVENT_INVISIBILITY) {
            ++ctx.partyInvisibilityEventCount;
        }
    }
    if (!F0818a_DM1_GROUP_GetDistanceToVisiblePartyWithRoute_Compat(
            &ctx, &activeGroup, -1, &state->world.masterRng, outDistance)) {
        return 0;
    }
    return *outDistance > 0;
}

/* GROUP.C F0201 first asks F0199 to walk the loaded map with F0198's
 * smell blocker.  The M11 state has no authenticated PC34 owner for a
 * decoded scent-list entry, so this live form deliberately exposes only
 * that direct-party branch.  F0819c receives NULL for the later stored-scent
 * branch and therefore leaves it unavailable rather than inventing a trail. */
static int m11_group_smell_party_direction_f0201(
    M11_GameViewState* state,
    unsigned short groupThing,
    const struct DungeonGroup_Compat* group,
    int groupX,
    int groupY,
    struct DM1GroupSmellDirectionPlan_Compat* outPlan) {
    struct DM1GroupBehaviorContext_Compat ctx;
    struct M11GroupSightRouteSource sight;
    struct DM1CreatureInfo_Compat sourceInfo;
    int primaryDir;
    int secondaryDir;
    int distance;

    if (!state || !group || !outPlan ||
        !m11_group_live_position_matches_source(
            state, groupThing, state->world.party.mapIndex, groupX, groupY) ||
        !m11_creature_source_info_i34(group->creatureType, &sourceInfo)) {
        return 0;
    }
    distance = abs(state->world.party.mapX - groupX) +
               abs(state->world.party.mapY - groupY);
    if (distance <= 0 || !m11_creature_compute_primary_secondary_dirs(
            state, groupX, groupY, state->world.party.mapX,
            state->world.party.mapY, &primaryDir, &secondaryDir)) {
        return 0;
    }

    memset(&ctx, 0, sizeof(ctx));
    memset(&sight, 0, sizeof(sight));
    sight.world = &state->world;
    sight.mapIndex = state->world.party.mapIndex;
    sight.smell = 1;
    ctx.currentGroupMapX = groupX;
    ctx.currentGroupMapY = groupY;
    ctx.currentGroupDistanceToParty = distance;
    ctx.currentGroupPrimaryDirToParty = primaryDir;
    ctx.currentGroupSecondaryDirToParty = secondaryDir;
    ctx.partyMapX = state->world.party.mapX;
    ctx.partyMapY = state->world.party.mapY;
    ctx.partyMapIndex = state->world.party.mapIndex;
    ctx.currentMapIndex = state->world.party.mapIndex;
    ctx.isSmellSquareBlocked = m11_group_sight_route_square_blocked;
    ctx.smellBlockerContext = &sight;
    ctx.creatureInfo = sourceInfo;

    if (!F0819c_DM1_GROUP_BuildSmelledPartyDirectionPlanWithRoute_Compat(
            &ctx, NULL, &state->world.masterRng, outPlan) ||
        !outPlan->valid || !outPlan->usedDirectPartyRoute ||
        outPlan->usedStoredScent || outPlan->directionOrdinal == 0) {
        return 0;
    }
    return 1;
}

static int m11_creature_maybe_launch_projectile(
    M11_GameViewState* state,
    unsigned short groupThing,
    int groupIndex,
    const struct DungeonGroup_Compat* group,
    const struct CreatureBehaviorProfile_Compat* profile,
    int groupX,
    int groupY,
    int dist) {
    struct DM1GroupBehaviorContext_Compat ctx;
    struct DM1ActiveGroup_Compat activeGroup;
    struct DM1CreatureProjectileAttack_Compat launch;
    DM1_CreatureProjectileCreateRequestPc34 createReq;
    struct ProjectileCreateInput_Compat input;
    struct TimelineEvent_Compat firstMove;
    int primaryDir = 0;
    int secondaryDir = 1;
    struct DM1CreatureInfo_Compat sourceInfo;
    int attackRange;
    int slot = -1;

    if (!state || !group || !profile) return 0;
    if (!m11_creature_source_info_i34((int)group->creatureType, &sourceInfo)) return 0;
    attackRange = DM1_ATTACK_RANGE(sourceInfo.ranges);
    if (attackRange <= 1 || dist <= 0 || dist > attackRange) return 0;

    /* ReDMCSB GROUP.C F0209 gates ranged attacks to the same row/column
     * before F0207 resolves projectile payload. */
    if (groupX != state->world.party.mapX && groupY != state->world.party.mapY) {
        return 0;
    }
    if (sourceInfo.attackTicks > 0 &&
        (state->world.gameTick % (uint32_t)sourceInfo.attackTicks) != 0u) {
        return 0;
    }
    if (attackRange > F0732_COMBAT_RngRandom_Compat(&state->world.masterRng, 16) + 1) {
        return 0;
    }
    if (!m11_creature_compute_primary_secondary_dirs(
            state, groupX, groupY,
            state->world.party.mapX, state->world.party.mapY,
            &primaryDir, &secondaryDir)) {
        return 0;
    }

    memset(&ctx, 0, sizeof(ctx));
    ctx.currentGroupMapX = groupX;
    ctx.currentGroupMapY = groupY;
    ctx.currentGroupDistanceToParty = dist;
    ctx.currentGroupPrimaryDirToParty = primaryDir;
    ctx.currentGroupSecondaryDirToParty = secondaryDir;
    ctx.partyMapX = state->world.party.mapX;
    ctx.partyMapY = state->world.party.mapY;
    ctx.partyMapIndex = state->world.party.mapIndex;
    ctx.currentMapIndex = state->world.party.mapIndex;
    ctx.partyChampionCount = state->world.party.championCount;
    ctx.creatureType = (int)group->creatureType;
    ctx.groupBehavior = (int)group->behavior;
    ctx.creatureCount = (int)group->count;
    ctx.creatureSize = sourceInfo.attributes & DM1_ATTR_SIZE_MASK;
    ctx.isArchenemy = (sourceInfo.attributes & CREATURE_ATTR_MASK_ARCHENEMY) ? 1 : 0;
    ctx.distanceToVisibleParty = dist;
    ctx.movementTicks = sourceInfo.movementTicks;
    ctx.currentTickLow = (int)(state->world.gameTick & 0xFFu);
    ctx.eventType = DM1_EVENT_UPDATE_BEHAVIOR_GROUP;
    ctx.eventTicks = (int)state->world.gameTick;
    ctx.creatureInfo = sourceInfo;

    memset(&activeGroup, 0, sizeof(activeGroup));
    activeGroup.groupThingIndex = THING_GET_INDEX(groupThing);
    activeGroup.directions = (int)group->direction;
    activeGroup.cells = (int)group->cells;
    activeGroup.targetMapX = state->world.party.mapX;
    activeGroup.targetMapY = state->world.party.mapY;
    activeGroup.homeMapX = groupX;
    activeGroup.homeMapY = groupY;

    memset(&launch, 0, sizeof(launch));
    if (!F0823_DM1_GROUP_ResolveProjectileAttack_Compat(
            &ctx, &activeGroup, 0, &state->world.masterRng, &launch) ||
        !launch.shouldLaunch) {
        return 0;
    }

    memset(&createReq, 0, sizeof(createReq));
    createReq.creatureGroupIndex = groupIndex;
    createReq.partyMapIndex = state->world.party.mapIndex;
    createReq.groupMapX = groupX;
    createReq.groupMapY = groupY;
    createReq.projectileThing = launch.projectileThing;
    createReq.targetCell = launch.targetCell;
    createReq.direction = launch.direction;
    createReq.kineticEnergy = launch.kineticEnergy;
    createReq.attack = launch.attack;
    createReq.stepEnergy = launch.stepEnergy;
    createReq.gameTick = (int)state->world.gameTick;
    if (!dm1_v1_build_creature_projectile_create_input_pc34(
            &createReq, &input)) {
        return 0;
    }

    memset(&firstMove, 0, sizeof(firstMove));
    if (!F0810_PROJECTILE_Create_Compat(&input, &state->world.projectiles,
                                        &slot, &firstMove)) {
        return 0;
    }
    /* F0212 publishes the live projectile together with C48/C49.  Do not
     * retain an unscheduled projectile when the bounded source timeline is
     * full; F0813 restores the exact newly allocated slot. */
    if (!F0721_TIMELINE_Schedule_Compat(&state->world.timeline, &firstMove)) {
        (void)F0813_PROJECTILE_Despawn_Compat(&state->world.projectiles, slot);
        return 0;
    }
    m11_audio_emit_creature_attack_sound_ex(state, group->creatureType,
                                            groupX, groupY,
                                            launch.useSpellSoundFallback);
    m11_log_event(state, M11_COLOR_LIGHT_RED,
                  "T%u: %s LAUNCHES PROJECTILE",
                  (unsigned int)state->world.gameTick,
                  m11_creature_name(state, (int)group->creatureType));
    return 1;
}

/* Process one creature group: check distance, maybe move, maybe attack. */
static void m11_process_one_creature_group(
    M11_GameViewState* state,
    unsigned short groupThing,
    int groupIndex) {
    const struct CreatureBehaviorProfile_Compat* profile;
    struct DungeonGroup_Compat* group;
    int groupX, groupY;
    int dist;
    int anyAlive;
    int i;

    if (!state || !state->world.things ||
        groupIndex < 0 || groupIndex >= state->world.things->groupCount) {
        return;
    }
    group = &state->world.things->groups[groupIndex];
    profile = CREATURE_GetProfile_Compat(group->creatureType);
    if (!profile) return;

    /* Check if any creature in the group is alive */
    anyAlive = 0;
    for (i = 0; i < (int)group->count + 1; ++i) {
        if (group->health[i] > 0) {
            anyAlive = 1;
            break;
        }
    }
    if (!anyAlive) return;

    /* Find where this group is on the map */
    if (!m11_find_group_position(&state->world,
                                 state->world.party.mapIndex,
                                 groupThing,
                                 &groupX, &groupY)) {
        return; /* not on current map */
    }
    if (!m11_group_live_position_matches_source(
            state, groupThing, state->world.party.mapIndex, groupX, groupY)) {
        return;
    }

    /* ReDMCSB GROUP.C F0209 T0209094_FleeFromTarget: a group that F0190/F0821
     * frightened into DM1_BEHAVIOR_FLEE retreats instead of approaching or
     * attacking.  This branch must precede both the same-square attack and
     * the approach routes; without it a fleeing group walked back at the
     * party and F0821's outcome was invisible in the live runtime. */
    if ((int)group->behavior == DM1_BEHAVIOR_FLEE) {
        int fleeX, fleeY;
        if (profile->movementTicks > 0 &&
            (state->world.gameTick % (uint32_t)profile->movementTicks) != 0u) {
            return;
        }
        if (m11_creature_try_flee(state, groupThing, groupX, groupY,
                                  &fleeX, &fleeY)) {
            m11_audio_emit_creature_movement_sound(
                state, group->creatureType, fleeX, fleeY);
            m11_log_event(state, M11_COLOR_LIGHT_CYAN,
                          "T%u: %s FLEES",
                          (unsigned int)state->world.gameTick,
                          m11_creature_name(state, group->creatureType));
        }
        return;
    }

    /* If on same square as party: attack */
    if (groupX == state->world.party.mapX && groupY == state->world.party.mapY) {
        /* Attack cadence: only attack every attackTicks ticks */
        if (profile->attackTicks > 0 &&
            (state->world.gameTick % (uint32_t)profile->attackTicks) == 0u) {
            /* ReDMCSB GROUP.C F0193: a Giggler steals instead of resolving
             * an ordinary melee attack.  Without this branch DM1's C02 dealt
             * plain damage and never took an item, even though F0822 was
             * source-locked. */
            if ((int)group->creatureType == DM1_CREATURE_TYPE_GIGGLER) {
                int target = m11_pick_alive_champion_index(
                    state, (int)state->world.gameTick);
                if (target >= 0 &&
                    m11_giggler_steal_from_champion(
                        state,
                        &state->world.things->groups[groupIndex],
                        target)) {
                    m11_audio_emit_creature_attack_sound(
                        state, group->creatureType, groupX, groupY);
                    return;
                }
            }
            m11_creature_attack_party(state, group, groupX, groupY);
        }
        return;
    }

    /* GROUP.C F0197-F0200 derives the distance from the raw map route and
     * C04 direction bits.  Do not substitute profile Manhattan ranges. */
    if (!m11_group_visible_party_distance_f0200(
            state, groupThing, group, groupX, groupY, &dist)) {
        struct DM1GroupSmellDirectionPlan_Compat smellPlan;
        int newX;
        int newY;

        int smelledParty;

        memset(&smellPlan, 0, sizeof(smellPlan));
        /* F0201 draws from masterRng, so it must keep being evaluated FIRST
         * and unconditionally, exactly as the original short-circuit did.
         * Gating the cadence ahead of it would skip those draws on
         * off-cadence ticks and desynchronise every later RNG consumer. */
        smelledParty = m11_group_smell_party_direction_f0201(
            state, groupThing, group, groupX, groupY, &smellPlan);
        if (profile->movementTicks > 0 &&
            (state->world.gameTick % (uint32_t)profile->movementTicks) != 0u) {
            return;
        }
        if (!smelledParty) {
            /* ReDMCSB GROUP.C F0209 WANDER: a group that can neither see nor
             * smell the party wanders instead of standing still.  F0810 owns
             * the 50% move roll, direction pick and F0811 validation. */
            if (m11_creature_try_wander(state, groupThing, group,
                                        groupX, groupY, &newX, &newY)) {
                m11_audio_emit_creature_movement_sound(
                    state, group->creatureType, newX, newY);
            }
            return;
        }
        if (m11_creature_try_move_with_directions(
                state, groupThing, groupX, groupY,
                smellPlan.primaryDirection, smellPlan.secondaryDirection,
                &newX, &newY)) {
            m11_audio_emit_creature_movement_sound(
                state, group->creatureType, newX, newY);
        }
        return;
    }

    if (m11_creature_maybe_launch_projectile(state, groupThing, groupIndex,
                                             group, profile, groupX, groupY,
                                             dist)) {
        return;
    }

    /* Movement cadence: only move every movementTicks ticks */
    if (profile->movementTicks > 0 &&
        (state->world.gameTick % (uint32_t)profile->movementTicks) != 0u) {
        return;
    }

    /* Try to move toward the party */
    {
        int newX, newY;
        if (m11_creature_try_move(state, groupThing, groupX, groupY, &newX, &newY)) {
            m11_audio_emit_creature_movement_sound(state, group->creatureType, newX, newY);
            /* Check if creature arrived at party square */
            if (newX == state->world.party.mapX &&
                newY == state->world.party.mapY) {
                m11_log_event(state, M11_COLOR_LIGHT_RED,
                              "T%u: %s REACHES THE PARTY!",
                              (unsigned int)state->world.gameTick,
                              m11_creature_name(state, group->creatureType));
            }
        }
    }
}

int M11_GameView_ProbeCreatureWanderStep(M11_GameViewState* state,
                                         unsigned short groupThing,
                                         int groupIndex,
                                         int groupMapX,
                                         int groupMapY,
                                         int* outNewX,
                                         int* outNewY) {
    int localX = groupMapX;
    int localY = groupMapY;
    int moved;
    if (outNewX) *outNewX = groupMapX;
    if (outNewY) *outNewY = groupMapY;
    if (!state || !state->world.things) return 0;
    if (groupIndex < 0 || groupIndex >= state->world.things->groupCount) return 0;
    moved = m11_creature_try_wander(
        state, groupThing, &state->world.things->groups[groupIndex],
        groupMapX, groupMapY, &localX, &localY);
    if (outNewX) *outNewX = localX;
    if (outNewY) *outNewY = localY;
    return moved;
}

int M11_GameView_ProbeGigglerStealFromChampion(M11_GameViewState* state,
                                               int groupIndex,
                                               int championIndex) {
    if (!state || !state->world.things) return 0;
    if (groupIndex < 0 || groupIndex >= state->world.things->groupCount) return 0;
    return m11_giggler_steal_from_champion(
        state, &state->world.things->groups[groupIndex], championIndex);
}

int M11_GameView_ProbeCreatureFleeStep(M11_GameViewState* state,
                                       unsigned short groupThing,
                                       int groupMapX,
                                       int groupMapY,
                                       int* outNewX,
                                       int* outNewY) {
    int localX = groupMapX;
    int localY = groupMapY;
    int moved;
    if (!state) return 0;
    moved = m11_creature_try_flee(state, groupThing, groupMapX, groupMapY,
                                  &localX, &localY);
    if (outNewX) *outNewX = localX;
    if (outNewY) *outNewY = localY;
    return moved;
}

int M11_GameView_ProbeCreatureProjectileRuntimeLaunch(M11_GameViewState* state,
                                                      unsigned short groupThing,
                                                      int groupIndex,
                                                      int groupMapX,
                                                      int groupMapY) {
    struct DungeonGroup_Compat* group;
    const struct CreatureBehaviorProfile_Compat* profile;
    int dist;
    if (!state || !state->world.things || groupIndex < 0 ||
        groupIndex >= state->world.things->groupCount) {
        return 0;
    }
    group = &state->world.things->groups[groupIndex];
    profile = CREATURE_GetProfile_Compat(group->creatureType);
    if (!profile) return 0;
    dist = abs(state->world.party.mapX - groupMapX) +
           abs(state->world.party.mapY - groupMapY);
    return m11_creature_maybe_launch_projectile(state, groupThing, groupIndex,
                                                group, profile, groupMapX,
                                                groupMapY, dist);
}

/* F0115 owns the compact SFT walk and C04 group decoding.  M11's tick
 * layer consumes its typed result instead of independently walking raw
 * squareFirstThings. */
static int m11_f0115_first_creature_tick_candidate(
    const M11_GameViewState* state,
    int mapIndex,
    int mapX,
    int mapY,
    DM1_F0115WorldGroupCandidatePc34* outCandidate)
{
    DM1_F0115WorldCandidatesPc34 candidates;
    int i;

    if (outCandidate) {
        memset(outCandidate, 0, sizeof(*outCandidate));
        outCandidate->thing = THING_ENDOFLIST;
    }
    if (!state || !state->world.dungeon || !state->world.things) {
        return 0;
    }
    memset(&candidates, 0, sizeof(candidates));
    if (!dm1_v1_f0115_world_candidates_pc34(
            &state->world, mapIndex, mapX, mapY, NULL, NULL, &candidates) ||
        !candidates.valid) {
        return 0;
    }
    for (i = 0; i < candidates.groupCount; ++i) {
        const DM1_F0115WorldGroupCandidatePc34* candidate =
            &candidates.groups[i];
        int groupIndex = THING_GET_INDEX(candidate->thing);
        if (THING_GET_TYPE(candidate->thing) != THING_TYPE_GROUP ||
            groupIndex < 0 || groupIndex >= state->world.things->groupCount) {
            continue;
        }
        if (outCandidate) {
            *outCandidate = *candidate;
        }
        return 1;
    }
    return 0;
}

int M11_GameView_ProbeDm1F0115CreatureTickCandidate(
    const M11_GameViewState* state,
    int mapIndex,
    int mapX,
    int mapY,
    DM1_F0115WorldGroupCandidatePc34* outCandidate)
{
    return m11_f0115_first_creature_tick_candidate(
        state, mapIndex, mapX, mapY, outCandidate);
}

static int m11_bootstrap_find_group_cb(void *ctx, int group_index,
                                      int *out_map, int *out_x, int *out_y)
{
    M11_GameViewState *state = (M11_GameViewState *)ctx;
    unsigned short groupThing;
    int mi;
    if (!state || !state->world.things || !state->world.dungeon) return 0;
    if (group_index < 0 || group_index >= state->world.things->groupCount) return 0;
    groupThing = (unsigned short)((THING_TYPE_GROUP << 10) | (group_index & 0x3FF));
    for (mi = 0; mi < (int)state->world.dungeon->header.mapCount; ++mi) {
        int gx, gy;
        if (m11_find_group_position(&state->world, mi, groupThing, &gx, &gy)) {
            *out_map = mi;
            *out_x = gx;
            *out_y = gy;
            return 1;
        }
    }
    return 0;
}

/* Visit source-owned F0115 group candidates on the current map and process
 * their AI.  This intentionally leaves HoC filtering and creature actions
 * outside the discovery boundary. */
static void m11_process_creature_ticks(M11_GameViewState* state) {
    int mapIdx;
    const struct DungeonMapDesc_Compat* map;
    int mx, my;

    if (!state || !state->active || state->partyDead) return;
    if (!state->world.dungeon || !state->world.things ||
        !state->world.things->squareFirstThings) return;

    /* F0882's PC34 world loader enters NEWMAP.C F0003, whose F0195 pass
     * activates the loaded C04 groups and schedules their source C37
     * behavior events before M11 can tick.  Do not let the historical M11
     * map-scan simulator manufacture movement or attacks if that source
     * timeline is absent or later rejected: a stock DM1 session must remain
     * owned by M10's F0190/F0209 dispatch.  The legacy scan below survives
     * only for isolated diagnostic worlds that do not identify as dm1. */
    if (m11_is_dm1_source_kind(state->sourceKind) &&
        strcmp(state->sourceId, "dm1") == 0) {
        return;
    }

    if (!state->creatureBehaviorBootstrapped &&
        state->world.things->groupCount > 0) {
        DM1_V1_CreatureBehaviorBootstrapResultPc34 bootstrapResult;
        if (dm1_v1_creature_behavior_bootstrap_pc34(
                &state->world, m11_bootstrap_find_group_cb, state,
                &bootstrapResult)) {
            state->creatureBehaviorBootstrapped = 1;
        }
    }

    /* Once behavior events are bootstrapped, M10's event-driven F0209
     * dispatch handles all creature AI through the timeline queue.  The
     * brute-force map scan below is only needed as a fallback before the
     * bootstrap has seeded initial UPDATE_BEHAVIOR_GROUP events, or when
     * no active group states exist for M10 to dispatch through. */
    if (state->creatureBehaviorBootstrapped &&
        state->world.pc34ActiveGroupSourceCount > 0) {
        return;
    }

    mapIdx = state->world.party.mapIndex;
    if (mapIdx < 0 || mapIdx >= (int)state->world.dungeon->header.mapCount) return;
    if (m11_is_stock_dm1_hall_map0(state)) {
        return;
    }
    map = &state->world.dungeon->maps[mapIdx];

    for (mx = 0; mx < (int)map->width; ++mx) {
        for (my = 0; my < (int)map->height; ++my) {
            DM1_F0115WorldGroupCandidatePc34 candidate;
            if (m11_f0115_first_creature_tick_candidate(
                    state, mapIdx, mx, my, &candidate)) {
                m11_process_one_creature_group(
                    state, candidate.thing, THING_GET_INDEX(candidate.thing));
            } else if (!state->world.dungeon->tilesLoaded) {
                unsigned short groupThing =
                    m11_find_group_on_square(&state->world, mapIdx, mx, my);
                if (groupThing != THING_NONE && groupThing != THING_ENDOFLIST) {
                    m11_process_one_creature_group(
                        state, groupThing, THING_GET_INDEX(groupThing));
                }
            }
        }
    }
}

/* ================================================================
 * XP award and level-up processing
 *
 * Helper for local M11 bonus/legacy XP paths. Source-locked F0231
 * damage XP is applied by M10 when the hit is resolved; tick emission
 * processing must stay presentation-only for that damage.
 * ================================================================ */
static void m11_award_combat_xp(M11_GameViewState* state,
                                int championIndex,
                                int damage) {
    struct ChampionLifecycleState_Compat* lc;
    struct LevelUpMarker_Compat marker;
    int xpAmount;
    int skillIndex;
    char name[16];

    if (!state) return;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return;
    if (!state->world.party.champions[championIndex].present) return;

    lc = &state->world.lifecycle.champions[championIndex];
    memset(&marker, 0, sizeof(marker));

    /* XP proportional to damage, minimum 1.
     * The lifecycle layer uses 20-skill indices: LIFECYCLE_SKILL_SWING
     * is the default melee sub-skill under Fighter. */
    xpAmount = damage;
    if (xpAmount < 1) xpAmount = 1;
    skillIndex = LIFECYCLE_SKILL_SWING;

    if (F0851_LIFECYCLE_AwardCombatXP_Compat(
            lc, championIndex, skillIndex, xpAmount,
            state->world.party.mapIndex, /* map difficulty */
            state->world.gameTick,
            state->world.lifecycle.lastCreatureAttackTime,
            &state->world.masterRng,
            &marker)) {
        /* Sync base skill level back to Phase 10 party state.
         * The lifecycle uses 20 sub-skills; Phase 10 only tracks the
         * 4 base classes (Fighter/Ninja/Priest/Wizard). */
        int baseIdx = (skillIndex - LIFECYCLE_HIDDEN_SKILL_FIRST) >> 2;
        if (baseIdx >= 0 && baseIdx < CHAMPION_SKILL_COUNT) {
            int newLevel = F0848_LIFECYCLE_ComputeSkillLevel_Compat(
                lc, baseIdx, 0);
            if (newLevel > 0) {
                state->world.party.champions[championIndex].skillLevels[baseIdx] =
                    (unsigned short)newLevel;
            }
        }

        /* Check for level-up */
        if (marker.newLevel > marker.previousLevel && marker.newLevel > 0) {
            m11_format_champion_name(
                state->world.party.champions[championIndex].name,
                name, sizeof(name));
            m11_log_event(state, M11_COLOR_LIGHT_GREEN,
                          "T%u: %s LEVELED UP! (%s %d -> %d)",
                          (unsigned int)state->world.gameTick,
                          name,
                          (baseIdx == LIFECYCLE_SKILL_FIGHTER)  ? "FIGHTER" :
                          (baseIdx == LIFECYCLE_SKILL_NINJA)    ? "NINJA"   :
                          (baseIdx == LIFECYCLE_SKILL_PRIEST)   ? "PRIEST"  :
                          (baseIdx == LIFECYCLE_SKILL_WIZARD)   ? "WIZARD"  :
                          "SKILL",
                          marker.previousLevel, marker.newLevel);
        }
    }
}

static void m11_award_magic_xp(M11_GameViewState* state,
                               int championIndex,
                               int skillIndex,
                               int experience) {
    struct ChampionLifecycleState_Compat* lc;
    struct LevelUpMarker_Compat marker;
    int levelBefore = 0;
    int levelAfter = 0;
    int baseIdx;
    int xpAmount;
    char name[16];

    if (!state) return;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return;
    if (!state->world.party.champions[championIndex].present) return;
    if (skillIndex < 0 || skillIndex >= LIFECYCLE_SKILL_COUNT) return;

    lc = &state->world.lifecycle.champions[championIndex];
    memset(&marker, 0, sizeof(marker));
    xpAmount = experience > 0 ? experience : 1;

    if (F0849_LIFECYCLE_AddSkillExperience_Compat(
            lc, skillIndex, xpAmount,
            state->world.party.mapIndex,
            state->world.gameTick,
            state->world.lifecycle.lastCreatureAttackTime,
            &levelBefore, &levelAfter)) {
        baseIdx = dm1_skill_get_base_index(skillIndex);
        if (baseIdx >= 0 && baseIdx < CHAMPION_SKILL_COUNT) {
            if (levelAfter > 0) {
                state->world.party.champions[championIndex].skillLevels[baseIdx] =
                    (unsigned short)levelAfter;
            }
        }
        if (levelAfter > levelBefore && levelAfter > 0) {
            (void)F0850_LIFECYCLE_ApplyLevelUp_Compat(
                lc, baseIdx, levelAfter, &state->world.masterRng, &marker);
            m11_format_champion_name(
                state->world.party.champions[championIndex].name,
                name, sizeof(name));
            m11_log_event(state, M11_COLOR_LIGHT_GREEN,
                          "T%u: %s LEVELED UP! (%s %d -> %d)",
                          (unsigned int)state->world.gameTick,
                          name,
                          (baseIdx == LIFECYCLE_SKILL_PRIEST)  ? "PRIEST"  :
                          (baseIdx == LIFECYCLE_SKILL_WIZARD)  ? "WIZARD"  :
                          "SKILL",
                          levelBefore, levelAfter);
        }
    }
}

static int m11_dm1_kill_notify_plan(
    const M11_GameViewState* state,
    int creatureType,
    DM1_MeleeKillNotifyPlanPc34* outPlan) {
    const struct CreatureBehaviorProfile_Compat* profile;
    DM1_MeleeKillNotifyInputPc34 in;
    int champIdx;

    if (!state || !outPlan) return 0;
    profile = CREATURE_GetProfile_Compat(creatureType);
    champIdx = state->world.party.activeChampionIndex;
    memset(&in, 0, sizeof(in));
    in.creatureType = creatureType;
    in.creatureBaseHealth = profile ? profile->baseHealth : 0;
    in.activeChampionIndex = champIdx;
    in.activeChampionPresent =
        champIdx >= 0 && champIdx < CHAMPION_MAX_PARTY &&
        state->world.party.champions[champIdx].present;
    return dm1_v1_melee_kill_notify_plan_f0231_pc34(&in, outPlan);
}

static void m11_apply_kill_notify_plan(
    M11_GameViewState* state,
    const DM1_MeleeKillNotifyPlanPc34* plan) {
    if (!state || !plan || !plan->valid) return;
    if (plan->shouldLogDefeated) {
        m11_log_event(state, M11_COLOR_LIGHT_GREEN,
                      "T%u: %s DEFEATED",
                      (unsigned int)state->world.gameTick,
                      (plan->creatureType >= 0 && plan->creatureType < 27)
                          ? m11_creature_name(state, plan->creatureType)
                          : "ENEMY");
    }
    if (plan->shouldAwardKillXp) {
        char name[16];
        m11_award_combat_xp(state, plan->championIndex, plan->xpBonus);
        m11_format_champion_name(
            state->world.party.champions[plan->championIndex].name,
            name, sizeof(name));
        m11_log_event(state, M11_COLOR_LIGHT_GREEN,
                      "T%u: %s EARNS %d KILL XP (%s)",
                      (unsigned int)state->world.gameTick,
                      name, plan->xpBonus,
                      m11_creature_name(state, plan->creatureType));
    }
}

/* ================================================================
 * Potion / flask use
 *
 * The active champion drinks a potion or water flask from a hand
 * slot.  Potions apply stat effects based on their DM1 type:
 *   - VEN (type 3): antidote / restore stamina
 *   - KU  (type 7): heal HP
 *   - ZO  (type 5): restore mana
 *   - MON (type 0): shield / temporary defense (logged only)
 *   - DES (type 2): poison (damage)
 *   - VI  (type 14): restore all stats partially
 *   - WATER FLASK (type 15): restore water
 *   - EMPTY FLASK (type 20): no effect
 * The potion thing is consumed through the live PC34 transaction, which
 * rewrites the original raw record and preserves its Power byte.
 * ================================================================ */

/* DM1 potion type indices (match s_potionTypeNames order) */
/* Keep the keyboard/use-item route on the same ReDMCSB PANEL.C model as the
 * authentic mouth click.  The retired route used a private generic heal,
 * stamina and mana model and treated unhandled real potion types as a
 * fabricated small heal. */
static int m11_v1_mouth_live_inventory_transaction(
    M11_GameViewState* state,
    struct ChampionState_Compat* champ,
    unsigned short leaderThing,
    DM1ConsumableChampionPc34* inOutChampion,
    const uint16_t* woundRandomMasks,
    int woundRandomMaskCount,
    DM1_V1_InventoryLiveUseReceiptPc34* outReceipt);

static void m11_schedule_source_potion_status_event_pc34(
    M11_GameViewState* state,
    const DM1ConsumableResultPc34* result)
{
    struct TimelineEvent_Compat event;

    if (!state || !result || !result->consumed ||
        result->eventType != DM1_EVENT_CHAMPION_SHIELD ||
        result->eventDelay <= 0 || result->amountApplied <= 0) {
        return;
    }

    /* ReDMCSB PANEL.C F0349 stores YA's C72 as a native status timeout:
     * B.Defense = the applied shield delta, C72 in aux0/aux2, and Priority
     * zero.  TIMELINE.C F0261 later subtracts B.Defense from the party
     * shield.  Keep this event source-shaped so the existing M10 dispatch
     * owns expiry instead of a second host countdown. */
    memset(&event, 0, sizeof(event));
    event.kind = TIMELINE_EVENT_STATUS_TIMEOUT;
    event.fireAtTick = state->world.gameTick +
                       (uint32_t)result->eventDelay;
    event.mapIndex = state->world.party.mapIndex;
    event.mapX = state->world.party.mapX;
    event.mapY = state->world.party.mapY;
    event.cell = -1;
    event.aux0 = result->eventType;
    event.aux1 = result->amountApplied;
    event.aux2 = result->eventType;
    event.aux4 = 0;
    (void)F0721_TIMELINE_Schedule_Compat(&state->world.timeline, &event);
}

static int m11_apply_source_potion_effect_pc34(
    M11_GameViewState* state,
    struct ChampionState_Compat* champ,
    unsigned short leaderThing,
    DM1ConsumableResultPc34* outResult)
{
    DM1ConsumableChampionPc34 sourceChampion;
    uint16_t woundMasks[M11_DM1_V1_VI_WOUND_MASK_MAX_PC34];
    DM1_V1_InventoryLiveUseReceiptPc34 liveReceipt;
    int potionType;
    int potionPower;
    int woundMaskCount = 0;

    if (!state || !champ || !outResult ||
        THING_GET_TYPE(leaderThing) != THING_TYPE_POTION ||
        !state->world.things || !state->world.things->potions ||
        (int)THING_GET_INDEX(leaderThing) >= state->world.things->potionCount) {
        return 0;
    }
    potionType = (int)state->world.things->potions[THING_GET_INDEX(leaderThing)].type;
    potionPower = (int)state->world.things->potions[THING_GET_INDEX(leaderThing)].power;
    memset(&sourceChampion, 0, sizeof(sourceChampion));
    sourceChampion.statistic[DM1_CONSUMABLE_STAT_STRENGTH] =
        (int16_t)champ->attributes[CHAMPION_ATTR_STRENGTH];
    sourceChampion.statistic[DM1_CONSUMABLE_STAT_DEXTERITY] =
        (int16_t)champ->attributes[CHAMPION_ATTR_DEXTERITY];
    sourceChampion.statistic[DM1_CONSUMABLE_STAT_WISDOM] =
        (int16_t)champ->attributes[CHAMPION_ATTR_WISDOM];
    sourceChampion.statistic[DM1_CONSUMABLE_STAT_VITALITY] =
        (int16_t)champ->attributes[CHAMPION_ATTR_VITALITY];
    sourceChampion.currentHealth = (int16_t)champ->hp.current;
    sourceChampion.maximumHealth = (int16_t)champ->hp.maximum;
    sourceChampion.currentStamina = (int16_t)champ->stamina.current;
    sourceChampion.maximumStamina = (int16_t)champ->stamina.maximum;
    sourceChampion.currentMana = (int16_t)champ->mana.current;
    sourceChampion.maximumMana = (int16_t)champ->mana.maximum;
    sourceChampion.shieldDefense =
        (int16_t)state->world.magic.partyShieldDefense;
    sourceChampion.wounds = champ->wounds;
    sourceChampion.poisonDose = champ->poisonDose;
    sourceChampion.food = champ->food;
    sourceChampion.water = champ->water;

    if (potionType == M11_DM1_V1_POTION_VI_PC34 && champ->wounds) {
        woundMaskCount = m11_dm1_v1_fill_vi_wound_random_masks_pc34(
            &state->world.masterRng, potionPower, woundMasks,
            M11_DM1_V1_VI_WOUND_MASK_MAX_PC34);
    }
    if (!m11_v1_mouth_live_inventory_transaction(
            state, champ, leaderThing, &sourceChampion,
            woundMaskCount > 0 ? woundMasks : NULL, woundMaskCount,
            &liveReceipt) || !liveReceipt.valid ||
        liveReceipt.kind != DM1_V1_INVENTORY_LIVE_USE_CONSUMABLE_PC34) {
        return 0;
    }
    *outResult = liveReceipt.consumable;

    champ->attributes[CHAMPION_ATTR_STRENGTH] =
        (unsigned short)sourceChampion.statistic[DM1_CONSUMABLE_STAT_STRENGTH];
    champ->attributes[CHAMPION_ATTR_DEXTERITY] =
        (unsigned short)sourceChampion.statistic[DM1_CONSUMABLE_STAT_DEXTERITY];
    champ->attributes[CHAMPION_ATTR_WISDOM] =
        (unsigned short)sourceChampion.statistic[DM1_CONSUMABLE_STAT_WISDOM];
    champ->attributes[CHAMPION_ATTR_VITALITY] =
        (unsigned short)sourceChampion.statistic[DM1_CONSUMABLE_STAT_VITALITY];
    champ->hp.current = (uint16_t)sourceChampion.currentHealth;
    champ->stamina.current = (uint16_t)sourceChampion.currentStamina;
    champ->mana.current = (uint16_t)sourceChampion.currentMana;
    champ->wounds = sourceChampion.wounds;
    champ->poisonDose = sourceChampion.poisonDose;
    champ->food = sourceChampion.food;
    champ->water = sourceChampion.water;
    state->world.magic.partyShieldDefense = sourceChampion.shieldDefense;
    state->world.lifecycle.status.partyShieldDefense = sourceChampion.shieldDefense;
    m11_schedule_source_potion_status_event_pc34(state, outResult);
    return 1;
}

int M11_GameView_UseItem(M11_GameViewState* state) {
    struct ChampionState_Compat* champ;
    unsigned short item = THING_NONE;
    int useSlot = -1;
    int thingType;
    int thingIndex;
    char itemName[48];
    char champName[16];

    if (!state || !state->active || state->partyDead) {
        return 0;
    }
    if (m11_dm1_hoc_menu_route_blocks_normal_input(state)) {
        /* ReDMCSB: COMMAND.C F0380 lines 2159, 2180, 2303,
         * 2309, 2338, and 2367 keep C040 candidate-panel input
         * isolated from normal inventory/object command effects. */
        return 0;
    }
    if (state->world.party.activeChampionIndex < 0 ||
        state->world.party.activeChampionIndex >= CHAMPION_MAX_PARTY) {
        m11_set_status(state, "USE", "NO ACTIVE CHAMPION");
        return 0;
    }
    champ = &state->world.party.champions[state->world.party.activeChampionIndex];
    if (!champ->present || champ->hp.current == 0) {
        m11_set_status(state, "USE", "CHAMPION CANNOT ACT");
        return 0;
    }

    /* Check right hand first, then left hand */
    if (champ->inventory[CHAMPION_SLOT_HAND_RIGHT] != THING_NONE) {
        useSlot = CHAMPION_SLOT_HAND_RIGHT;
    } else if (champ->inventory[CHAMPION_SLOT_HAND_LEFT] != THING_NONE) {
        useSlot = CHAMPION_SLOT_HAND_LEFT;
    }
    if (useSlot < 0) {
        m11_set_status(state, "USE", "HANDS ARE EMPTY");
        m11_set_inspect_readout(state, "NOTHING TO USE",
                                "PICK UP A POTION OR FLASK FIRST (G KEY)");
        return 0;
    }

    item = champ->inventory[useSlot];
    thingType = THING_GET_TYPE(item);
    thingIndex = THING_GET_INDEX(item);
    m11_get_source_item_name(state, state->world.things, item, itemName, sizeof(itemName));
    m11_format_champion_name(champ->name, champName, sizeof(champName));

    if (thingType == THING_TYPE_POTION) {
        /* Drink the potion */
        if (state->world.things->potions &&
            thingIndex >= 0 && thingIndex < state->world.things->potionCount) {
            struct DungeonPotion_Compat* pot =
                &state->world.things->potions[thingIndex];
            int potType = (int)pot->type;
            int potPower = (int)pot->power;

            if (potType == DM1_CONSUMABLE_POTION_EMPTY_FLASK_PC34) {
                m11_set_status(state, "USE", "FLASK IS EMPTY");
                m11_set_inspect_readout(state, "EMPTY FLASK",
                                        "NOTHING TO DRINK");
                return 0;
            }

            {
                DM1ConsumableResultPc34 consumableResult;
                if (!m11_apply_source_potion_effect_pc34(
                        state, champ, item, &consumableResult) ||
                    !consumableResult.consumed) {
                    m11_set_status(state, "USE", "POTION DATA ERROR");
                    return 0;
                }
            }

            /* Award priest XP for drinking a potion */
            m11_award_magic_xp(state,
                               state->world.party.activeChampionIndex,
                               LIFECYCLE_SKILL_HEAL,
                               potPower > 0 ? potPower / 10 + 1 : 1);

            m11_set_status(state, "USE", "POTION CONSUMED");
            m11_format_presented_text(state, state->inspectTitle,
                                      sizeof(state->inspectTitle),
                                      "DRANK %s", itemName);
            m11_format_presented_text(state, state->inspectDetail,
                                      sizeof(state->inspectDetail),
                                      "%s USED %s (POWER %d)",
                                      champName, itemName, potPower);
            m11_check_party_death(state);
            m11_refresh_hash(state);
            return 1;
        }
        m11_set_status(state, "USE", "POTION DATA ERROR");
        return 0;
    }

    /* Junk type: waterskin (type 2) can be drunk */
    if (thingType == THING_TYPE_JUNK) {
        if (state->world.things->junks &&
            thingIndex >= 0 && thingIndex < state->world.things->junkCount) {
            int junkType = (int)state->world.things->junks[thingIndex].type;
            if (junkType == 2) { /* WATERSKIN */
                if (champ->water + 40 > 255) {
                    champ->water = 255;
                } else {
                    champ->water += 40;
                }
                m11_log_event(state, M11_COLOR_LIGHT_BLUE,
                              "T%u: %s DRINKS FROM WATERSKIN",
                              (unsigned int)state->world.gameTick,
                              champName);
                m11_set_status(state, "USE", "DRANK WATER");
                m11_set_inspect_readoutf(state, "WATERSKIN",
                                         "%s QUENCHED THIRST", champName);
                m11_refresh_hash(state);
                return 1;
            }
        }
    }

    /* Food items: apple(29), corn(30), bread(31), cheese(32),
     * screamer slice(33), worm round(34), drumstick(35), dragon steak(36) */
    if (thingType == THING_TYPE_JUNK) {
        if (state->world.things->junks &&
            thingIndex >= 0 && thingIndex < state->world.things->junkCount) {
            int junkType = (int)state->world.things->junks[thingIndex].type;
            if (junkType >= 29 && junkType <= 36) {
                /* Eat food: restore food stat */
                int foodAmount = 20 + (junkType - 29) * 5;
                if (champ->food + foodAmount > 255) {
                    champ->food = 255;
                } else {
                    champ->food += (unsigned char)foodAmount;
                }
                /* Remove from hand */
                if (state->world.things->junks[thingIndex].doNotDiscard) {
                    m11_log_event(state, M11_COLOR_YELLOW,
                                  "T%u: %s ATE %s (KEEPS ITEM)",
                                  (unsigned int)state->world.gameTick,
                                  champName, itemName);
                } else {
                    champ->inventory[useSlot] = THING_NONE;
                }
                m11_log_event(state, M11_COLOR_LIGHT_GREEN,
                              "T%u: %s ATE %s (+%d FOOD)",
                              (unsigned int)state->world.gameTick,
                              champName, itemName, foodAmount);
                m11_set_status(state, "USE", "FOOD CONSUMED");
                m11_format_presented_text(state, state->inspectTitle,
                                          sizeof(state->inspectTitle),
                                          "ATE %s", itemName);
                m11_format_presented_text(state, state->inspectDetail,
                                          sizeof(state->inspectDetail),
                                          "%s FEELS LESS HUNGRY (+%d)",
                                          champName, foodAmount);
                m11_refresh_hash(state);
                return 1;
            }
        }
    }

    m11_set_status(state, "USE", "CANNOT USE THIS ITEM");
    m11_set_inspect_readout(state, itemName,
                            "THIS ITEM CANNOT BE USED DIRECTLY");
    return 0;
}

/* Forward declaration: defined later in file, alongside the other
 * projectile-action helpers.  Drives F0811 for each live projectile
 * once per orchestrator tick from inside ProcessTickEmissions. */
static void m11_advance_projectiles_v1(M11_GameViewState* state,
                                       int allowM10OwnedProbeAdvance);

/* Forward decl for explosion advance; implementation lives with other
 * projectile-action helpers.  Drives F0822 for each live explosion
 * once per orchestrator tick from inside ProcessTickEmissions so the
 * post-detonation aftermath progresses through its frame sequence
 * rather than freezing at the first burst frame. */
static void m11_advance_explosions_v1(M11_GameViewState* state);
static int m11_dm1_projectile_launch_cell(int championCell, int direction);

static int m11_spawn_action_projectile_ex(M11_GameViewState* state,
                                          int championIndex,
                                          int subtype,
                                          int category,
                                          int kineticEnergy,
                                          int impactAttack,
                                          int attackTypeCode,
                                          int launchCell,
                                          int launchDirection,
                                          int stepEnergy,
                                          int launcherStrength,
                                          unsigned short carriedThing,
                                          int potionPower);
static int m11_dm1_throw_skill_level(const M11_GameViewState* state,
                                     int championIndex);
static int m11_dm1_f0328_spawn_thrown_thing(M11_GameViewState* state,
                                            int championIndex,
                                            struct ChampionState_Compat* champ,
                                            unsigned short thrownThing,
                                            int throwSide);

void M11_GameView_ProcessTickEmissions(M11_GameViewState* state) {
    int i;
    if (!state) {
        return;
    }
    for (i = 0; i < state->lastTickResult.emissionCount; ++i) {
        const struct TickEmission_Compat* e = &state->lastTickResult.emissions[i];
        m11_audio_emit_for_emission(state, e);
        switch (e->kind) {
            case EMIT_DAMAGE_DEALT: {
                DM1_MeleeDamageEmissionInputPc34 meleeEmissionIn;
                DM1_MeleeDamageEmissionPlanPc34 meleeEmissionPlan;
                memset(&meleeEmissionIn, 0, sizeof(meleeEmissionIn));
                memset(&meleeEmissionPlan, 0, sizeof(meleeEmissionPlan));
                meleeEmissionIn.damage = (int)e->payload[2];
                meleeEmissionIn.combatOutcome = (int)e->payload[3];
                if (!dm1_v1_melee_damage_emission_plan_f0231_pc34(
                        &meleeEmissionIn, &meleeEmissionPlan) ||
                    !meleeEmissionPlan.showDamageFeedback) {
                    break;
                }
                m11_materialize_action_result(
                    state, DM1_V1_LIVE_ACTION_EFFECT_DAMAGE_PC34,
                    (int)e->payload[0], -1, meleeEmissionPlan.damage,
                    (int)e->payload[3], 0);
                m11_log_event(state, M11_COLOR_LIGHT_RED,
                              "T%u: DAMAGE %d DEALT",
                              (unsigned int)state->world.gameTick,
                              meleeEmissionPlan.damage);
                /* ReDMCSB: PROJEXPL.C F0231 lines 1534-1536 awards
                 * damage XP/stamina at hit resolution, and MENU.C F0407
                 * lines 1620-1628 separately applies the action tail XP.
                 * M10 owns those source effects; M11 only presents the
                 * positive EMIT_DAMAGE_DEALT feedback. */
                M11_GameView_NotifyCreatureHit(state, meleeEmissionPlan.damage);
                break;
            }
            case EMIT_KILL_NOTIFY: {
                /* payload[0] = creature type (if available), else -1 */
                int cType = (int)e->payload[0];
                DM1_MeleeKillNotifyPlanPc34 killPlan;
                if (m11_dm1_kill_notify_plan(
                        state, cType >= 0 ? cType : 0, &killPlan)) {
                    m11_apply_kill_notify_plan(state, &killPlan);
                }
                break;
            }
            case EMIT_XP_AWARD:
                m11_log_event(state, M11_COLOR_YELLOW,
                              "T%u: EXPERIENCE GAINED",
                              (unsigned int)state->world.gameTick);
                break;
            case EMIT_CHAMPION_DAMAGED: {
                int champIdx = (int)e->payload[0];
                int damage = (int)e->payload[2];
                if (damage > 0) {
                    M11_GameView_NotifyChampionDamage(state, champIdx, damage);
                    m11_log_event(state, M11_COLOR_LIGHT_RED,
                                  "T%u: CHAMPION %d DAMAGED %d",
                                  (unsigned int)state->world.gameTick,
                                  champIdx + 1, damage);
                }
                break;
            }
            case EMIT_CHAMPION_DAMAGE_HIDDEN: {
                int champIdx = (int)e->payload[0];
                /* TIMELINE.C F0254 redraws the exact champion panel and
                 * clears its saved damage graphic. The runtime renderer owns
                 * that overlay as championDamageTimer/Amount. */
                if (champIdx >= 0 && champIdx < CHAMPION_MAX_PARTY) {
                    state->championDamageTimer[champIdx] = 0;
                    state->championDamageAmount[champIdx] = 0;
                }
                break;
            }
            case EMIT_TEXT_MESSAGE: {
                char decoded[256];
                int textIndex = (int)e->payload[0];
                /* ReDMCSB TIMELINE.C F0245:949-954 calls F0168 with
                 * C1_TEXT_TYPE_MESSAGE, then F0047 directly.  The M10
                 * emission is already restricted to a hidden->visible
                 * TextString on the party square, so M11 only consumes its
                 * source index through the same message decoder. */
                if (F0508_DUNGEON_DecodeTextStringThing_Compat(
                        state->world.things, textIndex,
                        DUNGEON_TEXT_TYPE_MESSAGE, decoded,
                        (int)sizeof(decoded)) > 0) {
                    /* TEXT.C F0047 owns C015. Keep decoded source text in
                     * its source state, not in M11's diagnostic log. */
                    dm1_v1_text_set_game_time(
                        &state->dm1V1TextMessage,
                        (long)state->world.gameTick);
                    dm1_v1_text_print_message(&state->dm1V1TextMessage,
                                              DM1_V1_COLOR_WHITE,
                                              fs_po_gettext_in_domain(
                                                  "dm1", decoded));
                }
                break;
            }
            case EMIT_CHAMPION_DOWN: {
                int champIdx = (int)e->payload[0];
                char name[16];
                if (champIdx >= 0 && champIdx < CHAMPION_MAX_PARTY &&
                    state->world.party.champions[champIdx].present) {
                    m11_format_champion_name(
                        state->world.party.champions[champIdx].name,
                        name, sizeof(name));
                } else {
                    snprintf(name, sizeof(name), "CHAMPION");
                }
                m11_log_event(state, M11_COLOR_LIGHT_RED,
                              "T%u: %s HAS FALLEN",
                              (unsigned int)state->world.gameTick, name);
                break;
            }
            case EMIT_PARTY_MOVED:
                m11_log_event(state, M11_COLOR_LIGHT_GRAY,
                              "T%u: PARTY MOVED TO %d,%d",
                              (unsigned int)state->world.gameTick,
                              state->world.party.mapX,
                              state->world.party.mapY);
                break;
            case EMIT_PARTY_FELL:
                m11_log_event(state, M11_COLOR_YELLOW,
                              "T%u: FELL INTO PIT! LEVEL %d",
                              (unsigned int)state->world.gameTick,
                              (int)e->payload[0] + 1);
                m11_set_status(state, "PIT", "FELL TO NEXT LEVEL");
                snprintf(state->inspectTitle, sizeof(state->inspectTitle), "PIT FALL");
                snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                         "DROPPED TO LEVEL %d, POSITION (%d,%d)",
                         (int)e->payload[0] + 1,
                         (int)e->payload[1],
                         (int)e->payload[2]);
                break;
            case EMIT_PARTY_TELEPORTED:
                m11_log_event(state, M11_COLOR_LIGHT_CYAN,
                              "T%u: TELEPORTED TO MAP %d (%d,%d)",
                              (unsigned int)state->world.gameTick,
                              (int)e->payload[0] + 1,
                              (int)e->payload[1],
                              (int)e->payload[2]);
                m11_set_status(state, "TELEPORT", "PARTY TRANSPORTED");
                snprintf(state->inspectTitle, sizeof(state->inspectTitle), "TELEPORTER");
                snprintf(state->inspectDetail, sizeof(state->inspectDetail),
                         "ARRIVED AT LEVEL %d, POSITION (%d,%d)",
                         (int)e->payload[0] + 1,
                         (int)e->payload[1],
                         (int)e->payload[2]);
                break;
            case EMIT_DOOR_STATE:
                m11_materialize_action_result(
                    state, DM1_V1_LIVE_ACTION_EFFECT_DOOR_PC34,
                    -1, -1, 0, COMBAT_OUTCOME_INVALID, 1);
                m11_log_event(state, M11_COLOR_YELLOW,
                              "T%u: DOOR STATE CHANGED",
                              (unsigned int)state->world.gameTick);
                break;
            case EMIT_SPELL_EFFECT: {
                /* payload[0]=champIdx, [1]=spellKind, [2]=spellType,
                 * [3]=packed power ordinal + G0487 SkillIndex */
                int sChamp = (int)e->payload[0];
                int sKind = (int)e->payload[1];
                int sType = (int)e->payload[2];
                int sPow  = (int)EMIT_SPELL_EFFECT_UNPACK_POWER(e->payload[3]);
                int sSkill = (int)EMIT_SPELL_EFFECT_UNPACK_SKILL(e->payload[3]);
                int sXp = (int)EMIT_SPELL_EFFECT_UNPACK_XP(e->payload[3]);
                const char* kindStr = "SPELL";
                m11_materialize_action_result(
                    state, DM1_V1_LIVE_ACTION_EFFECT_SPELL_PC34,
                    sChamp, -1, sPow, sKind, 0);
                if (sKind == C2_SPELL_KIND_PROJECTILE_COMPAT) kindStr = "PROJECTILE";
                else if (sKind == C3_SPELL_KIND_OTHER_COMPAT) kindStr = "ENCHANTMENT";
                else if (sKind == C1_SPELL_KIND_POTION_COMPAT) kindStr = "POTION";
                m11_log_event(state, M11_COLOR_CYAN,
                              "T%u: %s EFFECT APPLIED (TYPE %d, POWER %d)",
                              (unsigned int)state->world.gameTick,
                              kindStr, sType, sPow);
                /* ReDMCSB: MENU.C F0412 lines 1826-1839 computes spell
                 * experience from G0487 Spell.SkillIndex, then lines
                 * 2034-2039 award it once and disable the caster after
                 * the spell effect succeeds. */
                m11_award_magic_xp(state, sChamp, sSkill, sXp);
                break;
            }
            case EMIT_ACTION_DISABLED:
                m11_disable_champion_action_after_spell_f0412(
                    state, (int)e->payload[0], (int)e->payload[1]);
                break;
            case EMIT_ACTION_ENABLED:
                m11_enable_champion_action_from_timeline(
                    state, (int)e->payload[0], (int)e->payload[1]);
                break;
            case EMIT_GAME_WON:
                if (!state->gameWon) {
                    state->gameWon = 1;
                    state->gameWonTick = state->world.gameTick;
                    m11_log_event(state, M11_COLOR_LIGHT_GREEN,
                                  "T%u: THE QUEST IS COMPLETE!",
                                  (unsigned int)state->world.gameTick);
                    m11_set_status(state, "ENDGAME", "VICTORY!");
                    snprintf(state->inspectTitle,
                             sizeof(state->inspectTitle), "VICTORY");
                    snprintf(state->inspectDetail,
                             sizeof(state->inspectDetail),
                             "LORD CHAOS IS DEFEATED. THE FIRESTAFF IS RESTORED.");
                    if (state->dm1FmtownsStartupReceiptValid) {
                        int t = dm1_v1_fmtowns_cd_track_for_event(3);
                        if (t > 0) m11_dm1_dispatch_fmtowns_cdda(state, t);
                    }
                    /* ReDMCSB STARTUP2.C F0750: F31 releases the game
                     * runtime, enables its screen and calls F2248 with the
                     * retail ENDING.ANM.  Only the admitted Towns Game
                     * owner may enter this path; PC34 victories keep their
                     * own ENDGAME.C presentation. */
                    (void)m11_csb_activate_fmtowns_ending(state);
                }
                break;
            case EMIT_PARTY_DEAD:
                if (!state->partyDead) {
                    state->partyDead = 1;
                    m11_log_event(state, M11_COLOR_LIGHT_RED,
                                  "T%u: ALL CHAMPIONS HAVE FALLEN",
                                  (unsigned int)state->world.gameTick);
                    m11_set_status(state, "DEATH", "PARTY WIPED");
                    snprintf(state->inspectTitle,
                             sizeof(state->inspectTitle), "GAME OVER");
                    snprintf(state->inspectDetail,
                             sizeof(state->inspectDetail),
                             "THE DUNGEON CLAIMS YOUR SOULS. LOAD A SAVE OR RETURN TO MENU.");
                    if (state->dm1FmtownsStartupReceiptValid) {
                        int t = dm1_v1_fmtowns_cd_track_for_event(2);
                        if (t > 0) m11_dm1_dispatch_fmtowns_cdda(state, t);
                    }
                }
                break;
            case EMIT_CREATURE_MOVED:
                m11_audio_emit_creature_movement_sound(
                    state, (int)e->payload[1],
                    (int)e->payload[2], (int)e->payload[3]);
                break;
            case EMIT_SENSOR_EFFECT: {
                /* ReDMCSB TIMELINE.C F0245:972-986 handles sensor
                 * walk-on/walk-off effects emitted by F0718.
                 * payload[0]=kind, [1]=sensorType, [2]=triggerEvent,
                 * [3]=textIndex or destMapIndex.
                 *
                 * This emission is an observation receipt only.  The
                 * source-owned movement pipeline applies the corresponding
                 * F0276 effect immediately after the timeline dispatch;
                 * rendering SHOW_TEXT here would print every walk-on message
                 * twice and would force it through the wrong presentation
                 * color. */
                break;
            }
            default:
                break;
        }
    }

    /* V1 projectile cycle: after the M10 orchestrator has advanced
     * one tick and its emissions have been processed, step each live
     * projectile via F0811 so the cast visibly travels and detonates
     * instead of freezing at its spawn cell.  Runs exactly once per
     * orchestrator tick; no-op when no projectiles are live. */
    m11_advance_projectiles_v1(state, 0);

    /* V1 explosion cycle: after projectiles have stepped (and may have
     * spawned new first-frame explosions on impact), advance every
     * live explosion one frame via F0822.  This turns the post-
     * detonation aftermath into the classic DM1 multi-frame progression
     * (poison/smoke clouds decay and dissipate; fireball/lightning
     * emit their damage action on the first advance and despawn the
     * slot) rather than leaving a single frozen burst frame. */
    m11_advance_explosions_v1(state);
}

static void m11_dm1_f0740_bind_driver(M11_GameViewState *state);

void M11_GameView_Init(M11_GameViewState* state) {
    if (!state) {
        return;
    }
    m11_dm1_c13_visible_runtime_handoff_clear(state);
    memset(state, 0, sizeof(*state));
    dm1_spell_init(&state->dm1SpellCasting);
    dm1_v1_text_init(&state->dm1V1TextMessage);
    firestaff_ra_overlay_init(&state->retroAchievementsOverlay);
    (void)M11_Audio_Init(&state->audioState);
    /* V1 presentation: debug HUD off by default, opt-in via env */
    {
        const char* dbg = getenv("FIRESTAFF_DEBUG_HUD");
        state->showDebugHUD = (dbg && dbg[0] == '1') ? 1 : 0;
    }
    state->candidateMirrorOrdinal = -1;
    state->candidateMirrorPartyIndex = -1;
    state->dm2State.inventoryEyeChampionIndex = -1;
    state->leaderHandObjectPresent = 0;
    state->leaderHandThing = THING_NONE;
    state->leaderHandIconIndex = -1;
    state->dm1ViewportRuntimeOrigin =
        DM1_V1_VIEWPORT_RUNTIME_ORIGIN_NEW_START_PC34;
    state->dm1ViewportPresentedPaletteIndex = -1;
    state->v1ScrollPanelActive = 0;
    state->v1ScrollPanelThing = THING_NONE;
    state->v1OpenChestThing = THING_NONE;
    state->v1OpenChestSlotsValid = 0;
    state->v1ObjectDescriptionThing = THING_NONE;
    state->v1ObjectDescriptionIconIndex = -1;
    state->v1FoodWaterPanelActive = 0;
    {
        int i;
        for (i = 0; i < CHAMPION_MAX_PARTY; ++i) {
            state->actionDisabledIndex[i] = 0xFFu;
            state->actionEnableSlotOrdinal[i] = 0xFFu;
        }
    }
    m11_set_status(state, "BOOT", "GAME VIEW NOT STARTED");
    m11_set_inspect_readout(state, "NO FOCUS", "PRESS ENTER OR CLICK THE VIEW TO READ THE FRONT CELL");

    /* M11 construction is on the launch critical path.  It previously
     * scanned PO files here, always selecting English first and allowing
     * filesystem latency to block game startup before TITLE/ENTRANCE.  M12
     * owns localized UI catalogs; the V1 engine therefore starts from its
     * original English strings until a selected game-domain catalog is
     * explicitly installed by the frontend. */
    DM1_V1_VBlankTiming_Init(&state->vblankTiming);
    DM1_V1_MovementPipeline_InitPc34Compat(&state->dm1V1MovementPipeline);
    DM1_SaveMenu_Init(&state->saveMenu);
    state->dm1MusicOn = 1;
    dm1_v1_f0740_f0743_music_state_init_pc34(&state->dm1MusicState);
    memset(&state->dm1MusicSource, 0, sizeof(state->dm1MusicSource));
    m11_dm1_f0740_bind_driver(state);
    state->dm1MusicSourceBound = 0;
    /* M11_Audio_Init may have admitted a hash-verified loose SONG.DAT.
     * Bind the F0740--F0743 owner only after its state has been initialised;
     * doing it above this reset silently discarded a valid original source. */
    if (state->audioState.originalSongAvailable &&
        state->audioState.originalSongDatPath[0]) {
        state->dm1MusicSourceBound = dm1_v1_f0740_f0743_bind_song_dat_pc34(
            state->audioState.originalSongDatPath, &state->dm1MusicSource);
    }
    /* Generate a random game ID (matches ReDMCSB G0525_l_GameID
     * = RANDOM(65536) * RANDOM(65536) in LOADSAVE.C F0435) */
    state->dm1GameID = ((uint32_t)(rand() & 0xFFFF) << 16) | (uint32_t)(rand() & 0xFFFF);
    /* DM1 V2 Phase 5: camera interpolation state starts at zero.
     * M11_GameView_SetCameraOffset() is called from the V2 presentation
     * lane after each V1 tick; V1 paths leave these fields zero. */
    state->camera_offset_x = 0;
    state->camera_offset_y = 0;
    state->camera_interpolated_facing = 0;
    state->camera_duration_ms = 96;
    /* Phase 5: zero the private camera controller */
    memset(&state->p5_camera, 0, sizeof(state->p5_camera));
}

void M11_GameView_SetBootProbeMode(M11_GameViewState* state, int enabled)
{
    if (state) state->bootProbeFastForward = enabled ? 1 : 0;
}

int M11_GameView_SetCsbEntranceF0128Raster(
    M11_GameViewState *state,
    const CSB_V1_ViewportFirstFrameMaterializationReceipt *material_receipt,
    const CSB_V1_ViewportFirstFrameRasterReceiptPc34 *raster_receipt,
    const uint8_t *viewport_pixels,
    size_t viewport_pixel_count,
    uint32_t source_tick,
    uint32_t session_generation)
{
    CSB_V1_ViewportFirstFrameMaterializationReceipt material_copy;
    CSB_V1_ViewportFirstFrameRasterReceiptPc34 raster_copy;

    if (!state) return 0;
    if (material_receipt) material_copy = *material_receipt;
    if (raster_receipt) raster_copy = *raster_receipt;
    state->csbStartupF0128EntranceBound = 0;
    memset(&state->csbStartupF0128EntranceMaterialReceipt, 0,
           sizeof(state->csbStartupF0128EntranceMaterialReceipt));
    memset(&state->csbStartupF0128EntranceRasterReceipt, 0,
           sizeof(state->csbStartupF0128EntranceRasterReceipt));
    if (!material_receipt || !raster_receipt || !viewport_pixels ||
        viewport_pixel_count != sizeof(state->csbStartupF0128EntrancePixels) ||
        source_tick == 0u || session_generation == 0u ||
        !material_copy.valid || !material_copy.consumed_by_m11_render ||
        !material_copy.real_graphics_session ||
        !material_copy.no_synthetic_pixels ||
        !material_copy.no_fallback_visuals ||
        material_copy.combined_material_hash == 0u ||
        !raster_copy.valid || !raster_copy.consumed_by_raster ||
        raster_copy.rejected || raster_copy.command_count <= 0 ||
        raster_copy.combined_material_hash !=
            material_copy.combined_material_hash ||
        raster_copy.raster_hash == 0u) {
        return 0;
    }

    state->csbStartupF0128EntranceMaterialReceipt = material_copy;
    state->csbStartupF0128EntranceRasterReceipt = raster_copy;
    memcpy(state->csbStartupF0128EntrancePixels, viewport_pixels,
           sizeof(state->csbStartupF0128EntrancePixels));
    state->csbStartupF0128EntranceSourceTick = source_tick;
    state->csbStartupF0128EntranceSessionGeneration = session_generation;
    state->csbStartupF0128EntranceBound = 1;
    return 1;
}

void M11_GameView_Shutdown(M11_GameViewState* state) {
    if (!state) {
        return;
    }
    if (state->csbHintOracleRuntime) {
        csb_hint_oracle_atari_runtime_free(
            (CSB_HintOracleAtariRuntime *)state->csbHintOracleRuntime);
        free(state->csbHintOracleRuntime);
        state->csbHintOracleRuntime = NULL;
    }
    free(state->csbHintOracleSaveInfo);
    state->csbHintOracleSaveInfo = NULL;
    free(state->csbFmtownsUtilityJapanesePixels);
    state->csbFmtownsUtilityJapanesePixels = NULL;
    state->csbFmtownsUtilityJapaneseActive = 0;
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        csb_v2_runtime_cleanup();
    }
    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
        /* The SDL device is a host resource, while decoded PCM remains
         * owned by the verified GDAT loader in the DM2 boot profile. */
        dm2_v1_sound_bind_playback_backend(NULL);
        m11_dm2_mve_presenter_close(&state->dm2DosMvePresenter);
        dm2_v1_mac_movie_decoder_close(&state->dm2MacMovieDecoder);
    }
    theron_v1_track01_cdda_stream_stop(&state->theronTrack01CddaStream);
    m11_nexus_release_title(state);
    /* FM Towns TITLE/SWOOSH is copied only into this state-owned RAM buffer
     * from the selected HME-242 IMG.  Release it before its boot profile
     * releases the backing disc receipt: shutdown/relaunch must neither
     * retain the original member nor leave a stale presentation route. */
    m11_dm2_release_fmtowns_title(state);
    {
        Theron_V1_BootProfile *theronProfile =
            (Theron_V1_BootProfile*)state->theronBootProfile;
        Theron_V1_World *theronWorld =
            (Theron_V1_World*)state->theronWorld;
        Theron_V1_Viewport *theronViewport =
            (Theron_V1_Viewport*)state->theronViewport;
        TrAssetBundle *theronAssets =
            (TrAssetBundle*)state->theronAssets;
        theron_v1_boot_runtime_release(&theronProfile,
                                       &theronWorld,
                                       &theronViewport,
                                       &theronAssets);
        state->theronBootProfile = theronProfile;
        state->theronWorld = theronWorld;
        state->theronViewport = theronViewport;
        state->theronAssets = theronAssets;
    }
    m11_v22_inplace_draw_shutdown();
    csb_v22_inplace_draw_shutdown();
    if (state->csbStartupRuntimeAssetSession) {
        csb_v1_boot_startup_runtime_asset_session_release_pc34(
            (CSB_V1_StartupRuntimeAssetSession_PC34 *)
                state->csbStartupRuntimeAssetSession);
        free(state->csbStartupRuntimeAssetSession);
        state->csbStartupRuntimeAssetSession = NULL;
    }
    m11_csb_release_fmtowns_title(state);
    m11_csb_release_fmtowns_switch(state);
    free(state->csbAmigaTitlBytes);
    state->csbAmigaTitlBytes = NULL;
    state->csbAmigaTitlByteCount = 0u;
    free(state->csbViewportFloorPixels);
    free(state->csbViewportCeilingPixels);
    state->csbViewportFloorPixels = NULL;
    state->csbViewportCeilingPixels = NULL;
    for (size_t i = 0; i < 15u; ++i) {
        free(state->csbViewportWallPixels[i]);
        state->csbViewportWallPixels[i] = NULL;
        state->csbViewportWallWidths[i] = 0;
        state->csbViewportWallHeights[i] = 0;
    }
    if (state->csbBootProfile) {
        csb_v1_boot_cleanup((CSB_V1_BootProfile*)state->csbBootProfile);
        free(state->csbBootProfile);
        state->csbBootProfile = NULL;
    }
    if (state->dm2BootProfile) {
        dm2_v1_boot_cleanup((DM2_V1_BootProfile*)state->dm2BootProfile);
        free(state->dm2BootProfile);
        state->dm2BootProfile = NULL;
        state->dm2World = NULL;
    }
    if (state->nexusLightRuntimeReady || state->nexusLightRuntime.initialized) {
        nexus_v1_light_runtime_shutdown(&state->nexusLightRuntime);
        state->nexusLightRuntimeReady = 0;
    }
    nexus_v2_hud_runtime_shutdown();
    nexus_v2_lighting_runtime_shutdown();
    nexus_v2_smooth_movement_runtime_shutdown();
    nexus_v2_touch_runtime_shutdown();
    if (state->assetsAvailable) {
        M11_AssetLoader_Shutdown(&state->assetLoader);
        state->assetsAvailable = 0;
    }
    free(state->fmtownsGraphicsDat);
    state->fmtownsGraphicsDat = NULL;
    state->fmtownsGraphicsDatSize = 0U;
    if (state->active) {
        F0883_WORLD_Free_Compat(&state->world);
    }
    M11_Audio_Shutdown(&state->audioState);
    memset(state, 0, sizeof(*state));
}

static void m11_nexus_release_title(M11_GameViewState* state) {
    Nexus_TitleScreen* title;
    if (!state || !state->nexusTitleScreen) {
        return;
    }
    title = (Nexus_TitleScreen*)state->nexusTitleScreen;
    nexus_title_free(title);
    free(title);
    state->nexusTitleScreen = NULL;
    state->nexusState.title_active = 0;
    state->nexusState.title_loaded = 0;
    state->nexusState.title_frame = 0;
    state->nexusState.champion_select_active = 0;
    state->nexusState.champion_cursor = 0;
    state->nexusState.champion_select_frame = 0;
}

