static M11_GameInputResult m11_theron_apply_startup_host_receipt(
    M11_GameViewState* state,
    const Theron_StartupHostReceipt* receipt,
    const char* runtime_receipt) {

    Theron_V1_BootHostReceiptCallbacks callbacks;
    Theron_V1_BootHostReceiptResult result;

    if (!state || !receipt) {
        return M11_GAME_INPUT_IGNORED;
    }

    callbacks.userdata = state;
    callbacks.set_status = m11_theron_boot_host_set_status;
    callbacks.set_inspect = m11_theron_boot_host_set_inspect;
    callbacks.log_event = m11_theron_boot_host_log_event;

    if (!theron_v1_boot_apply_startup_host_receipt(
            receipt, runtime_receipt, &callbacks, &result)) {
        return M11_GAME_INPUT_IGNORED;
    }

    switch (result) {
    case THERON_V1_BOOT_HOST_RECEIPT_RESULT_REDRAW:
        return M11_GAME_INPUT_REDRAW;
    case THERON_V1_BOOT_HOST_RECEIPT_RESULT_RETURN_TO_MENU:
        return M11_GAME_INPUT_RETURN_TO_MENU;
    case THERON_V1_BOOT_HOST_RECEIPT_RESULT_IGNORED:
    default:
        return M11_GAME_INPUT_IGNORED;
    }
}

static M11_GameInputResult m11_theron_apply_startup_action_host_receipt(
    M11_GameViewState *state,
    const Theron_StartupActionHostReceipt *receipt)
{
    Theron_V1_BootActionReceiptCallbacks callbacks;
    Theron_V1_BootHostReceiptResult result;

    if (!state || !receipt) {
        return M11_GAME_INPUT_IGNORED;
    }

    callbacks.userdata = state;
    callbacks.set_status = m11_theron_boot_host_set_status;
    callbacks.set_inspect = m11_theron_boot_host_set_inspect;
    callbacks.log_event = m11_theron_boot_host_log_event;
    callbacks.apply_state_receipt =
        m11_theron_boot_action_apply_state_receipt;
    callbacks.update_track01_cdda_lifecycle =
        m11_theron_boot_action_update_track01_cdda_lifecycle;

    if (!theron_v1_boot_apply_startup_action_host_receipt(
            receipt, &callbacks, &result)) {
        return M11_GAME_INPUT_IGNORED;
    }

    switch (result) {
    case THERON_V1_BOOT_HOST_RECEIPT_RESULT_REDRAW:
        return M11_GAME_INPUT_REDRAW;
    case THERON_V1_BOOT_HOST_RECEIPT_RESULT_RETURN_TO_MENU:
        return M11_GAME_INPUT_RETURN_TO_MENU;
    case THERON_V1_BOOT_HOST_RECEIPT_RESULT_IGNORED:
    default:
        return M11_GAME_INPUT_IGNORED;
    }
}

static void m11_theron_update_track01_cdda_lifecycle(M11_GameViewState *state)
{
    int title_active;

    if (!state) {
        return;
    }
    title_active = state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02 &&
        state->theronState.startup_phase == THERON_STARTUP_PHASE_TITLE;
    (void)theron_v1_track01_cdda_lifecycle_update(
        &state->theronTrack01CddaHandoff,
        title_active,
        &state->theronTrack01CddaStream);
}

/* Title music is admitted only from the same hash-verified CUE provenance
 * that admitted Track 02.  In particular, never infer a CDDA companion for
 * a loose BIN/ISO launch. */
static void m11_theron_bind_track01_cdda_handoff(
    M11_GameViewState *state,
    const char *cue_path,
    const char *verified_track02_md5)
{
    if (!state) {
        return;
    }
    theron_v1_track01_cdda_stream_stop(&state->theronTrack01CddaStream);
    memset(&state->theronTrack01CddaHandoff, 0,
           sizeof(state->theronTrack01CddaHandoff));
    if (!cue_path || !m11_path_has_extension(cue_path, ".cue") ||
        !verified_track02_md5 || !verified_track02_md5[0]) {
        return;
    }
    (void)theron_v1_track01_cdda_handoff_from_verified_media(
        cue_path, verified_track02_md5, &state->theronTrack01CddaHandoff);
}

static int m11_theron_apply_boot_runtime_receipt(
    M11_GameViewState *state,
    const Theron_V1_BootStartupRuntimeReceipt *receipt)
{
    if (!state || !receipt || !receipt->profile || !receipt->world ||
        !receipt->viewport || !receipt->assets) {
        return 0;
    }
    state->active = 1;
    state->startedFromLauncher = 1;
    state->sourceKind = M11_GAME_SOURCE_THERON_TRACK02;
    snprintf(state->bootAssetMd5,
             sizeof(state->bootAssetMd5),
             "%s",
             receipt->boot_asset_md5);
    snprintf(state->title, sizeof(state->title), "%s", receipt->title);
    snprintf(state->sourceId,
             sizeof(state->sourceId),
             "%s",
             receipt->source_id);
    snprintf(state->dungeonPath,
             sizeof(state->dungeonPath),
             "%s",
             receipt->dungeon_path);
    state->theronBootProfile = receipt->profile;
    state->theronWorld = receipt->world;
    state->theronViewport = receipt->viewport;
    state->theronAssets = receipt->assets;
    memset(&state->theronTrack01CddaHandoff,
           0,
           sizeof(state->theronTrack01CddaHandoff));
    /* THQUEST.ASM T400 startup handoff: boot owns the fresh Track 02
     * title-gate receipts through runtime detach. Accept then advances to
     * stage-select; the next explicit input opens the Soul Room. */
    m11_theron_apply_startup_state_receipt(
        state,
        &receipt->initial_state_receipt);
    m11_theron_apply_startup_state_receipt(
        state,
        &receipt->save_resume_state_receipt);
    m11_theron_apply_startup_media_state_receipt(
        state,
        &receipt->startup_media_state_receipt);
    (void)m11_theron_apply_startup_host_receipt(
        state,
        &receipt->launch_host_receipt,
        NULL);
    m11_theron_update_track01_cdda_lifecycle(state);
    return 1;
}

static void m11_theron_boot_runtime_startup_snapshot(
    const M11_GameViewState *state,
    Theron_V1_BootRuntimeStartupSnapshot *out_snapshot)
{
    if (!out_snapshot) {
        return;
    }
    memset(out_snapshot, 0, sizeof(*out_snapshot));
    if (!state) {
        return;
    }
    out_snapshot->startup_phase = state->theronState.startup_phase;
    out_snapshot->selected_dungeon = state->theronState.selected_dungeon;
    out_snapshot->boot_profile = state->theronBootProfile;
    out_snapshot->world = (const Theron_V1_World*)state->theronWorld;
    out_snapshot->assets = state->theronAssets;
    out_snapshot->startup_cursor = state->theronState.startup_cursor;
    out_snapshot->continue_focus =
        state->theronState.save_resume_continue_focus;
    out_snapshot->resume_claim = state->theronState.save_resume_claim;
    out_snapshot->tqsv_slot = state->theronState.save_resume_active_slot;
    out_snapshot->srm_slot =
        state->theronState.save_resume_srm_active_slot;
    out_snapshot->srm_import_status =
        state->theronState.save_resume_srm_import_status;
    out_snapshot->srm_root = state->theronState.save_resume_srm_root;
    out_snapshot->startup_text_prompt =
        state->theronState.startup_text_prompt;
    out_snapshot->startup_roster_names =
        state->theronState.startup_roster_names;
    out_snapshot->startup_roster_titles =
        state->theronState.startup_roster_titles;
    out_snapshot->startup_roster_name_count =
        state->theronState.startup_roster_name_count;
    out_snapshot->selected_mirrors_mask =
        state->theronState.selected_mirrors_mask;
    out_snapshot->companion_count = state->theronState.companion_count;
    out_snapshot->selected_mirror_order =
        state->theronState.selected_mirror_order;
    out_snapshot->selected_mirror_order_count =
        THERON_STARTUP_MAX_COMPANIONS;
}

