static M11_GameInputResult m11_theron_handle_startup_pointer(
    M11_GameViewState* state,
    int x,
    int y) {
    Theron_V1_BootStartupFullStartReceipt full_start;
    Theron_StartupActionHostReceipt receipt;

    theron_v1_startup_action_host_receipt_init(&receipt);

    if (!state ||
        state->sourceKind != M11_GAME_SOURCE_THERON_TRACK02 ||
        state->theronState.startup_phase == THERON_STARTUP_PHASE_IN_DUNGEON ||
        state->theronState.level_loaded) {
        return M11_GAME_INPUT_IGNORED;
    }
    /* Keep pointer activation on the same startup route as keyboard Enter.
     * Track 02 may reach the forcefield before the positive dungeon capture
     * exists; that is an in-menu admission boundary, not a request to leave
     * the Theron launcher.  Let the boot receipt publish the precise status
     * and keep the user on the Soul Room screen. */
    if (!m11_theron_boot_runtime_startup_full_start_receipt(state,
                                                            NULL,
                                                            &full_start) ||
        !theron_v1_boot_startup_execute_pointer_from_full_start_receipt(
            &full_start,
            x,
            y,
            &receipt)) {
        return m11_theron_apply_startup_action_host_receipt(state, &receipt);
    }
    return m11_theron_apply_startup_action_host_receipt(state, &receipt);
}

static int m11_csb_fmtowns_inventory_slot_rectangle(
    const M11_GameViewState *state, int source_slot_box,
    int *out_x, int *out_y, int *out_width, int *out_height)
{
    const CSB_V1_BootProfile *profile;
    int slot = source_slot_box - 8;
    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !state->csbBootProfile || slot < 0 || slot >= 30) return 0;
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if ((profile->variant_id != CSB_V1_VARIANT_FMTOWNS_EN &&
         profile->variant_id != CSB_V1_VARIANT_FMTOWNS_JA) ||
        !profile->graphics_verified ||
        !profile->fmtowns_inventory_rectangles_valid) return 0;
    if (out_x) *out_x = profile->fmtowns_inventory_rectangle_x[slot];
    if (out_y) *out_y = profile->fmtowns_inventory_rectangle_y[slot];
    if (out_width) *out_width = profile->fmtowns_inventory_rectangle_width[slot];
    if (out_height) *out_height = profile->fmtowns_inventory_rectangle_height[slot];
    return profile->fmtowns_inventory_rectangle_width[slot] > 0 &&
           profile->fmtowns_inventory_rectangle_height[slot] > 0;
}

static M11_GameInputResult m11_nexus_handle_startup_pointer(
    M11_GameViewState* state,
    int x,
    int y) {
    if (!state ||
        state->sourceKind != M11_GAME_SOURCE_NEXUS_DGN ||
        !state->nexusEngine) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (state->nexusState.title_active) {
        if (!state->nexusState.startup_host_capture_ready ||
            !state->nexusState.startup_menu_capture_uses_real_assets ||
            !state->nexusState.startup_title_menu_capture_route_joined ||
            !state->nexusState.startup_host_route_capture_matrix_ready ||
            !state->nexusState.startup_host_route_capture_matrix_exact) {
            m11_set_status(state, "ASSETS", "NEXUS MENU CAPTURE REQUIRED");
            return M11_GAME_INPUT_IGNORED;
        }
        Nexus_V1_LauncherRuntimeStartupSnapshot snapshot;
        Nexus_V1_StartupTitleExecution execution;
        Nexus_V1_StartupHostActionReceipt receipt;
        m11_nexus_runtime_startup_snapshot(state, &snapshot);
        if (!nexus_v1_launcher_startup_execute_title_pointer_from_snapshot(
                &snapshot,
                &execution,
                &receipt)) {
            return M11_GAME_INPUT_IGNORED;
        }
        return m11_nexus_apply_startup_action_receipt(state, &receipt);
    }
    if (state->nexusState.startup_save_select_active) {
        /* The startup layout helpers retain compatibility hit regions for
         * isolated state tests, but their fixed 320x224 rectangles are not a
         * Saturn input trace. Do not let them mutate the live M11 route until
         * the save-menu VDP/input capture is joined to this exact package. */
        if (!state->nexusState.startup_host_capture_ready ||
            !state->nexusState.startup_save_route_saturn_capture_exact ||
            !state->nexusState.startup_host_route_capture_matrix_ready ||
            !state->nexusState.startup_host_route_capture_matrix_exact) {
            m11_set_status(state, "ASSETS", "NEXUS SAVE MENU CAPTURE REQUIRED");
            return M11_GAME_INPUT_IGNORED;
        }
        Nexus_V1_LauncherRuntimeStartupSnapshot snapshot;
        Nexus_V1_StartupSaveExecution execution;
        Nexus_V1_StartupHostActionReceipt receipt;
        m11_nexus_runtime_startup_snapshot(state, &snapshot);
        if (!nexus_v1_launcher_startup_execute_save_pointer_from_snapshot(
                &snapshot,
                x,
                y,
                m11_nexus_startup_load_save_callback,
                state,
                &execution,
                &receipt)) {
            return M11_GAME_INPUT_IGNORED;
        }
        return m11_nexus_apply_startup_action_receipt(state, &receipt);
    }
    if (state->nexusState.champion_select_active) {
        /* As above, the planner's champion rows/footer are not proof of the
         * Saturn menu's actual VDP/input coordinates. Keep pointer-driven
         * roster changes capture-gated, including the START footer. */
        if (!state->nexusState.startup_host_capture_ready ||
            !state->nexusState.startup_champion_route_saturn_capture_exact ||
            !state->nexusState.startup_host_route_capture_matrix_ready ||
            !state->nexusState.startup_host_route_capture_matrix_exact) {
            m11_set_status(state, "ASSETS", "NEXUS CHAMPION MENU CAPTURE REQUIRED");
            return M11_GAME_INPUT_IGNORED;
        }
        Nexus_V1_LauncherRuntimeStartupSnapshot snapshot;
        Nexus_V1_StartupHostFacts facts;
        Nexus_V1_StartupChampionSnapshot pointer_snapshot;
        Nexus_V1_StartupAction pointer_action;
        Nexus_V1_StartupChampionExecution execution;
        Nexus_V1_StartupHostActionReceipt receipt;
        Nexus_V1_StartupDrawCommand startup_commands[80];
        Nexus_V1_DgnRenderCommand commands[NEXUS_V1_DGN_VIEW_RENDER_MAX_COMMANDS];
        Nexus_V1_StartupHostCallerReceipt host_caller_receipt;
        M11_GameInputResult result;
        int host_caller_valid = 0;

        memset(&facts, 0, sizeof(facts));
        memset(&pointer_snapshot, 0, sizeof(pointer_snapshot));
        memset(&pointer_action, 0, sizeof(pointer_action));
        m11_nexus_runtime_startup_snapshot(state, &snapshot);
        if (nexus_v1_launcher_startup_host_facts_from_snapshot(
                &snapshot, &facts) &&
            nexus_v1_startup_champion_handle_pointer_from_facts(
                facts.champion_pool,
                &pointer_snapshot,
                facts.slot_mask,
                facts.champion_cursor,
                facts.champion_frame,
                x,
                y,
                &pointer_action) &&
            pointer_action.kind == NEXUS_V1_STARTUP_ACTION_START_DUNGEON) {
            if (!m11_nexus_refresh_startup_host_caller(
                    state,
                    M12_MENU_INPUT_ACTION,
                    startup_commands,
                    (int)(sizeof(startup_commands) /
                          sizeof(startup_commands[0])),
                    commands,
                    (int)(sizeof(commands) / sizeof(commands[0])),
                    &host_caller_receipt)) {
                return M11_GAME_INPUT_IGNORED;
            }
            receipt = host_caller_receipt.ownership.runtime_route
                .host_action_receipt;
            result = m11_nexus_apply_startup_action_receipt(state, &receipt);
            if (state->nexusState.startup_dgn_render_blocked ||
                state->nexusState.startup_dgn_viewport_host_blocks_runtime) {
                m11_set_status(state, "NEXUS STARTUP",
                               m11_nexus_startup_render_blocker_message(state));
                return M11_GAME_INPUT_RETURN_TO_MENU;
            }
            return result;
        }
        m11_nexus_runtime_startup_snapshot(state, &snapshot);
        if (!nexus_v1_launcher_startup_execute_champion_pointer_from_snapshot(
                &snapshot,
                x,
                y,
                &execution,
                &receipt)) {
            return M11_GAME_INPUT_IGNORED;
        }
        if (execution.kind == NEXUS_V1_STARTUP_CHAMPION_EXEC_START_DUNGEON) {
            host_caller_valid = m11_nexus_refresh_startup_host_caller(
                state, M12_MENU_INPUT_ACTION, startup_commands,
                (int)(sizeof(startup_commands) / sizeof(startup_commands[0])),
                commands, (int)(sizeof(commands) / sizeof(commands[0])),
                &host_caller_receipt);
        }
        result = m11_nexus_apply_startup_action_receipt(state, &receipt);
        if (execution.kind == NEXUS_V1_STARTUP_CHAMPION_EXEC_START_DUNGEON &&
            (state->nexusState.startup_dgn_render_blocked ||
             state->nexusState.startup_dgn_viewport_host_blocks_runtime)) {
            m11_set_status(state, "NEXUS STARTUP",
                           m11_nexus_startup_render_blocker_message(state));
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
        if (!host_caller_valid) {
            (void)m11_nexus_refresh_startup_host_caller(
                state, M12_MENU_INPUT_NONE, startup_commands,
                (int)(sizeof(startup_commands) / sizeof(startup_commands[0])),
                commands, (int)(sizeof(commands) / sizeof(commands[0])),
                &host_caller_receipt);
        }
        return result;
    }
    return M11_GAME_INPUT_IGNORED;
}

static M11_GameInputResult m11_dm2_startup_enter_credits(
    M11_GameViewState *state)
{
    const DM2_V1_BootProfile *profile;
    const DM2_V1_AssetLoader *loader;
    DM2_V1_QueryGdatSummaryImageReceipt image;
    DM2_V1_InterfacePalette palette;
    uint32_t raw_hash = 0u;
    uint32_t raw_bytes = 0u;
    int credits_material_ready = 0;

    if (!state || !(profile = (const DM2_V1_BootProfile *)state->dm2BootProfile))
        return M11_GAME_INPUT_IGNORED;
    /* The Macintosh title menu owns Credits.MooV. */
    if (m11_dm2_is_mac_profile(profile) &&
        (profile->mac_movie_view_present_mask &
         (1u << DM2_V1_MAC_MOVIE_CREDITS)) != 0u) {
        state->dm2State.startup_credits_active = 1;
        state->dm2State.startup_credits_remaining_ticks = 0;
        if (!m11_dm2_bind_mac_movie_index(
                state, DM2_V1_MAC_MOVIE_CREDITS)) {
            /* A present authentic movie that cannot be decoded is a black,
             * fail-closed Mac credits route, never a PC image substitution. */
            state->dm2MacMovieRejected = 1;
        }
        return M11_GAME_INPUT_REDRAW;
    }
    /* SKProject startend.cpp::DM2_SHOW_CREDITS draws TITLE/0/dt07/1.
     * The pointer caller has already proved the matching RAW4 rectangle. */
    loader = dm2_v1_boot_asset_loader(
        (const DM2_V1_BootProfile *)state->dm2BootProfile);
    memset(&image, 0, sizeof(image));
    if (loader &&
        dm2_v1_query_gdat_summary_image_receipt(
            loader, DM2_GDAT_CATEGORY_TITLE, 0, 1, &image) &&
        image.accepted && image.metadata.width == 320u &&
        image.metadata.height == 200u &&
        ((image.metadata.bits_per_pixel == 8u &&
          dm2_v1_boot_interface_palette(
              (DM2_V1_BootProfile *)state->dm2BootProfile, &palette)) ||
         (image.metadata.bits_per_pixel == 4u && image.colors == 16u &&
          image.palette_hash != 0u)) &&
        dm2_v1_boot_gdat_raw_asset_proof(
            (DM2_V1_BootProfile *)state->dm2BootProfile,
            DM2_GDAT_CATEGORY_TITLE, 0, 1, 0x32435244u,
            &raw_hash, &raw_bytes) && raw_hash != 0u && raw_bytes > 0u) {
        credits_material_ready = 1;
    }
    if (!credits_material_ready) {
        /* The original event loop simply leaves TITLE/0/dt07/1 unavailable
         * when its material transaction cannot be proven.  There is no
         * source-owned status-panel string at this boundary, so do not
         * substitute an M11 English diagnostic. */
        return M11_GAME_INPUT_REDRAW;
    }
    state->dm2State.startup_credits_active = 1;
    state->dm2State.startup_credits_remaining_ticks = 1800;
    return M11_GAME_INPUT_REDRAW;
}

static M11_GameInputResult m11_dm2_handle_startup_pointer(
    M11_GameViewState *state,
    int x,
    int y,
    int buttonMask)
{
    DM2_V1_StartupExecution execution;
    DM2_V1_StartupHostActionReceipt action_receipt;
    DM2_V1_StartupMenuAuxPointerLayout aux_layout;

    if (!state ||
        state->sourceKind != M11_GAME_SOURCE_DM2_BOOT ||
        !state->dm2State.startup_menu_active) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (state->dm2DosMveIntroActive || state->dm2DosMveIntroRejected ||
        state->dm2FmtownsTitleBound ||
        (m11_dm2_is_fmtowns_profile(
             (const DM2_V1_BootProfile *)state->dm2BootProfile) &&
         state->dm2FmtownsTitleFinished &&
         !m11_dm2_fmtowns_skull_menu_ready(state))) {
        /* AUTOEXEC's TITLE stream precedes SKULL.EXP and has no menu click
         * table.  SKProject's SHOW_MENU_SCREEN only enters the GDAT-driven
         * mouse loop after that handoff, so a host pointer event must stay
         * inert until the selected P3 GDAT receipt proves the SKULL page. */
        return M11_GAME_INPUT_IGNORED;
    }
    if (state->dm2State.startup_credits_active) {
        memset(&aux_layout, 0, sizeof(aux_layout));
        if (dm2_v1_boot_startup_menu_aux_pointer_layout(
                (DM2_V1_BootProfile *)state->dm2BootProfile, &aux_layout) &&
            aux_layout.valid &&
            m11_point_in_rect(x, y,
                              aux_layout.dismiss_credits.x,
                              aux_layout.dismiss_credits.y,
                              aux_layout.dismiss_credits.w,
                              aux_layout.dismiss_credits.h)) {
            /* SKProject startend.cpp::DM2_SHOW_CREDITS lines 1381-1401:
             * DM2_EVENT_LOOP exits on its common 0xEF event, whose source
             * click table accepts either mouse button.  Do not make the
             * host's left-button convention trap the source-owned credits
             * screen. */
            state->dm2State.startup_credits_active = 0;
            state->dm2State.startup_credits_remaining_ticks = 0;
            if (state->dm2MacMovieActive) {
                state->dm2MacMovieActive = 0;
                dm2_v1_mac_movie_decoder_close(&state->dm2MacMovieDecoder);
            }
            return M11_GAME_INPUT_REDRAW;
        }
        return M11_GAME_INPUT_IGNORED;
    }
    if (state->dm2MacMovieActive) return M11_GAME_INPUT_IGNORED;
    memset(&aux_layout, 0, sizeof(aux_layout));
    if ((buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0 &&
        dm2_v1_boot_startup_menu_aux_pointer_layout(
            (DM2_V1_BootProfile *)state->dm2BootProfile, &aux_layout) &&
        aux_layout.valid) {
        if (m11_point_in_rect(x, y, aux_layout.show_credits.x,
                              aux_layout.show_credits.y,
                              aux_layout.show_credits.w,
                              aux_layout.show_credits.h)) {
            return m11_dm2_startup_enter_credits(state);
        }
        if (m11_point_in_rect(x, y, aux_layout.quit_game.x,
                              aux_layout.quit_game.y,
                              aux_layout.quit_game.w,
                              aux_layout.quit_game.h)) {
            /* SKProject HANDLE_UI_EVENT 0xE0 returns from SKULL.EXP; the
             * selected AUTOEXEC then owns the HME-242 END stream. Do not
             * replace that native transition with an immediate host exit. */
            if (m11_dm2_is_fmtowns_profile(
                    (const DM2_V1_BootProfile *)state->dm2BootProfile)) {
                return m11_dm2_bind_fmtowns_end(state)
                    ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
            }
            if (m11_dm2_is_amiga_profile(
                    (const DM2_V1_BootProfile *)state->dm2BootProfile)) {
                return m11_dm2_bind_amiga_stream(state, 2)
                    ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
            }
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
    }
    /* main_loop_m11 maps every SDL window point through its current content
     * rectangle before M11_GameView_HandlePointerButton reaches this source
     * handler.  Thus x/y are already the original 320x200 coordinates used
     * by SHOW_MENU_SCREEN's GDAT rectangles.  Mapping a miss again treated a
     * source coordinate as a host-window coordinate, moving a valid click on
     * scaled presentations.  Keep this boundary source-coordinate-only;
     * direct callers have the same public HandlePointerButton contract. */
    /* The SHOW_MENU_SCREEN RAW4 table installs 0xD7/0xD9 as primary-mouse
     * actions.  c_tmouse keeps the secondary press as a distinct event
     * (button 2 / event 1), whereas a left press becomes event 2.  Credits
     * deliberately uses its common 0xEF dismissal route above, but a
     * secondary press must not be reinterpreted as NEW or RESUME here.
     * Source: SKProject c_tmouse.cpp::command_interpreter and
     * SkWinCore.cpp::SHOW_MENU_SCREEN/HANDLE_UI_EVENT. */
    if ((buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (m11_dm2_preselection_input_active(state)) {
        M11_GameInputResult result = m11_dm2_preselection_mirror_pointer(
            state, x, y);
        if (result != M11_GAME_INPUT_IGNORED) return result;
    }
    if (!m11_dm2_boot_runtime_startup_pointer(
            state, x, y, &execution, &action_receipt)) {
        /* The original SHOW_MENU_SCREEN input table owns the only admissible
         * menu hit regions (GDAT rect ids 0x0197/0x0199, dispatched as
         * 0xD7/0xD9).  Do not fall through to Firestaff's old row/panel
         * layout: it could turn host-invented save rows into a gameplay
         * action. */
        return M11_GAME_INPUT_IGNORED;
    }
    return m11_dm2_startup_apply_host_action_receipt(state, &action_receipt);
}

static void m11_clear_v1_mouth_visual(M11_GameViewState* state) {
    if (!state) return;
    state->v1MouthVisualIconIndex = 0;
    state->v1MouthAnimationFrameCount = 0;
    state->v1MouthAnimationFrameIndex = 0;
    state->v1MouthAnimationDelayRemaining = 0;
    memset(state->v1MouthAnimationIcons, 0, sizeof(state->v1MouthAnimationIcons));
    memset(state->v1MouthAnimationDelays, 0, sizeof(state->v1MouthAnimationDelays));
}

static int m11_start_v1_mouth_animation(M11_GameViewState* state,
                                        const DM1ConsumableResultPc34* result) {
    DM1ConsumableMouthAnimationFramePc34 frames[DM1_CONSUMABLE_MOUTH_ANIMATION_FRAME_COUNT_PC34];
    int frameCount;
    int i;
    if (!state) return 0;

    frameCount = dm1_inventory_consumables_mouth_animation_pc34(
        result, frames, DM1_CONSUMABLE_MOUTH_ANIMATION_FRAME_COUNT_PC34);
    if (frameCount <= 0) {
        return 0;
    }

    state->v1MouthAnimationFrameCount = frameCount;
    state->v1MouthAnimationFrameIndex = 0;
    for (i = 0; i < frameCount && i < DM1_CONSUMABLE_MOUTH_ANIMATION_FRAME_COUNT_PC34; ++i) {
        state->v1MouthAnimationIcons[i] = frames[i].iconIndex;
        state->v1MouthAnimationDelays[i] = frames[i].delayTicks;
    }
    state->v1MouthVisualIconIndex = state->v1MouthAnimationIcons[0];
    state->v1MouthAnimationDelayRemaining = state->v1MouthAnimationDelays[0];
    return 1;
}

static int m11_tick_v1_mouth_animation(M11_GameViewState* state) {
    if (!state || state->v1MouthAnimationFrameCount <= 0) {
        return 0;
    }
    if (state->v1MouthAnimationDelayRemaining > 0) {
        --state->v1MouthAnimationDelayRemaining;
        if (state->v1MouthAnimationDelayRemaining > 0) {
            return 0;
        }
    }

    if (state->v1MouthAnimationFrameIndex + 1 >= state->v1MouthAnimationFrameCount) {
        state->v1MouthAnimationFrameCount = 0;
        state->v1MouthAnimationFrameIndex = 0;
        state->v1MouthAnimationDelayRemaining = 0;
        return 0;
    }

    ++state->v1MouthAnimationFrameIndex;
    state->v1MouthVisualIconIndex =
        state->v1MouthAnimationIcons[state->v1MouthAnimationFrameIndex];
    state->v1MouthAnimationDelayRemaining =
        state->v1MouthAnimationDelays[state->v1MouthAnimationFrameIndex];
    return 1;
}

M11_GameInputResult M11_GameView_HandlePointer(M11_GameViewState* state,
                                               int x,
                                               int y,
                                               int primaryButton) {
    M11_GameInputResult r = M11_GameView_HandlePointerButton(
        state,
        x,
        y,
        primaryButton ? DM1_V1_MOUSE_MASK_LEFT_PC34 : 0);
    /* When a click returned REDRAW and may have mutated world state
     * (inventory pickup, slot place, chest open, eye, mouth, action
     * row, action cell, etc.), refresh the world hash so that
     * determinism assertions (test_m11_inventory_full_panel) can
     * verify the world snapshot.  REDRAW-only clicks that didn't
     * mutate the world still trigger a hash refresh — F0891 is
     * idempotent and cheap. */
    if (r == M11_GAME_INPUT_REDRAW && state) {
        m11_refresh_world_hash_after_click(state);
    }
    return r;
}

static M12_MenuInput m11_touch_gesture_command_to_input(int command)
{
    /* ReDMCSB DEFS.H:238-243 names C001..C006; COMMAND.C F0380 dispatches
     * the very same queue entries to CLIKMENU.C F0365/F0366.  Keep this
     * translation beside the touch ingress rather than manufacturing a
     * second movement path. */
    switch (command) {
    case 1: return M12_MENU_INPUT_TURN_LEFT;
    case 2: return M12_MENU_INPUT_TURN_RIGHT;
    case 3: return M12_MENU_INPUT_UP;
    case 4: return M12_MENU_INPUT_STRAFE_RIGHT;
    case 5: return M12_MENU_INPUT_DOWN;
    case 6: return M12_MENU_INPUT_STRAFE_LEFT;
    default: return M12_MENU_INPUT_NONE;
    }
}

M11_GameInputResult M11_GameView_HandleTouchEvent(M11_GameViewState* state,
                                                  M11_TouchEventKind kind,
                                                  int x,
                                                  int y,
                                                  uint32_t nowMs)
{
    FsGestureFeedEvent event;
    FsGestureType gesture = FS_GG_GESTURE_NONE;
    FsGestureGameCommand command;

    if (!state || !state->active) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (!fs_gesture_gate_is_initialized() ||
        !fs_gesture_gate_is_enabled(fs_gesture_gate_active_game())) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (kind == M11_TOUCH_EVENT_CANCEL) {
        /* SDL can cancel a contact when the window loses the gesture (for
         * example a system gesture or app deactivation).  Never let that
         * incomplete contact become the first half of a later source click
         * or double-tap. */
        fs_gesture_recognizer_reset();
        return M11_GAME_INPUT_IGNORED;
    }
    switch (kind) {
    case M11_TOUCH_EVENT_DOWN: event.kind = FS_GG_FEED_DOWN; break;
    case M11_TOUCH_EVENT_MOVE: event.kind = FS_GG_FEED_MOVE; break;
    case M11_TOUCH_EVENT_UP:   event.kind = FS_GG_FEED_UP;   break;
    default: return M11_GAME_INPUT_IGNORED;
    }
    event.x = x;
    event.y = y;
    event.nowMs = nowMs;
    if (!fs_gesture_recognizer_step(&event, &gesture) ||
        kind != M11_TOUCH_EVENT_UP) {
        return M11_GAME_INPUT_IGNORED;
    }

    /* COMMAND.C F0358 resolves a primary pointer hit against the original
     * UI rectangles.  A stationary finger therefore remains a real source
     * click, including CSB's startup/HUD/viewport route. */
    if (gesture == FS_GG_GESTURE_TAP) {
        if (state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02) {
            /* Theron host contract: short touch is authentic PC Engine
             * Button I, including startup actions and dungeon ticks. */
            return M11_GameView_HandleInput(
                state, M11_TheronTouchButtonInput(0));
        }
        return M11_GameView_HandlePointer(state, x, y, 1);
    }
    /* INPUT.C:641-664 forwards the secondary button independently.  The
     * existing gesture table documents a stationary long press as that
     * source-owned right-button affordance (for example C083). */
    if (gesture == FS_GG_GESTURE_LONG_PRESS) {
        if (state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02) {
            /* Theron host contract: long touch is authentic PC Engine
             * Button II; no synthetic pointer-zone action is introduced. */
            return M11_GameView_HandleInput(
                state, M11_TheronTouchButtonInput(1));
        }
        return M11_GameView_HandlePointerButton(
            state, x, y, DM1_V1_MOUSE_MASK_RIGHT_PC34);
    }
    if (fs_gesture_translate_with_reason(fs_gesture_gate_active_game(),
                                         gesture, &command, NULL) &&
        command.accepted) {
        M12_MenuInput input = m11_touch_gesture_command_to_input(
            command.gameCommand);
        if (input != M12_MENU_INPUT_NONE) {
            return M11_GameView_HandleInput(state, input);
        }
    }
    return M11_GAME_INPUT_IGNORED;
}

M11_GameInputResult M11_GameView_HandlePointerMove(M11_GameViewState* state,
                                                   int x,
                                                   int y) {
    if (!state || !state->active) {
        return M11_GAME_INPUT_IGNORED;
    }
    state->pointerPositionKnown = 1;
    state->pointerX = x;
    state->pointerY = y;
    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT &&
        state->dm2State.leader_hand_object != 0u &&
        M11_GameView_Dm2LeaderHandObjectIconAvailable(state)) {
        return M11_GAME_INPUT_REDRAW;
    }
    /* ReDMCSB CLIKVIEW.C keeps the held object attached to the mouse
     * pointer.  The host loop redraws only when this route reports a
     * change; returning IGNORED here left the source-owned object cursor
     * frozen after pickup and made it appear that no object was held. */
    if (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) != THING_NONE) {
        return M11_GAME_INPUT_REDRAW;
    }
    return M11_GAME_INPUT_IGNORED;
}

M11_GameInputResult M11_GameView_HandlePointerButtonRelease(
    M11_GameViewState* state,
    int x,
    int y,
    int buttonMask) {
    int space;
    int zoneId;
    int command;
    int destinationAccepted;
    int sourceSlotBox;
    int destinationSlotBox;
    if (!state || !state->active ||
        (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0) {
        return M11_GAME_INPUT_IGNORED;
    }
    /* Theron Button I is an instantaneous controller event.  There is no
     * DM1-style held-object drag/release route in this source boundary, so a
     * desktop mouse release must not fall through to DM1 inventory handling. */
    if (state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02) {
        (void)x;
        (void)y;
        return M11_GAME_INPUT_IGNORED;
    }
    state->pointerPositionKnown = 1;
    state->pointerX = x;
    state->pointerY = y;
    /* PANEL.C F0353 is dispatched when the button is released after C071.
     * It redraws the normal action-hand panel, which first closes G0426 and
     * then (for a container action hand) reopens it through non-eye F0333.
     * Handle this before generic drag release routing: the eye is a held
     * control, never an inventory drag source. */
    if (state->v1EyePressActive) {
        return m11_finish_v1_eye_press(state) ? M11_GAME_INPUT_REDRAW :
                                                M11_GAME_INPUT_IGNORED;
    }
    {
        const int amiga_result = m11_csb_handle_amiga_appb_pointer_release(
            state, x, y, buttonMask);
        if (amiga_result != 0) {
            return amiga_result > 0 ? M11_GAME_INPUT_REDRAW :
                                      M11_GAME_INPUT_IGNORED;
        }
    }
    if (!state->v1InventoryDragActive) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (state->v1InventoryDragSourceSlotBox == 0) {
        state->v1InventoryDragActive = 0;
        return M11_GAME_INPUT_IGNORED;
    }
    sourceSlotBox = state->v1InventoryDragSourceSlotBox;
    state->v1InventoryDragActive = 0;
    state->v1InventoryDragSourceSlotBox = 0;
    if (!state->inventoryPanelActive || state->showDebugHUD) {
        return M11_GAME_INPUT_IGNORED;
    }
    {
        int nativeSlot = -1;
        if (m11_csb_fmtowns_inventory_source_slot_at_point(state, x, y, &nativeSlot) &&
            nativeSlot + 8 == sourceSlotBox) return M11_GAME_INPUT_REDRAW;
    }
    /* The C211..C218 status-hand boxes are a separate ReDMCSB COMMAND.C
     * route from the C507..C544 inventory boxes. The mouse-down path already
     * handled them, but mouse-up used to consult only the inventory list, so
     * a held object could never be placed into another champion's hand after
     * dragging. */
    space = DM1_V1_MOUSE_SPACE_NONE_PC34;
    zoneId = 0;
    command = DM1_V1_MouseRoutes_CommandForScreenPointPc34Compat(
        DM1_V1_MOUSE_LIST_INTERFACE_PC34, x, y,
        DM1_V1_MOUSE_MASK_LEFT_PC34, &space, &zoneId);
    destinationSlotBox = 0;
    destinationAccepted = 0;
    if (command >= 20 && command <= 27 &&
        zoneId >= 211 && zoneId <= 218) {
        destinationSlotBox = command - 20;
        /* F0302 commits the source-box transaction on mouse-down.  A normal
         * click consequently reaches the same C211..C218 box on mouse-up;
         * consuming that release must not exchange the object straight back
         * out of the leader hand. */
        if (destinationSlotBox == sourceSlotBox) {
            return M11_GAME_INPUT_REDRAW;
        }
        destinationAccepted = m11_process_v1_status_hand_slot_box_click(
            state, destinationSlotBox);
    }
    if (!destinationAccepted) {
        int destinationSpace = DM1_V1_MOUSE_SPACE_NONE_PC34;
        int destinationZone = 0;
        int destinationCommand =
            DM1_V1_MouseRoutes_CommandForScreenPointPc34Compat(
                DM1_V1_MOUSE_LIST_INVENTORY_PC34, x, y,
                DM1_V1_MOUSE_MASK_LEFT_PC34,
                &destinationSpace, &destinationZone);

        /* F0378 reaches G0456 chest children through the C101 parent. */
        if (destinationCommand == 81 && destinationZone == 101 &&
            m11_v1_open_chest_valid(state)) {
            destinationCommand = DM1_V1_MouseRoutes_CommandForScreenPointPc34Compat(
                DM1_V1_MOUSE_LIST_PANEL_CHEST_PC34, x, y,
                DM1_V1_MOUSE_MASK_LEFT_PC34, &destinationSpace, &destinationZone);
        }

        /* The C507..C544 inventory/chest path is known before its transaction
         * is entered, so reject a mouse-up over the original source slot.
         * This must happen before m11_process_v1_inventory_pointer_target:
         * that helper intentionally commits a slot exchange. */
        /* CHAMPION.C F0302:689-711 also owns C537..C544 chest exchanges.
         * Releasing over the pressed chest slot must not run F0302 twice. */
        if (destinationCommand >= 28 && destinationCommand <= 65 &&
            destinationSpace == DM1_V1_MOUSE_SPACE_VIEWPORT_PC34 &&
            destinationZone >= 507 && destinationZone <= 544) {
            destinationSlotBox = destinationCommand - 20;
            if (destinationSlotBox == sourceSlotBox) {
                return M11_GAME_INPUT_REDRAW;
            }
        }
        destinationAccepted = m11_process_v1_inventory_pointer_target(
            state, x, y, &destinationSlotBox);
    }
    /* CLIKVIEW's slot transaction is committed at mouse-down.  Mouse-up
     * only supplies a second destination when a drag crossed to another
     * source slot.  Re-running the same source box here swaps the object
     * straight back into the leader hand, producing the apparent vanish/
     * throw seen in the Hall of Champions. */
    if (!destinationAccepted) {
        return M11_GAME_INPUT_IGNORED;
    }
    return M11_GAME_INPUT_REDRAW;
}

/* CSB 2.x Atari ST keeps G0447's status clicks and C007..C010 inventory
 * bars as adjacent, but distinct, primary-mouse zones. The bar graphics
 * begin at 44/113/182/251 rather than the PC rows' 43/112/181/250, leaving
 * one physical pixel between a status box and its bar. The common M11 HUD
 * route deliberately makes a whole painted status tile convenient to click;
 * that wider host route is not source-faithful for the native ST page.
 *
 * ReDMCSB COMMAND.C:82-100, G0447_as_Graphic561_PrimaryMouseInput_Interface:
 * the Atari comments document both the +1 left edges and separate C012..C015
 * versus C007..C010 command ownership. */
static int m11_csb_native_champion_icon_pointer(
    M11_GameViewState *state, int icon_index, unsigned int *held_icon_ordinal,
    int platform_kind, M11_GameInputResult *out_result);

static int m11_csb_atari_st_top_row_pointer(
    M11_GameViewState *state, int x, int y, int button_mask,
    M11_GameInputResult *out_result)
{
    static const int status_left[CHAMPION_MAX_PARTY] = { 0, 69, 138, 207 };
    static const int bar_left[CHAMPION_MAX_PARTY] = { 44, 113, 182, 251 };
    const CSB_V1_BootProfile *profile;
    int slot;

    if (out_result) *out_result = M11_GAME_INPUT_IGNORED;
    if (!state || !out_result || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        y < 0 || y > 28) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (!profile || (profile->variant_id != CSB_V1_VARIANT_ST20_EN &&
                     profile->variant_id != CSB_V1_VARIANT_ST21_EN)) {
        return 0;
    }
    if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0) {
        int icon_index = -1;
        /* COMMAND.C G0447 keeps C125..C128 on ST 2.x.  GEM owns the cursor
         * raster; IO.C F0070 owns the durable GAMEBLOCK transaction. */
        if (x >= 274 && x <= 299 && y <= 13) icon_index = 0;
        else if (x >= 301 && x <= 319 && y <= 13) icon_index = 1;
        else if (x >= 301 && x <= 319 && y >= 15) icon_index = 2;
        else if (x >= 274 && x <= 299 && y >= 15) icon_index = 3;
        if (icon_index >= 0) {
            return m11_csb_native_champion_icon_pointer(
                state, icon_index, &state->csbAtariStHeldChampionIconOrdinal,
                3, out_result);
        }
        for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
            if (x >= status_left[slot] && x <= status_left[slot] + 42) {
                *out_result = m11_set_active_champion(state, slot)
                    ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
                return 1;
            }
            if (x >= bar_left[slot] && x <= bar_left[slot] + 22) {
                *out_result = m11_toggle_champion_inventory(state, slot);
                return 1;
            }
        }
        /* The four one-pixel seams are deliberately inert. */
        if (x == 43 || x == 112 || x == 181 || x == 250 ||
            x == 67 || x == 68 || x == 136 || x == 137 ||
            x == 205 || x == 206 || x == 274) {
            return 1;
        }
        /* G0447 owns its icon-grid gaps too; they are inert, not PC hits. */
        if (x >= 274 && x <= 319) return 1;
    } else if ((button_mask & DM1_V1_MOUSE_MASK_RIGHT_PC34) != 0) {
        /* ReDMCSB COMMAND.C G0447:97-100 (MEDIA413): Atari ST 2.x
         * installs a second C007..C010 set for the right button.  Unlike
         * the left bar-graph strips, each source rectangle spans its whole
         * 67-pixel champion tile.  This is not the generic PC HUD route:
         * its boundaries intentionally retain the ST's two-pixel gaps. */
        for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
            if (x >= status_left[slot] && x <= status_left[slot] + 66) {
                *out_result = m11_toggle_champion_inventory(state, slot);
                return 1;
            }
        }
        /* G0447 owns the entire native top row for a right click.  Its
         * unlisted two-pixel inter-tile gaps and the icon grid are inert;
         * they must still be consumed here, otherwise the generic PC HUD
         * route can incorrectly reinterpret a gap as a host inventory hit. */
        if (x >= 0 && x <= 319) return 1;
    }
    return 0;
}

/* The A31/A35 interface table is not the PC table with an Amiga skin.  In
 * particular, G0447 installs the four left-click C012..C015 status boxes
 * before the C007..C010 bar strips (and installs C007..C010 over the whole
 * status box for a right click).  The old native-page guard discarded every
 * left click in y=0..28, so a real Amiga C007 bar could not open C017 and a
 * C012 status click could not select its source champion.
 *
 * ReDMCSB COMMAND.C G0447:82-103 (MEDIA413 A31E/A31M/A35E/A35M) gives the
 * literal inclusive boxes below; F0380:2158-2184 sends C012..C015 to F0367
 * and C007..C010 to PANEL.C F0355. C125..C128 use F0070's durable
 * GAMEBLOCK formation transaction; its transient cursor raster remains
 * owned by the platform cursor layer and is never synthesized by M11. */
static int m11_csb_native_champion_icon_pointer(
    M11_GameViewState *state, int icon_index, unsigned int *held_icon_ordinal,
    int platform_kind, M11_GameInputResult *out_result)
{
    CSB_V1_BootProfile *profile;
    CsbV1F0070ChampionFormationStatePc34 formation;
    CsbV1F0070ChampionFormationReceiptPc34 receipt;
    int champion;

    if (out_result) *out_result = M11_GAME_INPUT_IGNORED;
    if (!state || !out_result || !held_icon_ordinal ||
        icon_index < 0 || icon_index >= 4 ||
        state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
        return 0;
    }
    profile = (CSB_V1_BootProfile *)state->csbBootProfile;
    if (!profile ||
        (platform_kind == 1 ? !m11_csb_is_amiga_profile(profile)
         : platform_kind == 2 ? !m11_csb_is_fmtowns_profile(profile)
         : platform_kind == 3 ? !(profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
                                  profile->variant_id == CSB_V1_VARIANT_ST21_EN)
                              : 1) ||
        !profile->runtime.party_state_valid) {
        return 0;
    }
    memset(&formation, 0, sizeof(formation));
    formation.champion_count = profile->runtime.party_state.ChampionCount;
    formation.party_direction = profile->runtime.party_state.PartyDirection;
    formation.held_icon_ordinal = *held_icon_ordinal;
    for (champion = 0;
         champion < formation.champion_count && champion < 4;
         ++champion) {
        const CSB_V1_Champion *source =
            &profile->runtime.party_state.Champions[champion];
        formation.cell[champion] = source->Cell;
        formation.direction[champion] = source->Direction;
        formation.attributes[champion] = source->Attributes;
    }
    /* ReDMCSB COMMAND.C G0447:375-391 binds F31E/F31J C125..C128 through
     * C113..C116, while its A31/A35 table gives the distinct literal cells.
     * F0380:2164-2170 dispatches all of them solely to IO.C F0070.
     * F0070:2395-2647 owns the GAMEBLOCK Cell/Direction/ICON transaction;
     * its native Amiga sprite and F31 IODRV cursor rasters stay external. */
    if (!csb_v1_f0070_champion_formation_click_pc34(
            &formation, icon_index, &receipt)) {
        return 1; /* The native command was consumed but made no mutation. */
    }
    *held_icon_ordinal = formation.held_icon_ordinal;
    for (champion = 0;
         champion < formation.champion_count && champion < 4;
         ++champion) {
        CSB_V1_Champion *destination =
            &profile->runtime.party_state.Champions[champion];
        destination->Cell = formation.cell[champion];
        destination->Direction = formation.direction[champion];
        destination->Attributes = formation.attributes[champion];
    }
    m11_sync_csb_state_from_boot_profile(state, profile);
    *out_result = M11_GAME_INPUT_REDRAW;
    return 1;
}

static int m11_csb_amiga_top_row_pointer(
    M11_GameViewState *state, int x, int y, int button_mask,
    M11_GameInputResult *out_result)
{
    static const int status_left[CHAMPION_MAX_PARTY] = { 0, 69, 138, 207 };
    static const int bar_left[CHAMPION_MAX_PARTY] = { 43, 112, 181, 250 };
    const CSB_V1_BootProfile *profile;
    int slot;

    if (out_result) *out_result = M11_GAME_INPUT_IGNORED;
    if (!state || !out_result || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        y < 0 || y > 28) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (!m11_csb_is_amiga_profile(profile)) return 0;

    if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0) {
        int icon_index = -1;
        /* The native A31/A35 icon grid is 26/19 pixels wide rather than
         * I34E's 19-pixel grid. Its one-pixel row/column gaps are inert. */
        if (x >= 274 && x <= 299 && y <= 13) icon_index = 0;
        else if (x >= 301 && x <= 319 && y <= 13) icon_index = 1;
        else if (x >= 301 && x <= 319 && y >= 15) icon_index = 2;
        else if (x >= 274 && x <= 299 && y >= 15) icon_index = 3;
        if (icon_index >= 0) {
            return m11_csb_native_champion_icon_pointer(
                state, icon_index, &state->csbAmigaHeldChampionIconOrdinal,
                1, out_result);
        }
        for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
            if (x >= status_left[slot] && x <= status_left[slot] + 42) {
                *out_result = m11_set_active_champion(state, slot)
                    ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
                return 1;
            }
            if (x >= bar_left[slot] && x <= bar_left[slot] + 23) {
                *out_result = m11_toggle_champion_inventory(state, slot);
                return 1;
            }
        }
        /* C125..C128's native gaps must not reach PC geometry. */
        if (x >= 274 && x <= 319) return 1;
        return 0;
    }
    if ((button_mask & DM1_V1_MOUSE_MASK_RIGHT_PC34) != 0) {
        for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
            /* A31/A35's right C007..C010 box spans name, hands and bar. */
            if (x >= status_left[slot] && x <= status_left[slot] + 66) {
                *out_result = m11_toggle_champion_inventory(state, slot);
                return 1;
            }
        }
        if (x >= 274 && x <= 319) return 1;
    }
    return 0;
}

/* F31E/F31J use the zone-addressed G0447 table, rather than the permissive
 * host status-tile convenience route below.  In particular a left click in
 * C151..C154 selects its champion (C012..C015); only the adjacent C187..190
 * 24x29 strips toggle C017.  The F31 table also has the PC/I34E 19x14 icon
 * cells at x=281/301.  F31's IODRV cursor pixels are still source-owned,
 * but its durable C125..C128 F0070 transaction mutates GAMEBLOCK exactly
 * as in IO.C, so the pointer cells must not remain inert.
 *
 * ReDMCSB COMMAND.C:374-396 (MEDIA730 F31E / MEDIA731 F31J), especially
 * G0447 C007..C015 and C125..C128; layout-696 C113..C116/C151..C154/
 * C187..C190. */
static int m11_csb_fmtowns_top_row_pointer(
    M11_GameViewState *state, int x, int y, int button_mask,
    M11_GameInputResult *out_result)
{
    static const int status_left[CHAMPION_MAX_PARTY] = { 0, 69, 138, 207 };
    static const int bar_left[CHAMPION_MAX_PARTY] = { 43, 112, 181, 250 };
    const CSB_V1_BootProfile *profile;
    int slot;

    if (out_result) *out_result = M11_GAME_INPUT_IGNORED;
    if (!state || !out_result || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        y < 0 || y > 28) {
        return 0;
    }
    profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    if (!m11_csb_is_fmtowns_profile(profile)) return 0;

    if ((button_mask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0) {
        int icon_index = -1;
        if (x >= 281 && x <= 299 && y <= 13) icon_index = 0;
        else if (x >= 301 && x <= 319 && y <= 13) icon_index = 1;
        else if (x >= 301 && x <= 319 && y >= 15) icon_index = 2;
        else if (x >= 281 && x <= 299 && y >= 15) icon_index = 3;
        if (icon_index >= 0) {
            return m11_csb_native_champion_icon_pointer(
                state, icon_index, &state->csbFmtownsHeldChampionIconOrdinal,
                2, out_result);
        }
        for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
            if (x >= bar_left[slot] && x <= bar_left[slot] + 23) {
                *out_result = m11_toggle_champion_inventory(state, slot);
                return 1;
            }
            if (x >= status_left[slot] && x <= status_left[slot] + 42) {
                *out_result = m11_set_active_champion(state, slot)
                    ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
                return 1;
            }
        }
        /* F31's icon-grid gaps belong to G0447 but are not commands. */
        if (x >= 281 && x <= 319) return 1;
    } else if ((button_mask & DM1_V1_MOUSE_MASK_RIGHT_PC34) != 0) {
        for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
            if (x >= status_left[slot] && x <= status_left[slot] + 66) {
                *out_result = m11_toggle_champion_inventory(state, slot);
                return 1;
            }
        }
        if (x >= 274 && x <= 319) return 1;
    }
    return 0;
}

M11_GameInputResult M11_GameView_HandlePointerButton(M11_GameViewState* state,
                                                     int x,
                                                     int y,
                                                     int buttonMask) {
    int slot;

    if (!state || !state->active || buttonMask == 0) {
        return M11_GAME_INPUT_IGNORED;
    }
    if (state->sourceKind == M11_GAME_SOURCE_CSB_HINT_ORACLE) {
        CSB_HintOracleAtariRuntime *runtime =
            (CSB_HintOracleAtariRuntime *)state->csbHintOracleRuntime;
        CSB_V1_AtariSaveInfo *save_info =
            (CSB_V1_AtariSaveInfo *)state->csbHintOracleSaveInfo;
        if ((buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0 || !runtime ||
            csb_hint_oracle_atari_runtime_handle_click(runtime, x, y, save_info) !=
                CSB_HINT_ORACLE_ATARI_RUNTIME_OK) return M11_GAME_INPUT_IGNORED;
        if (runtime->session.state == CSB_HINT_ORACLE_SESSION_CLOSED)
            return M11_GAME_INPUT_RETURN_TO_MENU;
        return M11_GAME_INPUT_REDRAW;
    }
    state->pointerPositionKnown = 1;
    state->pointerX = x;
    state->pointerY = y;
    if (m11_dm1_v1_blocks_host_map_overlay(state)) {
        state->mapOverlayActive = 0;
    }

    /* Theron uses a normal desktop pointer as the host device, but its
     * physical mouse buttons are controller buttons, not DM1's pointer-zone
     * table.  Keep pointer motion as position-only state (HandlePointerMove)
     * so moving over an object never selects or hops between objects.  During
     * startup Button I still needs the source-space menu hit test; Button II
     * is the source action command.  Once the dungeon is live both buttons
     * enter the authenticated Theron input facade directly.
     *
     * Source lock: THQUEST.ASM T400/T520/T560/T600/T700 owns the startup,
     * movement and action boundaries.  Do not route these events through the
     * ReDMCSB/DM1 C007..C116 pointer table. */
    if (state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02 &&
        !state->graphicsPopupActive) {
        if (state->theronState.startup_phase != THERON_STARTUP_PHASE_IN_DUNGEON ||
            !state->theronState.level_loaded) {
            if ((buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0) {
                return m11_theron_handle_startup_pointer(state, x, y);
            }
            if ((buttonMask & DM1_V1_MOUSE_MASK_RIGHT_PC34) != 0) {
                return M11_GameView_HandleInput(
                    state, M12_MENU_INPUT_ACTION);
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if ((buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0) {
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_ACCEPT);
        }
        if ((buttonMask & DM1_V1_MOUSE_MASK_RIGHT_PC34) != 0) {
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_ACTION);
        }
        return M11_GAME_INPUT_IGNORED;
    }

    if (state->graphicsPopupActive) {
        const int leftClick = (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0;
        const int rightClick = (buttonMask & DM1_V1_MOUSE_MASK_RIGHT_PC34) != 0;
        if (!leftClick && !rightClick) {
            return M11_GAME_INPUT_REDRAW;
        }
        /* The popup is an ordinary desktop menu: left click advances a
         * value, right click reverses it.  Before this branch, a right
         * click was swallowed by the modal and every mouse-adjustable value
         * could only be stepped forward.  Keep tabs and the close button
         * left-click-only so the standard right-click decrement gesture
         * cannot accidentally dismiss or change page. */
        if (m11_point_in_rect(x, y, M11_GRAPHICS_POPUP_X + 130,
                              M11_GRAPHICS_POPUP_Y + 6, 18, 12)) {
            if (!leftClick) return M11_GAME_INPUT_REDRAW;
            state->graphicsPopupActive = 0;
            return M11_GAME_INPUT_REDRAW;
        }
        if (m11_point_in_rect(x, y, M11_GRAPHICS_POPUP_X + 6,
                              M11_GRAPHICS_POPUP_Y + 23, 136, 12)) {
            if (!leftClick) return M11_GAME_INPUT_REDRAW;
            state->graphicsPopupPage = (x < M11_GRAPHICS_POPUP_X + 40) ?
                M11_GRAPHICS_POPUP_PAGE_PRESENTATION :
                (x < M11_GRAPHICS_POPUP_X + 78 ? M11_GRAPHICS_POPUP_PAGE_FILTERS :
                 (x < M11_GRAPHICS_POPUP_X + 114 ? M11_GRAPHICS_POPUP_PAGE_EFFECTS :
                                                   M11_GRAPHICS_POPUP_PAGE_CHEATS));
            state->graphicsPopupSelectedRow = 0;
            return M11_GAME_INPUT_REDRAW;
        }
        if (m11_point_in_rect(x, y, M11_GRAPHICS_POPUP_X + 6,
                              M11_GRAPHICS_POPUP_Y + 40, 136, 110)) {
            int row = (y - (M11_GRAPHICS_POPUP_Y + 40)) / 10;
            if (row >= 0 && row < m11_graphics_popup_row_count(state, state->graphicsPopupPage)) {
                if (row == state->graphicsPopupSelectedRow) {
                    return m11_graphics_popup_adjust(state, rightClick ? -1 : 1)
                        ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
                }
                state->graphicsPopupSelectedRow = row;
                return M11_GAME_INPUT_REDRAW;
            }
        }
        /* The graphics panel is modal. A click in its dimmed backdrop must
         * never fall through to a dungeon object, viewport, or HUD action. */
        return M11_GAME_INPUT_REDRAW;
    }

    /* Click dismisses normal dialogs; return-to-menu confirm acts on YES/NO. */
    if (state->dialogOverlayActive) {
        int choice = m11_dialog_choice_at_point(state, x, y);
        if (state->dm2MacOpenGameActive) {
            if (choice > 0) {
                return m11_dm2_mac_open_game_handle_choice(state, choice);
            }
            return M11_GAME_INPUT_REDRAW;
        }
        if (state->csbDiskMenuActive) {
            if (choice > 0) return m11_csb_handle_save_disk_choice(state, choice);
            return M11_GAME_INPUT_REDRAW;
        }
        if (state->dm1SaveDiskMenuStage != M11_DM1_SAVE_DISK_MENU_NONE) {
            if (choice > 0) {
                return m11_dm1_handle_save_disk_choice(state, choice);
            }
            return M11_GAME_INPUT_REDRAW;
        }
        if (state->returnToMenuConfirmActive) {
            if (choice == 1) {
                /* G2018 quit-guard: SAVE-AND-QUIT path also saves on click. */
                if (state->quitGuardActive) {
                    if (!m11_save_before_return_to_menu(state)) {
                        return M11_GAME_INPUT_REDRAW;
                    }
                    state->quitGuardActive = 0;
                }
                state->dialogSelectedChoice = choice;
                M11_GameView_DismissDialogOverlay(state);
                m11_set_status(state, "RETURN", "BACK TO LAUNCHER");
                return M11_GAME_INPUT_RETURN_TO_MENU;
            }
            if (choice == 2 || choice == 0) {
                int wasGuard = state->quitGuardActive;
                state->quitGuardActive = 0;
                if (choice == 2) state->dialogSelectedChoice = choice;
                M11_GameView_DismissDialogOverlay(state);
                m11_set_status(state, "RETURN",
                               wasGuard ? "CANCELLED (UNSAVED)" : "CANCELLED");
                return M11_GAME_INPUT_REDRAW;
            }
        }
        if (choice > 0) {
            state->dialogSelectedChoice = choice;
        }
        M11_GameView_DismissDialogOverlay(state);
        return M11_GAME_INPUT_REDRAW;
    }

    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        const CSB_V1_BootProfile *csb_profile =
            (const CSB_V1_BootProfile *)state->csbBootProfile;
        CSB_V1_BootStartupHostInputDispatchReceipt_PC34 dispatch_receipt;
        if (m11_csb_is_amiga_profile(csb_profile) &&
            state->csbState.startup_entrance_credits_active) {
            if ((buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0) {
                state->csbState.startup_entrance_credits_active = 0;
                state->csbState.startup_entrance_credits_remaining_ticks = 0;
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (m11_csb_is_amiga_profile(csb_profile) &&
            state->csbState.startup_entrance_active) {
            CsbTouchClickZonePc34Compat entrance_zone;
            if (!state->csbState.startup_entrance_opening_active &&
                CSB_TOUCHCLICK_Compat_HitTestInView(
                    CSB_TOUCH_CLICK_VIEW_ENTRANCE_PC34_COMPAT, x, y,
                    (unsigned int)buttonMask, &entrance_zone)) {
                /* ReDMCSB COMMAND.C G0445 / F0358 maps the native Amiga
                 * C407 and C411 zones to C200 (Enter) and M567 (Credits).
                 * C409 (Resume) is deliberately not treated as New Game:
                 * F0441 reaches F0435 for it and needs an authenticated
                 * original save corpus before it may mutate this runtime. */
                if (entrance_zone.commandId == 203u) {
                    state->csbState.startup_entrance_credits_active = 1;
                    state->csbState.startup_entrance_credits_remaining_ticks = 0;
                    return M11_GAME_INPUT_REDRAW;
                }
                if (entrance_zone.commandId == 200u) {
                    /* ENTRANCE.C:932-935 (MEDIA746 A31/A35) starts C01
                     * through F0709 at G3077 {64,64} before its delay. */
                    m11_csb_emit_amiga_entrance_sound(
                        state, CSB_V1_SOUND_SWITCH);
                    state->csbState.startup_entrance_opening_active = 1;
                    state->csbState.startup_entrance_opening_step = 1;
                    return M11_GAME_INPUT_REDRAW;
                }
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (m11_csb_is_fmtowns_profile(csb_profile) &&
            state->csbState.startup_title_active &&
            (state->csbFmtownsSwitchBound || state->csbFmtownsUtilityBound)) {
            return state->csbFmtownsUtilityBound
                ? m11_csb_handle_fmtowns_utility_pointer(state, x, y, buttonMask)
                : m11_csb_handle_fmtowns_switch_pointer(state, x, y, buttonMask);
        }
        if (m11_csb_is_fmtowns_profile(csb_profile) &&
            state->csbState.startup_entrance_active) {
            CsbTouchClickZonePc34Compat entrance_zone;

            /* CHTWE/CHTWJ hands C004 to the same F0806 Entrance wait loop
             * after its native Game program has loaded MINI.DAT.  The
             * program boundary is Towns-specific, but C200 remains the
             * source C407 primary-mouse command: COMMAND.C:342 and
             * layout-696 fix it at (244,45), 55x14.  Previously this
             * verified Towns C004 surface accepted only keyboard Return.
             * Consume only C407 with a real left button through the same
             * source-owned pointer dispatcher used by the PC entrance;
             * F0806 owns the resulting handoff. Other C004 clicks remain
             * inert until their native command owner is recovered. */
            if ((buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0 &&
                CSB_TOUCHCLICK_Compat_HitTestInView(
                    CSB_TOUCH_CLICK_VIEW_ENTRANCE_PC34_COMPAT, x, y,
                    (unsigned int)buttonMask, &entrance_zone) &&
                entrance_zone.commandId == 200u) {
                if (m11_csb_boot_runtime_startup_pointer_dispatch(
                        state, x, y, ENTRANCE_MOUSE_BUTTON_LEFT_COMPAT,
                        &dispatch_receipt) && dispatch_receipt.valid &&
                    dispatch_receipt.startup_active &&
                    dispatch_receipt.pointer_button_relevant) {
                    return m11_csb_startup_apply_host_input_dispatch_receipt(
                        state, &dispatch_receipt);
                }
            }
            return M11_GAME_INPUT_IGNORED;
        }
        /* M11 already normalizes SDL buttons to the PC34 mouse masks: left
         * is 0x0002 and right is 0x0001.  The standalone Entrance boundary
         * also accepts SDL's raw left-button bit (0x0001), but forwarding
         * M11's right-button mask to that compatibility adapter made a
         * right-click indistinguishable from Enter Dungeon.  Preserve the
         * original C200/C201 mouse table only for M11's source left button.
         * ReDMCSB COMMAND.C G0445/F0358, ENTRANCE.C F0441/F0806. */
        if (m11_csb_boot_runtime_startup_pointer_dispatch(
                state,
                x,
                y,
                (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34)
                    ? ENTRANCE_MOUSE_BUTTON_LEFT_COMPAT
                    : ((buttonMask & ENTRANCE_MOUSE_BUTTON_BONUS_DUNGEON_COMPAT)
                        ? ENTRANCE_MOUSE_BUTTON_BONUS_DUNGEON_COMPAT
                        : 0u),
                &dispatch_receipt) &&
            dispatch_receipt.valid &&
            dispatch_receipt.startup_active &&
            dispatch_receipt.pointer_button_relevant) {
            return m11_csb_startup_apply_host_input_dispatch_receipt(
                state,
                &dispatch_receipt);
        }
        /* The title/Entrance loop owns the entire pointer surface until it
         * has released C03_GAME.  In particular C083 is a live full-screen
         * right-button route; letting it run here toggles an inventory panel
         * behind Prison, while the raw-mask compatibility bug above could
         * instead start C200.  Neither live command exists during F0441's
         * startup wait. */
        if (state->csbState.startup_title_active ||
            state->csbState.startup_entrance_active) {
            return M11_GAME_INPUT_IGNORED;
        }
    }

    /* COMMAND.C resolves all live C007..C116 UI commands against the
     * current party.  CSB's party authority is GAMEBLOCK, so refresh the
     * presentation mirror once after the startup-only dispatcher and before
     * movement, champion, action, or spell hit testing. */
    if (m11_source_is_csb(state) && state->csbBootProfile) {
        m11_sync_csb_state_from_boot_profile(state, state->csbBootProfile);
    }

    /* CSBWin stores C232's eye/mouth hit boxes in the top status-band
     * coordinate range (the verified mouth box is x55..72, y12..29).  While
     * C017 owns the visible page they are not champion-status clicks, so
     * resolve these original controls before the normal C012--C015 top-row
     * dispatcher can close or switch the inventory panel. */
    if (m11_source_is_csb(state) && state->inventoryPanelActive &&
        (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0) {
        int control_command = 0;
        if (m11_csb_atari_st_inventory_control_at_point(
                state, x, y, &control_command)) {
            if ((control_command == 70 && m11_process_v1_mouth_click(state)) ||
                (control_command == 71 && m11_process_v1_eye_click(state))) {
                if (control_command == 71) state->v1EyePressActive = 1;
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
    }

    {
        M11_GameInputResult atari_top_row_result;
        if (m11_csb_atari_st_top_row_pointer(state, x, y, buttonMask,
                                             &atari_top_row_result)) {
            return atari_top_row_result;
        }
    }
    {
        M11_GameInputResult amiga_top_row_result;
        if (m11_csb_amiga_top_row_pointer(state, x, y, buttonMask,
                                          &amiga_top_row_result)) {
            return amiga_top_row_result;
        }
    }
    {
        M11_GameInputResult fmtowns_top_row_result;
        if (m11_csb_fmtowns_top_row_pointer(state, x, y, buttonMask,
                                            &fmtowns_top_row_result)) {
            return fmtowns_top_row_result;
        }
    }

    /* CSB's live mouse route is the same source-owned G0448 command surface
     * that COMMAND.C sends through F0358/F0359 into the C001..C006 queue.
     * Resolve it before the DM1 HUD path below.  Coordinates have already
     * passed through the presentation-to-source mapper in main_loop_m11, so
     * scaled and letterboxed views hit the original source geometry. */
    if (m11_source_is_csb(state)) {
        /* CSBWin's selected-inventory page replaces C0128 with C017. Its
         * own C232 IconDisplay rectangles must win before the normal live
         * command surface can interpret the same point as a viewport click. */
        if (state->inventoryPanelActive &&
            (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0) {
            int source_slot = -1;

            if ((m11_csb_atari_st_inventory_source_slot_at_point(
                     state, x, y, &source_slot) ||
                 m11_csb_fmtowns_inventory_source_slot_at_point(
                     state, x, y, &source_slot))) {
                if (!m11_process_v1_inventory_slot_box_click(
                        state, source_slot + 8)) {
                    return M11_GAME_INPUT_IGNORED;
                }
                state->v1InventoryDragActive = 1;
                state->v1InventoryDragSourceSlotBox = source_slot + 8;
                return M11_GAME_INPUT_REDRAW;
            }
        }
        CSB_V1_CommandInputGeometryResultPc34Compat csb_pointer;
        if (CSB_V1_CommandInputGeometryFromPointerPc34Compat(
                x, y, buttonMask, &csb_pointer)) {
            return M11_GameView_HandleInput(state, csb_pointer.input);
        }
    }

    /* Native A31/A35 and F31 C125..C128 formation cells, C012..C015 status
     * clicks, and C007..C010 bar clicks are resolved above with their G0447
     * boxes and F0070 GAMEBLOCK transaction. */
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
        (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0 && y >= 0 && y <= 28) {
        const CSB_V1_BootProfile *csb_profile =
            (const CSB_V1_BootProfile *)state->csbBootProfile;
        if (m11_csb_is_amiga_profile(csb_profile) ||
            m11_csb_is_fmtowns_profile(csb_profile)) {
            return M11_GAME_INPUT_IGNORED;
        }
    }

    if (state->sourceKind == M11_GAME_SOURCE_NEXUS_DGN &&
        state->nexusState.title_active &&
        (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0) {
        return M11_GAME_INPUT_IGNORED;
    }

    if (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) {
        M11_GameInputResult theronStartupPointer =
            m11_theron_handle_startup_pointer(state, x, y);
        if (theronStartupPointer != M11_GAME_INPUT_IGNORED) {
            return theronStartupPointer;
        }
    }
    if (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) {
        M11_GameInputResult nexusStartupPointer =
            m11_nexus_handle_startup_pointer(state, x, y);
        if (nexusStartupPointer != M11_GAME_INPUT_IGNORED) {
            return nexusStartupPointer;
        }
    }
    if (buttonMask & (DM1_V1_MOUSE_MASK_LEFT_PC34 |
                      DM1_V1_MOUSE_MASK_RIGHT_PC34)) {
        M11_GameInputResult dm2StartupPointer =
            m11_dm2_handle_startup_pointer(state, x, y, buttonMask);
        if (dm2StartupPointer != M11_GAME_INPUT_IGNORED) {
            return dm2StartupPointer;
        }
    }

    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT &&
        state->inventoryPanelActive &&
        m11_dm2_is_fmtowns_profile(
            (const DM2_V1_BootProfile *)state->dm2BootProfile)) {
        DM2_V1_DungeonInputOwner input_owner;
        DM2_V1_FmtownsUiRouteReceipt route;
        const DM2_V1_BootProfile *profile =
            (const DM2_V1_BootProfile *)state->dm2BootProfile;
        int route_bound = 0;
        memset(&route, 0, sizeof(route));
        if (dm2_v1_dungeon_input_owner_init_fmtowns(
                &input_owner, profile) &&
            dm2_v1_dungeon_input_owner_fmtowns_route_context(
                &input_owner, DM2_V1_FMTOWNS_UI_INVENTORY,
                (int16_t)x, (int16_t)y, (unsigned int)buttonMask, &route) &&
            route.accepted) {
            route_bound = 1;
        } else if (dm2_v1_dungeon_input_owner_init_fmtowns(
                       &input_owner, profile) &&
                   dm2_v1_dungeon_input_owner_fmtowns_route_context(
                       &input_owner, DM2_V1_FMTOWNS_UI_STATUS,
                       (int16_t)x, (int16_t)y, (unsigned int)buttonMask,
                       &route) && route.accepted) {
            /* SKWIN keeps the eye/mouth records in the champion/status
             * context even while CHANGE_VIEWPORT_TO_INVENTORY owns the
             * visible page.  Do not relabel that source context as an
             * inventory rectangle. */
            route_bound = 1;
        }
        if (route_bound) {
            int source_slot = -1;
            if (route.candidate.event_index == 11u) {
                state->inventoryPanelActive = 0;
                return M11_GAME_INPUT_REDRAW;
            }
            /* c_events.cpp:1846 DM2_CLICK_INVENTORY_EYE.  The native
             * Towns record is shared with the source inventory table, so
             * dispatch by the authenticated source context rather than by
             * a rectangle or a host coordinate.  v1e0976 is kept separate
             * from party.curacthero exactly as in the source runtime. */
            if (route.source_context.groupName &&
                strcmp(route.source_context.groupName,
                       "inventory.eye") == 0) {
                int eye_champion;
                if (!dm2_v1_runtime_click_inventory_eye() ||
                    (eye_champion =
                         dm2_v1_runtime_get_inventory_eye_champion_index()) < 0 ||
                    eye_champion >= CHAMPION_MAX_PARTY) {
                    return M11_GAME_INPUT_IGNORED;
                }
                state->dm2State.inventoryEyeChampionIndex = eye_champion;
                return M11_GAME_INPUT_REDRAW;
            }
            if (dm2_v1_fmtowns_inventory_slot_for_context(
                    &route.source_context, &source_slot) &&
                source_slot >= 0 && source_slot < 30) {
                DM2_V1_BootRuntimeInventoryReceipt inventory_receipt;
                int champion_index =
                    dm2_v1_runtime_get_active_champion_index();
                state->inventorySelectedSlot = source_slot;
                /* c_events.cpp:45 performs the source item-slot exchange
                 * immediately. Use the already authenticated GAME_LOAD
                 * record chain and LeaderPossession transaction; if the
                 * source owner rejects the operation, leave the selection
                 * visible but do not invent a host-side move. */
                memset(&inventory_receipt, 0, sizeof(inventory_receipt));
                if (champion_index >= 0 &&
                    dm2_v1_boot_runtime_swap_inventory_slot(
                        (DM2_V1_BootProfile *)state->dm2BootProfile,
                        champion_index, source_slot, &inventory_receipt)) {
                    m11_set_status(state, "DM2 FM TOWNS", "ITEM MOVED");
                }
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_REDRAW;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT &&
        state->inventoryPanelActive &&
        m11_dm2_is_mac_profile(
            (const DM2_V1_BootProfile *)state->dm2BootProfile)) {
        /* The English Macintosh CHARSHEET owns pointer dispatch through
         * dynamically published Control/Event records in CODE(3)/CODE(11).
         * Until those records are materialized from the retained application
         * source, consume the modal pointer event here.  Falling through to
         * the viewport or a PC/FMTowns inventory rectangle would turn an
         * unauthenticated click into movement or an item transaction. */
        return M11_GAME_INPUT_IGNORED;
    }

    /* Endgame restart/quit controls.  ReDMCSB ENDGAME.C F0444 lines
     * 485-559 installs G0446_as_Graphic561_PrimaryMouseInput_RestartGame
     * only after the final screen is drawn and only when
     * G0524_B_RestartGameAllowed is true.  Clicking restart latches the
     * G0523_B_RestartGameRequested mirror; ENDGAME.C lines 568-590 then
     * observes that latch while processing the queue before restarting.
     * Quit returns to the launcher. */
    if (state->gameWon) {
        DM1_V1_EndgamePresentationInputPc34 endgameInput = {0};
        DM1_V1_EndgamePresentationDecisionPc34 endgameDecision;
        endgameInput.gameWon = state->gameWon;
        endgameInput.finalHandoffReady = state->endgameFinalHandoffReady;
        endgameInput.endgameCalledWithTrue = state->endgameCalledWithTrue;
        endgameInput.finalDelayTicks = state->endgameFinalDelayTicks;
        endgameInput.fuseDelayTicks = state->endgameFuseSequenceDelayTicks;
        endgameInput.fuseDelayRemainingTicks = state->endgameFuseSequenceDelayRemainingTicks;
        endgameInput.textMessageDelayTicks = state->endgameTextMessageDelayTicks;
        endgameInput.restartAllowed = state->endgameRestartAllowed;
        endgameInput.pointerX = x;
        endgameInput.pointerY = y;
        endgameInput.pointerPressed = 1;
        dm1_v1_endgame_presentation_decide_pc34(&endgameInput, &endgameDecision);
        if (endgameDecision.presentationReady &&
            state->endgameF0444PresentationPhase <= 1) {
            if (!m11_dm1_f0444_endgame_material_bound(state, NULL, NULL,
                                                       NULL, NULL)) {
                return M11_GAME_INPUT_IGNORED;
            }
            state->endgameF0444PresentationPhase = 2;
            state->endgameTheEndDelayRemainingTicks = 300;
            if (state->dm1MusicSourceBound) {
                (void)M11_Audio_RequestSourceMusicTrack(&state->audioState, 3);
            }
            return M11_GAME_INPUT_REDRAW;
        }
        if (endgameDecision.presentationReady &&
            state->endgameF0444PresentationPhase == 3) {
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
        if (state->endgameF0444PresentationPhase == 2 &&
            state->endgameTheEndDelayRemainingTicks > 0) {
            return M11_GAME_INPUT_IGNORED;
        }
        if (endgameDecision.action == DM1_V1_ENDGAME_PRESENTATION_ACTION_RESTART_PC34) {
            DM1_V1_EndgameRestartLoadInputPc34 restartLoadInput = {0};
            DM1_V1_EndgameRestartLoadDecisionPc34 restartLoadDecision;
            state->endgameRestartRequested = 1;
            /* I34E ENDGAME.C F0444 lines 607-635 selects
             * C000_MODE_LOAD_SAVED_GAME and calls F0435.  A valid save
             * resumes in-place through F0462; a failed load reloads the
             * retained C006/C005 material and returns to T0444017.  Never
             * turn this into the launcher's generic new-session restart. */
            restartLoadInput.restartRequested = 1;
            restartLoadInput.loadSucceeded = M11_GameView_QuickLoad(state);
            restartLoadInput.f0444MaterialBound =
                m11_dm1_f0444_endgame_material_bound(state, NULL, NULL,
                                                       NULL, NULL);
            dm1_v1_endgame_restart_load_decide_pc34(
                &restartLoadInput, &restartLoadDecision);
            if (restartLoadDecision.resumeLoadedGame) {
                state->gameWon = 0;
                state->world.gameWon = 0;
                state->partyDead = 0;
                state->world.partyDead = 0;
                state->endgameRestartRequested = 0;
                state->endgameRestartAllowed = 1;
                state->endgameFinalHandoffReady = 0;
                state->endgameF0444PresentationPhase = 0;
                state->endgameTheEndDelayRemainingTicks = 0;
                return M11_GAME_INPUT_REDRAW;
            }
            state->endgameRestartRequested = 0;
            if (restartLoadDecision.returnToTheEnd) {
                state->endgameF0444PresentationPhase = 2;
                state->endgameTheEndDelayRemainingTicks = 300;
                if (state->dm1MusicSourceBound) {
                    (void)M11_Audio_RequestSourceMusicTrack(
                        &state->audioState, 3);
                }
                return M11_GAME_INPUT_REDRAW;
            }
            return restartLoadDecision.failClosed
                       ? M11_GAME_INPUT_IGNORED : M11_GAME_INPUT_REDRAW;
        }
        if (endgameDecision.action ==
            DM1_V1_ENDGAME_PRESENTATION_ACTION_RETURN_TO_MENU_PC34) {
            m11_set_status(state, "RETURN", "BACK TO LAUNCHER");
            return M11_GAME_INPUT_RETURN_TO_MENU;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    /* Source-backed champion mirror panel.  ReDMCSB routes the
     * Resurrect/Reincarnate/Cancel overlay through COMMAND.C C160..C162
     * with PC boxes 104..158/163..217 x 86..142 and cancel 104..217 x
     * 146..156 (Atari boxes are slightly wider; these are the PC rows
     * behind COMMAND.C 231..238 and 509..511).  Handle them before the
     * generic viewport hit test so x=130/y=115 and x=186/y=115 do not
     * get reinterpreted as movement/inspect clicks. */
    if (m11_dm1_hoc_menu_route_blocks_normal_input(state)) {
        if (state->candidateMirrorRenameActive) {
            if (!m11_dm1_hoc_c027_input_material_ready(state)) {
                return M11_GAME_INPUT_IGNORED;
            }
            if (m11_point_in_rect(x, y, 197, 147, 19, 9)) {
                int sensorIndex;
                if (!m11_front_mirror_first_sensor_index_pc34(state,
                                                               &sensorIndex)) {
                    return M11_GAME_INPUT_IGNORED;
                }
            }
            return M11_GameView_HandleMirrorCandidateRenameClick(state, x, y)
                       ? M11_GAME_INPUT_REDRAW
                       : M11_GAME_INPUT_IGNORED;
        }
        if (!m11_dm1_hoc_c040_input_material_ready(state)) {
            return M11_GAME_INPUT_IGNORED;
        }
        /* ReDMCSB COMMAND.C F0359:1985-1990 checks G0415 before it even
         * scans G0457's C160/C161/C162 boxes.  A C040 panel restored while
         * the transient G4055 leader hand is occupied must therefore remain
         * modal: its buttons neither finalize nor cancel the candidate.
         * This matters equally to the native A31/A35 path, where C017/C040
         * is rendered from the selected ADF rather than a PC34 session. */
        if (DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) !=
            THING_NONE) {
            return M11_GAME_INPUT_IGNORED;
        }
        if (m11_point_in_rect(x, y, 104, 86, 55, 57)) {
            int sensorIndex;
            if (!m11_front_mirror_first_sensor_index_pc34(state,
                                                           &sensorIndex)) {
                return M11_GAME_INPUT_IGNORED;
            }
            return M11_GameView_ConfirmMirrorCandidate(state, 0)
                       ? M11_GAME_INPUT_REDRAW
                       : M11_GAME_INPUT_IGNORED;
        }
        if (m11_point_in_rect(x, y, 163, 86, 55, 57)) {
            if (!m11_dm1_hoc_c027_input_material_ready(state)) {
                return M11_GAME_INPUT_IGNORED;
            }
            return M11_GameView_BeginMirrorCandidateReincarnateRename(state)
                       ? M11_GAME_INPUT_REDRAW
                       : M11_GAME_INPUT_IGNORED;
        }
        if (m11_point_in_rect(x, y, 104, 146, 114, 11)) {
            return M11_GameView_CancelMirrorCandidate(state)
                       ? M11_GAME_INPUT_REDRAW
                       : M11_GAME_INPUT_IGNORED;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    /* CSB uses the same PC34 G0447 primary interface table for its
     * right-button champion inventory toggles.  Keep this restricted to the
     * shared HUD route: CSB viewport and spell ownership remain in their
     * dedicated source handlers below. */
    if ((m11_is_dm1_source_kind(state->sourceKind) ||
         state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) &&
        !state->showDebugHUD &&
        (buttonMask & DM1_V1_MOUSE_MASK_RIGHT_PC34)) {
        int space = DM1_V1_MOUSE_SPACE_NONE_PC34;
        int zoneId = 0;
        int command;

        command = DM1_V1_MouseRoutes_CommandForScreenPointPc34Compat(
            DM1_V1_MOUSE_LIST_INTERFACE_PC34,
            x, y,
            DM1_V1_MOUSE_MASK_RIGHT_PC34,
            &space,
            &zoneId);
        if (command >= 7 && command <= 10 && zoneId >= 151 && zoneId <= 154) {
            int championIndex = command - 7;
            return m11_toggle_champion_inventory(state, championIndex);
        }

        command = DM1_V1_MouseRoutes_CommandForScreenPointPc34Compat(
            state->inventoryPanelActive ? DM1_V1_MOUSE_LIST_INVENTORY_PC34
                                        : DM1_V1_MOUSE_LIST_MOVEMENT_PC34,
            x, y,
            DM1_V1_MOUSE_MASK_RIGHT_PC34,
            &space,
            &zoneId);
        if ((command == 83 && zoneId == 2) || (command == 11 && zoneId == 2)) {
            state->mapOverlayActive = 0;
            M11_GameView_ToggleInventoryPanel(state);
            return M11_GAME_INPUT_REDRAW;
        }
        return M11_GAME_INPUT_IGNORED;
    }

    if ((buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) == 0) {
        return M11_GAME_INPUT_IGNORED;
    }

    /* COMMAND.C G0447 maps C007..C010 to the visible C187..C190 bar
     * regions.  They are the normal DM1 mouse path for opening a specific
     * champion's inventory.  C012..C015 covers the remaining status-box
     * surface and selects that champion through F0367/F0368. */
    /* Input geometry belongs to the DM1 runtime, not to the optional V1
     * chrome compositor.  V2.x retains the original status-bar ownership,
     * so C007..C015 must remain clickable when its presentation mode turns
     * the V1 chrome switch off. */
    /* ReDMCSB COMMAND.C G0447 C007..C015 is shared by the PC34 DM1 and
     * CSB game views.  CSB previously skipped this branch solely because it
     * has its own source kind, leaving visible champion HUD boxes inert.
     * The toggle helper writes through CSB's runtime mirror, so this admits
     * only the original interface command rather than a DM1 world fallback. */
    if ((m11_is_dm1_source_kind(state->sourceKind) ||
         state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) &&
        !state->showDebugHUD) {
        int space = DM1_V1_MOUSE_SPACE_NONE_PC34;
        int zoneId = 0;
        int command;

        /* V2 keeps the original champion-input behaviour, but its composed
         * four-slot HUD starts at x=12 with a 77px stride.  The source C187
         * table is anchored at x=0/69, so using it alone makes the visible
         * portrait area (most noticeably champion four) miss the input
         * route.  Bind the rendered portrait/name region to C007..C010;
         * hand cells on the right remain available to their own routes. */
        if (m11_v2_vertical_slice_enabled(state)) {
            for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
                int slotX = m11_party_panel_x(state) +
                            slot * m11_party_slot_step(state);
                if (m11_point_in_rect(x, y, slotX, M11_PARTY_PANEL_Y,
                                      47, M11_PARTY_SLOT_H)) {
                    return m11_toggle_champion_inventory(state, slot);
                }
            }
        } else {
            /* The V1 top row visibly identifies a champion through its
             * F0292 name plaque and F0287 vertical bar graph.  Make both
             * painted surfaces live inventory targets; the two hand-slot
             * rectangles remain on their separate COMMAND.C routes. */
            for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
                DM1_V1_ChampionStatusRectPc34 statusRect;
                DM1_V1_ChampionStatusRectPc34 nameRect;
                DM1_V1_ChampionStatusRectPc34 handRect;
                int overHand = 0;
                int hand;
                if (dm1_v1_champion_status_box_rect_pc34(slot, &statusRect) &&
                    dm1_v1_champion_status_name_rect_pc34(slot, &nameRect)) {
                    for (hand = 0; hand < 2; ++hand) {
                        if (dm1_v1_champion_status_hand_rect_pc34(
                                slot, hand, &handRect) &&
                            m11_point_in_rect(x, y,
                                              handRect.x, handRect.y,
                                              handRect.w, handRect.h)) {
                            overHand = 1;
                            break;
                        }
                    }
                    /* The full F0287/F0292 status-box surface represents
                     * its champion.  A hand cell has an independent item
                     * route only while the inventory is already open.  With
                     * the panel closed it is still a visible part of that
                     * champion's HUD tile, so it must open the champion
                     * rather than silently swallowing the click. */
                    if ((!overHand || !state->inventoryPanelActive) &&
                        (m11_point_in_rect(x, y,
                                           statusRect.x, statusRect.y,
                                           statusRect.w, statusRect.h) ||
                         m11_point_in_rect(x, y,
                                           nameRect.x, nameRect.y,
                                           nameRect.w, nameRect.h))) {
                        return m11_toggle_champion_inventory(state, slot);
                    }
                }
            }
        }

        command = DM1_V1_MouseRoutes_CommandForScreenPointPc34Compat(
            DM1_V1_MOUSE_LIST_INTERFACE_PC34,
            x, y,
            DM1_V1_MOUSE_MASK_LEFT_PC34,
            &space,
            &zoneId);
        (void)space;
        if (command >= 7 && command <= 10 &&
            zoneId >= 187 && zoneId <= 190) {
            return m11_toggle_champion_inventory(state, command - 7);
        }
        if (command >= 12 && command <= 15 &&
            zoneId >= 151 && zoneId <= 154) {
            return m11_set_active_champion(state, command - 12)
                ? M11_GAME_INPUT_REDRAW : M11_GAME_INPUT_IGNORED;
        }
    }

    {
        M11_GameInputResult spellResult =
            m11_handle_dm1_spell_area_pointer(state, x, y);
        if (spellResult != M11_GAME_INPUT_IGNORED) {
            return spellResult;
        }
    }

    if (state->inventoryPanelActive && !state->showDebugHUD) {
        int space = DM1_V1_MOUSE_SPACE_NONE_PC34;
        int zoneId = 0;
        /* CSBWin's C017 inventory owns its active slot geometry in C232.
         * Resolve that data-owned layer before any PC3.4 C507 table can see
         * the same screen coordinates. */
        if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
            (buttonMask & DM1_V1_MOUSE_MASK_LEFT_PC34) != 0) {
            int source_slot = -1;

            if (m11_csb_atari_st_inventory_source_slot_at_point(
                    state, x, y, &source_slot)) {
                if (!m11_process_v1_inventory_slot_box_click(
                        state, source_slot + 8)) {
                    return M11_GAME_INPUT_IGNORED;
                }
                state->v1InventoryDragActive = 1;
                state->v1InventoryDragSourceSlotBox = source_slot + 8;
                return M11_GAME_INPUT_REDRAW;
            }
        }
        int command = DM1_V1_MouseRoutes_CommandForScreenPointPc34Compat(
            DM1_V1_MOUSE_LIST_INVENTORY_PC34,
            x, y,
            DM1_V1_MOUSE_MASK_LEFT_PC34,
            &space,
            &zoneId);
        (void)space;
        if (command >= 20 && command <= 27 &&
            zoneId >= 211 && zoneId <= 218) {
            if (m11_process_v1_status_hand_slot_box_click(state,
                                                          command - 20)) {
                /* C211..C218 use the same F0302 leader-hand transaction as
                 * the inventory page. Preserve their source slot ordinal so
                 * mouse-up can either keep a same-box click stable or place
                 * the held object in another authenticated hand box. */
                state->v1InventoryDragActive = 1;
                state->v1InventoryDragSourceSlotBox = command - 20;
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (command >= 28 && command <= 57 && zoneId >= 507 && zoneId <= 536) {
            if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
                /* SKProject CHANGE_VIEWPORT_TO_INVENTORY has a distinct
                 * GDAT/CHAMPIONS layout and event table. These are DM1
                 * GRAPHICS.DAT slots, so no DM2 ObjectID may pass through
                 * this substitute click route. */
                state->inventoryPanelActive = 0;
                return M11_GAME_INPUT_IGNORED;
            }
            if (m11_process_v1_inventory_pointer_target(
                    state, x, y, &slot)) {
                state->v1InventoryDragActive = 1;
                state->v1InventoryDragSourceSlotBox = slot;
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (command == 81 && zoneId == 101) {
            if (m11_process_v1_inventory_pointer_target(
                    state, x, y, &slot)) {
                state->v1InventoryDragActive = 1;
                state->v1InventoryDragSourceSlotBox = slot;
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }

        /* ── ReDMCSB COMMAND.C G0449 mouth/eye click routes ──
         * Command 70 (zone 545) = mouth: eat/drink item in leader hand
         * Command 71 (zone 546) = eye: inspect item or show champion stats
         * Ref: PANEL.C F0349_INVENTORY_ProcessCommand70_ClickOnMouth
         *      PANEL.C F0352_INVENTORY_ProcessCommand71_ClickOnEye */
        if (command == 70 && zoneId == 545) {
            if (m11_process_v1_mouth_click(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (command == 71 && zoneId == 546) {
            if (m11_process_v1_eye_click(state)) {
                state->v1EyePressActive = 1;
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }

        /* ReDMCSB COMMAND.C F0380 routes the four visible inventory-panel
         * controls after the slot/mouth/eye lanes: C141 toggles music,
         * C140 enters the save path, C145 starts/restores resting, and C011
         * closes the panel.  The hit table was already source-locked, but
         * without this dispatch the visible icons were inert. */
        if (command == 141 && zoneId == 565) {
            int musicOn = M11_GameView_ToggleMusic(state);
            m11_set_status(state, "MUSIC", musicOn ? "MUSIC ON" : "MUSIC OFF");
            return M11_GAME_INPUT_REDRAW;
        }
        if (command == 140 && zoneId == 562) {
            /* C140 leaves the inventory route before LOADSAVE takes over. */
            state->inventoryPanelActive = 0;
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_SAVE_GAME);
        }
        if (command == 145 && zoneId == 564) {
            /* C145 switches to the resting input list, not the inventory
             * overlay's local navigation list. */
            state->inventoryPanelActive = 0;
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_REST_TOGGLE);
        }
        if (command == 11 && zoneId == 566) {
            M11_GameView_ToggleInventoryPanel(state);
            return M11_GAME_INPUT_REDRAW;
        }
    }

    /* The procedural utility-panel buttons (inspect / save /
     * load / back header) exist only in the debug HUD.  In V1
     * mode the right column shows the authentic DM1 action +
     * spell frames, so clicks in y=28..66 must fall through to
     * the DM1 action-menu and icon-cell hit tests below instead
     * of being intercepted by invisible hotspots.  Without this
     * gate a click on action-row 0 (y=58..66) lands inside the
     * invisible save/load button row (y=56..65) and is silently
     * swallowed. */
    if (state->showDebugHUD) {
        if (m11_point_in_utility_button(x, y, M11_UTILITY_INSPECT_X, M11_UTILITY_INSPECT_W)) {
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_ACCEPT);
        }
        if (m11_point_in_utility_button(x, y, M11_UTILITY_SAVE_X, M11_UTILITY_SAVE_W)) {
            if (M11_GameView_QuickSave(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (m11_point_in_utility_button(x, y, M11_UTILITY_LOAD_X, M11_UTILITY_LOAD_W)) {
            if (M11_GameView_QuickLoad(state)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
        if (m11_point_in_rect(x, y,
                              M11_UTILITY_PANEL_X,
                              M11_UTILITY_PANEL_Y,
                              M11_UTILITY_PANEL_W,
                              12)) {
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_BACK);
        }
    }

    /* DM1 action-hand icon cell hits — clicking a champion's
     * action cell activates them (F0389_MENUS_SetActingChampion)
     * and switches the right-column action area into menu mode.
     * Clicking the acting champion's cell again clears it
     * (F0388_MENUS_ClearActingChampion).  Hit rectangles are
     * resolved through the DM1/ReDMCSB action-area layout API so
     * click geometry stays locked to layout-696 C089..C092, matching
     * F0386_MENUS_DrawActionIcon geometry.  Only active
     * in V1 mode once the authentic frames have rendered, mirroring
     * the visible-cells gate used in m11_draw_utility_panel. */
    if (!state->showDebugHUD) {
        ActionAreaRoutePc34Compat sourceRoute;

        /* When in action-menu mode, clicks on the three action
         * rows drive F0391_MENUS_DidClickTriggerAction: the
         * chosen action is resolved against the ActionList, the
         * action is performed (within our bounded model), and
         * the acting champion is always cleared afterwards — even
         * when the row is empty (ACTION_NONE) the click still
         * falls through to the icon-cell test below so the user
         * can switch champions without first hitting an icon.
         *
         * Row hit geometry matches COMMAND.C C113..C115 / F0387
         * zones 85/86/87: x=234..318, y=86..96, 98..108,
         * 110..120.  We test the rows BEFORE the icon cells because
         * menu-mode rows intentionally overlap the idle icon-cell
         * strip; the visible mode decides which surface owns clicks.
         *
         * Ref: ReDMCSB MENU.C F0391_MENUS_DidClickTriggerAction. */
        if (state->actingChampionOrdinal != 0) {
            unsigned char actions[3];
            int actionCount = 0;

            if (M11_GameView_GetActingActionIndices(state, actions)) {
                /* G0507's source list is contiguous: only the C113..C115
                 * rows with a real ActionIndex may reach F0391. */
                if (actions[0] != 0xFFu) {
                    actionCount = 1;
                    if (actions[1] != 0xFFu) {
                        actionCount = 2;
                        if (actions[2] != 0xFFu) {
                            actionCount = 3;
                        }
                    }
                }
            }
            /* FM Towns uses a narrower 87-pixel panel at x=232..318
             * with three 7-pixel-tall text rows starting at y=77.
             * Hit-test directly against the source-locked geometry
             * instead of the PC34 route table. */
            /* FMTOWNS.H maps the common F0387/F0391 action path to
             * DRAW_DMENU/DYNAMENU for both DM1 and CSB.  CSB's CHTWE/CHTWJ
             * Game handoff deliberately does not populate DM1's startup
             * receipt, so using that receipt as the sole F31 discriminator
             * sent a real CSB F31 action panel through PC34 C113..C115
             * geometry.  The recovered F31 geometry below is the durable
             * input owner; its panel pixels remain separately fail-closed
             * until the CHTW* DRAW_DMENU raster consumer is recovered.
             * ReDMCSB FMTOWNS.H:76,498,650; MENU.C F0391. */
            if (actionCount > 0 &&
                (state->dm1FmtownsStartupReceiptValid ||
                 (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
                  m11_csb_is_fmtowns_profile(
                      (const CSB_V1_BootProfile *)state->csbBootProfile)))) {
                int fmx1 = 232, fmy1 = 77, fmx2 = 318;
                if (x >= fmx1 && x <= fmx2 && y >= fmy1 &&
                    y < fmy1 + (int)(actionCount * DM1_V1_FMTOWNS_CHAR_Y_HYT)) {
                    int row = (y - fmy1) / DM1_V1_FMTOWNS_CHAR_Y_HYT;
                    if (row >= 0 && row < actionCount &&
                        actions[row] != DM1_V1_FMTOWNS_DYNAMENU_SLOT_DISABLED) {
                        (void)M11_GameView_TriggerActionRow(state, row);
                        return M11_GAME_INPUT_REDRAW;
                    }
                    return M11_GAME_INPUT_REDRAW;
                }
            }
            /* F0371 resolves G0452 before it calls F0391.  The route table
             * carries C112/C113/C114/C115 and is cross-checked against the
             * source touch matrix; do not derive a command from pixels here. */
            if (actionCount > 0 && !state->dm1FmtownsStartupReceiptValid &&
                !(state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
                  m11_csb_is_fmtowns_profile(
                      (const CSB_V1_BootProfile *)state->csbBootProfile)) &&
                action_area_routes_GetTouchMatrixInvariant() &&
                action_area_routes_ResolveNameMenuClick(
                    x, y, (unsigned int)actionCount, &sourceRoute)) {
                if (sourceRoute.commandId >= 113u &&
                    sourceRoute.commandId <= 115u &&
                    sourceRoute.actionListIndex >= 0) {
                    (void)M11_GameView_TriggerActionRow(
                        state, sourceRoute.actionListIndex);
                    return M11_GAME_INPUT_REDRAW;
                }
                /* C112 is the source-owned pass zone.  PC34 F0391 returns
                 * without committing an action here, but it still reaches
                 * F0388 through F0391(-1) and closes the action menu.  The
                 * Atari ST 2.x G0452 table uses this literal C112 box too;
                 * merely redrawing it left the native action menu latched.
                 * ReDMCSB CLIKMENU.C F0371:529-539; MENU.C F0391:803-838. */
                if (sourceRoute.commandId == 112u) {
                    M11_GameView_ClearActingChampion(state);
                    return M11_GAME_INPUT_REDRAW;
                }
            }
        }

        if (state->actingChampionOrdinal == 0 &&
            action_area_routes_GetTouchMatrixInvariant() &&
            action_area_routes_ResolveIconClick(
                x, y, (unsigned int)state->world.party.championCount,
                &sourceRoute)) {
            int slotHit = sourceRoute.championIndex;
            /* Toggle: click on already-acting champion clears. */
            if (state->actingChampionOrdinal ==
                    (unsigned int)(slotHit + 1)) {
                M11_GameView_ClearActingChampion(state);
                return M11_GAME_INPUT_REDRAW;
            }
            if (M11_GameView_SetActingChampion(state, slotHit)) {
                return M11_GAME_INPUT_REDRAW;
            }
            return M11_GAME_INPUT_IGNORED;
        }
    }

    /* Firestaff focus-card shortcuts are debug/non-V1 helpers only.  In
     * authentic V1 chrome, ReDMCSB COMMAND.C G0448 owns the right-column
     * movement-arrow rectangles (C068..C073) below; the old focus-card box
     * at x=218..303/y=106..139 overlaps the top arrow row and must not
     * preempt C001/C002/C003. */
    if ((state->showDebugHUD ||
         (!m11_v1_chrome_mode_enabled(state) &&
          state->sourceKind != M11_GAME_SOURCE_CSB_BOOT)) &&
        (m11_point_in_rect(x, y,
                           M11_PROMPT_STRIP_X,
                           M11_PROMPT_STRIP_Y,
                           M11_PROMPT_STRIP_W,
                           M11_PROMPT_STRIP_H) ||
         m11_point_in_rect(x, y, 218, 106, 86, 34))) {
        return M11_GameView_HandleInput(state, M12_MENU_INPUT_ACCEPT);
    }

    /* ReDMCSB COMMAND.C G0448 maps the source movement-arrow zones
     * (C068/C070/C069/C073/C072/C071) to commands 1/3/2/6/5/4;
     * CLIKMENU.C F0366 then treats C004 as relative right movement. */
    /* CSB retains COMMAND.C G0448's source hit zones even if the optional
     * DM1 chrome switch is off. Otherwise the same clicks would reach the
     * host focus-card shortcut above instead of C068..C073. */
    if ((m11_v1_chrome_mode_enabled(state) ||
         state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) &&
        !state->showDebugHUD) {
        int space = DM1_V1_MOUSE_SPACE_NONE_PC34;
        int zoneId = 0;
        int command = DM1_V1_MouseRoutes_CommandForScreenPointPc34Compat(
            DM1_V1_MOUSE_LIST_MOVEMENT_PC34,
            x, y,
            DM1_V1_MOUSE_MASK_LEFT_PC34,
            &space,
            &zoneId);
        (void)space;
        /* ReDMCSB COMMAND.C G0448: C068/C070/C069/C073/C072/C071 →
         * commands 1/3/2/6/5/4. Commands 1/2 are absolute turn;
         * commands 3/5 are direction-aware forward/back;
         * commands 4/6 are absolute strafe. Route directly to the
         * matching M12_MENU_INPUT_* so keyboard and mouse share the
         * same switch-case pipeline (m11_apply_dm1_v1_pipeline_tick
         * or m11_apply_tick). */
        if (command >= 1 && command <= 6) {
            M12_MenuInput arrowInput;
            switch (command) {
                case 1: arrowInput = M12_MENU_INPUT_LEFT;         break;
                case 2: arrowInput = M12_MENU_INPUT_RIGHT;        break;
                case 3: arrowInput = M12_MENU_INPUT_UP;           break;
                case 5: arrowInput = M12_MENU_INPUT_DOWN;         break;
                case 4: arrowInput = M12_MENU_INPUT_STRAFE_RIGHT;  break;
                case 6: arrowInput = M12_MENU_INPUT_STRAFE_LEFT;   break;
                default: arrowInput = M12_MENU_INPUT_NONE;        break;
            }
            if (arrowInput != M12_MENU_INPUT_NONE) {
                return M11_GameView_HandleInput(state, (int)arrowInput);
            }
        }
    }

    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT ||
        m11_point_in_rect(x, y,
                          M11_VIEWPORT_X,
                          M11_VIEWPORT_Y,
                          M11_VIEWPORT_W,
                          M11_VIEWPORT_H)) {
        if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
            DM2_V1_BootProfile *profile =
                (DM2_V1_BootProfile *)state->dm2BootProfile;
            DM2_V1_DungeonInputOwner input_owner;
            DM2_V1_DungeonInputReceipt input_receipt;
            M12_MenuInput routed_input = M12_MENU_INPUT_NONE;

            /* The Macintosh build does not use the PC MOUSE_INPUT rectangle
             * table.  Its C080 owner resolves the renderer's live c_rwbb
             * target list first, then dispatches the recovered Mac action
             * owner.  Bypass the PC admission gate here or this path can
             * never reach m11_process_dm2_v1_c080_click. */
            if (profile && m11_dm2_is_mac_profile(profile)) {
                return m11_process_dm2_v1_c080_click(state, x, y);
            }

            /* SKProject routes a live DM2 click through c_tmouse/c_input's
             * active GDAT table.  PC-English uses its recovered PC matrix;
             * FM Towns uses only its authenticated RAW4 rectangle subset. */
            if (!profile ||
                ((strcmp(profile->graphics_md5,
                         "027ff3b8ddc2c4c4cdda7ada0b0bc46c") == 0) ?
                     !dm2_v1_dungeon_input_owner_init_fmtowns(
                         &input_owner, profile) :
                     !dm2_v1_dungeon_input_owner_init(
                         &input_owner, profile->graphics_md5)) ||
                !dm2_v1_dungeon_input_owner_route(
                    &input_owner, (int16_t)x, (int16_t)y, buttonMask,
                    NULL, NULL, &input_receipt) ||
                !input_receipt.accepted) {
                return M11_GAME_INPUT_IGNORED;
            }
            switch (input_receipt.event_index) {
            case 1: routed_input = M12_MENU_INPUT_TURN_LEFT; break;
            case 2: routed_input = M12_MENU_INPUT_TURN_RIGHT; break;
            case 3: routed_input = M12_MENU_INPUT_UP; break;
            case 4: routed_input = M12_MENU_INPUT_STRAFE_RIGHT; break;
            case 5: routed_input = M12_MENU_INPUT_DOWN; break;
            case 6: routed_input = M12_MENU_INPUT_STRAFE_LEFT; break;
            case 80:
                return m11_process_dm2_v1_c080_click(state, x, y);
            case 116: case 117: case 118: case 119:
            case 120: case 121: case 122: case 123:
                if (dm2_v1_runtime_activate_action_hand(
                        (input_receipt.event_index - 116u) / 2u,
                        (input_receipt.event_index - 116u) % 2u))
                    return M11_GAME_INPUT_REDRAW;
                return M11_GAME_INPUT_IGNORED;
            case 112:
                /* COMMAND.C event 0x70 closes the source hand/action panel
                 * without committing an action. */
                M11_GameView_ClearActingChampion(state);
                return M11_GAME_INPUT_REDRAW;
            case 11:
                /* c_input.cpp panel event 11 is the source inventory-panel
                 * close lane.  Keep it distinct from the DM1 C011 table:
                 * this branch is admitted only after the authenticated DM2
                 * Towns route has resolved the native rectangle. */
                if (state->inventoryPanelActive) {
                    state->inventoryPanelActive = 0;
                    return M11_GAME_INPUT_REDRAW;
                }
                return M11_GAME_INPUT_IGNORED;
            case 142:
                /* Source sleep/wake table: 142 enters sleep and 143 wakes.
                 * The runtime owns the bit; no host timer is created here. */
                dm2_v1_runtime_set_sleeping(1);
                return M11_GAME_INPUT_REDRAW;
            case 143:
                dm2_v1_runtime_set_sleeping(0);
                return M11_GAME_INPUT_REDRAW;
            case 113: case 114: case 115: {
                DM2_V1_EngageCommandReceipt command_receipt;
                if (dm2_v1_runtime_proceed_hand_command(
                        input_receipt.event_index - 113u,
                        &command_receipt))
                    return M11_GAME_INPUT_REDRAW;
                return M11_GAME_INPUT_IGNORED;
            }
            default: break;
            }
            if (routed_input == M12_MENU_INPUT_NONE) {
                /* Viewport and other source zones need their c_input owner;
                 * do not turn them into a generic movement shortcut. */
                return M11_GAME_INPUT_IGNORED;
            }
            return M11_GameView_HandleInput(state, routed_input);
        }
        if ((m11_is_dm1_source_kind(state->sourceKind) ||
             state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) &&
            !state->showDebugHUD) {
            int space = DM1_V1_MOUSE_SPACE_NONE_PC34;
            int zoneId = 0;
            int command = DM1_V1_MouseRoutes_CommandForScreenPointPc34Compat(
                DM1_V1_MOUSE_LIST_MOVEMENT_PC34,
                x, y,
                DM1_V1_MOUSE_MASK_LEFT_PC34,
                &space,
                &zoneId);
            if (command == 80 && space == DM1_V1_MOUSE_SPACE_SCREEN_PC34 && zoneId == 7) {
                /* ReDMCSB COMMAND.C G0448 maps a left-click in C007_ZONE_VIEWPORT
                 * to C080_COMMAND_CLICK_IN_DUNGEON_VIEW.  The source then enters
                 * CLIKVIEW.C F0377/F0372/F0275 to test front-wall sensors,
                 * champion mirrors, door buttons and wall ornaments.  CSB retains
                 * this source command surface in every presentation mode, and so
                 * does DM1: Modern may filter the raster, but it never replaces
                 * COMMAND.C input with Firestaff's procedural left/right viewport
                 * steering shortcuts. Movement remains owned by C068..C073. */
                return m11_process_v1_c080_click(state, x, y);
            }
            return M11_GAME_INPUT_IGNORED;
        }
        return M11_GameView_HandleInput(state, m11_pointer_viewport_input(state, x, y));
    }

    if (m11_point_in_rect(x, y,
                          M11_CONTROL_STRIP_X,
                          M11_CONTROL_STRIP_Y,
                          M11_CONTROL_STRIP_W,
                          M11_CONTROL_STRIP_H)) {
        /* This is Firestaff's diagnostic control strip.  Classic DM1 owns
         * movement through COMMAND.C G0448's C068..C073 zones in C013; the
         * strip is neither drawn nor an input owner for a source DM1 frame. */
        if (m11_is_dm1_source_kind(state->sourceKind) &&
            strcmp(state->sourceId, "dm1") == 0 &&
            !state->showDebugHUD && m11_v1_chrome_mode_enabled(state)) {
            return M11_GAME_INPUT_IGNORED;
        }
        /* v2.8.x: the on-screen arrow buttons mirror the keyboard
         * convention: Left/Right = strafe, Up/Down = forward/back
         * (matches the original DM1 PC 3.4 arrow-zone semantics
         * the user requested).  Action button still routes to
         * M12_MENU_INPUT_ACTION. */
        if (m11_point_in_rect(x, y, 18, 167, 15, 10)) {
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_STRAFE_LEFT);
        }
        if (m11_point_in_rect(x, y, 35, 167, 15, 10)) {
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_UP);
        }
        if (m11_point_in_rect(x, y, 52, 167, 15, 10)) {
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_STRAFE_RIGHT);
        }
        if (m11_point_in_rect(x, y, 69, 167, 15, 10)) {
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_DOWN);
        }
        if (m11_point_in_rect(x, y, 86, 167, 12, 10)) {
            return M11_GameView_HandleInput(state, M12_MENU_INPUT_ACTION);
        }
    }

    {
        int slotStep = m11_party_slot_step(state);
        int slotW    = m11_party_slot_w(state);
        for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
            int slotX = m11_party_panel_x(state) + slot * slotStep;
            if (m11_point_in_rect(x, y,
                                  slotX,
                                  M11_PARTY_PANEL_Y + 20,
                                  slotW,
                                  M11_PARTY_SLOT_H - 20)) {
                if (m11_set_active_champion(state, slot)) {
                    return M11_GAME_INPUT_REDRAW;
                }
                return M11_GAME_INPUT_IGNORED;
            }
        }
    }

    /* Final fallback: if we got here without returning yet, this
     * is a click that didn't match any of the per-zone routes
     * above.  We still don't mutate the world, so we don't refresh
     * the hash. */
    return M11_GAME_INPUT_IGNORED;
}

/* Update lastWorldHash after a click that mutated the world.
 * The click paths (inventory pickup, slot place, chest open, etc.)
 * modify world state but do not run a full tick; the tick is what
 * normally refreshes state->lastWorldHash.  Callers that
 * assert world-hash determinism (test_m11_inventory_full_panel)
 * rely on this hook.  F0891_ORCH_WorldHash_Compat returns 0 if the
 * world is uninitialised, which is the sentinel we want to detect
 * via the assert helper. */
static void m11_refresh_world_hash_after_click(M11_GameViewState* state) {
    if (state == 0) return;
    F0891_ORCH_WorldHash_Compat(&state->world, &state->lastWorldHash);
}

static void m11_draw_party_arrow(unsigned char* framebuffer,
                                 int framebufferWidth,
                                 int framebufferHeight,
                                 int x,
                                 int y,
                                 int size,
                                 int direction,
                                 unsigned char color) {
    int i;
    int cx = x + size / 2;
    int cy = y + size / 2;
    for (i = 0; i < size / 3; ++i) {
        switch (direction) {
            case DIR_NORTH:
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, cx, y + 2 + i, color);
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, cx - i, y + 3 + i, color);
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, cx + i, y + 3 + i, color);
                break;
            case DIR_EAST:
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x + size - 3 - i, cy, color);
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x + size - 4 - i, cy - i, color);
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x + size - 4 - i, cy + i, color);
                break;
            case DIR_SOUTH:
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, cx, y + size - 3 - i, color);
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, cx - i, y + size - 4 - i, color);
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, cx + i, y + size - 4 - i, color);
                break;
            case DIR_WEST:
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x + 2 + i, cy, color);
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x + 3 + i, cy - i, color);
                m11_put_pixel(framebuffer, framebufferWidth, framebufferHeight, x + 3 + i, cy + i, color);
                break;
            default:
                break;
        }
    }
}

typedef struct {
    int x;
    int y;
    int w;
    int h;
} M11_ViewRect;

/* Forward declaration for floor ornament rendering (defined after door ornaments). */
static int m11_draw_floor_ornament(const M11_GameViewState* state,
                                   unsigned char* framebuffer,
                                   int fbW, int fbH,
                                   const M11_ViewRect* rect,
                                   int ornamentOrdinal,
                                   int depthIndex,
                                   int sideHint);

enum {
    M11_MAX_CELL_CREATURES = 4, /* DM1 supports up to 4 creature groups per square */
    M11_MAX_CELL_ITEMS    = 4, /* DM1 scatters up to 4 floor items visibly */
    M11_MAX_CELL_PROJECTILES =
        DM1_V1_VIEWPORT_RUNTIME_MATERIALIZATION_MAX_RENDERABLE_PROJECTILES
};

typedef struct M11_ViewportCell {
    int valid;
    int mapX;
    int mapY;
    int relForward;
    int relSide;
    unsigned char square;
    int elementType;
    int thingCount;
    unsigned short firstThing;
    int doorState;
    int doorType;
    int doorVertical;
    int hasDoorThing;
    int creatureType; /* -1 if no creature, else creature type index (0-26) */
    /* All creature group types on this square (up to 4, -1 terminated) */
    int creatureTypes[M11_MAX_CELL_CREATURES];
    int creatureCountsPerGroup[M11_MAX_CELL_CREATURES]; /* creature count per group (count+1) */
    int creatureDirections[M11_MAX_CELL_CREATURES]; /* DungeonGroup_Compat.direction per group */
    int creatureCells[M11_MAX_CELL_CREATURES]; /* F0115-relative cell 0..3 */
    int creatureGroupCount; /* number of valid entries in creatureTypes[] */
    /* First floor item info for sprite rendering (legacy single-item) */
    int firstItemThingType;    /* THING_TYPE_WEAPON..JUNK, or -1 if no item */
    int firstItemSubtype;      /* weapon/armour/potion/junk subtype, or -1 */
    /* All visible floor items (up to 4) for multi-item scatter */
    int floorItemTypes[M11_MAX_CELL_ITEMS];    /* THING_TYPE_*, -1 sentinel */
    int floorItemSubtypes[M11_MAX_CELL_ITEMS]; /* subtype per item, -1 sentinel */
    int floorItemCells[M11_MAX_CELL_ITEMS];    /* relative cell 0..3 */
    unsigned short floorItemThings[M11_MAX_CELL_ITEMS]; /* source THING */
    int floorItemCount; /* number of valid entries in floorItem arrays */
    /* Wall/door ornament ordinal from thing data (0-15, -1 if none) */
    int wallOrnamentOrdinal;
    int championPortraitOrdinal; /* ReDMCSB G0289: 0-based portrait index, or -1 */
    /* Original C127 sensor cell accepted by F0172 for this visible wall. */
    int championPortraitWallCell;
    int doorOrnamentOrdinal;
    /* First projectile graphic index (416-438) from GRAPHICS.DAT, or -1 */
    int firstProjectileGfxIndex;
    /* Set only after the live F0142/F0115 record has resolved its exact
     * PC34 material.  A live object Slot with unavailable thing data must
     * not inherit an older spell graphic or a procedural marker. */
    int firstProjectileMaterialReady;
    int firstProjectileSubtype;
    int firstProjectileUsesObjectMaterial;
    int firstProjectileObjectAspectIndex;
    /* First projectile direction relative to party facing.
     * 0 = moving away from party, 1 = moving right, 2 = toward party,
     * 3 = moving left.  -1 if no projectile or direction unknown.
     * Used for DM1-faithful projectile sprite mirroring. */
    int firstProjectileRelDir;
    /* First projectile sub-cell position (0-3, or -1 if none).
     * In DM1, projectiles occupy a specific sub-cell (quadrant) within
     * the tile.  0=NW, 1=NE, 2=SW, 3=SE (absolute).  The relative
     * sub-cell position (relative to party facing) determines the
     * projectile's viewport offset within the cell face area.
     * Ref: ReDMCSB DUNVIEW.C F115 — M11_CELL(P141_T_Thing) positioning. */
    int firstProjectileCell;
    /* DM1 F0115/F0791 flip flags for first projectile bitmap:
     * bit0 = horizontal, bit1 = vertical. */
    int firstProjectileFlipFlags;
    /* F0115 C2900 draws every admitted live C14 in effect-list order. */
    int renderableProjectileCount;
    int projectileGfxIndices[M11_MAX_CELL_PROJECTILES];
    int projectileSubtypes[M11_MAX_CELL_PROJECTILES];
    int projectileUsesObjectMaterial[M11_MAX_CELL_PROJECTILES];
    int projectileObjectAspectIndices[M11_MAX_CELL_PROJECTILES];
    int projectileRelDirs[M11_MAX_CELL_PROJECTILES];
    int projectileCells[M11_MAX_CELL_PROJECTILES];
    int projectileFlipFlags[M11_MAX_CELL_PROJECTILES];
    /* Floor ornament ordinal for this square (1-based ordinal, 0 = none).
     * In DM1, corridor/pit/stair/teleporter squares may have floor
     * ornaments assigned via random generation or sensor things.
     * Ref: ReDMCSB DUNGEON.C F169 — SquareAspect[C4_FLOOR_ORNAMENT_ORDINAL]. */
    int floorOrnamentOrdinal;
    /* Inscription text-string thing index (into things->textStrings[]),
     * or -1 if no inscription text on this wall.  Set when the wall
     * ornament matches the map's inscription ornament index and a
     * TEXT_STRING thing exists on this square.
     * Ref: ReDMCSB DUNGEON.C:2593 G0290_T_DungeonView_InscriptionThing. */
    int inscriptionTextIndex;
    /* First explosion type (0-50), or -1 */
    int firstExplosionType;
    /* First explosion currentFrame (0..maxFrames-1), or -1 if none. */
    int firstExplosionFrame;
    /* First explosion maxFrames (from Phase17_ExplosionMaxFrames), or
     * 0 if none.  Used by the viewport burst renderer to modulate
     * size/intensity across the classic DM1 multi-frame aftermath. */
    int firstExplosionMaxFrames;
    /* First explosion residual attack (0..255), or -1 if none.  Poison
     * cloud and smoke decay this per frame; the burst renderer uses it
     * to fade the cloud as it dissipates. */
    int firstExplosionAttack;
    int firstExplosionCell;
    int firstExplosionCentered;
    /* DM1 owns every visible F0172/F0115 materialization choice.  D1C also
     * carries the HoC wall-overlay specialization below. */
    int dm1MaterializationDecisionReady;
    DM1_V1_ViewportRuntimeMaterializationDecisionPc34 dm1MaterializationDecision;
    int dm1RuntimeRenderDecisionReady;
    DM1_V1_ChampionMirrorRuntimeRenderDecisionPc34 dm1RuntimeRenderDecision;
    DM1_F0115RuntimeSummaryPc34 summary;
} M11_ViewportCell;

static int m11_viewport_cell_is_wall_free(const M11_ViewportCell* cell);

static int m11_viewport_cell_has_renderable_projectile(
    const M11_ViewportCell* cell) {
    if (!cell || !cell->firstProjectileMaterialReady ||
        !dm1_v1_projectile_renderable_pc34(cell->summary.projectiles,
                                            cell->firstProjectileGfxIndex)) {
        return 0;
    }
    /* C127/C026 belongs to DUNVIEW's wall-overlay route. The live F0115
     * receipt may still admit an independent projectile on that square, but
     * a mirror payload may never reach M11's generic projectile blitter. */
    return !cell->dm1RuntimeRenderDecisionReady ||
           !cell->dm1RuntimeRenderDecision.suppressMirrorAsProjectile ||
           cell->dm1RuntimeRenderDecision.drawRuntimeProjectile;
}

static int m11_viewport_cell_projectile_sample(
    const M11_ViewportCell* cell,
    int index,
    M11_ViewportCell* outSample)
{
    if (!cell || !outSample || index < 0 ||
        index >= cell->renderableProjectileCount ||
        index >= M11_MAX_CELL_PROJECTILES) {
        return 0;
    }
    *outSample = *cell;
    outSample->summary.projectiles = 1;
    outSample->firstProjectileGfxIndex = cell->projectileGfxIndices[index];
    outSample->firstProjectileMaterialReady = 1;
    outSample->firstProjectileSubtype = cell->projectileSubtypes[index];
    outSample->firstProjectileUsesObjectMaterial =
        cell->projectileUsesObjectMaterial[index];
    outSample->firstProjectileObjectAspectIndex =
        cell->projectileObjectAspectIndices[index];
    outSample->firstProjectileRelDir = cell->projectileRelDirs[index];
    outSample->firstProjectileCell = cell->projectileCells[index];
    outSample->firstProjectileFlipFlags = cell->projectileFlipFlags[index];
    return 1;
}

static int m11_viewport_cell_has_renderable_explosion(
    const M11_ViewportCell* cell) {
    return cell &&
           cell->dm1MaterializationDecisionReady &&
           cell->dm1MaterializationDecision.drawDeferredSpellEffects &&
           cell->dm1MaterializationDecision.liveRenderableExplosionCount > 0;
}

/* F0115 reaches alcoves through C2548 rather than C2500, but that changes
 * only the placement material. C127 payload ownership still applies before
 * either object route reaches an M11 blitter. */
static int m11_dm1_floor_item_material_allowed(const M11_ViewportCell* cell,
                                                int alcoveRoute)
{
    if (!cell || !cell->dm1MaterializationDecisionReady ||
        (!alcoveRoute && !cell->dm1MaterializationDecision.drawFloorItems)) {
        return 0;
    }
    return !cell->dm1RuntimeRenderDecisionReady ||
           !cell->dm1RuntimeRenderDecision.suppressMaterializedItemPayload ||
           cell->dm1RuntimeRenderDecision.drawFloorObject;
}

static int m11_viewport_cell_explosion_material(
    const M11_ViewportCell* cell,
    int index,
    M11_ViewportCell* outMaterial)
{
    const DM1_V1_ViewportRuntimeMaterializationDecisionPc34* decision;

    if (!cell || !outMaterial || !cell->dm1MaterializationDecisionReady) {
        return 0;
    }
    decision = &cell->dm1MaterializationDecision;
    if (index < 0 || index >= decision->liveRenderableExplosionCount) {
        return 0;
    }
    *outMaterial = *cell;
    outMaterial->firstExplosionType = decision->liveRenderableExplosionTypes[index];
    outMaterial->firstExplosionFrame = decision->liveRenderableExplosionFrames[index];
    outMaterial->firstExplosionMaxFrames =
        decision->liveRenderableExplosionMaxFrames[index];
    outMaterial->firstExplosionAttack = decision->liveRenderableExplosionAttacks[index];
    outMaterial->firstExplosionCell = decision->liveRenderableExplosionCells[index];
    outMaterial->firstExplosionCentered =
        decision->liveRenderableExplosionCentered[index];
    return 1;
}

static int m11_sample_viewport_cell(const M11_GameViewState* state,
                                    int relForward,
                                    int relSide,
                                    M11_ViewportCell* outCell);
static int m11_build_dm1_front_champion_portrait_receipt(
    const M11_ViewportCell* cell,
    DM1_V1_ChampionMirrorRenderReceiptPc34* outReceipt);
static int m11_build_dm1_hoc_front_mirror_runtime_decision(
    const M11_GameViewState* state,
    const M11_ViewportCell* frontCell,
    DM1_V1_ChampionMirrorRuntimeRenderDecisionPc34* outDecision);
static int m11_front_mirror_host_material_ready(
    const M11_GameViewState* state);

static int m11_projectile_associated_thing_material(
    const M11_GameViewState* state,
    unsigned short thing,
    int* outThingType,
    int* outThingSubtype,
    int* outWeaponProjectileAspectOrdinal)
{
    const struct DungeonThings_Compat* things;
    const unsigned char* raw;
    DM1_WeaponInfo weaponInfo;
    int objectWeight;
    int thingType;

    if (!state || !outThingType || !outThingSubtype ||
        !outWeaponProjectileAspectOrdinal || thing == THING_NONE ||
        thing == THING_ENDOFLIST) {
        return 0;
    }
    things = state->world.things;
    if (!things) {
        return 0;
    }
    thingType = THING_GET_TYPE(thing);
    /* ReDMCSB F0328 carries the original C05..C0B Thing into
     * F0212.Projectile.Slot.  F0142/F0115 must consume that same loaded
     * F0156 record, and F0140 proves the containing F0159 chain is still
     * intact.  A decoded object mirror cannot authorize a flying object. */
    if (!dm1_v1_dungeon_get_object_weight_f0140_pc34(
            things, thing, &objectWeight)) {
        return 0;
    }
    raw = dm1_v1_dungeon_get_thing_data_pc34(things, thing);
    if (!raw) {
        return 0;
    }
    *outThingType = thingType;
    *outThingSubtype = 0;
    *outWeaponProjectileAspectOrdinal = 0;

    switch (thingType) {
        case THING_TYPE_WEAPON:
            *outThingSubtype = raw[2] & 0x7f;
            if (!dm1_weapon_info_pc34(*outThingSubtype, &weaponInfo)) return 0;
            *outWeaponProjectileAspectOrdinal =
                (weaponInfo.attributes >> 8) & 0x1f;
            return 1;
        case THING_TYPE_ARMOUR:
            *outThingSubtype = raw[2] & 0x7f;
            return 1;
        case THING_TYPE_SCROLL:
            return 1;
        case THING_TYPE_POTION:
            *outThingSubtype = raw[3] & 0x7f;
            return 1;
        case THING_TYPE_CONTAINER:
            return 1;
        case THING_TYPE_JUNK:
            *outThingSubtype = raw[2] & 0x7f;
            return 1;
        default:
            return 0;
    }
}

static int m11_fluxcage_field_source_bound(
    const M11_GameViewState* state,
    int mapIndex,
    int mapX,
    int mapY)
{
    if (!state) return 0;
    return dm1_v1_viewport_runtime_fluxcage_source_bound_pc34(
        state->world.dungeon, state->world.things,
        &state->world.explosions, mapIndex, mapX, mapY);
}

static int m11_build_dm1_viewport_materialization_decision(
    const M11_GameViewState* state,
    M11_ViewportCell* cell,
    DM1_V1_ViewportRuntimeMaterializationDecisionPc34* outDecision)
{
    DM1_V1_ViewportRuntimeMaterializationInputPc34 input;
    if (!state || !cell || !outDecision) {
        return 0;
    }
    memset(&input, 0, sizeof(input));
    input.relativeForward = cell->relForward;
    input.relativeSide = cell->relSide;
    input.elementType = cell->elementType;
    input.floorItemCount = cell->floorItemCount;
    input.projectileCount = cell->summary.projectiles;
    input.projectileCell = cell->firstProjectileCell;
    input.mapIndex = state->world.party.mapIndex;
    input.mapX = cell->mapX;
    input.mapY = cell->mapY;
    input.partyDirection = state->world.party.direction;
    input.suppressFluxcages = state->endgameDoNotDrawFluxcages;
    input.sourceBoundFluxcage = m11_fluxcage_field_source_bound(
        state, input.mapIndex, input.mapX, input.mapY);
    input.liveProjectiles = &state->world.projectiles;
    input.liveExplosions = &state->world.explosions;
    input.hasVisibleChampionMirrorPayload =
        cell->relForward == 1 && cell->relSide == 0 &&
        cell->championPortraitOrdinal >= 0;
    /* ReDMCSB rebuilds F0172/F0115 view state after every entrance or save
     * handoff. The live effect lists remain authoritative; provenance never
     * selects an M11 fallback. */
    input.runtimeOrigin = (DM1_V1_ViewportRuntimeOriginPc34)
        state->dm1ViewportRuntimeOrigin;
    if (!dm1_v1_viewport_runtime_materialization_decide_pc34(&input,
                                                               outDecision)) {
        return 0;
    }
    /* ReDMCSB: DUNVIEW.C F0115:5668-5683 and :5916-5933 consumes the
     * current effect records after F0219/F0220 mutation. The DM1 decision
     * owns this projection; M11 only transfers it to the legacy blitters. */
    cell->renderableProjectileCount = 0;
    cell->firstProjectileGfxIndex = -1;
    cell->firstProjectileMaterialReady = 0;
    cell->firstProjectileUsesObjectMaterial = 0;
    cell->firstProjectileObjectAspectIndex = -1;
    cell->firstProjectileFlipFlags = 0;
    if (outDecision->liveRenderableProjectileCount > 0) {
        int projectileIndex;
        cell->summary.projectiles = outDecision->liveProjectileCount;
        cell->summary.total += outDecision->liveProjectileCount;
        /* ReDMCSB DUNVIEW.C F0115:5668-5900 consumes every live C14 in
         * effect-list order. A broken object record, missing C2900 cell, or
         * unresolved PC34 material is a no-draw for that record only. */
        for (projectileIndex = 0;
             projectileIndex < outDecision->liveRenderableProjectileCount &&
             cell->renderableProjectileCount < M11_MAX_CELL_PROJECTILES;
             ++projectileIndex) {
            DM1_ProjectileMaterialResolutionPc34 material;
            int thingType = -1;
            int thingSubtype = -1;
            int weaponProjectileAspectOrdinal = 0;
            int hasAssociatedThing;
            int associatedThingResolved;
            int projectileCell =
                outDecision->liveRenderableProjectileCells[projectileIndex];
            int projectileRelDir =
                (outDecision->liveRenderableProjectileDirections[projectileIndex] -
                 state->world.party.direction) & 3;
            int sourceCell =
                (projectileCell - state->world.party.direction) & 3;
            int sourceX;
            int sourceY;
            int renderIndex;

            if (!dm1_viewport_3d_c2900_projectile_raw_zone_point(
                    outDecision->row, sourceCell, &sourceX, &sourceY)) {
                continue;
            }
            hasAssociatedThing =
                outDecision->liveRenderableProjectileAssociatedThings[projectileIndex] != THING_NONE &&
                outDecision->liveRenderableProjectileAssociatedThings[projectileIndex] != THING_ENDOFLIST;
            associatedThingResolved = m11_projectile_associated_thing_material(
                state, outDecision->liveRenderableProjectileAssociatedThings[projectileIndex],
                &thingType, &thingSubtype, &weaponProjectileAspectOrdinal);
            if ((hasAssociatedThing && !associatedThingResolved) ||
                !dm1_v1_projectile_material_resolve_pc34(
                    outDecision->liveRenderableProjectileSubtypes[projectileIndex],
                    thingType, thingSubtype, weaponProjectileAspectOrdinal,
                    &material)) {
                continue;
            }
            renderIndex = cell->renderableProjectileCount++;
            cell->projectileGfxIndices[renderIndex] = material.graphic_index;
            cell->projectileSubtypes[renderIndex] =
                outDecision->liveRenderableProjectileSubtypes[projectileIndex];
            cell->projectileUsesObjectMaterial[renderIndex] =
                material.uses_object_aspect;
            cell->projectileObjectAspectIndices[renderIndex] = material.aspect_index;
            cell->projectileRelDirs[renderIndex] = projectileRelDir;
            cell->projectileCells[renderIndex] = projectileCell;
            cell->projectileFlipFlags[renderIndex] = 0;
            if (!material.uses_object_aspect) {
                cell->projectileGfxIndices[renderIndex] =
                    dm1_v1_projectile_graphic_index(material.aspect_index,
                                                     projectileRelDir);
                cell->projectileFlipFlags[renderIndex] =
                    dm1_v1_projectile_flip_flags(material.aspect_index,
                                                  projectileRelDir,
                                                  projectileCell,
                                                  cell->mapX, cell->mapY);
            }
            (void)sourceX;
            (void)sourceY;
        }
        if (cell->renderableProjectileCount > 0) {
            M11_ViewportCell firstProjectile;
            if (m11_viewport_cell_projectile_sample(cell, 0, &firstProjectile)) {
                cell->firstProjectileGfxIndex = firstProjectile.firstProjectileGfxIndex;
                cell->firstProjectileMaterialReady = 1;
                cell->firstProjectileSubtype = firstProjectile.firstProjectileSubtype;
                cell->firstProjectileUsesObjectMaterial =
                    firstProjectile.firstProjectileUsesObjectMaterial;
                cell->firstProjectileObjectAspectIndex =
                    firstProjectile.firstProjectileObjectAspectIndex;
                cell->firstProjectileRelDir = firstProjectile.firstProjectileRelDir;
                cell->firstProjectileCell = firstProjectile.firstProjectileCell;
                cell->firstProjectileFlipFlags = firstProjectile.firstProjectileFlipFlags;
            }
        }
    }
    if (outDecision->liveExplosionCount > 0) {
        cell->summary.explosions = outDecision->liveExplosionCount;
        cell->summary.total += outDecision->liveExplosionCount;
        cell->firstExplosionType = outDecision->liveExplosionType;
        cell->firstExplosionFrame = outDecision->liveExplosionFrame;
        cell->firstExplosionMaxFrames = outDecision->liveExplosionMaxFrames;
        cell->firstExplosionAttack = outDecision->liveExplosionAttack;
    }
    if (outDecision->liveRenderableExplosionCount > 0) {
        /* Fluxcage and rebirth may precede a normal C15 record in the live
         * slot array. F0115 handles those through distinct routes, so M11's
         * ordinary F0114 consumer must start from the first admitted record,
         * not reuse the unfiltered summary's first slot. */
        cell->firstExplosionType = outDecision->liveRenderableExplosionTypes[0];
        cell->firstExplosionFrame = outDecision->liveRenderableExplosionFrames[0];
        cell->firstExplosionMaxFrames =
            outDecision->liveRenderableExplosionMaxFrames[0];
        cell->firstExplosionAttack = outDecision->liveRenderableExplosionAttacks[0];
    }
    return 1;
}

static int m11_dm1_v2_cell_would_seed_visible_effect(
    const M11_ViewportCell* cell)
{
    return cell && cell->valid &&
           (m11_viewport_cell_has_renderable_projectile(cell) ||
            m11_viewport_cell_has_renderable_explosion(cell) ||
            (cell->summary.teleporters > 0 &&
             cell->elementType == DUNGEON_ELEMENT_TELEPORTER));
}

static int m11_count_dm1_v2_visible_effect_seeds_from_viewport(
    const M11_GameViewState* state)
{
    int count = 0;
    int depth;
    if (!state || !state->active) {
        return 0;
    }
    for (depth = 1; depth <= 3; ++depth) {
        int side;
        for (side = -1; side <= 1; ++side) {
            M11_ViewportCell cell;
            if (m11_sample_viewport_cell(state, depth, side, &cell)) {
                if (m11_dm1_v2_cell_would_seed_visible_effect(&cell)) {
                    ++count;
                }
            }
        }
    }
    return count;
}

int M11_GameView_ProbeDm1V2LiveEffectSeedCount(
    const M11_GameViewState* state)
{
    return m11_count_dm1_v2_visible_effect_seeds_from_viewport(state);
}

/* Draw a GRAPHICS.DAT-backed projectile sprite in the given area.
 * relativeDir: projectile direction relative to party facing (0-3), or -1.
 *   0 = flying away, 1 = flying right, 2 = flying toward, 3 = flying left.
 * relativeCell: projectile sub-cell relative to party facing (0-3), or -1.
 *   0 = back-left, 1 = back-right, 2 = front-left, 3 = front-right.
 *   When >= 0, the sprite is offset within the face area to match the
 *   DM1 quadrant-based projectile positioning.  When -1, centered.
 * In DM1, projectile sprites are mirrored horizontally when the relative
 * direction is 1 (right-bound); left-bound (3) and forward/backward (0,2)
 * use the normal sprite orientation.
 * Ref: ReDMCSB DUNVIEW.C F115 — projectile coordinate lookup uses
 * G218_aaaauc_Graphic558_ObjectCoordinateSets to position projectiles
 * within the viewport cell based on their sub-cell.
 * Returns 1 if a real sprite was drawn, 0 for fallback. */
static void m11_blit_scaled_flip(const M11_AssetSlot* slot,
                                 unsigned char* framebuffer,
                                 int fbW,
                                 int fbH,
                                 int dstX,
                                 int dstY,
                                 int dstW,
                                 int dstH,
                                 int transparentColor,
                                 int flipHorizontal,
                                 int flipVertical) {
    int dy;
    if (!slot || !slot->loaded || !slot->pixels || !framebuffer ||
        dstW <= 0 || dstH <= 0) {
        return;
    }
    for (dy = 0; dy < dstH; ++dy) {
        int sy = dy * (int)slot->height / dstH;
        int fbY = dstY + dy;
        int dx;
        if (flipVertical) sy = (int)slot->height - 1 - sy;
        if (fbY < 0 || fbY >= fbH) continue;
        for (dx = 0; dx < dstW; ++dx) {
            int sx = dx * (int)slot->width / dstW;
            int fbX = dstX + dx;
            unsigned char pixel;
            if (flipHorizontal) sx = (int)slot->width - 1 - sx;
            if (fbX < 0 || fbX >= fbW) continue;
            pixel = slot->pixels[sy * (int)slot->width + sx];
            if (transparentColor >= 0 && pixel == (unsigned char)transparentColor) continue;
            framebuffer[fbY * fbW + fbX] = pixel;
        }
    }
}

static int m11_projectile_aspect_flip_flags(int aspectIndex,
                                            int relativeDir,
                                            int relativeCell,
                                            int mapX,
                                            int mapY) {
    return dm1_v1_projectile_flip_flags(aspectIndex,
                                        relativeDir,
                                        relativeCell,
                                        mapX,
                                        mapY);
}

static int m11_draw_projectile_sprite(const M11_GameViewState* state,
                                      unsigned char* framebuffer,
                                      int framebufferWidth,
                                      int framebufferHeight,
                                      int x, int y, int w, int h,
                                      int gfxIndex, int depthIndex,
                                      int relativeDir,
                                      int relativeCell,
                                      int flipFlags,
                                      int sourceZoneRow) {
    return m11_draw_projectile_sprite_ex(state,
                                        framebuffer,
                                        framebufferWidth,
                                        framebufferHeight,
                                        x,
                                        y,
                                        w,
                                        h,
                                        gfxIndex,
                                        depthIndex,
                                        relativeDir,
                                        relativeCell,
                                        flipFlags,
                                        sourceZoneRow,
                                        -1,
                                        0);
}

static int m11_draw_projectile_sprite_ex(const M11_GameViewState* state,
                                         unsigned char* framebuffer,
                                         int framebufferWidth,
                                         int framebufferHeight,
                                         int x, int y, int w, int h,
                                         int gfxIndex, int depthIndex,
                                         int relativeDir,
                                         int relativeCell,
                                         int flipFlags,
                                         int sourceZoneRow,
                                         int transparentColor,
                                         int usesF0791Blit) {
    const M11_AssetSlot* slot;
    DM1_ProjectileSpriteBlitPlan plan;
    int effectiveTransparentColor;
    if (!state || !state->assetsAvailable || gfxIndex < 454 ||
        gfxIndex >= 486) return 0;
    (void)relativeDir;
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
        !m11_csb_install_runtime_source_graphic(state, (unsigned int)gfxIndex)) {
        return 0;
    }
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, (unsigned int)gfxIndex);
    /* F0115 may scale only a decoded M613 projectile surface. A cache entry
     * with dimensions but no pixel payload is not source material. */
    if (!slot || !slot->loaded || !slot->pixels ||
        slot->width == 0 || slot->height == 0) return 0;
    if (!dm1_v1_projectile_sprite_blit_plan(
            &plan,
            gfxIndex,
            depthIndex,
            relativeCell,
            flipFlags,
            sourceZoneRow,
            M11_VIEWPORT_X,
            M11_VIEWPORT_Y,
            M11_VIEWPORT_W,
            M11_VIEWPORT_H,
            x,
            y,
            w,
            h,
            (int)slot->width,
            (int)slot->height)) {
        return 0;
    }
    /* ReDMCSB DUNVIEW.C F0115 uses F0791/C10 for CSB C2900 projectile
     * source-zone blits.  DM1 wrapper calls and non-F0791 callers keep the
     * projectile plan's native transparent color instead of blindly trusting
     * a caller-provided material color. */
    effectiveTransparentColor =
        (usesF0791Blit && transparentColor >= 0)
            ? transparentColor
            : plan.transparent_color;
    if (plan.flip_flags & 0x02) {
        m11_blit_scaled_flip(slot, framebuffer, framebufferWidth, framebufferHeight,
                             plan.draw_x, plan.draw_y,
                             plan.draw_w, plan.draw_h,
                             effectiveTransparentColor,
                             (plan.flip_flags & 0x01) ? 1 : 0,
                             1);
    } else if (plan.flip_flags & 0x01) {
        M11_AssetLoader_BlitScaledMirror(slot, framebuffer, framebufferWidth,
                                         framebufferHeight,
                                         plan.draw_x, plan.draw_y,
                                         plan.draw_w, plan.draw_h,
                                         effectiveTransparentColor);
    } else {
        M11_AssetLoader_BlitScaled(slot, framebuffer, framebufferWidth,
                                   framebufferHeight,
                                   plan.draw_x, plan.draw_y,
                                   plan.draw_w, plan.draw_h,
                                   effectiveTransparentColor);
    }
    /* ReDMCSB DUNVIEW.C F0115:5645-5683 materializes M613 projectile
     * bitmaps in the C2900 lane after its source-zone/flip plan resolves. */
    if (m11_is_dm1_source_kind(state->sourceKind)) {
        s_m11_dm1_projectile_host_presentation_receipt.valid = 1;
        s_m11_dm1_projectile_host_presentation_receipt.projectileLane = 1;
        s_m11_dm1_projectile_host_presentation_receipt.objectMaterial = 0;
        s_m11_dm1_projectile_host_presentation_receipt.graphicsId = gfxIndex;
        s_m11_dm1_projectile_host_presentation_receipt.objectAspectIndex = -1;
        s_m11_dm1_projectile_host_presentation_receipt.transparentColor =
            effectiveTransparentColor;
        s_m11_dm1_projectile_host_presentation_receipt.flipFlags = plan.flip_flags;
        s_m11_dm1_projectile_host_presentation_receipt.sourceZoneRow = sourceZoneRow;
        s_m11_dm1_projectile_host_presentation_receipt.destinationX = plan.draw_x;
        s_m11_dm1_projectile_host_presentation_receipt.destinationY = plan.draw_y;
        s_m11_dm1_projectile_host_presentation_receipt.destinationW = plan.draw_w;
        s_m11_dm1_projectile_host_presentation_receipt.destinationH = plan.draw_h;
        s_m11_dm1_projectile_host_presentation_receipt.assetWidth = (int)slot->width;
        s_m11_dm1_projectile_host_presentation_receipt.assetHeight = (int)slot->height;
    }
    return 1;
}

static int m11_draw_thrown_object_projectile_sprite(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int gfxIndex,
    int objectAspectIndex,
    int depthIndex,
    int relativeCell,
    int viewLane,
    int sourceZoneRow)
{
    const M11_AssetSlot* slot;
    DM1_ThrownObjectProjectileBlitPlanPc34 plan;

    if (!state || !state->assetsAvailable || gfxIndex < DM1_GRAPHIC_FIRST_OBJECT) {
        return 0;
    }
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                (unsigned int)gfxIndex);
    if (!slot || !slot->loaded || !slot->pixels ||
        slot->width == 0 || slot->height == 0 ||
        !dm1_v1_thrown_object_projectile_blit_plan_pc34(
            &plan, gfxIndex, objectAspectIndex, depthIndex, relativeCell,
            viewLane, sourceZoneRow, M11_VIEWPORT_X, M11_VIEWPORT_Y, M11_VIEWPORT_W,
            M11_VIEWPORT_H, (int)slot->width, (int)slot->height)) {
        return 0;
    }
    /* ReDMCSB DUNVIEW.C F0115:5896-5900 jumps from F0142's positive
     * OBJECT_ASPECT result to T0115015 with the C2900 projectile position.
     * This is an effect-lane draw only, never an F0115 floor-item receipt. */
    if (plan.use_mirror) {
        M11_AssetLoader_BlitScaledMirror(slot, framebuffer, framebufferWidth,
                                         framebufferHeight, plan.draw_x,
                                         plan.draw_y, plan.draw_w, plan.draw_h,
                                         plan.transparent_color);
    } else {
        M11_AssetLoader_BlitScaled(slot, framebuffer, framebufferWidth,
                                   framebufferHeight, plan.draw_x, plan.draw_y,
                                   plan.draw_w, plan.draw_h,
                                   plan.transparent_color);
    }
    if (m11_is_dm1_source_kind(state->sourceKind)) {
        s_m11_dm1_projectile_host_presentation_receipt.valid = 1;
        s_m11_dm1_projectile_host_presentation_receipt.projectileLane = 1;
        s_m11_dm1_projectile_host_presentation_receipt.objectMaterial = 1;
        s_m11_dm1_projectile_host_presentation_receipt.graphicsId = gfxIndex;
        s_m11_dm1_projectile_host_presentation_receipt.objectAspectIndex =
            objectAspectIndex;
        s_m11_dm1_projectile_host_presentation_receipt.transparentColor =
            plan.transparent_color;
        s_m11_dm1_projectile_host_presentation_receipt.flipFlags =
            plan.use_mirror ? 1 : 0;
        s_m11_dm1_projectile_host_presentation_receipt.sourceZoneRow = sourceZoneRow;
        s_m11_dm1_projectile_host_presentation_receipt.destinationX = plan.draw_x;
        s_m11_dm1_projectile_host_presentation_receipt.destinationY = plan.draw_y;
        s_m11_dm1_projectile_host_presentation_receipt.destinationW = plan.draw_w;
        s_m11_dm1_projectile_host_presentation_receipt.destinationH = plan.draw_h;
        s_m11_dm1_projectile_host_presentation_receipt.assetWidth = (int)slot->width;
        s_m11_dm1_projectile_host_presentation_receipt.assetHeight = (int)slot->height;
    }
    return 1;
}

static int m11_draw_viewport_projectile_sprite(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int x,
    int y,
    int w,
    int h,
    const M11_ViewportCell* cell,
    int depthIndex,
    int sourceZoneRow)
{
    M11_Dm1F0115C2900CaptureRequest* capture =
        &s_m11_dm1_f0115_c2900_capture_request;
    const M11_AssetSlot* slot;
    unsigned int materialFNV1a;
    int rendered;

    if (!cell) {
        return 0;
    }
    if (state && m11_is_dm1_source_kind(state->sourceKind) &&
        !m11_is_stock_dm1_hall_map0(state) && capture->owner == state &&
        capture->runtimeTick == state->world.gameTick) {
        /* ReDMCSB DUNVIEW.C F0115:5635-5900 consumes every admitted C14 in
         * C2900 order. Count before material resolution: a missing original
         * M613 or F0142/G0209/M612 surface must clear this frame's receipt. */
        capture->requestedMaterialCount++;
    }
    if (cell->firstProjectileUsesObjectMaterial) {
        rendered = m11_draw_thrown_object_projectile_sprite(
            state, framebuffer, framebufferWidth, framebufferHeight,
            cell->firstProjectileGfxIndex,
            cell->firstProjectileObjectAspectIndex, depthIndex,
            cell->firstProjectileCell, cell->relSide, sourceZoneRow);
    } else {
        rendered = m11_draw_projectile_sprite(
            state, framebuffer, framebufferWidth, framebufferHeight, x, y, w, h,
            cell->firstProjectileGfxIndex, depthIndex, cell->firstProjectileRelDir,
            cell->firstProjectileCell, cell->firstProjectileFlipFlags, sourceZoneRow);
    }
    if (!rendered || capture->owner != state ||
        capture->runtimeTick != state->world.gameTick ||
        capture->requestedMaterialCount <= 0) {
        return rendered;
    }
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                (unsigned int)cell->firstProjectileGfxIndex);
    materialFNV1a = slot && slot->loaded && slot->pixels &&
        slot->width > 0 && slot->height > 0
        ? m11_dm1_runtime_capture_fnv1a(
              slot->pixels, (size_t)slot->width * (size_t)slot->height)
        : 0u;
    if (materialFNV1a == 0u) {
        return rendered;
    }
    materialFNV1a ^= (unsigned int)cell->firstProjectileGfxIndex;
    materialFNV1a *= 16777619u;
    materialFNV1a ^= (unsigned int)cell->firstProjectileUsesObjectMaterial;
    materialFNV1a *= 16777619u;
    materialFNV1a ^= (unsigned int)cell->firstProjectileObjectAspectIndex;
    materialFNV1a *= 16777619u;
    materialFNV1a ^= (unsigned int)sourceZoneRow;
    materialFNV1a *= 16777619u;
    materialFNV1a ^= (unsigned int)depthIndex;
    materialFNV1a *= 16777619u;
    if (capture->materialFNV1a == 0u) {
        capture->materialFNV1a = 2166136261u;
    }
    capture->materialFNV1a ^= materialFNV1a;
    capture->materialFNV1a *= 16777619u;
    if (capture->materialFNV1a == 0u) {
        capture->materialFNV1a = 1u;
    }
    capture->completedMaterialCount++;
    return rendered;
}

static int m11_dm1_v1_f0663_smoke_surface_ready(
    const M11_GameViewState* state,
    const M11_AssetSlot* slot,
    int expected_graphic_index,
    DM1_V1_F0663SmokeSurfaceReceiptPc34* outReceipt)
{
    DM1_V1_F0663SourceSurfacePc34 surface;

    if (!state || !slot || !outReceipt || !state->assetsAvailable ||
        !slot->loaded || !slot->pixels || slot->width == 0 ||
        slot->height == 0) {
        return 0;
    }
    memset(&surface, 0, sizeof(surface));
    surface.graphicsDatOwned = 1;
    surface.graphicIndex = (int)slot->graphicIndex;
    surface.width = (int)slot->width;
    surface.height = (int)slot->height;
    surface.indexedPixelCount = surface.width * surface.height;
    surface.indexedPixels = slot->pixels;
    surface.pixelsFNV1a = dm1_v1_f0663_smoke_material_fnv1a_pc34(
        surface.indexedPixels, surface.indexedPixelCount);
    if (!surface.pixelsFNV1a) return 0;
    return dm1_v1_f0663_smoke_surface_receipt_pc34(
               &surface, expected_graphic_index,
               dm1_v1_f0663_smoke_palette_changes_pc34(),
               DM1_V1_F0663_PALETTE_COUNT_PC34, outReceipt) &&
           outReceipt->valid && outReceipt->suppressSyntheticFallback;
}

static int m11_dm1_v1_f0675_scaled_material_ready(
    const M11_GameViewState* state,
    const M11_AssetSlot* slot,
    int scaledWidth,
    int scaledHeight,
    const unsigned char* paletteChanges,
    int paletteChangeCount)
{
    DM1_V1_F0675SourceSurfacePc34 surface;
    DM1_V1_F0675ScaledMaterialReceiptPc34 receipt;

    if (!state || !state->assetsAvailable || !slot || !slot->loaded ||
        !slot->pixels || slot->width == 0 || slot->height == 0) {
        return 0;
    }
    memset(&surface, 0, sizeof(surface));
    surface.graphicsDatOwned = 1;
    surface.graphicIndex = (int)slot->graphicIndex;
    surface.width = (int)slot->width;
    surface.height = (int)slot->height;
    surface.indexedPixelCount = surface.width * surface.height;
    surface.indexedPixels = slot->pixels;
    surface.pixelsFNV1a = dm1_v1_f0675_scaled_material_fnv1a_pc34(
        surface.indexedPixels, surface.indexedPixelCount);
    if (!surface.pixelsFNV1a) return 0;
    memset(&receipt, 0, sizeof(receipt));
    return dm1_v1_f0675_scaled_material_receipt_pc34(
               &surface, scaledWidth, scaledHeight, paletteChanges,
               paletteChangeCount, &receipt) && receipt.valid &&
           receipt.suppressSyntheticFallback;
}

