static int m11_refill_ready_hand_after_dm1_shoot(M11_GameViewState* state,
                                                 int championIndex) {
    static const int sourceQuiverOrder[] = {
        CHAMPION_SLOT_QUIVER_1, /* C12_SLOT_QUIVER_LINE1_1 */
        CHAMPION_SLOT_QUIVER_3, /* C07_SLOT_QUIVER_LINE2_1 */
        CHAMPION_SLOT_QUIVER_2, /* C08_SLOT_QUIVER_LINE1_2 */
        CHAMPION_SLOT_QUIVER_4  /* C09_SLOT_QUIVER_LINE2_2 */
    };
    struct ChampionState_Compat* champ;
    unsigned short actionThing;
    DM1_WeaponInfo actionInfo;
    size_t i;

    if (!state) return 0;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return 0;
    if (championIndex >= state->world.party.championCount) return 0;
    champ = &state->world.party.champions[championIndex];
    if (!champ->present || champ->hp.current == 0) return 0;
    if (champ->inventory[CHAMPION_SLOT_HAND_LEFT] != THING_NONE) return 0;

    actionThing = m11_get_action_hand_thing(champ);
    if (!m11_dm1_shoot_weapon_info_for_thing(state, actionThing, &actionInfo)) {
        return 0;
    }

    for (i = 0; i < sizeof(sourceQuiverOrder) / sizeof(sourceQuiverOrder[0]); ++i) {
        int slot = sourceQuiverOrder[i];
        unsigned short ammoThing = champ->inventory[slot];
        DM1_WeaponInfo ammoInfo;
        if (!m11_dm1_shoot_weapon_info_for_thing(state, ammoThing, &ammoInfo) ||
            !m11_dm1_shoot_ammunition_matches(&actionInfo, &ammoInfo)) continue;
        champ->inventory[CHAMPION_SLOT_HAND_LEFT] = ammoThing;
        champ->inventory[slot] = THING_NONE;
        return 1;
    }
    return 0;
}

static int m11_refill_ready_hand_after_shoot(M11_GameViewState* state,
                                             int championIndex) {
    if (!state) return 0;
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        int sourceSlot = -1;
        uint16_t movedThing = THING_NONE;
        int m11SourceSlot;

        if (!csb_v1_runtime_refill_ready_hand_after_shoot_from_boot_profile_pc34(
                state->csbBootProfile,
                championIndex,
                &sourceSlot,
                &movedThing)) {
            return 0;
        }
        if (championIndex >= 0 &&
            championIndex < state->world.party.championCount &&
            championIndex < CHAMPION_MAX_PARTY) {
            struct ChampionState_Compat* champ =
                &state->world.party.champions[championIndex];
            champ->inventory[CHAMPION_SLOT_HAND_LEFT] = movedThing;
            m11SourceSlot = m11_csb_mapped_inventory_slot(sourceSlot);
            if (m11SourceSlot >= 0 && m11SourceSlot < CHAMPION_SLOT_COUNT) {
                champ->inventory[m11SourceSlot] = THING_NONE;
            }
        }
        return 1;
    }
    return m11_refill_ready_hand_after_dm1_shoot(state, championIndex);
}

