static int m11_dm1_v1_f0662_invisibility_material_ready(
    const M11_GameViewState* state,
    DM1_V1_F0662InvisibilityMaterialReceiptPc34* outReceipt)
{
    DM1_V1_F0662SourceSurfacePc34 icon;
    DM1_V1_F0662GlyphSourcePc34 glyph;
    M11_FontState loadedFont;
    const M11_FontState* sourceFont;
    const M11_AssetSlot* slot;

    if (!state || !outReceipt || !state->assetsAvailable) return 0;
    sourceFont = &state->originalFont;
    if (!state->originalFontAvailable || !M11_Font_IsLoaded(sourceFont)) {
        M11_Font_Init(&loadedFont);
        if (!M11_Font_LoadFromGraphicsDat(&loadedFont,
                                          state->assetLoader.fileState,
                                          state->assetLoader.runtimeState)) {
            return 0;
        }
        sourceFont = &loadedFont;
    }
    if (M11_Font_ResolvedGraphicIndex(sourceFont) != M11_FONT_GRAPHIC_INDEX_PC34 &&
        M11_Font_ResolvedGraphicIndex(sourceFont) != M11_FONT_GRAPHIC_INDEX_LEGACY) {
        return 0;
    }
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                DM1_V1_F0662_C028_CHAMPION_ICONS_PC34);
    if (!slot || !slot->loaded || !slot->pixels) return 0;
    memset(&icon, 0, sizeof(icon));
    icon.graphicsDatOwned = 1;
    icon.graphicIndex = (int)slot->graphicIndex;
    icon.width = (int)slot->width;
    icon.height = (int)slot->height;
    icon.indexedPixelCount = icon.width * icon.height;
    icon.indexedPixels = slot->pixels;
    icon.pixelsFNV1a = dm1_v1_f0662_invisibility_material_fnv1a_pc34(
        icon.indexedPixels, icon.indexedPixelCount);
    memset(&glyph, 0, sizeof(glyph));
    glyph.graphicsDatOwned = 1;
    glyph.graphicIndex = M11_Font_ResolvedGraphicIndex(sourceFont);
    glyph.bits = sourceFont->bitmap;
    glyph.byteCount = M11_FONT_BITMAP_BYTES;
    glyph.bitsFNV1a = dm1_v1_f0662_invisibility_material_fnv1a_pc34(
        glyph.bits, glyph.byteCount);
    return icon.pixelsFNV1a && glyph.bitsFNV1a &&
           dm1_v1_f0662_invisibility_material_receipt_pc34(
               &icon, &glyph,
               dm1_v1_f0662_invisibility_palette_changes_pc34(),
               DM1_V1_F0662_PALETTE_CHANGE_COUNT_PC34, outReceipt) &&
           outReceipt->valid && outReceipt->suppressSyntheticFallback &&
           outReceipt->championIconGraphicIndex == (int)slot->graphicIndex &&
           outReceipt->m653GraphicIndex == glyph.graphicIndex;
}

static int m11_draw_dm1_v1_top_row_receipt(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    Dm1V1ChampionTopRowAssetsReceiptPc34 assets;
    Dm1V1ChampionTopRowFramePc34 frame;
    Dm1V1ChampionTopRowPresentationReceiptPc34 presentation;
    Dm1V1ChampionPanelMaterialReceiptPc34 panelMaterials;
    Dm1V1ChampionRedrawMaterialsPc34 redrawMaterials;
    Dm1V1ChampionRedrawPriorityReceiptPc34 redraw;
    Dm1V1ChampionPartyInventoryHandoffReceiptPc34 handoff;
    DM1_V1_F0659ShieldMaterialReceiptPc34 shieldMaterial;
    DM1_V1_F0662InvisibilityMaterialReceiptPc34 invisibilityMaterial;
    int shieldMaterialReady;
    int invisibilityMaterialReady;
    int statusBarFrameReady;
    int operationIndex;

    if (!m11_dm1_v1_top_row_receipt_required(state) || !framebuffer) {
        return 0;
    }

    if (!dm1_v1_champion_panel_material_from_m11_loader_pc34(
            (M11_AssetLoader*)&state->assetLoader, &state->originalFont,
            &G9010_auc_VgaPaletteBrightest_Compat[0][0],
            VGA_PALETTE_PC34_COLOR_COUNT, &panelMaterials) ||
        !panelMaterials.valid || !panelMaterials.suppressSyntheticFallback ||
        !dm1_v1_champion_top_row_assets_from_m11_loader_pc34(
            (M11_AssetLoader*)&state->assetLoader, &assets) ||
        !dm1_v1_champion_top_row_frame_from_party_pc34(
            &state->world.party, (int)state->actingChampionOrdinal,
            (int)state->world.magic.event71CountInvisibility,
            &assets.assets, &frame) ||
        !dm1_v1_champion_top_row_presentation_from_frame_pc34(
            &frame, &assets, &presentation) || !presentation.valid ||
        !m11_dm1_v1_party_inventory_handoff_from_frame(
            state, &presentation, &redrawMaterials, &redraw, &handoff) ||
        !handoff.valid) {
        m11_clear_dm1_v1_top_row_receipt_zones(
            framebuffer, framebufferWidth, framebufferHeight);
        return 0;
    }

    if (!m11_dm1_v1_top_row_atomic_host_consume(
            state, &assets, framebuffer, framebufferWidth, framebufferHeight)) {
        m11_clear_dm1_v1_top_row_receipt_zones(
            framebuffer, framebufferWidth, framebufferHeight);
        return 0;
    }

    memset(&shieldMaterial, 0, sizeof(shieldMaterial));
    shieldMaterialReady = m11_dm1_v1_f0659_shield_material_ready(
        state, &shieldMaterial);
    memset(&invisibilityMaterial, 0, sizeof(invisibilityMaterial));
    invisibilityMaterialReady = m11_dm1_v1_f0662_invisibility_material_ready(
        state, &invisibilityMaterial);

    /* BASE.C F0659/F0662 are conditional source consumers.  Their material
     * is not needed on an ordinary frame, but an active shield or invisibility
     * count makes the corresponding original pixels part of this frame's
     * contract.  Do not publish a superficially valid top row with those
     * effects silently omitted. */
    if (((state->world.magic.fireShieldDefense > 0 ||
          state->world.magic.spellShieldDefense > 0 ||
          state->world.magic.partyShieldDefense > 0) &&
         !shieldMaterialReady) ||
        (frame.invisibilityCount > 0 && !invisibilityMaterialReady)) {
        m11_clear_dm1_v1_top_row_receipt_zones(
            framebuffer, framebufferWidth, framebufferHeight);
        return 0;
    }

    /* Validate the complete F0355/F0293 handoff before any presentation.
     * The ordered handoff retains both the F0292 top row and F0320/F0345
     * overlays, so one missing original material rejects the entire frame. */
    for (operationIndex = 0; operationIndex < handoff.operationCount;
         ++operationIndex) {
        const Dm1V1ChampionPartyInventoryHandoffOpPc34* operation =
            &handoff.operations[operationIndex];
        if (operation->kind == DM1_V1_CHAMPION_PARTY_INVENTORY_HANDOFF_TOP_ROW_PC34) {
            const Dm1V1ChampionTopRowPresentationOpPc34* source;
            if (operation->sourceOperationIndex < 0 ||
                operation->sourceOperationIndex >= presentation.operationCount) {
                m11_clear_dm1_v1_top_row_receipt_zones(
                    framebuffer, framebufferWidth, framebufferHeight);
                return 0;
            }
            source = &presentation.operations[operation->sourceOperationIndex];
            if (source->championSlot != operation->championSlot ||
                source->zoneId != operation->zoneId ||
                source->graphicIndex != operation->graphicIndex ||
                source->sourcePixels != operation->sourcePixels ||
                ((source->kind == DM1_V1_CHAMPION_TOP_ROW_OP_BLIT_DEAD_STATUS_PC34 ||
                  source->kind == DM1_V1_CHAMPION_TOP_ROW_OP_COMPOSE_ICON_PC34 ||
                  source->kind == DM1_V1_CHAMPION_TOP_ROW_OP_BLIT_HAND_PC34) &&
                 !m11_dm1_v1_top_row_receipt_source_slot(state, source))) {
                m11_clear_dm1_v1_top_row_receipt_zones(
                    framebuffer, framebufferWidth, framebufferHeight);
                return 0;
            }
        } else if (operation->kind == DM1_V1_CHAMPION_PARTY_INVENTORY_HANDOFF_REDRAW_PC34) {
            const Dm1V1ChampionRedrawPriorityOpPc34* source;
            if (operation->sourceOperationIndex < 0 ||
                operation->sourceOperationIndex >= redraw.operationCount) {
                m11_clear_dm1_v1_top_row_receipt_zones(
                    framebuffer, framebufferWidth, framebufferHeight);
                return 0;
            }
            source = &redraw.operations[operation->sourceOperationIndex];
            if (source->championSlot != operation->championSlot ||
                source->graphicIndex != operation->graphicIndex ||
                source->sourcePixels != operation->sourcePixels ||
                source->pendingDamageAmount != operation->pendingDamageAmount ||
                (source->kind != DM1_V1_CHAMPION_REDRAW_STATUS_PC34 &&
                 source->kind != DM1_V1_CHAMPION_REDRAW_POISON_PC34 &&
                 source->kind != DM1_V1_CHAMPION_REDRAW_DAMAGE_PC34) ||
                ((source->kind == DM1_V1_CHAMPION_REDRAW_POISON_PC34 ||
                  source->kind == DM1_V1_CHAMPION_REDRAW_DAMAGE_PC34) &&
                 !m11_dm1_v1_redraw_receipt_source_slot(state, source)) ||
                (source->kind == DM1_V1_CHAMPION_REDRAW_DAMAGE_PC34 &&
                 (source->pendingDamageAmount <= 0 ||
                  !m11_dm1_pc34_hud_font_is_source_bound(state)))) {
                m11_clear_dm1_v1_top_row_receipt_zones(
                    framebuffer, framebufferWidth, framebufferHeight);
                return 0;
            }
        } else {
            m11_clear_dm1_v1_top_row_receipt_zones(
                framebuffer, framebufferWidth, framebufferHeight);
            return 0;
        }
    }

    for (operationIndex = 0;
         operationIndex < presentation.operationCount;
         ++operationIndex) {
        const Dm1V1ChampionTopRowPresentationOpPc34* operation =
            &presentation.operations[operationIndex];
        switch (operation->kind) {
            case DM1_V1_CHAMPION_TOP_ROW_OP_CLEAR_STATUS_PC34:
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              operation->x, operation->y,
                              operation->width, operation->height,
                              (unsigned char)operation->color);
                if (shieldMaterialReady) {
                    m11_draw_dm1_v1_f0659_shield_borders(
                        state, &shieldMaterial, framebuffer, framebufferWidth,
                        framebufferHeight, operation->championSlot);
                }
                break;

            case DM1_V1_CHAMPION_TOP_ROW_OP_CLEAR_NAME_PC34:
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              operation->x, operation->y,
                              operation->width, operation->height,
                              (unsigned char)operation->color);
                break;

            case DM1_V1_CHAMPION_TOP_ROW_OP_CLEAR_BAR_PC34:
            case DM1_V1_CHAMPION_TOP_ROW_OP_FILL_BAR_PC34:
                /* F0287's command/frame receipt owns all C195..C206 writes.
                 * A rejected receipt has already cleared these source zones. */
                break;

            case DM1_V1_CHAMPION_TOP_ROW_OP_BLIT_DEAD_STATUS_PC34:
            case DM1_V1_CHAMPION_TOP_ROW_OP_BLIT_HAND_PC34: {
                const M11_AssetSlot* slot =
                    m11_dm1_v1_top_row_receipt_source_slot(state, operation);
                M11_AssetLoader_BlitRegion(slot,
                    operation->sourceX, operation->sourceY,
                    operation->width, operation->height,
                    framebuffer, framebufferWidth, framebufferHeight,
                    operation->x, operation->y, operation->color);
                if (operation->kind ==
                    DM1_V1_CHAMPION_TOP_ROW_OP_BLIT_HAND_PC34) {
                    const int handIndex = operation->zoneId -
                        (211 + operation->championSlot * 2);
                    const struct ChampionState_Compat* champion = NULL;
                    int iconIndex;

                    /* F0291 owns the C033/C034/C035 hand frame, then
                     * F0038 overlays the real 16x16 object (or empty-hand)
                     * icon. The receipt path already consumed the frame but
                     * used to stop before that second source-owned blit. */
                    if (handIndex >= 0 && handIndex < 2 &&
                        operation->championSlot >= 0 &&
                        operation->championSlot <
                            state->world.party.championCount) {
                        champion = &state->world.party.champions[
                            operation->championSlot];
                        iconIndex = m11_v1_status_hand_icon_index(
                            state, operation->championSlot, handIndex);
                        if (champion->present && champion->hp.current > 0 &&
                            iconIndex >= 0) {
                            DM1_V1_ChampionStatusRectPc34 iconRect;
                            if (dm1_v1_champion_status_hand_icon_rect_pc34(
                                    operation->championSlot, handIndex,
                                    &iconRect)) {
                                (void)m11_draw_dm_object_icon_index(
                                    state, framebuffer, framebufferWidth,
                                    framebufferHeight, iconIndex,
                                    iconRect.x, iconRect.y, 0);
                            }
                        }
                    }
                }
                break;
            }

            case DM1_V1_CHAMPION_TOP_ROW_OP_COMPOSE_ICON_PC34: {
                const M11_AssetSlot* slot =
                    m11_dm1_v1_top_row_receipt_source_slot(state, operation);
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              operation->x, operation->y,
                              operation->width, operation->height,
                              (unsigned char)operation->color);
                /* CHAMDRAW.C F0622 applies F0662 to C028 only for an
                 * invisible party. Without C028/M653 and the exact source
                 * palette table, leave its original background clear. */
                M11_AssetLoader_BlitRegion(slot,
                    operation->sourceX, operation->sourceY,
                    operation->width, operation->height,
                    framebuffer, framebufferWidth, framebufferHeight,
                    operation->x, operation->y,
                    DM1_COLOR_DARKEST_GRAY);
                if (frame.invisibilityCount > 0) {
                    m11_apply_v1_champion_icon_invisibility_remap(
                        framebuffer, framebufferWidth, framebufferHeight,
                        operation->x, operation->y,
                        operation->width, operation->height);
                }
                break;
            }

            case DM1_V1_CHAMPION_TOP_ROW_OP_DRAW_NAME_PC34:
                /* F0292 -> F0053 only has a valid glyph route through the
                 * original M653 font.  The already-cleared source field is
                 * intentionally left empty when it is unavailable. */
                if (operation->championSlot >= 0 &&
                    operation->championSlot < state->world.party.championCount &&
                    state->world.party.champions[operation->championSlot].present &&
                    m11_dm1_pc34_hud_font_is_source_bound(state)) {
                    char name[16];
                    m11_format_champion_name(
                        state->world.party.champions[operation->championSlot].name,
                        name, sizeof(name));
                    m11_draw_dm1_status_name_text(
                        framebuffer, framebufferWidth, framebufferHeight,
                        operation->x,
                        operation->y + DM1_V1_CPNBC_NAME_BOX_PRINT_Y_PC34,
                        name, (unsigned char)operation->color,
                        (unsigned char)dm1_v1_champion_status_name_clear_color_pc34());
                }
                break;

            default:
                m11_clear_dm1_v1_top_row_receipt_zones(
                    framebuffer, framebufferWidth, framebufferHeight);
                return 0;
        }
    }

    statusBarFrameReady = m11_draw_dm1_v1_status_bar_frame_receipt(
        state, &assets, framebuffer, framebufferWidth, framebufferHeight);
    if (!statusBarFrameReady) {
        m11_clear_dm1_v1_top_row_receipt_zones(
            framebuffer, framebufferWidth, framebufferHeight);
        m11_clear_dm1_v1_status_bar_receipt_zones(
            framebuffer, framebufferWidth, framebufferHeight);
        return 0;
    }

    /* The handoff appends source-owned overlays after F0292's complete
     * champion top row.  C032/C015/C016 are never synthesized or replaced. */
    for (operationIndex = 0; operationIndex < handoff.operationCount;
         ++operationIndex) {
        const Dm1V1ChampionPartyInventoryHandoffOpPc34* operation =
            &handoff.operations[operationIndex];
        if (operation->kind == DM1_V1_CHAMPION_PARTY_INVENTORY_HANDOFF_REDRAW_PC34) {
            const Dm1V1ChampionRedrawPriorityOpPc34* source =
                &redraw.operations[operation->sourceOperationIndex];
            /* F0293 repeats F0292 status ownership in its priority walk.
             * The top-row receipt above has already consumed those status
             * operations. Only F0345/F0320 overlays own a separate original
             * source bitmap and must reach the loader again. */
            if (source->kind == DM1_V1_CHAMPION_REDRAW_POISON_PC34 ||
                source->kind == DM1_V1_CHAMPION_REDRAW_DAMAGE_PC34) {
                const M11_AssetSlot* slot =
                    m11_dm1_v1_redraw_receipt_source_slot(state, source);
                M11_AssetLoader_BlitRegion(slot, 0, 0,
                    source->width, source->height,
                    framebuffer, framebufferWidth, framebufferHeight,
                    source->x, source->y, 0);
                if (source->kind == DM1_V1_CHAMPION_REDRAW_DAMAGE_PC34) {
                    DM1_V1_ChampionStatusRectPc34 origin;
                    char damageText[8];
                    const int isInventory = source->graphicIndex == 16;
                    if (!dm1_v1_champion_damage_number_origin_variant_pc34(
                            source->championSlot,
                            source->pendingDamageAmount,
                            isInventory, &origin)) {
                        m11_clear_dm1_v1_top_row_receipt_zones(
                            framebuffer, framebufferWidth, framebufferHeight);
                        return 0;
                    }
                    snprintf(damageText, sizeof(damageText), "%d",
                             source->pendingDamageAmount);
                    m11_draw_v1_damage_number_text(
                        framebuffer, framebufferWidth, framebufferHeight,
                        origin.x, origin.y, damageText);
                }
            }
        }
    }
    {
        const unsigned int materialFNV1a =
            m11_dm1_v1_top_row_material_fnv1a(&assets);
        if (materialFNV1a == 0u) {
            m11_clear_dm1_v1_top_row_receipt_zones(
                framebuffer, framebufferWidth, framebufferHeight);
            return 0;
        }
        m11_dm1_runtime_capture_route_evidence(
            state, M11_DM1_RUNTIME_CAPTURE_TOP_ROW, 1,
            1, 1,
            state->world.gameTick, (unsigned int)frame.actingChampionOrdinal,
            materialFNV1a);
    }
    return 1;
}

static void m11_draw_party_panel(const M11_GameViewState* state,
                                 unsigned char* framebuffer,
                                 int framebufferWidth,
                                 int framebufferHeight) {
    int slot;
    int activeIndex = -1;
    int useV2PartyHud = 0;
    int slotStep;
    int slotW;
    if (state) {
        activeIndex = state->world.party.activeChampionIndex;
        /* CSB V2.x may transform the final presented surface, but its
         * 320x200 source page remains the PC3.4 C017/C040 composition.
         * Drawing the alternate party HUD here made V2 alter source pixels
         * before the presentation pass and violated the V2.1/V2.2 contract. */
        useV2PartyHud = m11_v2_vertical_slice_enabled(state) &&
            state->sourceKind != M11_GAME_SOURCE_CSB_BOOT;
    }
    if (m11_dm1_v1_top_row_receipt_required(state)) {
        if (m11_draw_dm1_v1_top_row_receipt(
                state, framebuffer, framebufferWidth, framebufferHeight)) {
            return;
        }
        {
            m11_dm1_runtime_capture_route_evidence(
                state, M11_DM1_RUNTIME_CAPTURE_TOP_ROW, 0, 0, 0,
                0u, 0u, 0u);
        }
        /* A source-owned top row is atomic. Once its receipt rejects, the
         * direct legacy painter must not republish a partial HUD with omitted
         * bars, borders, icons, or original text. */
        m11_clear_dm1_v1_top_row_receipt_zones(
            framebuffer, framebufferWidth, framebufferHeight);
        m11_clear_dm1_v1_status_bar_receipt_zones(
            framebuffer, framebufferWidth, framebufferHeight);
        return;
    }
    slotStep = m11_party_slot_step(state);
    slotW    = m11_party_slot_w(state);
    if (useV2PartyHud) {
        m11_blit_v2_slice_asset(&m11_v2_party_hud_four_slot_base,
                                framebuffer, framebufferWidth, framebufferHeight,
                                M11_PARTY_PANEL_X, M11_PARTY_PANEL_Y, 1);
    }
    for (slot = 0; slot < CHAMPION_MAX_PARTY; ++slot) {
        int x = m11_party_panel_x(state) + slot * slotStep;
        int y = M11_PARTY_PANEL_Y;
        int slotH = M11_PARTY_SLOT_H;
        char line[48];
        int drewStatusBox = 0;
        if (!useV2PartyHud) {
            DM1_V1_ChampionStatusRectPc34 statusRect;
            if (dm1_v1_champion_status_box_rect_pc34(slot, &statusRect)) {
                x = statusRect.x;
                y = statusRect.y;
                slotW = statusRect.w;
                slotH = statusRect.h;
            }
        }

        if (slot < state->world.party.championCount && state->world.party.champions[slot].present) {
            char name[16];
            const struct ChampionState_Compat* champ = &state->world.party.champions[slot];
            int isDead = (champ->hp.current == 0);
            m11_format_champion_name(champ->name, name, sizeof(name));

            if (useV2PartyHud) {
                int cellBaseX = x + 47;
                int cellY = y + 6;
                int cell;
                if (slot == activeIndex) {
                    m11_blit_v2_slice_asset(&m11_v2_party_hud_four_slot_active_overlay,
                                            framebuffer, framebufferWidth, framebufferHeight,
                                            x, y, 1);
                }
                for (cell = 0; cell < 3; ++cell) {
                    m11_blit_v2_slice_asset(&m11_v2_party_hud_cell_base,
                                            framebuffer, framebufferWidth, framebufferHeight,
                                            cellBaseX + cell * 6,
                                            cellY + (cell == 1 ? 1 : 0), 1);
                }
                if (slot == activeIndex) {
                    m11_blit_v2_slice_asset(&m11_v2_party_hud_cell_highlight,
                                            framebuffer, framebufferWidth, framebufferHeight,
                                            cellBaseX,
                                            cellY, 1);
                }
                drewStatusBox = 1;
            }

            /* V1 source status-box background.  ReDMCSB marks
             * C007_GRAPHIC_STATUS_BOX as "never used"; alive champion
             * status boxes are cleared to C12 darkest-gray, then name,
             * bars, hands, and optional shield borders are drawn on top
            * (CHAMPION.C F0292).  Dead champions still use graphic 8. */
            if (!useV2PartyHud) {
                int baseGfx = dm1_v1_champion_status_box_base_graphic_pc34(
                    (int)champ->present,
                    (int)champ->hp.current);
                if (baseGfx && state->assetsAvailable) {
                    const M11_AssetSlot* boxAsset = M11_AssetLoader_Load(
                        (M11_AssetLoader*)&state->assetLoader,
                        baseGfx);
                    if (boxAsset &&
                        DM1_ChampionPanel_AssetSurfaceAccepted(
                            baseGfx, baseGfx,
                            boxAsset->loaded,
                            boxAsset->pixels != NULL,
                            boxAsset->width, boxAsset->height,
                            slotW, slotH)) {
                        M11_AssetLoader_BlitRegion(boxAsset,
                            0, 0, slotW, slotH,
                            framebuffer, framebufferWidth, framebufferHeight,
                            /* CHAMDRAW.C F0292's C008 dead status box is a
                             * complete source surface. Black pixels erase
                             * old bars/hands; it has no host transparency. */
                            x, y, -1);
                        drewStatusBox = 1;
                    }
                }
                if (!isDead) {
                    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  x, y, slotW, slotH,
                                  (unsigned char)
                                      dm1_v1_champion_status_box_fill_color_pc34());
                    drewStatusBox = 1;
                }
            }
            /* ReDMCSB CHAMDRAW.C F0292 only continues with the name, bars,
             * hand slots, and overlays after it has established this status
             * surface.  CSB's C017/C040 page is source-owned, so a missing
             * decoded C008/base surface must leave the zone black instead of
             * falling through to the shared M11 procedural panel path. */
            if (!drewStatusBox &&
                state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              x, y, slotW, slotH, M11_COLOR_BLACK);
                continue;
            }
            if (!drewStatusBox && !m11_v1_chrome_mode_enabled(state) &&
                !m11_is_dm1_source_kind(state->sourceKind) &&
                !s_m11_dm1_hoc_presented_frame_consumer_receipt.suppressFallbackVisuals) {
                /* Procedural fallback.  V1 uses the same source status-box
                 * rectangle as C007/C008 (67x29); V2 keeps the legacy
                 * 71x28 shell baked into its vertical-slice HUD assets. */
                int fallbackH = useV2PartyHud ? M11_PARTY_SLOT_H : slotH;
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              x, y, slotW, fallbackH, M11_COLOR_BLACK);
                m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                              x, y, slotW, fallbackH, M11_COLOR_LIGHT_CYAN);
            }

            /* GRAPHICS.DAT-backed shield border overlays (67×29).
             * ReDMCSB CHAMDRAW.C F0292 draws shield borders immediately after
             * the alive status-box background and before setting the deferred
             * name/stat/hand/action refresh bits.  Keep this before top-row
             * text, bars, and hand slots so changed-status refreshes preserve
             * the source overdraw order. */
            if (!useV2PartyHud && state->assetsAvailable && !isDead) {
                int borderGraphics[3] = {0, 0, 0};
                int borderCount =
                    dm1_v1_champion_status_shield_border_graphics_pc34(
                        (int)state->world.magic.fireShieldDefense,
                        (int)state->world.magic.spellShieldDefense,
                        (int)state->world.magic.partyShieldDefense,
                        borderGraphics);
                int borderOrdinal;
                for (borderOrdinal = 0; borderOrdinal < borderCount; ++borderOrdinal) {
                    unsigned int borderGfx = (unsigned int)borderGraphics[borderOrdinal];
                    if (borderGfx) {
                        const M11_AssetSlot* borderAsset = M11_AssetLoader_Load(
                            (M11_AssetLoader*)&state->assetLoader, borderGfx);
                        if (borderAsset &&
                            DM1_ChampionPanel_AssetSurfaceAccepted(
                                (int)borderGfx, (int)borderGfx,
                                borderAsset->loaded,
                                borderAsset->pixels != NULL,
                                borderAsset->width, borderAsset->height,
                                slotW, slotH)) {
                            int borderX;
                            int borderY;
                            int borderW;
                            int borderH;
                            DM1_V1_ChampionStatusRectPc34 borderRect;
                            if (!dm1_v1_champion_status_shield_border_rect_pc34(
                                    slot, &borderRect)) {
                                continue;
                            }
                            borderX = borderRect.x;
                            borderY = borderRect.y;
                            borderW = borderRect.w;
                            borderH = borderRect.h;
                            M11_AssetLoader_BlitRegion(borderAsset,
                                0, 0, borderW, borderH,
                                framebuffer, framebufferWidth, framebufferHeight,
                                borderX, borderY, 0); /* transparentColor=0 (black) */
                        }
                    }
                }
            }

            /* No invented active-champion frame in V1.  The source
             * indicates leader/active state through the champion-name
             * text color (yellow for leader, gold otherwise), not a
             * double rectangular border around the status box. */

            /* V1 champion name/title status text. Source F0292 does not
             * draw the 19x14 champion icon inside the compact status box.
             * It clears C159+n (43x7) to C01 then writes Name[8] at the
             * fixed C163+n TEXT2 origin, clipped to seven 6px cells. */
            if (!useV2PartyHud) {
                unsigned char nameColor = (unsigned char)
                    dm1_v1_champion_status_name_color_pc34(
                        (int)champ->present,
                        (int)champ->hp.current,
                        slot == state->world.party.activeChampionIndex);
                {
                    DM1_V1_ChampionStatusRectPc34 nameRect;
                    if (!dm1_v1_champion_status_name_rect_pc34(slot,
                                                               &nameRect)) {
                        continue;
                    }
                    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  nameRect.x, nameRect.y, nameRect.w, nameRect.h,
                                  (unsigned char)
                                      dm1_v1_champion_status_name_clear_color_pc34());
                }
                {
                    DM1_V1_ChampionStatusRectPc34 nameTextRect;
                    if (!dm1_v1_champion_status_name_text_rect_pc34(
                            slot, &nameTextRect)) {
                        continue;
                    }
                    m11_draw_dm1_status_name_text(
                        framebuffer, framebufferWidth, framebufferHeight,
                        nameTextRect.x,
                        nameTextRect.y + DM1_V1_CPNBC_NAME_BOX_PRINT_Y_PC34,
                        name,
                        nameColor,
                        (unsigned char)dm1_v1_champion_status_name_clear_color_pc34());
                }
            } else {
                int nameOffX = 4;
                if (slot == activeIndex) {
                    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                                  x + nameOffX, y + 3, name, &g_text_shadow);
                } else {
                    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                                  x + nameOffX, y + 3, name, &g_text_small);
                }
            }
            if (isDead && useV2PartyHud) {
                M11_TextStyle ds = g_text_small;
                ds.color = M11_COLOR_RED;
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              x + 4, y + 12, "DEAD", &ds);
            }
            /* Pass 43: champion HP/stamina/mana bar graphs.
             *
             * V1 mode (default): source-faithful vertical bars per
             * CHAMDRAW.C F0287_CHAMPION_DrawBarGraphs.  Each of the
             * three bars is a 4x25 rectangle bottom-anchored inside
             * the 24x29 bar-graph region at the right side of the
             * 67x29 status-box frame.  Blank portion is darkest-gray
             * (C12), filled portion is the per-champion color.  Bar
             * drains from the top: when current < maximum, the
             * (max-current)/max fraction of the bar at the top is
             * filled with darkest-gray first, and only the remaining
             * bottom portion shows the champion color.  Dead
             * champions skip F0287 entirely after F0292 blits C008
             * and prints the name (CHAMDRAW.C:816-842), so V1 must
             * leave the dead-box graphic unobscured by bar columns.
             *
             * V2 vertical-slice / non-source opt-out: legacy horizontal
             * 59x{2,1,1} strip is preserved so the pre-baked HUD sprite
             * stays pixel-aligned.  Authenticated DM1 V1 ignores the
             * opt-out and always uses the source model.
             *
             * Ref: firestaff_pc34_core_amalgam.c l.11229..11260 for
             * F0287; zones_h_reconstruction.json records 187..206;
             * parity-evidence/pass43_bar_graphs.md.
             *
             * (2026-06-16) The amalgam reference is historical;
             * the file is unbuilt legacy code.  F0287 lives in
             * src/dm1/dm1_v1_champion_stats_pc34_compat.c. */
            /* Authenticated DM1 V1 always owns F0287's source bar model.
             * The environment switch is retained for non-source/debug A/B
             * sessions, but must not re-enable the retired horizontal host
             * bars in a real DM1 frame. */
            {
                const int sourceDm1BarGraphs =
                    !useV2PartyHud && m11_is_dm1_source_kind(state->sourceKind);
                if (!isDead &&
                    (sourceDm1BarGraphs || m11_v1_bar_graphs_enabled(state))) {
                    int statIdx;
                    int curs[3];
                    int maxs[3];
                    curs[0] = (long)champ->hp.current;
                    maxs[0] = (long)champ->hp.maximum;
                    curs[1] = (long)champ->stamina.current;
                    maxs[1] = (long)champ->stamina.maximum;
                    curs[2] = (long)champ->mana.current;
                    maxs[2] = (long)champ->mana.maximum;
                    for (statIdx = 0; statIdx < 3; ++statIdx) {
                        DM1_ChampionPanel_BarFillModel barModel;
                        if (DM1_ChampionPanel_BuildPc34BarFillModel(
                                slot, statIdx, curs[statIdx], maxs[statIdx],
                                &barModel)) {
                            if (barModel.emitsBlank) {
                                m11_fill_rect(framebuffer, framebufferWidth,
                                              framebufferHeight,
                                              barModel.blankX,
                                              barModel.blankY,
                                              barModel.blankWidth,
                                              barModel.blankHeight,
                                              (unsigned char)barModel.blankColor);
                            }
                            if (barModel.emitsFill) {
                                m11_fill_rect(framebuffer, framebufferWidth,
                                              framebufferHeight,
                                              barModel.fillX,
                                              barModel.fillY,
                                              barModel.fillWidth,
                                              barModel.fillHeight,
                                              (unsigned char)barModel.fillColor);
                            }
                        } else {
                            DM1_V1_ChampionStatusRectPc34 barRect;
                            if (!dm1_v1_champion_status_bar_rect_pc34(
                                    slot, statIdx, &barRect)) {
                                continue;
                            }
                            m11_fill_rect(framebuffer, framebufferWidth,
                                          framebufferHeight,
                                          barRect.x, barRect.y, barRect.w, barRect.h,
                                          (unsigned char)
                                              DM1_COLOR_DARKEST_GRAY);
                        }
                    }
                } else if (!sourceDm1BarGraphs &&
                           !m11_v1_bar_graphs_enabled(state)) {
                    int hpWidth = champ->hp.maximum > 0 ? (int)(champ->hp.current * 59) / (int)champ->hp.maximum : 0;
                    int staminaWidth = champ->stamina.maximum > 0 ? (int)(champ->stamina.current * 59) / (int)champ->stamina.maximum : 0;
                    int manaWidth = champ->mana.maximum > 0 ? (int)(champ->mana.current * 59) / (int)champ->mana.maximum : 0;
                    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  x + 4, y + 20, 59, 2, M11_COLOR_DARK_GRAY);
                    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  x + 4, y + 20, hpWidth, 2, isDead ? M11_COLOR_DARK_GRAY : M11_COLOR_LIGHT_RED);
                    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  x + 4, y + 23, 59, 1, M11_COLOR_DARK_GRAY);
                    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  x + 4, y + 23, staminaWidth, 1, M11_COLOR_LIGHT_GREEN);
                    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  x + 4, y + 25, 59, 1, M11_COLOR_DARK_GRAY);
                    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  x + 4, y + 25, manaWidth, 1, M11_COLOR_LIGHT_BLUE);
                }
            }

            /* V1 status-box hand slots.  Source F0292/F0291 draws
             * ready/action hand slot boxes at zones C211..C218 for
             * present living champions; these are separate from the
             * right-column action icon cells. */
            if (!useV2PartyHud && !isDead) {
                int readyX, readyY, actionX, actionY;
                DM1_V1_ChampionStatusRectPc34 readyRect;
                DM1_V1_ChampionStatusRectPc34 actionRect;
                if (!dm1_v1_champion_status_hand_slot_box_rect_pc34(
                        slot, 0, &readyRect) ||
                    !dm1_v1_champion_status_hand_slot_box_rect_pc34(
                        slot, 1, &actionRect)) {
                    continue;
                }
                readyX = readyRect.x;
                readyY = readyRect.y;
                actionX = actionRect.x;
                actionY = actionRect.y;
                (void)m11_draw_v1_status_hand_slot(
                    state, champ, framebuffer, framebufferWidth, framebufferHeight,
                    slot, 0, readyX, readyY);
                (void)m11_draw_v1_status_hand_slot(
                    state, champ, framebuffer, framebufferWidth, framebufferHeight,
                    slot, 1, actionX, actionY);
            }


            /* GRAPHICS.DAT-backed POISONED label (96×15, graphic 32).
             * Drawn below the status box when champion is poisoned.
             * Ref: ReDMCSB INVNTORY.C — drawn when poisonDose > 0. */
            if (state->assetsAvailable && champ->poisonDose > 0) {
                const M11_AssetSlot* poisonLbl = M11_AssetLoader_Load(
                    (M11_AssetLoader*)&state->assetLoader,
                    (unsigned int)dm1_v1_graphic_poisoned_label_pc34());
                if (poisonLbl &&
                    DM1_ChampionPanel_AssetSurfaceAccepted(
                        dm1_v1_graphic_poisoned_label_pc34(),
                        dm1_v1_graphic_poisoned_label_pc34(),
                        poisonLbl->loaded, poisonLbl->pixels != NULL,
                        poisonLbl->width, poisonLbl->height, 96, 15)) {
                    /* Center the 96-wide label within the source status-box
                     * zone; in DM1 this spills across adjacent boxes, which
                     * is the correct original behaviour.  Preserve the old
                     * V2 positioning while V1 routes through C007 geometry. */
                    int lblX, lblY, lblW, lblH;
                    if (!useV2PartyHud) {
                        DM1_V1_ChampionStatusRectPc34 lblRect;
                        if (dm1_v1_champion_poison_label_rect_pc34(
                                slot, (int)poisonLbl->width,
                                (int)poisonLbl->height, &lblRect)) {
                            lblX = lblRect.x;
                            lblY = lblRect.y;
                            lblW = lblRect.w;
                            lblH = lblRect.h;
                            M11_AssetLoader_BlitRegion(poisonLbl,
                                0, 0, lblW, lblH,
                                framebuffer, framebufferWidth, framebufferHeight,
                                lblX, lblY, 0);
                        }
                    } else {
                        int poisonBaseW = 67;
                        int poisonBaseH = 29;
                        lblX = x + (poisonBaseW - (int)poisonLbl->width) / 2;
                        lblY = y + poisonBaseH;
                        lblW = (int)poisonLbl->width;
                        lblH = (int)poisonLbl->height;
                        M11_AssetLoader_BlitRegion(poisonLbl,
                            0, 0, lblW, lblH,
                            framebuffer, framebufferWidth, framebufferHeight,
                            lblX, lblY, 0);
                    }
                }
            }

            /* GRAPHICS.DAT-backed damage indicator.  ReDMCSB CHAMDRAW.C
             * F0623:688-699 uses C016/C179..C182 for the inventory
             * champion and C015/C167..C170 for the other status boxes,
             * then prints the centered damage number in the same zone. */
            if (state->championDamageTimer[slot] > 0) {
                int useBigDamage =
                    (!useV2PartyHud &&
                     state->inventoryPanelActive &&
                     slot == state->world.party.activeChampionIndex);
                int drewDamageSurface = 0;
                /* F0623 presents C015/C016 and its F0053 number as one
                 * source-owned operation.  A loaded but non-M653 768-byte
                 * record must not leave the real backing surface behind
                 * with foreign glyphs over it. */
                if (state->assetsAvailable &&
                    (!m11_is_dm1_source_kind(state->sourceKind) ||
                     m11_dm1_pc34_hud_font_is_source_bound(state))) {
                    const int damageGraphic = useBigDamage
                        ? dm1_v1_graphic_champion_damage_big_pc34()
                        : dm1_v1_graphic_champion_damage_small_pc34();
                    const int damageWidth = useBigDamage ? 32 : 45;
                    const int damageHeight = useBigDamage ? 29 : 7;
                    const M11_AssetSlot* dmgAsset = M11_AssetLoader_Load(
                        (M11_AssetLoader*)&state->assetLoader,
                        (unsigned int)damageGraphic);
                    if (dmgAsset &&
                        DM1_ChampionPanel_AssetSurfaceAccepted(
                            damageGraphic, damageGraphic,
                            dmgAsset->loaded, dmgAsset->pixels != NULL,
                            dmgAsset->width, dmgAsset->height,
                            damageWidth, damageHeight)) {
                        int dmgX, dmgY, dmgW, dmgH;
                        int haveDamageGeometry = 0;
                        if (useBigDamage) {
                            DM1_V1_ChampionStatusRectPc34 dmgRect;
                            if (dm1_v1_champion_inventory_damage_indicator_rect_pc34(
                                    slot, (int)dmgAsset->width,
                                    (int)dmgAsset->height, &dmgRect)) {
                                dmgX = dmgRect.x;
                                dmgY = dmgRect.y;
                                dmgW = dmgRect.w;
                                dmgH = dmgRect.h;
                                haveDamageGeometry = 1;
                            }
                        } else if (!useV2PartyHud) {
                            DM1_V1_ChampionStatusRectPc34 dmgRect;
                            if (dm1_v1_champion_damage_indicator_rect_pc34(
                                    slot, (int)dmgAsset->width,
                                    (int)dmgAsset->height, &dmgRect)) {
                                dmgX = dmgRect.x;
                                dmgY = dmgRect.y;
                                dmgW = dmgRect.w;
                                dmgH = dmgRect.h;
                                haveDamageGeometry = 1;
                            }
                        } else {
                            int dmgBaseW = 67;
                            int dmgBaseH = 29;
                            dmgX = x + (dmgBaseW - (int)dmgAsset->width) / 2;
                            dmgY = y + (dmgBaseH - (int)dmgAsset->height) / 2;
                            dmgW = (int)dmgAsset->width;
                            dmgH = (int)dmgAsset->height;
                            haveDamageGeometry = 1;
                        }
                        if (haveDamageGeometry) {
                            M11_AssetLoader_BlitRegion(dmgAsset,
                                0, 0, dmgW, dmgH,
                                framebuffer, framebufferWidth, framebufferHeight,
                                /* ReDMCSB CHAMPION.C F0320 uses
                                 * C10_COLOR_FLESH for both C015 and C016.
                                 * Black is source artwork, not transparency. */
                                dmgX, dmgY, M11_COLOR_FLESH);
                            drewDamageSurface = 1;
                        }
                    }
                }
                /* Draw the damage number after its source surface.
                 * ReDMCSB CHAMPION.C F0320 lines 1745-1775 (DM1 PC34
                 * MEDIA009 path) uses fixed x/y origins for the 1/2/3-digit
                 * damage string instead of centering in C167/C179. */
                {
                    char dmgNum[8];
                    M11_TextStyle dmgStyle = g_text_small;
                    int dmgNumX;
                    int dmgNumY;
                    dmgStyle.color = M11_COLOR_WHITE;
                    snprintf(dmgNum, sizeof(dmgNum), "%d",
                             state->championDamageAmount[slot]);
                    if (!useV2PartyHud) {
                        DM1_V1_ChampionStatusRectPc34 origin;
                        if (dm1_v1_champion_damage_number_origin_variant_pc34(
                                slot, state->championDamageAmount[slot],
                                useBigDamage, &origin)) {
                            dmgNumX = origin.x;
                            dmgNumY = origin.y;
                            if (drewDamageSurface) {
                                m11_draw_v1_damage_number_text(
                                    framebuffer, framebufferWidth,
                                    framebufferHeight,
                                    dmgNumX, dmgNumY, dmgNum);
                            }
                        }
                    } else {
                        int dmgBaseW = 67;
                        int dmgBaseH = 29;
                        dmgNumX = x + dmgBaseW / 2 -
                                  m11_measure_text_pixels(dmgNum, &dmgStyle) / 2;
                        dmgNumY = y + dmgBaseH / 2 - 3;
                        m11_draw_text(framebuffer, framebufferWidth,
                                      framebufferHeight,
                                      dmgNumX,
                                      dmgNumY,
                                      dmgNum, &dmgStyle);
                    }
                }
            }
        } else {
            /* ReDMCSB CHAMDRAW.C F0293:1134-1138 visits only party
             * indices below G0305_ui_PartyChampionCount. M11 retains
             * its framebuffer across HUD draws, so restore the unused
             * V1 status rectangle before taking that source-faithful
             * no-draw branch; otherwise a departed fourth champion
             * remains visible after a party-size transition. Keep the
             * old structural empty cells for debug/V2 surfaces only. */
            if (!useV2PartyHud && !state->showDebugHUD) {
                m11_fill_rect(framebuffer, framebufferWidth,
                              framebufferHeight, x, y, slotW, slotH,
                              M11_COLOR_BLACK);
                continue;
            }
            m11_fill_rect(framebuffer, framebufferWidth,
                          framebufferHeight, x, y, 71, 28,
                          M11_COLOR_BLACK);
            m11_draw_rect(framebuffer, framebufferWidth,
                          framebufferHeight, x, y, 71, 28,
                          M11_COLOR_DARK_GRAY);
            m11_draw_rect(framebuffer, framebufferWidth,
                          framebufferHeight, x + 1, y + 1, 69, 26,
                          M11_COLOR_DARK_GRAY);
            if (state->assetsAvailable) {
                const M11_AssetSlot* boxAsset = M11_AssetLoader_Load(
                    (M11_AssetLoader*)&state->assetLoader,
                    (unsigned int)dm1_v1_champion_status_box_graphic_pc34());
                if (boxAsset && boxAsset->loaded && boxAsset->pixels &&
                    boxAsset->width == 67 && boxAsset->height == 29) {
                    M11_AssetLoader_BlitRegion(boxAsset,
                        0, 0, 67, 29,
                        framebuffer, framebufferWidth, framebufferHeight,
                        x, y, 0);
                }
            }
            if (state->showDebugHUD) {
                snprintf(line, sizeof(line), "SLOT %d", slot + 1);
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              x + 4, y + 6, line, &g_text_small);
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              x + 4, y + 16, "EMPTY", &g_text_small);
            }
        }
    }
}

static void m11_format_front_cell_prompt(const M11_GameViewState* state,
                                         const M11_ViewportCell* cell,
                                         char* outAction,
                                         size_t outActionSize,
                                         char* outHint,
                                         size_t outHintSize) {
    char champion[16];
    if (outAction && outActionSize > 0U) {
        outAction[0] = '\0';
    }
    if (outHint && outHintSize > 0U) {
        outHint[0] = '\0';
    }
    if (!cell || !cell->valid) {
        snprintf(outAction, outActionSize, "FOCUS VOID");
        snprintf(outHint, outHintSize, "TURN TO RE-ENTER THE MAP");
        return;
    }
    if (cell->summary.groups > 0) {
        m11_get_active_champion_label(state, champion, sizeof(champion));
        snprintf(outAction, outActionSize, "ATTACK WITH %s", champion);
        snprintf(outHint, outHintSize, "SPACE OR CLICK CENTER STRIKES, A/D OR LOWER CORNERS STRAFE, TAB SWAPS CHAMPION");
        return;
    }
    if (cell->summary.projectiles > 0 || cell->summary.explosions > 0) {
        snprintf(outAction, outActionSize, "FOCUS ACTIVE EFFECT");
        snprintf(outHint, outHintSize, "SPACE WAITS, ENTER INSPECTS, TURN IF THE CELL STAYS HOT");
        return;
    }
    if (cell->elementType == DUNGEON_ELEMENT_DOOR) {
        if (m11_viewport_cell_is_open(cell)) {
            snprintf(outAction, outActionSize, "FOCUS OPEN DOOR");
            snprintf(outHint, outHintSize, "UP OR CLICK CENTER CROSSES, A/D STRAFES, ENTER INSPECTS, SPACE CLOSES THE DOOR");
        } else {
            snprintf(outAction, outActionSize, "FOCUS CLOSED DOOR");
            snprintf(outHint, outHintSize, "SPACE OPENS THE DOOR, ENTER INSPECTS, A/D STRAFES, TURN TO SEARCH");
        }
        return;
    }
    if (cell->elementType == DUNGEON_ELEMENT_PIT && (cell->square & 0x08)) {
        snprintf(outAction, outActionSize, "FOCUS PIT");
        snprintf(outHint, outHintSize, "UP RISKS A DROP, ENTER INSPECTS BEFORE COMMITTING");
        return;
    }
    if (cell->elementType == DUNGEON_ELEMENT_STAIRS) {
        snprintf(outAction, outActionSize, "FOCUS STAIRS");
        snprintf(outHint, outHintSize, "UP CLIMBS, ENTER INSPECTS, SPACE WAITS");
        return;
    }
    if (cell->elementType == DUNGEON_ELEMENT_TELEPORTER) {
        snprintf(outAction, outActionSize, "FOCUS TELEPORTER");
        snprintf(outHint, outHintSize, "UP TESTS THE RIFT, ENTER INSPECTS FIRST");
        return;
    }
    if (cell->summary.items > 0 || cell->summary.sensors > 0 || cell->summary.textStrings > 0) {
        snprintf(outAction, outActionSize, "FOCUS INTERACTABLE");
        snprintf(outHint, outHintSize, "ENTER INSPECTS, G GRABS FLOOR ITEMS, A/D STRAFES, SPACE WAITS");
        return;
    }
    if (m11_viewport_cell_is_open(cell)) {
        snprintf(outAction, outActionSize, "FOCUS CLEAR PASSAGE");
        snprintf(outHint, outHintSize, "UP ADVANCES, A/D OR LOWER CORNERS STRAFE, ENTER INSPECTS, TAB SWAPS CHAMPION");
        return;
    }
    snprintf(outAction, outActionSize, "FOCUS BLOCKED");
    snprintf(outHint, outHintSize, "ENTER INSPECTS, SPACE WAITS, TURN TO SEARCH");
}

/* ── Full-screen map overlay (M key) ──
 *
 * Period-faithful presentation modeled after DM1 / ReDMCSB automap style:
 * - Full-screen black fill to guarantee no HUD bleed-through
 * - Stone-gray single border (not bright yellow/brown double frame)
 * - Compact title without debug dimensions
 * - Muted tile palette: walls dark, corridors mid-gray, specials subdued
 * - Minimal footer — just the dismiss key, not a keybinding reference card
 */

/* Map-specific muted tile colors — period-faithful restraint.
 * Walls blend into the background; corridors are the primary readable
 * feature.  Special tiles (doors, stairs, pits) use subdued accents
 * rather than the saturated utility-palette colors. */
static unsigned char m11_map_tile_color(int elementType) {
    switch (elementType) {
        case DUNGEON_ELEMENT_WALL:       return M11_COLOR_BLACK;      /* walls vanish into bg */
        case DUNGEON_ELEMENT_CORRIDOR:   return M11_COLOR_DARK_GRAY;  /* explored floor */
        case DUNGEON_ELEMENT_PIT:        return M11_COLOR_BROWN;      /* subtle hazard */
        case DUNGEON_ELEMENT_STAIRS:     return M11_COLOR_LIGHT_GRAY; /* notable but muted */
        case DUNGEON_ELEMENT_DOOR:       return M11_COLOR_BROWN;      /* structural feature */
        case DUNGEON_ELEMENT_TELEPORTER: return M11_COLOR_NAVY;       /* arcane, not neon */
        case DUNGEON_ELEMENT_FAKEWALL:   return M11_COLOR_DARK_GRAY;  /* blends with corridor */
        default: return M11_COLOR_BLACK;
    }
}

static void m11_draw_fullscreen_map(const M11_GameViewState* state,
                                   unsigned char* framebuffer,
                                   int framebufferWidth,
                                   int framebufferHeight) {
    int panelX, panelY, panelW, panelH;
    const struct DungeonMapDesc_Compat* mapDesc = NULL;
    int mapW = 0, mapH = 0;
    int cellSize;
    int offsetX, offsetY;
    int gx, gy;

    if (!state || !state->active || !state->world.dungeon) return;
    if (state->world.party.mapIndex < 0 ||
        state->world.party.mapIndex >= (int)state->world.dungeon->header.mapCount) return;
    mapDesc = &state->world.dungeon->maps[state->world.party.mapIndex];
    mapW = (int)mapDesc->width;
    mapH = (int)mapDesc->height;
    if (mapW <= 0 || mapH <= 0) return;

    /* Full-screen black fill — guarantees no HUD content leaks through
     * at any edge, regardless of panel inset.  This is the primary
     * clipping-cleanliness measure (S2.3). */
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  0, 0, framebufferWidth, framebufferHeight, M11_COLOR_BLACK);

    /* Panel inset — generous margins for a deliberate, composed feel
     * rather than an edge-to-edge utility window. */
    panelX = 8;
    panelY = 6;
    panelW = framebufferWidth - 16;
    panelH = framebufferHeight - 12;

    /* Single stone-gray border — period-appropriate, not flashy */
    m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                  panelX, panelY, panelW, panelH, M11_COLOR_DARK_GRAY);

    /* Title — compact, no debug dimensions */
    {
        char mapTitle[32];
        M11_TextStyle titleStyle = g_text_shadow;
        titleStyle.color = M11_COLOR_LIGHT_GRAY;
        snprintf(mapTitle, sizeof(mapTitle), "LEVEL %d",
                 state->world.party.mapIndex + 1);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      panelX + 6, panelY + 4, mapTitle, &titleStyle);
    }

    /* Compute cell size to fit map in available area */
    {
        int availW = panelW - 12;
        int availH = panelH - 28; /* title + footer headroom */
        int cw = availW / mapW;
        int ch = availH / mapH;
        cellSize = cw < ch ? cw : ch;
        if (cellSize < 2) cellSize = 2;
        if (cellSize > 12) cellSize = 12;
        offsetX = panelX + 6 + (availW - mapW * cellSize) / 2;
        offsetY = panelY + 18 + (availH - mapH * cellSize) / 2;
    }

    /* Draw each tile */
    for (gy = 0; gy < mapH; ++gy) {
        for (gx = 0; gx < mapW; ++gx) {
            unsigned char square = 0;
            unsigned char fill = M11_COLOR_BLACK;
            int drawX = offsetX + gx * cellSize;
            int drawY = offsetY + gy * cellSize;
            int ok = m11_get_square_byte(&state->world,
                                         state->world.party.mapIndex,
                                         gx, gy, &square);
            if (ok) {
                if (m11_is_explored(state, gx, gy)) {
                    fill = m11_map_tile_color(square >> 5);
                } else {
                    /* Unexplored: pure black — indistinguishable from void */
                    fill = M11_COLOR_BLACK;
                }
            }
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          drawX, drawY, cellSize - 1, cellSize - 1, fill);

            /* Party position marker — white dot, restrained */
            if (gx == state->world.party.mapX && gy == state->world.party.mapY) {
                int cx = drawX + cellSize / 2 - 1;
                int cy = drawY + cellSize / 2 - 1;
                int ms = cellSize > 4 ? cellSize - 3 : 2;
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              cx, cy, ms, ms, M11_COLOR_WHITE);
                if (cellSize >= 6) {
                    m11_draw_party_arrow(framebuffer, framebufferWidth, framebufferHeight,
                                         cx - 1, cy - 1, ms + 2,
                                         state->world.party.direction, M11_COLOR_LIGHT_GRAY);
                }
            }
        }
    }

    /* Footer — minimal dismiss hint, not a keybinding cheat sheet */
    {
        int fs = state->fontScale > 1 ? state->fontScale : 1;
        int footerH = 8 * fs + 4;
        M11_TextStyle footerStyle = g_text_small;
        footerStyle.color = M11_COLOR_DARK_GRAY;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      panelX + 6, panelY + panelH - footerH, "PRESS M", &footerStyle);
    }
}

/* ── Full inventory panel (I key) ──
 * ReDMCSB-faithful composition: portrait+name at top, hands row,
 * body column, containers, backpack grid.  All equipment slots are
 * uniform 16×16 icon boxes matching the original SLOT_BOX structure
 * from Fontanel’s INVNTORY.C / OBJECT.C DrawIconInSlotBox.
 *
 * Original DM1 layout reference (viewport-relative):
 *   [Portrait 32×29]  [Name]       Hands: [Ready][Action]
 *   [Stats bars]       Body:  HEAD  NECK  TORSO  LEGS  FEET
 *                      Containers: POUCH×2  QUIVER×4
 *                      Backpack: 4×2 grid
 *                      Panel: Food/Water or object details
 */

/* Helper: draw one equipment slot box using original GRAPHICS.DAT
 * slot box bitmaps (18×18).  The legacy non-source view may use a
 * procedural 16×16 diagnostic box when the asset is unavailable; CSB and
 * DM1 never may.
 *
 * Original DM1 uses three slot box variants:
 *   graphic 33 = normal slot (C033_GRAPHIC_SLOT_BOX_NORMAL)
 *   graphic 34 = wounded champion slot (C034_GRAPHIC_SLOT_BOX_WOUNDED)
 *   graphic 35 = acting-hand slot (C035_GRAPHIC_SLOT_BOX_ACTING_HAND)
 *
 * Ref: DEFS.H lines 2193-2195, ReDMCSB INVNTORY.C DrawIconInSlotBox. */
static void m11_draw_inv_slot(const M11_GameViewState* state,
                              const struct ChampionState_Compat* champ,
                              unsigned char* fb, int fbW, int fbH,
                              int sx, int sy,
                              int slotIdx, const char* shortLabel) {
    /* Original slot boxes are 18×18 in GRAPHICS.DAT */
    static const int SZ_ORIG = 18;
    static const int SZ = 16; /* fallback procedural size */
    unsigned short thingId = champ->inventory[slotIdx];
    int selected = (slotIdx == state->inventorySelectedSlot);
    int isDead = (champ->hp.current == 0);
    int isActingHand = (slotIdx == CHAMPION_SLOT_HAND_LEFT ||
                        slotIdx == CHAMPION_SLOT_HAND_RIGHT);
    int drewSlotBox = 0;
    int slotBoxW = SZ, slotBoxH = SZ; /* effective size for item overlay */

    /* Try original GRAPHICS.DAT slot box graphic */
    if (state->assetsAvailable) {
        unsigned int gfxIdx;
        if (isActingHand)
            gfxIdx = (unsigned int)dm1_v1_graphic_slot_box_acting_hand_pc34();
        else if (isDead)
            gfxIdx = (unsigned int)dm1_v1_graphic_slot_box_wounded_pc34();
        else
            gfxIdx = (unsigned int)dm1_v1_graphic_slot_box_normal_pc34();

        const M11_AssetSlot* boxSlot = M11_AssetLoader_Load(
            (M11_AssetLoader*)&state->assetLoader, gfxIdx);
        if (boxSlot && boxSlot->loaded && boxSlot->pixels &&
            boxSlot->width == SZ_ORIG && boxSlot->height == SZ_ORIG) {
            M11_AssetLoader_Blit(boxSlot, fb, fbW, fbH, sx, sy, 0);
            drewSlotBox = 1;
            slotBoxW = SZ_ORIG;
            slotBoxH = SZ_ORIG;
        }
    }

    if (!drewSlotBox && !m11_is_dm1_source_kind(state->sourceKind) &&
        !m11_source_is_csb(state)) {
        /* Non-source diagnostic/legacy fallback. DM1 V1 and CSB must retain
         * the clear source panel until their slot-box material is decoded,
         * never invent a frame. ReDMCSB INVNTORY.C DrawIconInSlotBox. */
        unsigned char borderColor = selected ? M11_COLOR_LIGHT_GREEN : M11_COLOR_DARK_GRAY;
        m11_fill_rect(fb, fbW, fbH, sx, sy, SZ, SZ, M11_COLOR_BLACK);
        m11_draw_rect(fb, fbW, fbH, sx, sy, SZ, SZ, borderColor);
    }

    /* Selection highlight: bright border around the slot box */
    if (selected && (drewSlotBox ||
                     (!m11_is_dm1_source_kind(state->sourceKind) &&
                      !m11_source_is_csb(state)))) {
        m11_draw_rect(fb, fbW, fbH, sx, sy, slotBoxW, slotBoxH,
                      M11_COLOR_LIGHT_GREEN);
    }

    if (thingId != THING_NONE && thingId != THING_ENDOFLIST) {
        /* Occupied — DM1 draws the source 16×16 object icon in the
         * slot box (F0038_OBJECT_DrawIconInSlotBox), not the larger
         * viewport object sprite.  Fall back to the legacy sprite/tag
         * path only when the icon atlas is unavailable. */
        int drewSprite = 0;
        if (state->assetsAvailable && state->world.things) {
            int iconIndex = m11_object_icon_index_for_thing(
                state, state->world.things, thingId);
            drewSprite = m11_draw_dm_object_icon_index(
                state, fb, fbW, fbH, iconIndex, sx + 1, sy + 1, 0);
        }
        if (!drewSprite && state->assetsAvailable && state->world.things &&
            !m11_is_dm1_source_kind(state->sourceKind) &&
            !m11_source_is_csb(state)) {
            unsigned int gfxIdx = m11_inventory_thing_sprite_index(
                state->world.things, thingId);
            if (gfxIdx > 0 && gfxIdx < M11_GFX_ITEM_SPRITE_END) {
                const M11_AssetSlot* slot = M11_AssetLoader_Load(
                    (M11_AssetLoader*)&state->assetLoader, gfxIdx);
                if (slot && slot->loaded && slot->pixels &&
                    slot->width > 0 && slot->height > 0) {
                    /* Compatibility fallback: scale item sprite into the slot box. */
                    M11_AssetLoader_BlitScaled(slot, fb, fbW, fbH,
                                              sx + 1, sy + 1,
                                              slotBoxW - 2, slotBoxH - 2, 0);
                    drewSprite = 1;
                }
            }
        }
        if (!drewSprite && !m11_is_dm1_source_kind(state->sourceKind) &&
            !m11_source_is_csb(state)) {
            /* Diagnostic/legacy fallback only. Normal DM1 and CSB use
             * F0038's icon atlas or leave an unavailable icon blank. */
            int thingType = THING_GET_TYPE(thingId);
            const char* tag = "?";
            M11_TextStyle s = g_text_small;
            s.color = M11_COLOR_WHITE;
            switch (thingType) {
                case THING_TYPE_WEAPON:    tag = "Wp"; break;
                case THING_TYPE_ARMOUR:    tag = "Ar"; break;
                case THING_TYPE_SCROLL:    tag = "Sc"; break;
                case THING_TYPE_POTION:    tag = "Po"; break;
                case THING_TYPE_CONTAINER: tag = "Ch"; break;
                case THING_TYPE_JUNK:      tag = "Jk"; break;
                default: break;
            }
            m11_draw_text(fb, fbW, fbH, sx + 3, sy + 4, tag, &s);
        }
    } else if (!drewSlotBox && !m11_is_dm1_source_kind(state->sourceKind) &&
               !m11_source_is_csb(state)) {
        /* Diagnostic/legacy hint only; it is not a DM1 or CSB source visual. */
        M11_TextStyle dim = g_text_small;
        dim.color = M11_COLOR_DARK_GRAY;
        m11_draw_text(fb, fbW, fbH, sx + 2, sy + 4, shortLabel, &dim);
    }
}

static void m11_draw_v1_scroll_text_line(unsigned char* framebuffer,
                                         int framebufferWidth,
                                         int framebufferHeight,
                                         int centerX,
                                         int y,
                                         const char* line,
                                         int foreground,
                                         int background) {
    unsigned char encoded[DM1_V1_MESSAGE_MAX_LENGTH];

    if (!line || !g_activeOriginalFont ||
        !M11_Font_IsLoaded(g_activeOriginalFont)) {
        return;
    }

    dm1_v1_text_scroll_encode_line(line, encoded, sizeof(encoded));
    {
        int len = (int)strlen((const char*)encoded);
        int width = len * 6;
        int startX = centerX - (width / 2);
        int ci;
        for (ci = 0; ci < len; ++ci) {
            unsigned char ch = encoded[ci];
            int fontX = (int)ch * M11_FONT_CHAR_CELL_WIDTH + M11_FONT_X_OFFSET;
            int row, col;
            int dx = startX + ci * 6;
            for (row = 0; row < M11_FONT_CHAR_VISIBLE_H; ++row) {
                for (col = 0; col < 5; ++col) {
                    int px = dx + col;
                    int py = y + row;
                    if (px < 0 || px >= framebufferWidth ||
                        py < 0 || py >= framebufferHeight) continue;
                    if (M11_Font_GetPixel(g_activeOriginalFont,
                                          fontX + col, row)) {
                        framebuffer[py * framebufferWidth + px] =
                            (unsigned char)foreground;
                    } else if (background >= 0) {
                        framebuffer[py * framebufferWidth + px] =
                            (unsigned char)background;
                    }
                }
            }
        }
    }
}

static int m11_dm1_v1_f0341_receipt_from_loader(
    const M11_GameViewState* state,
    DM1_V1_F0341ScrollMaterialReceiptPc34* outReceipt)
{
    DM1_V1_F0341SourceSurfacePc34 panel;
    DM1_V1_F0341GlyphSourcePc34 glyph;
    const M11_AssetSlot* slot;

    if (!state || !outReceipt || !state->assetsAvailable ||
        !m11_dm1_pc34_hud_font_is_source_bound(state)) return 0;
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader, 23u);
    if (!slot || !slot->loaded || !slot->pixels || !slot->width || !slot->height) {
        return 0;
    }
    memset(&panel, 0, sizeof(panel));
    panel.graphicsDatOwned = 1;
    panel.graphicIndex = (int)slot->graphicIndex;
    panel.width = (int)slot->width;
    panel.height = (int)slot->height;
    panel.indexedPixelCount = panel.width * panel.height;
    panel.indexedPixels = slot->pixels;
    panel.pixelsFNV1a = dm1_v1_f0341_scroll_material_fnv1a_pc34(
        slot->pixels, panel.indexedPixelCount);
    memset(&glyph, 0, sizeof(glyph));
    glyph.graphicsDatOwned = 1;
    glyph.graphicIndex = M11_Font_ResolvedGraphicIndex(&state->originalFont);
    glyph.bits = state->originalFont.bitmap;
    glyph.byteCount = M11_FONT_BITMAP_BYTES;
    glyph.bitsFNV1a = dm1_v1_f0341_scroll_material_fnv1a_pc34(
        glyph.bits, glyph.byteCount);
    return panel.pixelsFNV1a && glyph.bitsFNV1a &&
        dm1_v1_f0341_scroll_material_receipt_pc34(
            &panel, 1, &glyph, 1, outReceipt);
}

static int m11_draw_v1_inventory_action_hand_scroll_panel(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight) {
    char decoded[DM1_V1_SCROLL_TEXT_MAX_LENGTH];
    const char* presentedText;
    DM1_V1_ScrollLayout layout;
    int panelX = 0, panelY = 0;
    int centerX;
    int drewPanel = 0;
    int i;
    DM1_V1_F0341ScrollMaterialReceiptPc34 materialReceipt;

    if (!DM1_V1_M11Runtime_DecodeInventoryActionHandScrollTextPc34Compat(
            state, decoded, sizeof(decoded))) {
        return 0;
    }
    /* The scroll THING and its decoded TextString remain source-owned.  PO
     * lookup happens only in this draw transaction, so selecting Original
     * localization never mutates DUNGEON.DAT or the runtime decoder receipt. */
    presentedText = fs_po_gettext_in_domain(
        state->sourceKind == M11_GAME_SOURCE_CSB_BOOT ? "csb" : "dm1",
        decoded);
    {
        DM1_V1_LayoutZoneRectPc34 panelRect =
            dm1_v1_inventory_panel_rect_pc34();
        if (!dm1_v1_inventory_panel_zone_id_pc34()) {
            return 0;
        }
        panelX = panelRect.x;
        panelY = panelRect.y;
    }

    /* ReDMCSB PANEL.C F0347 chooses the action-hand scroll as panel
     * content, F0342 dispatches it to F0341, and F0341 blits graphic C023
     * into C101_ZONE_PANEL before printing decoded TextString lines. */
    memset(&materialReceipt, 0, sizeof(materialReceipt));
    if (state && state->assetsAvailable &&
        m11_dm1_v1_f0341_receipt_from_loader(state, &materialReceipt) &&
        materialReceipt.valid && materialReceipt.suppressSyntheticFallback) {
        const M11_AssetSlot* scrollPanel = M11_AssetLoader_Load(
            (M11_AssetLoader*)&state->assetLoader,
            (unsigned int)dm1_v1_graphic_panel_open_scroll_pc34());
        if (scrollPanel &&
            DM1_ChampionPanel_AssetSurfaceAccepted(
                dm1_v1_graphic_panel_open_scroll_pc34(),
                dm1_v1_graphic_panel_open_scroll_pc34(),
                scrollPanel->loaded, scrollPanel->pixels != NULL,
                scrollPanel->width, scrollPanel->height,
                materialReceipt.panelSourceW, materialReceipt.panelSourceH) &&
            materialReceipt.panelGraphicIndex == (int)scrollPanel->graphicIndex &&
            materialReceipt.panelSourceW == (int)scrollPanel->width &&
            materialReceipt.panelSourceH == (int)scrollPanel->height) {
            M11_AssetLoader_BlitRegion(scrollPanel, 0, 0,
                                       materialReceipt.panelSourceW,
                                       materialReceipt.panelSourceH,
                                       framebuffer, framebufferWidth,
                                       framebufferHeight,
                                       M11_VIEWPORT_X + panelX,
                                       M11_VIEWPORT_Y + panelY,
                                       materialReceipt.panelTransparentColor);
            drewPanel = 1;
        }
    }
    if (!drewPanel) return 0;

    dm1_v1_text_scroll_measure_layout(presentedText, &layout);
    centerX = M11_VIEWPORT_X + 162;
    for (i = 0; i < layout.storedLineCount; ++i) {
        m11_draw_v1_scroll_text_line(framebuffer,
                                     framebufferWidth,
                                     framebufferHeight,
                                     centerX,
                                     M11_VIEWPORT_Y + layout.firstLineY +
                                         i * DM1_V1_TEXT_LINE_HEIGHT,
                                     layout.lines[i],
                                     materialReceipt.textForeground,
                                     materialReceipt.textBackground);
    }
    return 1;
}

static const DM1_V1_F0342MaterialOperationPc34*
m11_dm1_v1_f0342_operation(
    const DM1_V1_F0342ObjectDescriptionMaterialReceiptPc34* receipt,
    int kind)
{
    int index;
    if (!receipt || !receipt->valid) return NULL;
    for (index = 0; index < receipt->operationCount; ++index) {
        if (receipt->operations[index].kind == kind) {
            return &receipt->operations[index];
        }
    }
    return NULL;
}

/* F0342 is an all-or-nothing original material transaction: C020/C029 and
 * M653 share one PC34 receipt before C101/C504/C506/C556 may be presented. */
static int m11_dm1_v1_f0342_receipt_from_loader(
    const M11_GameViewState* state,
    DM1_V1_F0342ObjectDescriptionMaterialReceiptPc34* outReceipt)
{
    static const int graphics[] = {20, 29};
    DM1_V1_F0342SourceSurfacePc34 surfaces[2];
    DM1_V1_F0342GlyphSourcePc34 glyph;
    int index;

    if (!state || !outReceipt || !state->assetsAvailable ||
        !m11_dm1_pc34_hud_font_is_source_bound(state)) {
        return 0;
    }
    memset(surfaces, 0, sizeof(surfaces));
    for (index = 0; index < (int)(sizeof(graphics) / sizeof(graphics[0]));
         ++index) {
        const M11_AssetSlot* slot = M11_AssetLoader_Load(
            (M11_AssetLoader*)&state->assetLoader, (unsigned int)graphics[index]);
        if (!slot || !slot->loaded || !slot->pixels || !slot->width ||
            !slot->height) {
            return 0;
        }
        surfaces[index].graphicsDatOwned = 1;
        surfaces[index].graphicIndex = graphics[index];
        surfaces[index].width = (int)slot->width;
        surfaces[index].height = (int)slot->height;
        surfaces[index].indexedPixelCount =
            (int)slot->width * (int)slot->height;
        surfaces[index].indexedPixels = slot->pixels;
        surfaces[index].pixelsFNV1a =
            dm1_v1_f0342_object_description_material_fnv1a_pc34(
                slot->pixels, surfaces[index].indexedPixelCount);
        if (!surfaces[index].pixelsFNV1a) return 0;
    }
    memset(&glyph, 0, sizeof(glyph));
    glyph.graphicsDatOwned = 1;
    glyph.graphicIndex = M11_Font_ResolvedGraphicIndex(&state->originalFont);
    glyph.bits = state->originalFont.bitmap;
    glyph.byteCount = M11_FONT_BITMAP_BYTES;
    glyph.bitsFNV1a = dm1_v1_f0342_object_description_material_fnv1a_pc34(
        glyph.bits, glyph.byteCount);
    if (!glyph.bitsFNV1a) return 0;
    return dm1_v1_f0342_object_description_material_receipt_pc34(
        surfaces, (int)(sizeof(surfaces) / sizeof(surfaces[0])),
        &glyph, 1, outReceipt);
}

static int m11_draw_v1_inventory_object_description_panel(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight) {
    int panelX = 0, panelY = 0, panelW = 0, panelH = 0;
    int circleX = 0, circleY = 0, circleW = 0, circleH = 0;
    int iconX = 0, iconY = 0, iconW = 0, iconH = 0;
    int nameX = 0, nameY = 0, nameW = 0, nameH = 0;
    int bodyX = 0, bodyY = 0;
    const M11_AssetSlot* panel;
    const M11_AssetSlot* circle;
    DM1_V1_F0342ObjectDescriptionMaterialReceiptPc34 materialReceipt;
    const DM1_V1_F0342MaterialOperationPc34* panelOperation;
    const DM1_V1_F0342MaterialOperationPc34* circleOperation;
    const DM1_V1_F0342MaterialOperationPc34* nameOperation;
    const DM1_V1_F0342MaterialOperationPc34* bodyOperation;
    char wrapped[6][24];
    size_t lineCount;
    size_t i;

    if (!state || !framebuffer || !state->v1ObjectDescriptionPanelActive ||
        state->v1ObjectDescriptionThing == THING_NONE ||
        DM1_V1_M11Runtime_GetLeaderHandThingPc34Compat(state) != state->v1ObjectDescriptionThing ||
        !m11_v1_object_panel_source_material_current(state)) {
        return 0;
    }
    {
        DM1_V1_LayoutZoneRectPc34 panelRect =
            dm1_v1_inventory_panel_rect_pc34();
        DM1_V1_LayoutZoneRectPc34 circleRect =
            dm1_v1_object_description_circle_rect_pc34();
        DM1_V1_LayoutZoneRectPc34 iconRect =
            dm1_v1_object_description_icon_rect_pc34();
        panelX = panelRect.x;
        panelY = panelRect.y;
        panelW = panelRect.w;
        panelH = panelRect.h;
        circleX = circleRect.x;
        circleY = circleRect.y;
        circleW = circleRect.w;
        circleH = circleRect.h;
        iconX = iconRect.x;
        iconY = iconRect.y;
        iconW = iconRect.w;
        iconH = iconRect.h;
        if (!dm1_v1_inventory_panel_zone_id_pc34() ||
            !dm1_v1_object_description_continuation_origin_pc34(
                &bodyX, &bodyY)) {
            return 0;
        }
    }

    /* PANEL.C F0342:1140-1145 owns C020/C029 and their layout-696
     * destinations. Missing PC34 material leaves the C017 base intact; it
     * must not become a host-drawn description panel. */
    if (!state->assetsAvailable || iconW != 16 || iconH != 16) return 0;
    panel = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                 (unsigned int)dm1_v1_graphic_panel_empty_pc34());
    circle = M11_AssetLoader_Load(
        (M11_AssetLoader*)&state->assetLoader,
        (unsigned int)dm1_v1_graphic_object_description_circle_pc34());
    if (!panel || !circle ||
        !DM1_ChampionPanel_AssetSurfaceAccepted(
            dm1_v1_graphic_panel_empty_pc34(),
            dm1_v1_graphic_panel_empty_pc34(),
            panel->loaded, panel->pixels != NULL,
            panel->width, panel->height, panelW, panelH) ||
        !DM1_ChampionPanel_AssetSurfaceAccepted(
            dm1_v1_graphic_object_description_circle_pc34(),
            dm1_v1_graphic_object_description_circle_pc34(),
            circle->loaded, circle->pixels != NULL,
            circle->width, circle->height, 26, 26) ||
        circle->width > (unsigned short)circleW ||
        circle->height > (unsigned short)circleH) {
        return 0;
    }
    memset(&materialReceipt, 0, sizeof(materialReceipt));
    if (!m11_dm1_v1_f0342_receipt_from_loader(state, &materialReceipt) ||
        !materialReceipt.suppressSyntheticFallback ||
        !(panelOperation = m11_dm1_v1_f0342_operation(
            &materialReceipt, DM1_V1_F0342_PANEL_BACKGROUND_PC34)) ||
        !(circleOperation = m11_dm1_v1_f0342_operation(
            &materialReceipt, DM1_V1_F0342_OBJECT_CIRCLE_PC34)) ||
        !(nameOperation = m11_dm1_v1_f0342_operation(
            &materialReceipt, DM1_V1_F0342_OBJECT_NAME_PC34)) ||
        !(bodyOperation = m11_dm1_v1_f0342_operation(
            &materialReceipt, DM1_V1_F0342_OBJECT_BODY_PC34)) ||
        panelOperation->graphicIndex != (int)panel->graphicIndex ||
        panelOperation->sourceW != (int)panel->width ||
        panelOperation->sourceH != (int)panel->height ||
        panelOperation->transparentColor != -1 ||
        circleOperation->graphicIndex != (int)circle->graphicIndex ||
        circleOperation->sourceW != (int)circle->width ||
        circleOperation->sourceH != (int)circle->height ||
        circleOperation->transparentColor != M11_COLOR_DARK_GRAY ||
        nameOperation->graphicIndex != materialReceipt.m653GraphicIndex ||
        bodyOperation->graphicIndex != materialReceipt.m653GraphicIndex ||
        nameOperation->paletteForeground != M11_COLOR_SILVER ||
        bodyOperation->paletteForeground != M11_COLOR_SILVER ||
        nameOperation->paletteBackground != -1 ||
        bodyOperation->paletteBackground != -1) {
        return 0;
    }
    M11_AssetLoader_BlitRegion(panel,
                               panelOperation->sourceX, panelOperation->sourceY,
                               panelOperation->sourceW, panelOperation->sourceH,
                               framebuffer, framebufferWidth, framebufferHeight,
                               M11_VIEWPORT_X + panelX, M11_VIEWPORT_Y + panelY,
                               panelOperation->transparentColor);
    M11_AssetLoader_BlitRegion(circle,
                               circleOperation->sourceX, circleOperation->sourceY,
                               circleOperation->sourceW, circleOperation->sourceH,
                               framebuffer, framebufferWidth, framebufferHeight,
                               M11_VIEWPORT_X + circleX, M11_VIEWPORT_Y + circleY,
                               circleOperation->transparentColor);

    if (state->v1ObjectDescriptionIconIndex >= 0) {
        (void)m11_draw_dm_object_icon_index(state, framebuffer, framebufferWidth,
                                            framebufferHeight,
                                            state->v1ObjectDescriptionIconIndex,
                                            M11_VIEWPORT_X + iconX,
                                            M11_VIEWPORT_Y + iconY, 0);
    }

    {
        DM1_V1_LayoutZoneRectPc34 nameRect;
        if (dm1_v1_object_description_name_rect_for_text_pc34(
                M11_Font_MeasureString(state->v1ObjectDescriptionName),
                7, &nameRect)) {
            nameX = nameRect.x;
            nameY = nameRect.y;
            nameW = nameRect.w;
            nameH = nameRect.h;
        } else {
            nameW = 0;
            nameH = 0;
        }
    }
    if (nameW > 0 && nameH > 0) {
        (void)nameW;
        (void)nameH;
        M11_Font_DrawString(g_activeOriginalFont, framebuffer,
                            framebufferWidth, framebufferHeight,
                            M11_VIEWPORT_X + nameX, M11_VIEWPORT_Y + nameY,
                            state->v1ObjectDescriptionName,
                            (unsigned char)nameOperation->paletteForeground,
                            nameOperation->paletteBackground, 1);
    }

    memset(wrapped, 0, sizeof(wrapped));
    lineCount = INVENTORY_Compat_WrapObjectDescriptionText(
        state->v1ObjectDescriptionBody, &wrapped[0][0], 6u, sizeof(wrapped[0]), NULL);
    for (i = 0; i < lineCount && i < 6u; ++i) {
        M11_Font_DrawString(g_activeOriginalFont, framebuffer,
                            framebufferWidth, framebufferHeight,
                            M11_VIEWPORT_X + bodyX,
                            M11_VIEWPORT_Y + bodyY + (int)i * 7,
                            wrapped[i],
                            (unsigned char)bodyOperation->paletteForeground,
                            bodyOperation->paletteBackground, 1);
    }
    return 1;
}

/* PANEL.C F0339 follows a successfully drawn F0342 detail panel. C018 and
 * C019 are original GRAPHICS.DAT surfaces; missing material gets no host
 * substitute. */
static int m11_draw_v1_inventory_panel_arrow_or_eye(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int pressingEye)
{
    DM1_V1_LayoutZoneRectPc34 rect;
    DM1_V1_F0352SourceSurfacePc34 surfaces[2];
    DM1_V1_F0352GlyphSourcePc34 glyph;
    DM1_V1_F0352EyeMaterialReceiptPc34 receipt;
    const M11_AssetSlot* source;
    const M11_AssetSlot* arrow;
    const M11_AssetSlot* eye;
    int graphic;

    if (!state || !framebuffer || !state->assetsAvailable ||
        !dm1_v1_arrow_or_eye_zone_id_pc34()) {
        return 0;
    }
    rect = dm1_v1_arrow_or_eye_rect_pc34();
    if (rect.w <= 0 || rect.h <= 0) return 0;
    graphic = dm1_v1_graphic_arrow_or_eye_pc34(pressingEye != 0);
    if (graphic <= 0) return 0;
    if (!m11_dm1_pc34_hud_font_is_source_bound(state)) return 0;
    arrow = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                 DM1_V1_F0352_C018_ARROW_PC34);
    eye = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                               DM1_V1_F0352_C019_EYE_PC34);
    if (!arrow || !eye || !arrow->loaded || !eye->loaded ||
        !arrow->pixels || !eye->pixels) return 0;
    memset(surfaces, 0, sizeof(surfaces));
    memset(&glyph, 0, sizeof(glyph));
    surfaces[0].graphicsDatOwned = 1;
    surfaces[0].graphicIndex = (int)arrow->graphicIndex;
    surfaces[0].width = (int)arrow->width;
    surfaces[0].height = (int)arrow->height;
    surfaces[0].indexedPixelCount = surfaces[0].width * surfaces[0].height;
    surfaces[0].indexedPixels = arrow->pixels;
    surfaces[0].pixelsFNV1a = dm1_v1_f0352_eye_material_fnv1a_pc34(
        arrow->pixels, surfaces[0].indexedPixelCount);
    surfaces[1].graphicsDatOwned = 1;
    surfaces[1].graphicIndex = (int)eye->graphicIndex;
    surfaces[1].width = (int)eye->width;
    surfaces[1].height = (int)eye->height;
    surfaces[1].indexedPixelCount = surfaces[1].width * surfaces[1].height;
    surfaces[1].indexedPixels = eye->pixels;
    surfaces[1].pixelsFNV1a = dm1_v1_f0352_eye_material_fnv1a_pc34(
        eye->pixels, surfaces[1].indexedPixelCount);
    glyph.graphicsDatOwned = 1;
    glyph.graphicIndex = M11_Font_ResolvedGraphicIndex(&state->originalFont);
    glyph.bits = state->originalFont.bitmap;
    glyph.byteCount = M11_FONT_BITMAP_BYTES;
    glyph.bitsFNV1a = dm1_v1_f0352_eye_material_fnv1a_pc34(
        glyph.bits, glyph.byteCount);
    if (!surfaces[0].pixelsFNV1a || !surfaces[1].pixelsFNV1a ||
        !glyph.bitsFNV1a ||
        !dm1_v1_f0352_eye_material_receipt_pc34(
            surfaces, 2, &glyph, 1, &receipt) ||
        !receipt.valid || !receipt.suppressSyntheticFallback ||
        receipt.panelZoneIndex != dm1_v1_arrow_or_eye_zone_id_pc34() ||
        receipt.panelX != rect.x || receipt.panelY != rect.y ||
        receipt.sourceWidth != rect.w || receipt.sourceHeight != rect.h ||
        receipt.m653GraphicIndex != glyph.graphicIndex) return 0;
    source = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                  (unsigned int)graphic);
    if (!source || !source->loaded || !source->pixels ||
        source->width != (unsigned short)rect.w ||
        source->height != (unsigned short)rect.h) {
        return 0;
    }
    M11_AssetLoader_Blit(source, framebuffer, framebufferWidth,
                         framebufferHeight,
                         M11_VIEWPORT_X + rect.x,
                         M11_VIEWPORT_Y + rect.y,
                         receipt.transparentColor);
    return 1;
}

static void m11_draw_v1_food_water_bar(unsigned char* framebuffer,
                                       int framebufferWidth,
                                       int framebufferHeight,
                                       int x,
                                       int y,
                                       int w,
                                       int h,
                                       int shadowOffset,
                                       int amount,
                                       int sourceColor) {
    DM1_V1_NeedsBarRenderCommandPc34Compat cmd;
    if (!DM1_V1_Needs_BuildBarRenderCommandPc34Compat(
            x, y, w, h, shadowOffset, amount, sourceColor, &cmd) ||
        !cmd.draw) {
        return;
    }
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  cmd.shadowX, cmd.shadowY, cmd.shadowWidth, cmd.shadowHeight,
                  (unsigned char)cmd.shadowColor);
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  cmd.x, cmd.y, cmd.width, cmd.height,
                  (unsigned char)cmd.fillColor);
}

static int m11_draw_v1_inventory_food_water_panel(const M11_GameViewState* state,
                                                  unsigned char* framebuffer,
                                                  int framebufferWidth,
                                                  int framebufferHeight) {
    const struct ChampionState_Compat* champ;
    const M11_AssetSlot* panel;
    const M11_AssetSlot* food;
    const M11_AssetSlot* water;
    const M11_AssetSlot* poison = NULL;
    int championIndex;
    int panelX = 0, panelY = 0, panelW = 0, panelH = 0;

    if (!state || !framebuffer || !state->v1FoodWaterPanelActive ||
        !state->inventoryPanelActive || state->showDebugHUD) {
        return 0;
    }
    championIndex = state->world.party.activeChampionIndex;
    if (championIndex < 0 || championIndex >= CHAMPION_MAX_PARTY) return 0;
    champ = &state->world.party.champions[championIndex];
    if (!champ->present) return 0;
    {
        DM1_V1_LayoutZoneRectPc34 panelRect =
            dm1_v1_inventory_panel_rect_pc34();
        if (!dm1_v1_inventory_panel_zone_id_pc34()) {
            return 0;
        }
        panelX = panelRect.x;
        panelY = panelRect.y;
        panelW = panelRect.w;
        panelH = panelRect.h;
    }

    /* PANEL.C F0345:1597-1606 owns C020/C030/C031 and, conditionally,
     * C032.  These indexed surfaces and their C101/C500..C502 geometry are
     * part of one panel transaction.  A hand-drawn box or partial label set
     * changes the original layout, so incomplete PC34 material consumes the
     * route without drawing a substitute. */
    if (!state->assetsAvailable) {
        return 1;
    }
    panel = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                 (unsigned int)dm1_v1_graphic_panel_empty_pc34());
    food = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                (unsigned int)dm1_v1_graphic_food_label_pc34());
    water = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                 (unsigned int)dm1_v1_graphic_water_label_pc34());
    if (!panel || !food || !water ||
        !DM1_ChampionPanel_AssetSurfaceAccepted(
            dm1_v1_graphic_panel_empty_pc34(),
            dm1_v1_graphic_panel_empty_pc34(),
            panel->loaded, panel->pixels != NULL,
            panel->width, panel->height, panelW, panelH) ||
        !DM1_ChampionPanel_AssetSurfaceAccepted(
            dm1_v1_graphic_food_label_pc34(),
            dm1_v1_graphic_food_label_pc34(),
            food->loaded, food->pixels != NULL,
            food->width, food->height, 34, 9) ||
        !DM1_ChampionPanel_AssetSurfaceAccepted(
            dm1_v1_graphic_water_label_pc34(),
            dm1_v1_graphic_water_label_pc34(),
            water->loaded, water->pixels != NULL,
            water->width, water->height, 46, 9)) {
        return 1;
    }
    {
        dm1_v1_champion_panel_food_water_runtime_receipt_pc34_t receipt;
        const int panelScreenX = M11_VIEWPORT_X + panelX;
        const int panelScreenY = M11_VIEWPORT_Y + panelY;

        /* F0134's C12 status fill and F0135/F0658's C020/C030/C031 blits
         * form one source transaction. It is admitted only with the exact
         * PC34 LIGHT0 palette and C101/C500/C501 destinations. */
        if (!dm1_v1_champion_panel_food_water_material_admit_runtime_pc34(
                panel, food, water,
                &G9010_auc_VgaPaletteBrightest_Compat[0][0],
                VGA_PALETTE_PC34_COLOR_COUNT * 3u,
                panelScreenX, panelScreenY,
                panelScreenX + 32,
                panelScreenY + 13 - (((int)food->height + 1) / 2),
                panelScreenX + 32,
                panelScreenY + 36 - (((int)water->height + 1) / 2),
                framebufferWidth, framebufferHeight, &receipt)) {
            return 1;
        }
    }
    if (champ->poisonDose > 0) {
        poison = M11_AssetLoader_Load(
            (M11_AssetLoader*)&state->assetLoader,
            (unsigned int)dm1_v1_graphic_poisoned_label_pc34());
        if (!poison ||
            !DM1_ChampionPanel_AssetSurfaceAccepted(
                dm1_v1_graphic_poisoned_label_pc34(),
                dm1_v1_graphic_poisoned_label_pc34(),
                poison->loaded, poison->pixels != NULL,
                poison->width, poison->height, 96, 15)) {
            return 1;
        }
    }

    M11_AssetLoader_Blit(panel, framebuffer, framebufferWidth, framebufferHeight,
                         M11_VIEWPORT_X + panelX, M11_VIEWPORT_Y + panelY,
                         M11_COLOR_RED);
    /* F0658 resolves C500/C501/C502 before it blits with C12 transparent.
     * The retained zone geometry is viewport-relative: C500=(112,60),
     * C501=(112,83), C502=(112,102). */
    M11_AssetLoader_Blit(food, framebuffer, framebufferWidth, framebufferHeight,
                         M11_VIEWPORT_X + panelX + 32,
                         M11_VIEWPORT_Y + panelY + 13 - (((int)food->height + 1) / 2),
                         M11_COLOR_DARK_GRAY);
    M11_AssetLoader_Blit(water, framebuffer, framebufferWidth, framebufferHeight,
                         M11_VIEWPORT_X + panelX + 32,
                         M11_VIEWPORT_Y + panelY + 36 - (((int)water->height + 1) / 2),
                         M11_COLOR_DARK_GRAY);
    if (poison) {
        M11_AssetLoader_Blit(poison, framebuffer, framebufferWidth, framebufferHeight,
                             M11_VIEWPORT_X + panelX + 32,
                             M11_VIEWPORT_Y + panelY + 58 - (((int)poison->height + 1) / 2),
                             M11_COLOR_DARK_GRAY);
    }

    {
        const dm1_v1_champion_panel_food_water_status_box_contract_pc34_t*
            foodWaterContract =
                dm1_v1_champion_panel_food_water_status_box_contract_pc34();
        dm1_v1_champion_panel_food_water_bar_zone_pc34_t foodBar =
            dm1_v1_champion_panel_food_bar_zone_pc34();
        dm1_v1_champion_panel_food_water_bar_zone_pc34_t waterBar =
            dm1_v1_champion_panel_water_bar_zone_pc34();

        /* PANEL.C F0344 supplies both the warning thresholds and the two
         * normal colours consumed by F0343's horizontal C103/C104 fills.
         * There is no source-defined default palette if that contract is
         * unavailable, so retain the authentic C020/C030/C031 panel but do
         * not invent alternate food or water bars. */
        if (!foodWaterContract) {
            return 1;
        }
        m11_draw_v1_food_water_bar(framebuffer, framebufferWidth, framebufferHeight,
                                   M11_VIEWPORT_X + foodBar.x,
                                   M11_VIEWPORT_Y + foodBar.y,
                                   foodBar.w, foodBar.h,
                                   foodBar.shadow_offset,
                                   (int)champ->food,
                                   foodWaterContract->food_base_color);
        m11_draw_v1_food_water_bar(framebuffer, framebufferWidth, framebufferHeight,
                                   M11_VIEWPORT_X + waterBar.x,
                                   M11_VIEWPORT_Y + waterBar.y,
                                   waterBar.w, waterBar.h,
                                   waterBar.shadow_offset,
                                   (int)champ->water,
                                   foodWaterContract->water_base_color);
    }
    return 1;
}

static int m11_draw_v1_mouth_visual_frame(const M11_GameViewState* state,
                                          unsigned char* framebuffer,
                                          int framebufferWidth,
                                          int framebufferHeight) {
    if (!state || !framebuffer || state->showDebugHUD ||
        state->v1MouthVisualIconIndex <= 0) {
        return 0;
    }
    /* ReDMCSB PANEL.C F0349 draws C205/C206 into C545_ZONE_MOUTH.
     * COMMAND.C maps C545 to viewport-relative x=56,y=13 in the
     * same 16x16 object-icon footprint used by F0332. */
    return m11_draw_dm_object_icon_index(state,
                                         framebuffer,
                                         framebufferWidth,
                                         framebufferHeight,
                                         state->v1MouthVisualIconIndex,
                                         M11_VIEWPORT_X + 56,
                                         M11_VIEWPORT_Y + 13,
                                         0);
}

/* ReDMCSB TEXT2.C F0644: the interface font takes a baseline y coordinate,
 * copies six pixels from each eight-pixel M653 cell at x=char*8+3, and
 * advances six pixels.  It is distinct from the eight-pixel inscription
 * renderer used by M11_Font_DrawString. */
static int m11_draw_dm1_pc34_interface_text(
    const M11_FontState* font,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int x,
    int y,
    const char* text,
    unsigned char foreground,
    unsigned char background)
{
    int drawn = 0;

    if (!font || !M11_Font_IsLoaded(font) || !framebuffer || !text) {
        return 0;
    }
    while (*text) {
        (void)m11_draw_dm1_m653_cell_at_baseline(
            font, framebuffer, framebufferWidth, framebufferHeight,
            x, y, (unsigned char)*text, foreground, background);
        x += 6;
        text++;
        drawn = 1;
    }
    return drawn;
}

/* ReDMCSB REVIVE.C F0281 (PC F20/F20J path) prints C027's fixed guides
 * through F0052 at viewport coordinates, then writes the current name/title
 * and C09 cursor to the same original M653 font surface.  This is deliberately
 * separate from m11_draw_text_original(): the resurrection panel must neither
 * scale nor fall back to Firestaff's host font when PC34 M653 is unavailable. */
static int m11_draw_dm1_hoc_rename_pc34_text(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    const DM1_V1_ResurrectionRenameUiGatePc34Compat* rename;
    const M11_FontState* font;

    if (!state || !framebuffer || !state->candidateMirrorRenameActive ||
        !state->originalFontAvailable ||
        !M11_Font_IsLoaded(&state->originalFont) ||
        !m11_dm1_pc34_hud_font_is_source_bound(state)) {
        return 0;
    }

    rename = &state->candidateMirrorRename;
    font = &state->originalFont;

    /* REVIVE.C F0281:408-409, F0052_TEXT_PrintToViewport(..., C13, ...).
     * F0052 writes C12 behind each M653 glyph; preserve that exact erase
     * behavior so a full host redraw cannot leave old typed characters. */
    (void)m11_draw_dm1_pc34_interface_text(
        font, framebuffer, framebufferWidth, framebufferHeight,
        M11_VIEWPORT_X + 177, M11_VIEWPORT_Y + 58,
        "_______", M11_COLOR_SILVER, M11_COLOR_DARK_GRAY);
    (void)m11_draw_dm1_pc34_interface_text(
        font, framebuffer, framebufferWidth, framebufferHeight,
        M11_VIEWPORT_X + 105, M11_VIEWPORT_Y + 76,
        "___________________", M11_COLOR_SILVER, M11_COLOR_DARK_GRAY);

    /* REVIVE.C F0281:418-419 and 543-544: the gate retains these as
     * viewport-relative coordinates.  Convert exactly once at the M11
     * framebuffer boundary. */
    if (rename->name[0] != '\0') {
        (void)m11_draw_dm1_pc34_interface_text(
            font, framebuffer, framebufferWidth, framebufferHeight,
            M11_VIEWPORT_X + 177, M11_VIEWPORT_Y + 91,
            rename->name, M11_COLOR_SILVER, M11_COLOR_DARK_GRAY);
    }
    if (rename->title[0] != '\0') {
        (void)m11_draw_dm1_pc34_interface_text(
            font, framebuffer, framebufferWidth, framebufferHeight,
            M11_VIEWPORT_X + 105, M11_VIEWPORT_Y + 109,
            rename->title, M11_COLOR_SILVER, M11_COLOR_DARK_GRAY);
    }
    if (!(rename->fieldMode ==
              DM1_V1_RESURRECTION_RENAME_UI_FIELD_TITLE_PC34_COMPAT &&
          rename->characterIndex >=
              DM1_V1_RESURRECTION_RENAME_UI_TITLE_MAX_PC34_COMPAT)) {
        /* REVIVE.C F0281:609, 648 and 687: C09 cursor uses the same C12
         * background and is absent only when the title field is full. */
        (void)m11_draw_dm1_pc34_interface_text(
            font, framebuffer, framebufferWidth, framebufferHeight,
            M11_VIEWPORT_X + rename->cursorX,
            M11_VIEWPORT_Y + rename->cursorY,
            "_", M11_COLOR_ORANGE, M11_COLOR_DARK_GRAY);
    }
    return 1;
}

/* ReDMCSB LOADSAVE.C F0435:2803-2816 restores each saved 32x29 4bpp
 * M516_CHAMPIONS.Portrait before the resumed dungeon is presented.  A
 * resumed PC34 champion must therefore retain its save-owned pixels in the
 * inventory panel; the GRAPHICS.DAT atlas is only a new-recruit fallback. */
static int m11_draw_saved_champion_portrait_pc34(
    const struct ChampionState_Compat* champion,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    int dstX,
    int dstY)
{
    int y;

    if (!champion || !champion->portraitBitmapValid || !framebuffer ||
        framebufferWidth <= 0 || framebufferHeight <= 0 ||
        dstX < 0 || dstY < 0 ||
        dstX + CHAMPION_PORTRAIT_BITMAP_WIDTH > framebufferWidth ||
        dstY + CHAMPION_PORTRAIT_BITMAP_HEIGHT > framebufferHeight) {
        return 0;
    }
    for (y = 0; y < CHAMPION_PORTRAIT_BITMAP_HEIGHT; ++y) {
        const unsigned char* src = champion->portraitBitmap +
            y * (CHAMPION_PORTRAIT_BITMAP_WIDTH / 2);
        unsigned char* dst = framebuffer + (dstY + y) * framebufferWidth + dstX;
        int x;

        for (x = 0; x < CHAMPION_PORTRAIT_BITMAP_WIDTH; x += 2) {
            const unsigned char packed = src[x / 2];
            dst[x] = (unsigned char)(packed >> 4);
            dst[x + 1] = (unsigned char)(packed & 0x0fU);
        }
    }
    return 1;
}

static int m11_dm1_v1_f0355_inventory_material_ready(
    const M11_GameViewState* state)
{
    DM1_V1_F0355SourceSurfacePc34 surfaces[2];
    DM1_V1_F0355GlyphSourcePc34 glyph;
    DM1_V1_F0355InventoryMaterialReceiptPc34 receipt;
    M11_FontState loadedFont;
    const M11_FontState* sourceFont;
    const M11_AssetSlot* inventory;
    const M11_AssetSlot* slot;

    /* F0355 does not draw text itself, but its material receipt still binds
     * the active inventory session to raw M653. If the frame has not selected
     * its original font yet, decode that same record from this GRAPHICS.DAT
     * loader; a host font is never considered. */
    if (!state || !state->assetsAvailable) return 0;
    sourceFont = &state->originalFont;
    if (!state->originalFontAvailable || !M11_Font_IsLoaded(sourceFont)) {
        M11_Font_Init(&loadedFont);
        if (!M11_Font_LoadFromGraphicsDat(&loadedFont,
                                          state->assetLoader.fileState,
                                          state->assetLoader.runtimeState)) {
            return 0;
        }
        sourceFont = &loadedFont;
    }
    if (M11_Font_ResolvedGraphicIndex(sourceFont) != M11_FONT_GRAPHIC_INDEX_PC34 &&
        M11_Font_ResolvedGraphicIndex(sourceFont) != M11_FONT_GRAPHIC_INDEX_LEGACY) {
        return 0;
    }
    inventory = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                     DM1_V1_F0355_C017_INVENTORY_PC34);
    slot = M11_AssetLoader_Load((M11_AssetLoader*)&state->assetLoader,
                                DM1_V1_F0355_C033_SLOT_PC34);
    if (!inventory || !slot || !inventory->loaded || !slot->loaded ||
        !inventory->pixels || !slot->pixels) return 0;
    memset(surfaces, 0, sizeof(surfaces));
    memset(&glyph, 0, sizeof(glyph));
    surfaces[0].graphicsDatOwned = 1;
    surfaces[0].graphicIndex = (int)inventory->graphicIndex;
    surfaces[0].width = (int)inventory->width;
    surfaces[0].height = (int)inventory->height;
    surfaces[0].indexedPixelCount = surfaces[0].width * surfaces[0].height;
    surfaces[0].indexedPixels = inventory->pixels;
    surfaces[0].pixelsFNV1a = dm1_v1_f0355_inventory_material_fnv1a_pc34(
        inventory->pixels, surfaces[0].indexedPixelCount);
    surfaces[1].graphicsDatOwned = 1;
    surfaces[1].graphicIndex = (int)slot->graphicIndex;
    surfaces[1].width = (int)slot->width;
    surfaces[1].height = (int)slot->height;
    surfaces[1].indexedPixelCount = surfaces[1].width * surfaces[1].height;
    surfaces[1].indexedPixels = slot->pixels;
    surfaces[1].pixelsFNV1a = dm1_v1_f0355_inventory_material_fnv1a_pc34(
        slot->pixels, surfaces[1].indexedPixelCount);
    glyph.graphicsDatOwned = 1;
    glyph.graphicIndex = M11_Font_ResolvedGraphicIndex(sourceFont);
    glyph.bits = sourceFont->bitmap;
    glyph.byteCount = M11_FONT_BITMAP_BYTES;
    glyph.bitsFNV1a = dm1_v1_f0355_inventory_material_fnv1a_pc34(
        glyph.bits, glyph.byteCount);
    return surfaces[0].pixelsFNV1a && surfaces[1].pixelsFNV1a &&
           glyph.bitsFNV1a &&
           dm1_v1_f0355_inventory_material_receipt_pc34(
               surfaces, 2, &glyph, 1, &receipt) && receipt.valid &&
           receipt.suppressSyntheticFallback &&
           receipt.inventoryGraphicIndex == (int)inventory->graphicIndex &&
           receipt.slotGraphicIndex == (int)slot->graphicIndex &&
           receipt.m653GraphicIndex == glyph.graphicIndex;
}

static void m11_draw_inventory_panel(const M11_GameViewState* state,
                                    unsigned char* framebuffer,
                                    int framebufferWidth,
                                    int framebufferHeight) {
    /* Normal V1 inventory replaces the source viewport with C017.
     * Keep the old expansive Firestaff workbench layout only when the
     * debug HUD is explicitly enabled. */
    int panelX = state && state->showDebugHUD ? 8 : M11_VIEWPORT_X;
    int panelY = state && state->showDebugHUD ? 8 : M11_VIEWPORT_Y;
    int panelW = state && state->showDebugHUD ? framebufferWidth - 16 : M11_VIEWPORT_W;
    int panelH = state && state->showDebugHUD ? framebufferHeight - 16 : M11_VIEWPORT_H;
    const struct ChampionState_Compat* champ;
    char champion[32];
    int isDead;
    int bpI;

    /* Portrait proportions from ReDMCSB: 32×29 pixels */
    static const int PORT_W = 32;
    static const int PORT_H = 29;
    /* Slot box size: 18×18 when using original GRAPHICS.DAT assets,
     * 16×16 as procedural fallback. */
    int SZ = 16;
    static const int GAP = 2; /* spacing between adjacent slot boxes */

    /* Layout anchors */
    int portX, portY;   /* portrait position */
    int nameX, nameY;   /* champion name */
    int handY;          /* hands row Y */
    int handLX, handRX; /* hand slot X positions */
    int bodyX, bodyY;   /* body column anchor (Head at top) */
    int contX, contY;   /* container section anchor */
    int bpX, bpY;       /* backpack grid anchor */
    int panelBottom;    /* bottom info panel Y */

    if (!state || !state->active) return;
    /* PANEL.C F0355 publishes C017 before any inventory slot or panel
     * overlay. For normal DM1, a missing raw C017/C033/M653 receipt leaves
     * the viewport untouched rather than reconstructing inventory chrome. */
    if (!state->showDebugHUD && m11_is_dm1_source_kind(state->sourceKind) &&
        !m11_dm1_v1_f0355_inventory_material_ready(state)) return;
    if (state->world.party.activeChampionIndex < 0 ||
        state->world.party.activeChampionIndex >= CHAMPION_MAX_PARTY) return;
    champ = &state->world.party.champions[state->world.party.activeChampionIndex];
    isDead = (champ->hp.current == 0);

    /* Use 18×18 slot boxes when GRAPHICS.DAT assets are available */
    if (state->assetsAvailable) {
        const M11_AssetSlot* testBox = M11_AssetLoader_Load(
            (M11_AssetLoader*)&state->assetLoader,
            (unsigned int)dm1_v1_graphic_slot_box_normal_pc34());
        if (testBox && testBox->loaded && testBox->pixels &&
            testBox->width == 18 && testBox->height == 18)
            SZ = 18;
    }

    /* ── Panel background. Normal V1 uses C017 as a viewport-sized
     * replacement backdrop. Debug mode keeps the older scaled C020
     * workbench panel for diagnostics. ── */
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  panelX, panelY, panelW, panelH, M11_COLOR_BLACK);
    if (state->assetsAvailable) {
        const M11_AssetSlot* panelBg = M11_AssetLoader_Load(
            (M11_AssetLoader*)&state->assetLoader,
            (unsigned int)(state->showDebugHUD
                ? dm1_v1_graphic_panel_empty_pc34()
                : dm1_v1_graphic_inventory_backdrop_pc34()));
        if (!state->showDebugHUD) {
            if (panelBg &&
                DM1_ChampionPanel_AssetSurfaceAccepted(
                    dm1_v1_graphic_inventory_backdrop_pc34(),
                    dm1_v1_graphic_inventory_backdrop_pc34(),
                    panelBg->loaded, panelBg->pixels != NULL,
                    panelBg->width, panelBg->height,
                    M11_VIEWPORT_W, M11_VIEWPORT_H)) {
                M11_AssetLoader_Blit(panelBg, framebuffer, framebufferWidth,
                                     framebufferHeight, panelX, panelY, 0);
            }
        } else if (panelBg && panelBg->loaded && panelBg->pixels &&
                   panelBg->width > 0 && panelBg->height > 0) {
                M11_AssetLoader_BlitScaled(panelBg,
                    framebuffer, framebufferWidth, framebufferHeight,
                    panelX, panelY, panelW, panelH, 0);
        }
    }

    if (!state->showDebugHUD && state->candidateMirrorPanelActive) {
        int zx = 0, zy = 0, zw = 0, zh = 0;
        int drewPanel = 0;
        {
            DM1_V1_LayoutZoneRectPc34 panelRect =
                dm1_v1_inventory_panel_rect_pc34();
            zx = panelRect.x;
            zy = panelRect.y;
            zw = panelRect.w;
            zh = panelRect.h;
        }
        if (dm1_v1_inventory_panel_zone_id_pc34() && state->assetsAvailable) {
            const M11_AssetSlot* rrPanel = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)(state->candidateMirrorRenameActive
                    ? M11_GFX_PANEL_RENAME_CHAMPION
                    : M11_GFX_PANEL_RESURRECT_REINCARNATE));
            if (rrPanel && rrPanel->loaded && rrPanel->pixels &&
                rrPanel->width == zw && rrPanel->height == zh) {
                M11_AssetLoader_Blit(rrPanel, framebuffer, framebufferWidth,
                                     framebufferHeight,
                                     M11_VIEWPORT_X + zx,
                                     M11_VIEWPORT_Y + zy, 6);
                drewPanel = 1;
            }
        }
        /* ReDMCSB REVIVE.C F0281 draws C027 and F0282 draws C040. These
         * are original GRAPHICS.DAT panels, not host UI layouts: when the
         * exact panel cannot be loaded, keep the already-cleared C017
         * viewport and fail closed. Do not replace it with host art/text. */
        if (!drewPanel) {
            return;
        }
        if (state->candidateMirrorRenameActive) {
            /* C027 alone is valid when M653 cannot be proven.  Do not use
             * host text or guessed coordinates as a substitute. */
            (void)m11_draw_dm1_hoc_rename_pc34_text(
                state, framebuffer, framebufferWidth, framebufferHeight);
        }
        return;
    }

    if (state->showDebugHUD) {
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      panelX, panelY, panelW, panelH, M11_COLOR_BROWN);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      panelX + 1, panelY + 1, panelW - 2, panelH - 2, M11_COLOR_DARK_GRAY);
    } else {
        /* Normal V1 dynamic overlay phase: draw every Firestaff-modeled
         * champion inventory object into the source slot-box namespace.
         * This keeps placement anchored to layout-696 C507..C536 instead
         * of the older freehand workbench/debug layout.  The runtime model
         * now carries all 30 DM1 champion inventory slots, including the
         * full C520..C536 backpack namespace. */
        int sourceSlotBox;
        int slotIdx;

        for (sourceSlotBox = 8; sourceSlotBox <= 37; ++sourceSlotBox) {
            DM1_V1_InventorySlotBoxZonePc34 zone;
            int zx = 0, zy = 0;
            int f31_profile = state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
                m11_csb_is_fmtowns_profile((const CSB_V1_BootProfile *)
                                            state->csbBootProfile);
            int f31_slot = m11_csb_fmtowns_inventory_slot_rectangle(
                state, sourceSlotBox, &zx, &zy, NULL, NULL);
            int slotBoxGraphic = dm1_v1_graphic_slot_box_normal_pc34();
            memset(&zone, 0, sizeof(zone));
            if (!slotBoxGraphic || (f31_profile && !f31_slot) || (!f31_slot &&
                !dm1_v1_inventory_source_slot_box_zone_pc34(
                    sourceSlotBox, &zone))) {
                continue;
            }
            if (!f31_slot) { zx = zone.x; zy = zone.y; }
            if (state->assetsAvailable) {
                const M11_AssetSlot* boxSlot = M11_AssetLoader_Load(
                    (M11_AssetLoader*)&state->assetLoader,
                    (unsigned int)slotBoxGraphic);
                if (boxSlot &&
                    DM1_ChampionPanel_AssetSurfaceAccepted(
                        slotBoxGraphic, slotBoxGraphic,
                        boxSlot->loaded, boxSlot->pixels != NULL,
                        boxSlot->width, boxSlot->height,
                        DM1_SLOT_BOX_SIZE, DM1_SLOT_BOX_SIZE)) {
                    M11_AssetLoader_Blit(boxSlot, framebuffer, framebufferWidth,
                                         framebufferHeight,
                                         M11_VIEWPORT_X + zx - 1,
                                         M11_VIEWPORT_Y + zy - 1, 0);
                }
            }
        }
        for (slotIdx = 0; slotIdx < CHAMPION_SLOT_COUNT; ++slotIdx) {
            unsigned short thingId = champ->inventory[slotIdx];
            int sourceSlotBox =
                dm1_v1_inventory_source_slot_box_for_champion_slot_pc34(slotIdx);
            if (!sourceSlotBox) continue;
            if (thingId != THING_NONE && thingId != THING_ENDOFLIST &&
                state->assetsAvailable &&
                (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT ||
                 state->world.things)) {
                DM1_V1_InventorySlotBoxZonePc34 zone;
                int iconIndex = m11_v1_inventory_slot_icon_index_for_thing(
                    state, slotIdx, thingId);
                int zx = 0, zy = 0;
                int f31_profile = state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
                    m11_csb_is_fmtowns_profile((const CSB_V1_BootProfile *)
                                                state->csbBootProfile);
                int f31_slot = m11_csb_fmtowns_inventory_slot_rectangle(
                    state, sourceSlotBox, &zx, &zy, NULL, NULL);
                memset(&zone, 0, sizeof(zone));
                if ((!f31_profile &&
                     dm1_v1_inventory_source_slot_box_zone_pc34(
                         sourceSlotBox, &zone)) || f31_slot) {
                    if (!f31_slot) { zx = zone.x; zy = zone.y; }
                    (void)m11_draw_dm_object_icon_index(
                        state, framebuffer, framebufferWidth, framebufferHeight,
                        iconIndex,
                        M11_VIEWPORT_X + zx,
                        M11_VIEWPORT_Y + zy,
                        0);
                }
            }
        }
        /* PANEL.C F0355 calls CHAMDRAW.C F0292 after its F0291 slot loop.
         * F0435 restored this exact 32x29 M516 bitmap from the save; it is
         * not interchangeable with the C026 recruit atlas.  The order is
         * observable because C509's box overlaps the portrait's lower edge.
         * Leave the C017 inset untouched when no saved portrait is valid. */
        (void)m11_draw_saved_champion_portrait_pc34(
            champ, framebuffer, framebufferWidth, framebufferHeight,
            M11_VIEWPORT_X + 5, M11_VIEWPORT_Y + 4);
        if (DM1_V1_M11Runtime_GetOpenChestThingPc34Compat(state) != THING_NONE) {
            unsigned short chestSlots[8];
            int chestOrdinal;
            int chestPanelX = 0, chestPanelY = 0, chestPanelW = 0, chestPanelH = 0;
            (void)m11_v1_read_open_chest_slots(state, chestSlots);
            {
                DM1_V1_LayoutZoneRectPc34 panelRect =
                    dm1_v1_inventory_panel_rect_pc34();
                chestPanelX = panelRect.x;
                chestPanelY = panelRect.y;
                chestPanelW = panelRect.w;
                chestPanelH = panelRect.h;
            }
            /* ReDMCSB PANEL.C:1132-1133 routes containers to CHEST.C F0333;
             * CHEST.C:43-48 opens G0426_T_OpenChest and blits C025 into
             * G0032/C101 before F0038 draws C537..C544 slot boxes. */
            if (state->assetsAvailable &&
                dm1_v1_inventory_panel_zone_id_pc34()) {
                const M11_AssetSlot* chestPanel = M11_AssetLoader_Load(
                    (M11_AssetLoader*)&state->assetLoader,
                    (unsigned int)M11_GFX_PANEL_OPEN_CHEST);
                if (chestPanel && chestPanel->loaded && chestPanel->pixels &&
                    chestPanel->width == (unsigned short)chestPanelW &&
                    chestPanel->height == (unsigned short)chestPanelH) {
                    M11_AssetLoader_Blit(chestPanel, framebuffer, framebufferWidth,
                                         framebufferHeight,
                                         M11_VIEWPORT_X + chestPanelX,
                                         M11_VIEWPORT_Y + chestPanelY, 8);
                }
            }
            for (chestOrdinal = 0; chestOrdinal < 8; ++chestOrdinal) {
                DM1_V1_InventorySlotBoxZonePc34 zone;
                int zx = 0, zy = 0;
                memset(&zone, 0, sizeof(zone));
                if (!dm1_v1_inventory_chest_slot_box_zone_pc34(
                        chestOrdinal, &zone)) {
                    continue;
                }
                zx = zone.x;
                zy = zone.y;
                if (state->assetsAvailable) {
                    const M11_AssetSlot* boxSlot = M11_AssetLoader_Load(
                        (M11_AssetLoader*)&state->assetLoader,
                        (unsigned int)dm1_v1_graphic_slot_box_normal_pc34());
                    if (boxSlot &&
                        DM1_ChampionPanel_AssetSurfaceAccepted(
                            dm1_v1_graphic_slot_box_normal_pc34(),
                            dm1_v1_graphic_slot_box_normal_pc34(),
                            boxSlot->loaded, boxSlot->pixels != NULL,
                            boxSlot->width, boxSlot->height,
                            DM1_SLOT_BOX_SIZE, DM1_SLOT_BOX_SIZE)) {
                        M11_AssetLoader_Blit(boxSlot, framebuffer, framebufferWidth,
                                             framebufferHeight,
                                             M11_VIEWPORT_X + zx - 1,
                                             M11_VIEWPORT_Y + zy - 1, 0);
                    }
                }
                if (chestSlots[chestOrdinal] != THING_NONE &&
                    chestSlots[chestOrdinal] != THING_ENDOFLIST &&
                    state->assetsAvailable &&
                    (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT ||
                     state->world.things)) {
                    int iconIndex = m11_object_icon_index_for_thing(
                        state, state->world.things, chestSlots[chestOrdinal]);
                    (void)m11_draw_dm_object_icon_index(
                        state, framebuffer, framebufferWidth, framebufferHeight,
                        iconIndex, M11_VIEWPORT_X + zx, M11_VIEWPORT_Y + zy, 0);
                }
            }
            (void)m11_draw_v1_inventory_panel_arrow_or_eye(
                state, framebuffer, framebufferWidth, framebufferHeight,
                state->v1OpenChestOpenedByEye);
        }
        if (m11_draw_v1_inventory_food_water_panel(
                state, framebuffer, framebufferWidth, framebufferHeight)) {
            return;
        }
        if (m11_draw_v1_inventory_object_description_panel(
                state, framebuffer, framebufferWidth, framebufferHeight)) {
            /* F0342's normal object route reaches F0339 with
             * P0707_B_PressingEye set. The eye indicator must use C019 from
             * the same verified GRAPHICS.DAT session as the panel. */
            (void)m11_draw_v1_inventory_panel_arrow_or_eye(
                state, framebuffer, framebufferWidth, framebufferHeight, 1);
            return;
        }
        if (m11_draw_v1_inventory_champion_stats_panel(
                state, framebuffer, framebufferWidth, framebufferHeight)) {
            return;
        }
        (void)m11_draw_v1_inventory_action_hand_scroll_panel(
            state, framebuffer, framebufferWidth, framebufferHeight);
        (void)m11_draw_v1_mouth_visual_frame(
            state, framebuffer, framebufferWidth, framebufferHeight);
        /* C017/F0355 and the source slot-box namespace above own the normal
         * PC34 inventory page.  The legacy freehand workbench below was
         * written for the debug HUD and overpainted C017 with differently
         * sized slots, labels and bars.  That made a clicked champion's
         * inventory visibly diverge from ReDMCSB.  Keep that layout solely
         * for debug HUD; the normal V1 page must stop after its source-backed
         * panel layers. */
        return;
    }

    /* ── Champion identity ── portrait + name + stat bars */
    portX = panelX + 5;
    portY = panelY + 4;
    m11_get_active_champion_label(state, champion, sizeof(champion));

    /* Portrait box — GRAPHICS.DAT champion portrait (graphic 26,
     * C026_GRAPHIC_CHAMPION_PORTRAITS, 256×87 strip of 32×29 portraits).
     * M027_PORTRAIT_X(index) = (index & 7) * 32
     * M028_PORTRAIT_Y(index) = (index >> 3) * 29
     * Falls back to small icon (graphic 28) or silhouette. */
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  portX, portY, PORT_W, PORT_H, M11_COLOR_DARK_GRAY);
    m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                  portX, portY, PORT_W, PORT_H,
                  isDead ? M11_COLOR_RED : M11_COLOR_LIGHT_CYAN);
    {
        int drewPortrait = m11_draw_saved_champion_portrait_pc34(
            champ, framebuffer, framebufferWidth, framebufferHeight, portX, portY);
        if (!drewPortrait && state->assetsAvailable) {
            /* Try full 32×29 portrait from graphic 26 first */
            const M11_AssetSlot* portraits = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)dm1_v1_graphic_champion_portraits_pc34());
            if (portraits && portraits->loaded && portraits->pixels &&
                portraits->width >= 256 && portraits->height >= 29) {
                int pIdx = champ->portraitIndex & 0x1F; /* 0–23 range */
                int srcPX = (pIdx & 7) * M11_PORTRAIT_W;
                int srcPY = (pIdx >> 3) * M11_PORTRAIT_H;
                if (srcPX + M11_PORTRAIT_W <= (int)portraits->width &&
                    srcPY + M11_PORTRAIT_H <= (int)portraits->height) {
                    M11_AssetLoader_BlitRegion(portraits,
                        srcPX, srcPY, M11_PORTRAIT_W, M11_PORTRAIT_H,
                        framebuffer, framebufferWidth, framebufferHeight,
                        portX, portY, 0);
                    drewPortrait = 1;
                }
            }
            /* Fallback: small icon from graphic 28 */
            if (!drewPortrait) {
                const M11_AssetSlot* iconStrip = M11_AssetLoader_Load(
                    (M11_AssetLoader*)&state->assetLoader,
                    (unsigned int)dm1_v1_graphic_champion_icons_pc34());
                if (iconStrip && iconStrip->loaded && iconStrip->pixels &&
                    iconStrip->width > 0 && iconStrip->height > 0) {
                    int iconCol = champ->portraitIndex & 3;
                    int srcX = iconCol * M11_CHAMPION_ICON_W;
                    if (srcX + M11_CHAMPION_ICON_W <= (int)iconStrip->width) {
                        M11_AssetLoader_BlitRegion(iconStrip,
                            srcX, 0, M11_CHAMPION_ICON_W, M11_CHAMPION_ICON_H,
                            framebuffer, framebufferWidth, framebufferHeight,
                            portX + 1, portY + 1, 0);
                        drewPortrait = 1;
                    }
                }
            }
        }
        if (!drewPortrait && (m11_is_dm1_source_kind(state->sourceKind) ||
                             m11_source_is_csb(state))) {
            /* ReDMCSB C026 or LOADSAVE.C M516 portrait pixels are the only
             * valid DM1/CSB portrait owners.  A missing source portrait is
             * an asset failure, not permission to paint a host silhouette. */
            return;
        }
        if (!drewPortrait) {
            /* Diagnostic fallback for non-source fixtures only. */
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          portX + 9,  portY + 8, 3, 3, M11_COLOR_WHITE);
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          portX + 20, portY + 8, 3, 3, M11_COLOR_WHITE);
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          portX + 10, portY + 19, 12, 2,
                          isDead ? M11_COLOR_RED : M11_COLOR_LIGHT_GRAY);
        }
    }

    /* Champion name — prominent, right of portrait */
    nameX = portX + PORT_W + 6;
    nameY = portY + 2;
    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                  nameX, nameY, champion, &g_text_title);

    if (isDead) {
        M11_TextStyle deadStyle = g_text_small;
        deadStyle.color = M11_COLOR_RED;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      nameX, nameY + 14,
                      m11_translate_for_state(state, "DEAD"), &deadStyle);
    }

    /* Stat bars — compact DM-style HP/STA/MANA right of portrait */
    {
        int barX = nameX;
        int barY = nameY + (isDead ? 22 : 14);
        int barMaxW = 80;
        int barH = 3;
        int hpW = champ->hp.maximum > 0
            ? (int)(champ->hp.current * barMaxW) / (int)champ->hp.maximum : 0;
        int staW = champ->stamina.maximum > 0
            ? (int)(champ->stamina.current * barMaxW) / (int)champ->stamina.maximum : 0;
        int manaW = champ->mana.maximum > 0
            ? (int)(champ->mana.current * barMaxW) / (int)champ->mana.maximum : 0;

        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      barX, barY, barMaxW, barH, M11_COLOR_DARK_GRAY);
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      barX, barY, hpW, barH,
                      isDead ? M11_COLOR_DARK_GRAY : M11_COLOR_LIGHT_RED);

        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      barX, barY + barH + 1, barMaxW, barH, M11_COLOR_DARK_GRAY);
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      barX, barY + barH + 1, staW, barH, M11_COLOR_LIGHT_GREEN);

        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      barX, barY + 2 * (barH + 1), barMaxW, barH, M11_COLOR_DARK_GRAY);
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      barX, barY + 2 * (barH + 1), manaW, barH, M11_COLOR_LIGHT_BLUE);
    }

    /* ── Hands row — ReDMCSB places Ready Hand + Action Hand as the
     * first two slots, prominently above the body equipment column.
     * In the original, these are the primary interaction slots. ── */
    handY = portY + PORT_H + 4;
    handLX = panelX + 5;
    handRX = handLX + SZ + GAP;

    /* Thin section label */
    {
        M11_TextStyle hlbl = g_text_small;
        hlbl.color = M11_COLOR_BROWN;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      handLX, handY - 1, "HANDS", &hlbl);
    }
    handY += 7;
    m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                      handLX, handY, CHAMPION_SLOT_HAND_LEFT, "L");
    m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                      handRX, handY, CHAMPION_SLOT_HAND_RIGHT, "R");

    /* ── Body column — Head → Neck → Torso → Legs → Feet ──
     * Vertical column to the right of hands, matching ReDMCSB’s
     * equipment slot arrangement.  Each slot is a 16×16 icon box. */
    bodyX = handRX + SZ + 10;
    bodyY = handY;
    {
        static const int bodySlots[5] = {
            CHAMPION_SLOT_HEAD, CHAMPION_SLOT_NECK, CHAMPION_SLOT_TORSO,
            CHAMPION_SLOT_LEGS, CHAMPION_SLOT_FEET
        };
        static const char* bodyLabels[5] = { "Hd", "Nk", "To", "Lg", "Ft" };
        int bi;
        M11_TextStyle blbl = g_text_small;
        blbl.color = M11_COLOR_BROWN;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      bodyX, handY - 8, "BODY", &blbl);
        for (bi = 0; bi < 5; ++bi) {
            m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                              bodyX, bodyY + bi * (SZ + GAP),
                              bodySlots[bi], bodyLabels[bi]);
        }
    }

    /* ── Container region: Pouches + Quiver ──
     * Positioned to the right of the body column, matching the
     * original’s right-side container layout. */
    contX = bodyX + SZ + 10;
    contY = handY;
    {
        M11_TextStyle clbl = g_text_small;
        clbl.color = M11_COLOR_BROWN;

        /* Pouches (2 slots side by side) */
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      contX, contY - 1, "POUCH", &clbl);
        contY += 7;
        m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                          contX, contY, CHAMPION_SLOT_POUCH_1, "1");
        m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                          contX + SZ + GAP, contY, CHAMPION_SLOT_POUCH_2, "2");

        /* Quiver (4 slots in a row) */
        contY += SZ + GAP + 4;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      contX, contY, "QUIVER", &clbl);
        contY += 8;
        m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                          contX, contY, CHAMPION_SLOT_QUIVER_1, "1");
        m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                          contX + (SZ + GAP), contY, CHAMPION_SLOT_QUIVER_2, "2");
        m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                          contX + 2 * (SZ + GAP), contY, CHAMPION_SLOT_QUIVER_3, "3");
        m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                          contX + 3 * (SZ + GAP), contY, CHAMPION_SLOT_QUIVER_4, "4");
    }

    /* ── Backpack grid — 4×2, the largest container section ──
     * ReDMCSB: BACKPACK slots 13–20, drawn as 4-wide × 2-tall grid
     * at the bottom of the equipment area. */
    bpX = panelX + 5;
    bpY = handY + 5 * (SZ + GAP) + 6;
    m11_draw_hline(framebuffer, framebufferWidth, framebufferHeight,
                   panelX + 3, bpY - 3, panelW - 6, M11_COLOR_DARK_GRAY);
    {
        M11_TextStyle plbl = g_text_small;
        plbl.color = M11_COLOR_BROWN;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      bpX, bpY, "BACKPACK", &plbl);
    }
    bpY += 8;
    for (bpI = 0; bpI < 8; ++bpI) {
        int col = bpI % 4;
        int row = bpI / 4;
        char bpLabel[4];
        snprintf(bpLabel, sizeof(bpLabel), "%d", bpI + 1);
        m11_draw_inv_slot(state, champ, framebuffer, framebufferWidth, framebufferHeight,
                          bpX + col * (SZ + GAP),
                          bpY + row * (SZ + GAP),
                          CHAMPION_SLOT_BACKPACK_1 + bpI, bpLabel);
    }

    /* ── Bottom panel area — food/water status (ReDMCSB: G424_i_PanelContent) ── */
    panelBottom = bpY + 2 * (SZ + GAP) + 4;
    m11_draw_hline(framebuffer, framebufferWidth, framebufferHeight,
                   panelX + 3, panelBottom - 2, panelW - 6, M11_COLOR_DARK_GRAY);
    {
        int avgFood = (int)champ->food;
        int avgWater = (int)champ->water;
        int labelDrawn = 0;
        int fwX = panelX + 5;
        int fwY = panelBottom;

        /* GRAPHICS.DAT-backed food/water labels (graphics 30, 31).
         * Food label: 34×9, Water label: 46×9.  ReDMCSB PANEL.C owns
         * these bitmap labels; an authenticated DM1 page must not replace
         * them with host text when either source record is unavailable. */
        if (state->assetsAvailable) {
            const M11_AssetSlot* foodLbl = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)dm1_v1_graphic_food_label_pc34());
            const M11_AssetSlot* waterLbl = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)dm1_v1_graphic_water_label_pc34());
            if (foodLbl && foodLbl->loaded && foodLbl->pixels &&
                foodLbl->width > 0 && foodLbl->height > 0 &&
                waterLbl && waterLbl->loaded && waterLbl->pixels &&
                waterLbl->width > 0 && waterLbl->height > 0) {
                char numBuf[8];
                M11_TextStyle fwNumStyle = g_text_small;
                fwNumStyle.color = M11_COLOR_LIGHT_GRAY;
                M11_AssetLoader_BlitRegion(foodLbl,
                    0, 0, (int)foodLbl->width, (int)foodLbl->height,
                    framebuffer, framebufferWidth, framebufferHeight,
                    fwX, fwY, 0);
                snprintf(numBuf, sizeof(numBuf), "%d", avgFood > 999 ? 999 : avgFood);
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              fwX + (int)foodLbl->width + 2, fwY, numBuf, &fwNumStyle);
                fwX += (int)foodLbl->width + 30;
                M11_AssetLoader_BlitRegion(waterLbl,
                    0, 0, (int)waterLbl->width, (int)waterLbl->height,
                    framebuffer, framebufferWidth, framebufferHeight,
                    fwX, fwY, 0);
                snprintf(numBuf, sizeof(numBuf), "%d", avgWater > 999 ? 999 : avgWater);
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              fwX + (int)waterLbl->width + 2, fwY, numBuf, &fwNumStyle);
                labelDrawn = 1;
            }
        }
        if (!labelDrawn && !m11_is_dm1_source_kind(state->sourceKind)) {
            char foodWater[48];
            M11_TextStyle fwStyle = g_text_small;
            fwStyle.color = M11_COLOR_LIGHT_GRAY;
            snprintf(foodWater, sizeof(foodWater), "FOOD %d  WATER %d",
                     avgFood > 999 ? 999 : avgFood,
                     avgWater > 999 ? 999 : avgWater);
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          fwX, fwY, foodWater, &fwStyle);
        }
    }

    /* ── Inventory damage overlay: GRAPHICS.DAT graphic 16 (32×29) ── */
    /* In DM1, when the inventory view is open and the active champion
     * takes damage, graphic 16 ("damage to champion big", 32×29) is
     * drawn on the portrait area instead of graphic 15 (small).
     * Ref: ReDMCSB CHAMPION.C F0291 — G0423_i_InventoryChampionOrdinal. */
    {
        int activeSlot = state->world.party.activeChampionIndex;
        if (activeSlot >= 0 && activeSlot < 4 &&
            state->championDamageTimer[activeSlot] > 0) {
            int dmgDrawn = 0;
            if (state->assetsAvailable) {
                const M11_AssetSlot* dmg16 = M11_AssetLoader_Load(
                    (M11_AssetLoader*)&state->assetLoader,
                    (unsigned int)dm1_v1_graphic_champion_damage_big_pc34());
                if (dmg16 && dmg16->loaded && dmg16->pixels &&
                    dmg16->width == 32 && dmg16->height == 29) {
                    M11_AssetLoader_BlitRegion(dmg16,
                        0, 0, 32, 29,
                        framebuffer, framebufferWidth, framebufferHeight,
                        portX, portY, M11_COLOR_FLESH);
                    dmgDrawn = 1;
                }
            }
            if (!dmgDrawn && !m11_is_dm1_source_kind(state->sourceKind)) {
                /* Non-source diagnostic sessions may retain the old visual
                 * cue, but an authenticated DM1 page must never replace
                 * ReDMCSB C016 with a host-colour rectangle. */
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              portX, portY, PORT_W, PORT_H, M11_COLOR_LIGHT_RED);
            }
            /* C016 owns both the portrait damage surface and its number in
             * a source DM1 inventory frame.  Do not leak a host-drawn number
             * when the original bitmap is unavailable. */
            if (dmgDrawn || !m11_is_dm1_source_kind(state->sourceKind)) {
                char dmgNum[8];
                M11_TextStyle dmgStyle = g_text_small;
                dmgStyle.color = M11_COLOR_WHITE;
                snprintf(dmgNum, sizeof(dmgNum), "%d",
                         state->championDamageAmount[activeSlot]);
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              portX + PORT_W / 2 - 4,
                              portY + PORT_H / 2 - 3,
                              dmgNum, &dmgStyle);
            }
        }
    }

    /* Footer — key hints are debug-only. The original inventory panel
     * does not put helper text at the bottom edge; it relies on the
     * player knowing the controls. In V1 we honour that. */
    if (state->showDebugHUD) {
        M11_TextStyle footStyle = g_text_small;
        footStyle.color = M11_COLOR_DARK_GRAY;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      panelX + 5, panelY + panelH - 10,
                      "I CLOSE  TAB CHAMPION", &footStyle);
    }
}

static void m11_clear_csb_v1_message_area_source_owned(
    const M11_GameViewState* state,
    unsigned char* framebuffer,
    int framebufferWidth,
    int framebufferHeight)
{
    DM1_V1_LayoutZoneRectPc34 messageRect;
    const CSB_V1_BootProfile *boot_profile;
    const CSB_V1_RuntimeTextMessageReceipt *receipt;
    int message_width;

    if (!state || !framebuffer || state->showDebugHUD ||
        state->sourceKind != M11_GAME_SOURCE_CSB_BOOT ||
        !m11_v1_chrome_mode_enabled(state) || m11_v2_vertical_slice_enabled(state) ||
        !dm1_v1_message_area_zone_id_pc34()) {
        return;
    }
    /* TEXT.C F0049 clears C015 before a source-owned TextString message is
     * printed. M11's messageLog is host telemetry, not CSB GAMEBLOCK/TEXT
     * state, so it must not become visible game text. */
    messageRect = dm1_v1_message_area_rect_pc34();
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  messageRect.x, messageRect.y,
                  messageRect.w, messageRect.h, M11_COLOR_BLACK);

    /* CSBWin Timer.cpp::ProcessTT_OPENROOM queues a newly visible DB2 on the
     * party square through QuePrintLines.  The runtime receipt contains only
     * F0168-decoded bytes from that exact DUNGEON.DAT record.  Do not consult
     * M11's host log and do not use its generic text fallback: absent source
     * bytes or the original C015 font leaves the area black. */
    boot_profile = (const CSB_V1_BootProfile *)state->csbBootProfile;
    receipt = boot_profile ? &boot_profile->runtime.csbwin_text_message_receipt
                           : NULL;
    if (!receipt ||
        !csb_v1_runtime_text_message_active_pc34(&boot_profile->runtime) ||
        !g_activeOriginalFont || !M11_Font_IsLoaded(g_activeOriginalFont)) {
        return;
    }
    {
        const char* presented = fs_po_gettext_in_domain("csb", receipt->text);
        message_width = (int)m11_count_visible_glyphs_utf8(presented) *
                        DM1_V1_TEXT_CHARACTER_WIDTH;
        if (message_width < 1 || message_width > messageRect.w) return;
        (void)m11_draw_original_font_utf8_presentation(
            g_activeOriginalFont, framebuffer,
            framebufferWidth, framebufferHeight,
            messageRect.x, messageRect.y,
            presented, M11_COLOR_WHITE);
    }
}

static void m11_draw_v1_message_area(const M11_GameViewState* state,
                                     unsigned char* framebuffer,
                                     int framebufferWidth,
                                     int framebufferHeight) {
    const char* texts[M11_MESSAGE_LOG_CAPACITY];
    int colors[M11_MESSAGE_LOG_CAPACITY];
    DM1_V1_MessageRenderPlanPc34Compat plan;
    int messageX, messageY, messageW, messageH;
    DM1_V1_LayoutZoneRectPc34 messageRect;
    int reverseIndex;
    int row;
    int savedFontScaleOverride;

    if (!state || !framebuffer || state->showDebugHUD) {
        return;
    }
    /* The CSB HUD pass publishes its F0168-decoded C02/DSA receipt through
     * the source-owned C015 renderer.  This final main-draw call used to
     * clear that result and replace it with M11 telemetry.  Re-run the same
     * source consumer here and stop: CSB GAMEBLOCK text, never the host log,
     * owns the final presented message area. */
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        m11_clear_csb_v1_message_area_source_owned(
            state, framebuffer, framebufferWidth, framebufferHeight);
        return;
    }
    /* V2.x changes presentation, not TEXT.C ownership. Only the legacy
     * non-DM1 log renderer remains limited to the V1 chrome path. */
    if (!m11_is_dm1_source_kind(state->sourceKind) &&
        (!m11_v1_chrome_mode_enabled(state) ||
         m11_v2_vertical_slice_enabled(state))) {
        return;
    }
    if (!dm1_v1_message_area_zone_id_pc34()) {
        return;
    }
    messageRect = dm1_v1_message_area_rect_pc34();
    messageX = messageRect.x;
    messageY = messageRect.y;
    messageW = messageRect.w;
    messageH = messageRect.h;

    /* ReDMCSB TEXT.C owns C015_ZONE_MESSAGE_AREA as a full-width black
     * scrolling text surface: C014 is the 320x27 bottom container,
     * C015 is bottom-anchored at y=199, DEFS.H sets
     * M532_MESSAGE_AREA_ROW_COUNT=4 for PC media, COORD.C sets
     * G2088_C7_TextLineHeight=7 and G2092_MessageAreaWidth=320, and
     * F0049_TEXT_MESSAGEAREA_Clear fills C015 black before printing.  The
     * DM1 font is six visible pixels tall on a seven-pixel line; anchoring
     * rows at 173/180/187/194 keeps all four rows readable through y=199.
     * Keep Firestaff's synthetic telemetry filtered at this boundary; only
     * player-facing messages are drawn. */
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  messageX, messageY, messageW, messageH, M11_COLOR_BLACK);

    /* M11's DM1 messageLog is host telemetry and inspect/status scaffolding,
     * not the TEXT.C state that owns C015.  Showing a filtered subset still
     * leaks invented lines such as READY or INSPECT into the original game
     * surface.  CSB has its own source-bound receipt consumer below; DM1
     * deliberately stays blank until its decoded TEXT.C state is connected. */
    if (m11_is_dm1_source_kind(state->sourceKind)) {
        int sourceRow;
        /* TEXT.C's C015 rows and F0053 glyphs are one M653-owned source
         * operation.  A loaded 768-byte payload with another graphic
         * identity must leave the cleared message area untouched. */
        if (!m11_dm1_pc34_hud_font_is_source_bound(state)) {
            return;
        }
        for (sourceRow = 0;
             sourceRow < DM1_V1_MESSAGE_AREA_ROW_COUNT;
             ++sourceRow) {
            const DM1_V1_MessageRow* row = dm1_v1_text_get_row(
                &state->dm1V1TextMessage, sourceRow);
            if (!row || row->text[0] == '\0') {
                continue;
            }
            (void)m11_draw_original_font_utf8_presentation(
                g_activeOriginalFont, framebuffer,
                framebufferWidth, framebufferHeight,
                messageX,
                messageY + sourceRow * DM1_V1_TEXT_LINE_HEIGHT,
                row->text, (unsigned char)row->color);
        }
        return;
    }

    for (reverseIndex = 0; reverseIndex < state->messageLog.count; ++reverseIndex) {
        const M11_LogEntry* entry = m11_log_entry_at(&state->messageLog, reverseIndex);
        texts[reverseIndex] = entry ? entry->text : NULL;
        colors[reverseIndex] = entry ? (int)entry->color : 0;
    }
    DM1_V1_TextMessage_BuildLogRenderPlanPc34Compat(
        texts, colors, state->messageLog.count, &plan);

    savedFontScaleOverride = g_m11_font_scale_override;
    g_m11_font_scale_override = 0;
    for (row = 0; row < DM1_V1_MESSAGE_AREA_ROW_COUNT; ++row) {
        const char* text = plan.rows[row].text;
        M11_TextStyle style;
        char clipped[M11_MESSAGE_MAX_LENGTH];
        if (!text || text[0] == '\0') {
            continue;
        }
        style = g_text_small;
        style.color = (unsigned char)plan.rows[row].color;
        m11_copy_text_fitting_pixels(clipped, sizeof(clipped), text,
                                     messageW, &style);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      messageX,
                      messageY + row * plan.lineHeight + plan.textTopAdjust,
                      clipped,
                      &style);
    }
    g_m11_font_scale_override = savedFontScaleOverride;
}

static void m11_draw_map_panel(const M11_GameViewState* state,
                               unsigned char* framebuffer,
                               int framebufferWidth,
                               int framebufferHeight) {
    static const int radius = 2;
    static const int cell = 11;
    int cx;
    int cy;
    int gx;
    int gy;
    int baseX = 228;
    int baseY = 78;
    if (!state || !state->active) {
        return;
    }
    for (gy = -radius; gy <= radius; ++gy) {
        for (gx = -radius; gx <= radius; ++gx) {
            unsigned char square = 0;
            int drawX = baseX + (gx + radius) * cell;
            int drawY = baseY + (gy + radius) * cell;
            unsigned char fill = M11_COLOR_BLACK;
            int ok = m11_get_square_byte(&state->world,
                                         state->world.party.mapIndex,
                                         state->world.party.mapX + gx,
                                         state->world.party.mapY + gy,
                                         &square);
            if (ok) {
                fill = m11_tile_color(square >> 5);
                /* Dim unexplored cells */
                if (!m11_is_explored(state,
                                     state->world.party.mapX + gx,
                                     state->world.party.mapY + gy)) {
                    fill = M11_COLOR_NAVY;
                }
            }
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          drawX, drawY, cell - 1, cell - 1, fill);
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          drawX, drawY, cell - 1, cell - 1, M11_COLOR_BLACK);
            if (gx == 0 && gy == 0) {
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              drawX + 2, drawY + 2, cell - 5, cell - 5, M11_COLOR_LIGHT_GREEN);
                m11_draw_party_arrow(framebuffer, framebufferWidth, framebufferHeight,
                                     drawX + 2, drawY + 2, cell - 5,
                                     state->world.party.direction, M11_COLOR_BLACK);
            }
        }
    }
    cx = baseX + radius * cell;
    cy = baseY + radius * cell;
    m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                  cx - cell, cy - cell, cell * 3 - 1, cell * 3 - 1, M11_COLOR_YELLOW);
}

static void m11_theron_startup_layout_set_label(
    M11_TheronStartupElement* element,
    const char* label) {
    if (!element) return;
    snprintf(element->label,
             sizeof(element->label),
             "%s",
             label ? label : "");
}

static void m11_theron_startup_layout_set_rect(
    M11_TheronStartupElement* element,
    int x,
    int y,
    int w,
    int h) {
    if (!element) return;
    element->x = x;
    element->y = y;
    element->w = w;
    element->h = h;
}

static M11_TheronStartupElementKind m11_theron_startup_element_kind_from_layout(
    Theron_StartupLayoutElementKind kind) {

    switch (kind) {
    case THERON_STARTUP_LAYOUT_ELEMENT_TITLE:
        return M11_THERON_STARTUP_ELEMENT_TITLE;
    case THERON_STARTUP_LAYOUT_ELEMENT_CHAPTER:
        return M11_THERON_STARTUP_ELEMENT_CHAPTER;
    case THERON_STARTUP_LAYOUT_ELEMENT_CONTINUE:
        return M11_THERON_STARTUP_ELEMENT_CONTINUE;
    case THERON_STARTUP_LAYOUT_ELEMENT_STAGE:
        return M11_THERON_STARTUP_ELEMENT_STAGE;
    case THERON_STARTUP_LAYOUT_ELEMENT_MIRROR:
        return M11_THERON_STARTUP_ELEMENT_MIRROR;
    case THERON_STARTUP_LAYOUT_ELEMENT_FORCEFIELD:
        return M11_THERON_STARTUP_ELEMENT_FORCEFIELD;
    default:
        return M11_THERON_STARTUP_ELEMENT_TITLE;
    }
}

int M11_GameView_GetTheronStartupLayout(
    const M11_GameViewState* state,
    M11_TheronStartupElement* elements,
    int maxElements) {
    Theron_V1_BootStartupHostRenderReceipt host_render;
    int count;
    int i;

    if (!state || !elements || maxElements <= 0) {
        return 0;
    }
    if (state->sourceKind != M11_GAME_SOURCE_THERON_TRACK02) {
        return 0;
    }
    memset(elements, 0, (size_t)maxElements * sizeof(elements[0]));
    for (i = 0; i < maxElements; ++i) {
        elements[i].portraitIndex = -1;
        elements[i].primaryClass = -1;
    }

    if (!m11_theron_boot_runtime_startup_host_render_receipt(state,
                                                             NULL,
                                                             &host_render)) {
        return 0;
    }
    count = host_render.layout_count;
    if (count > maxElements) {
        count = maxElements;
    }
    for (i = 0; i < count; ++i) {
        const Theron_StartupLayoutElement* src = &host_render.layout[i];
        elements[i].kind =
            m11_theron_startup_element_kind_from_layout(src->kind);
        elements[i].phase = (int)src->phase;
        elements[i].cursor = src->cursor;
        elements[i].enabled = src->enabled;
        elements[i].selected = src->selected;
        elements[i].dungeonId = (int)src->dungeon_id;
        elements[i].mirrorIndex = src->mirror_index;
        elements[i].selectedOrder = src->selected_order;
        elements[i].portraitIndex = src->portrait_index;
        elements[i].primaryClass = src->primary_class;
        elements[i].saveKind = src->save_kind;
        elements[i].saveSlot = src->save_slot;
        m11_theron_startup_layout_set_label(&elements[i], src->label);
        snprintf(elements[i].decodedName,
                 sizeof(elements[i].decodedName),
                 "%s",
                 src->decoded_name);
        snprintf(elements[i].decodedTitle,
                 sizeof(elements[i].decodedTitle),
                 "%s",
                 src->decoded_title);
        m11_theron_startup_layout_set_rect(
            &elements[i], src->x, src->y, src->w, src->h);
    }
    return count;
}

int M11_GameView_GetTheronStartupRenderRows(
    const M11_GameViewState* state,
    char rows[][M11_THERON_STARTUP_RENDER_ROW_CAPACITY],
    int maxRows) {
    Theron_V1_BootStartupHostRenderReceipt host_render;
    int row_count;
    int i;

    if (!state || !rows || maxRows <= 0) {
        return 0;
    }
    if (state->sourceKind != M11_GAME_SOURCE_THERON_TRACK02) {
        return 0;
    }

    if (!m11_theron_boot_runtime_startup_host_render_receipt(state,
                                                             NULL,
                                                             &host_render)) {
        return 0;
    }
    row_count = host_render.row_count;
    if (row_count > maxRows) {
        row_count = maxRows;
    }
    memset(rows, 0,
           (size_t)maxRows * M11_THERON_STARTUP_RENDER_ROW_CAPACITY);
    for (i = 0; i < row_count; ++i) {
        snprintf(rows[i],
                 M11_THERON_STARTUP_RENDER_ROW_CAPACITY,
                 "%s",
                 host_render.rows[i]);
    }
    return row_count;
}

static void m11_theron_draw_font_tile_text(
    unsigned char *framebuffer, int fbw, int fbh,
    int x, int y, const char *text,
    const Theron_Track02FontTileReceipt *font,
    int color_index)
{
    int cx = x;
    const char *p;
    for (p = text; *p != '\0'; ++p) {
        unsigned char ch = (unsigned char)*p;
        if (ch < THERON_TRACK02_FONT_FIRST_CHAR ||
            ch >= THERON_TRACK02_FONT_FIRST_CHAR +
                  THERON_TRACK02_FONT_TILE_COUNT) {
            cx += (int)THERON_TRACK02_FONT_PIXEL_WIDTH;
            continue;
        }
        int tile_idx = ch - THERON_TRACK02_FONT_FIRST_CHAR;
        const uint8_t *pixels = font->pixels[tile_idx];
        int px, py;
        for (py = 0; py < (int)THERON_TRACK02_FONT_PIXEL_HEIGHT; ++py) {
            for (px = 0; px < (int)THERON_TRACK02_FONT_PIXEL_WIDTH; ++px) {
                if (pixels[py * THERON_TRACK02_FONT_PIXEL_WIDTH + px] != 0) {
                    int dx = cx + px;
                    int dy = y + py;
                    if (dx >= 0 && dx < fbw && dy >= 0 && dy < fbh) {
                        framebuffer[dy * fbw + dx] =
                            (unsigned char)color_index;
                    }
                }
            }
        }
        cx += (int)THERON_TRACK02_FONT_PIXEL_WIDTH;
    }
}

static const M11_TextStyle *m11_theron_startup_text_style(
    Theron_StartupRenderTextStyle style,
    M11_TextStyle *scratch)
{
    switch (style) {
    case THERON_STARTUP_RENDER_TEXT_TITLE:
        return &g_text_title;
    case THERON_STARTUP_RENDER_TEXT_SHADOW:
        return &g_text_shadow;
    case THERON_STARTUP_RENDER_TEXT_ACTIVE:
        if (scratch) {
            *scratch = g_text_shadow;
            scratch->color = M11_COLOR_YELLOW;
            return scratch;
        }
        return &g_text_shadow;
    case THERON_STARTUP_RENDER_TEXT_LOCKED:
        if (scratch) {
            *scratch = g_text_small;
            scratch->color = M11_COLOR_DARK_GRAY;
            return scratch;
        }
        return &g_text_small;
    case THERON_STARTUP_RENDER_TEXT_PICKED:
        if (scratch) {
            *scratch = g_text_shadow;
            scratch->color = M11_COLOR_LIGHT_GREEN;
            return scratch;
        }
        return &g_text_shadow;
    case THERON_STARTUP_RENDER_TEXT_SMALL:
    default:
        if (scratch) {
            *scratch = g_text_small;
            scratch->color = M11_COLOR_LIGHT_GRAY;
            return scratch;
        }
        return &g_text_small;
    }
}

typedef struct M11_TheronStartupGraphicContext {
    unsigned char *framebuffer;
    int framebufferWidth;
    int framebufferHeight;
} M11_TheronStartupGraphicContext;

static void m11_theron_startup_exec_fill_rect(
    void *userdata, int x, int y, int w, int h, int color)
{
    M11_TheronStartupGraphicContext *context =
        (M11_TheronStartupGraphicContext*)userdata;
    if (!context || !context->framebuffer) {
        return;
    }
    m11_fill_rect(context->framebuffer,
                  context->framebufferWidth,
                  context->framebufferHeight,
                  x,
                  y,
                  w,
                  h,
                  color);
}

static void m11_theron_startup_exec_draw_rect(
    void *userdata, int x, int y, int w, int h, int color)
{
    M11_TheronStartupGraphicContext *context =
        (M11_TheronStartupGraphicContext*)userdata;
    if (!context || !context->framebuffer) {
        return;
    }
    m11_draw_rect(context->framebuffer,
                  context->framebufferWidth,
                  context->framebufferHeight,
                  x,
                  y,
                  w,
                  h,
                  color);
}

static void m11_theron_startup_exec_plot_pixel(
    void *userdata, int x, int y, int color)
{
    M11_TheronStartupGraphicContext *context =
        (M11_TheronStartupGraphicContext*)userdata;
    if (!context || !context->framebuffer ||
        x < 0 || y < 0 ||
        x >= context->framebufferWidth ||
        y >= context->framebufferHeight) {
        return;
    }
    context->framebuffer[y * context->framebufferWidth + x] =
        (unsigned char)color;
}

static int m11_theron_draw_startup_graphics_from_receipt(
    const M11_GameViewState *state,
    unsigned char *framebuffer,
    int framebufferWidth,
    int framebufferHeight,
    Theron_V1_BootStartupUiCallerReceipt *out_receipt)
{
    M11_TheronStartupGraphicContext context;
    Theron_StartupGraphicExecutor executor;
    Theron_V1_BootStartupUiCallerReceipt receipt;

    if (!state || !framebuffer) {
        return 0;
    }
    context.framebuffer = framebuffer;
    context.framebufferWidth = framebufferWidth;
    context.framebufferHeight = framebufferHeight;
    executor.userdata = &context;
    executor.fill_rect = m11_theron_startup_exec_fill_rect;
    executor.draw_rect = m11_theron_startup_exec_draw_rect;
    executor.plot_pixel = m11_theron_startup_exec_plot_pixel;
    if (!m11_theron_boot_runtime_startup_ui_caller_receipt(
            state,
            &executor,
            &receipt)) {
        return 0;
    }
    if (out_receipt) {
        *out_receipt = receipt;
    }
    return receipt.host_render_valid &&
           receipt.host_render.graphics_route_valid &&
           !receipt.raw_graphics_plan_consumer_required;
}

static void m11_theron_draw_startup_screen(const M11_GameViewState* state,
                                           const Theron_V1_World* world,
                                           unsigned char* framebuffer,
                                           int framebufferWidth,
                                           int framebufferHeight) {
    Theron_V1_BootStartupHostRenderReceipt host_render;
    Theron_V1_BootStartupUiCallerReceipt ui_caller;
    int i;
    const Theron_StartupRenderPlan *plan;
    if (!state || !framebuffer) {
        return;
    }

    if (!m11_theron_boot_runtime_startup_ui_caller_receipt(state,
                                                           NULL,
                                                           &ui_caller) ||
        !ui_caller.host_render_valid ||
        !ui_caller.host_render.render_plan_valid) {
        return;
    }
    host_render = ui_caller.host_render;
    plan = &host_render.render_plan;

    if (world && world->runtime_media.startup_palette_valid) {
        uint8_t rgb6[256][3];
        memset(rgb6, 0, sizeof(rgb6));
        for (i = 0; i < 16; ++i) {
            rgb6[i][0] = world->runtime_media.startup_palette_rgb8[i][0] >> 2;
            rgb6[i][1] = world->runtime_media.startup_palette_rgb8[i][1] >> 2;
            rgb6[i][2] = world->runtime_media.startup_palette_rgb8[i][2] >> 2;
        }
        (void)M11_Render_SetIndexedPaletteRgb6(rgb6);
    }

    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  0, 0, framebufferWidth, framebufferHeight,
                  plan->background_color);

    if (world && world->runtime_media.startup_presentation_allowed &&
        world->runtime_media.startup_palette_valid &&
        state->theronState.startup_bitmap_atlas_ready) {
        const Theron_Track02StartupBitmapAtlas *atlas =
            &state->theronState.startup_bitmap_atlas;
        unsigned int phase_route = 0u;
        int ri;

        switch (plan->phase) {
        case THERON_STARTUP_PHASE_TITLE:
            phase_route = THERON_TRACK02_STARTUP_BITMAP_ROUTE_TITLE;
            break;
        case THERON_STARTUP_PHASE_STAGE_SELECT:
            phase_route = THERON_TRACK02_STARTUP_BITMAP_ROUTE_STAGE;
            break;
        case THERON_STARTUP_PHASE_SOUL_ROOM:
            phase_route = THERON_TRACK02_STARTUP_BITMAP_ROUTE_SOUL_ROOM;
            break;
        case THERON_STARTUP_PHASE_READY:
            phase_route = THERON_TRACK02_STARTUP_BITMAP_ROUTE_FORCEFIELD;
            break;
        default:
            break;
        }

        for (ri = 0; ri < (int)atlas->route_count; ++ri) {
            const Theron_Track02StartupBitmapAtlasRoute *route =
                &atlas->routes[ri];
            /* Routes are identified by their source-owned bit, not by the
             * order in which the decoder happened to append them.  The
             * atlas pixels use the fixed 256-pixel row stride from
             * THERON_TRACK02_STARTUP_BITMAP_ATLAS_MAX_WIDTH; a narrower
             * route therefore cannot be read as a tightly packed image. */
            if (route->route_bit != phase_route) continue;
            if (route->width > 0u && route->height > 0u) {
                int bx = (framebufferWidth - (int)route->width) / 2;
                int by = plan->border_y > 0 ? plan->border_y : 8;
                int px, py;
                for (py = 0; py < (int)route->height; ++py) {
                    for (px = 0; px < (int)route->width; ++px) {
                        uint8_t idx = route->pixels[
                            (size_t)py *
                                THERON_TRACK02_STARTUP_BITMAP_ATLAS_MAX_WIDTH +
                            (size_t)px];
                        if (idx > 0u) {
                            m11_put_pixel(framebuffer, framebufferWidth,
                                          framebufferHeight,
                                          bx + px, by + py, idx);
                        }
                    }
                }
            }
        }
    }

    (void)m11_theron_draw_startup_graphics_from_receipt(state,
                                                        framebuffer,
                                                        framebufferWidth,
                                                        framebufferHeight,
                                                        &ui_caller);
    /* Font tiles are authentic Track 02 bytes, but their screen coordinates,
     * palette ownership and command meaning are not yet bound to a captured
     * VDC/VCE consumer.  Do not let the host render plan turn those bytes into
     * a synthetic startup menu.  The explicit presentation gate is the only
     * path allowed to make source-backed startup pixels visible. */
    if (world && world->runtime_media.startup_presentation_allowed &&
        state->theronState.startup_font_tiles_ready) {
        /* The render plan still carries a host layout border for fixture and
         * no-media routes.  It is not a Track 02 bitmap, so never paint it
         * over an authenticated startup atlas.  THQUEST.ASM owns the
         * startup surface; until its frame tiles are decoded, leaving the
         * unbound border absent is the source-faithful result. */
        for (i = 0; i < plan->text_count; ++i) {
            const Theron_StartupRenderTextCommand *command = &plan->text[i];
            int ci = M11_COLOR_WHITE;
            switch (command->style) {
            case THERON_STARTUP_RENDER_TEXT_TITLE:   ci = M11_COLOR_YELLOW; break;
            case THERON_STARTUP_RENDER_TEXT_ACTIVE:  ci = M11_COLOR_YELLOW; break;
            case THERON_STARTUP_RENDER_TEXT_LOCKED:  ci = M11_COLOR_DARK_GRAY; break;
            case THERON_STARTUP_RENDER_TEXT_PICKED:  ci = M11_COLOR_LIGHT_GREEN; break;
            default: ci = M11_COLOR_WHITE; break;
            }
            m11_theron_draw_font_tile_text(
                framebuffer, framebufferWidth, framebufferHeight,
                command->x, command->y, command->text,
                &state->theronState.startup_font_tile_receipt, ci);
        }
    } else if (!state->theronState.startup_media_ready &&
               !state->theronState.startup_capture_media_bound &&
               theron_v1_boot_startup_host_render_plan_fallback_allowed(
                   &ui_caller.host_render)) {
        /* A host render receipt without an executor does not prove that the
         * Track 02 graphics executor was absent.  Once authenticated media
         * is bound, the old M11 border/text path is synthetic and must not
         * leak over a real startup surface.  Fixture/no-data sessions retain
         * this compatibility renderer until their source route is available. */
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      plan->border_x, plan->border_y,
                      plan->border_w, plan->border_h,
                      plan->border_color);
        for (i = 0; i < plan->text_count; ++i) {
            const Theron_StartupRenderTextCommand *command = &plan->text[i];
            M11_TextStyle scratch;
            const M11_TextStyle *style =
                m11_theron_startup_text_style(command->style, &scratch);
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          command->x, command->y, command->text, style);
        }
    }
}

/* Install the palette that belongs to an authenticated VDC/VCE capture
 * before M11 presents its indexed framebuffer.  The viewport capture loader
 * already verifies the complete VRAM/VCE pair; this is only the host-side
 * palette handoff for those source-owned indices.  Do not call this for the
 * unbound Track 02 atlas or the default viewport palette.
 *
 * Source: HuC6260/HuC6270 VCE BGR333 snapshot contract and the captured
 * Mednafen Theron screen route (VRAM f11c6b2a, VCE ea83f117). */
static int m11_theron_install_authenticated_vce_palette(
    const Theron_V1_Viewport *viewport) {
    uint8_t rgb6[256][3];
    int i;

    if (!viewport || !viewport->vram_trace_loaded) {
        return 0;
    }
    memset(rgb6, 0, sizeof(rgb6));
    for (i = 0; i < 256; ++i) {
        const uint32_t rgba = viewport->palette.entries[i].rgba;
        rgb6[i][0] = (uint8_t)((rgba >> 18) & 0x3fu);
        rgb6[i][1] = (uint8_t)((rgba >> 10) & 0x3fu);
        rgb6[i][2] = (uint8_t)((rgba >> 2) & 0x3fu);
    }
    return M11_Render_SetIndexedPaletteRgb6(rgb6) == M11_RENDER_OK;
}

void M11_GameView_DrawGraphicsPopup(const M11_GameViewState* state,
                                    unsigned char* framebuffer,
                                    int framebufferWidth,
                                    int framebufferHeight) {
    static const char* const presentation[] = { "MODE", "SCALE", "FILTER", "ASPECT", "INTEGER", "VSYNC", "FPS", "RES", "WINDOW" };
    static const char* const filters[] = { "SCANLINE", "SCAN %", "PALETTE", "GAMMA", "BRIGHT", "CONTRAST", "DITHER", "SHARPEN", "SHARP %", "PRESET", "SMOOTH" };
    static const char* const effects[] = { "PHOSPHOR", "DECAY", "GRID", "GRID %", "MOTION", "BLUR %", "LIGHT", "TURN PAN" };
    static const char* const cheats[] = { "CHEATS", "SPEED" };
    /* The last renderer enum value has legacy name M11_SCALE_STRETCH, but
     * ComputePresentationRect preserves the selected aspect in that mode.
     * Label the F10 control after its actual behaviour. */
    static const char* const scaleNames[] = {
        "1X", "2X", "3X", "4X", "FIT", "FIT SMOOTH"
    };
    const char* const* rows;
    M12_Config config;
    int i, slot, rowCount, v2;
    char value[40];
    M11_TextStyle title = g_text_small;
    M11_TextStyle normal = g_text_small;
    M11_TextStyle selected = g_text_small;

    if (!state || !state->graphicsPopupActive || !framebuffer ||
        framebufferWidth <= 0 || framebufferHeight <= 0) {
        return;
    }
    M12_Config_Load(&config, NULL);
    slot = m11_graphics_popup_game_slot(state);
    v2 = state->presentationMode != M12_PRESENTATION_V1_ORIGINAL;
    rows = state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_PRESENTATION ? presentation :
           state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_FILTERS ? filters :
           state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_EFFECTS ? effects : cheats;
    rowCount = m11_graphics_popup_row_count(state, state->graphicsPopupPage);
    title.color = M11_COLOR_YELLOW;
    normal.color = M11_COLOR_WHITE;
    selected.color = M11_COLOR_LIGHT_GREEN;
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  M11_GRAPHICS_POPUP_X, M11_GRAPHICS_POPUP_Y,
                  M11_GRAPHICS_POPUP_W, M11_GRAPHICS_POPUP_H,
                  M11_COLOR_BLACK);
    m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                  M11_GRAPHICS_POPUP_X, M11_GRAPHICS_POPUP_Y,
                  M11_GRAPHICS_POPUP_W, M11_GRAPHICS_POPUP_H,
                  M11_COLOR_LIGHT_BLUE);
    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                  M11_GRAPHICS_POPUP_X + 6, M11_GRAPHICS_POPUP_Y + 8,
                  "GRAPHICS F10 ESC TAB", &title);
    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                  M11_GRAPHICS_POPUP_X + 134, M11_GRAPHICS_POPUP_Y + 8, "X", &title);
    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                  M11_GRAPHICS_POPUP_X + 6, M11_GRAPHICS_POPUP_Y + 23,
                  state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_PRESENTATION ? "[PRES] FILT FX CH" :
                  state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_FILTERS ? "PRES [FILT] FX CH" :
                  state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_EFFECTS ? "PRES FILT [FX] CH" :
                                                                                  "PRES FILT FX [CH]", &selected);
    if (!v2 && (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_FILTERS ||
                state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_EFFECTS))
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      M11_GRAPHICS_POPUP_X + 6, M11_GRAPHICS_POPUP_Y + 34,
                      "V1: EFFECTS LOCKED", &normal);
    for (i = 0; i < rowCount; ++i) {
        M11_TextStyle line = i == state->graphicsPopupSelectedRow ? selected :
                             ((!v2 && (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_FILTERS ||
                                       state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_EFFECTS)) ? title : normal);
        int y = M11_GRAPHICS_POPUP_Y + 42 + i * 10;
        value[0] = '\0';
        if (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_PRESENTATION) {
            switch (i) {
                case 0: snprintf(value, sizeof(value), "%s", m11_graphics_popup_mode_name(state->presentationMode)); break;
                case 1: snprintf(value, sizeof(value), "%s", scaleNames[config.scaleModeIndex >= 0 && config.scaleModeIndex <= 5 ? config.scaleModeIndex : M11_SCALE_FIT]); break;
                case 2: snprintf(value, sizeof(value), "%s", config.scalingFilterIndex ? "LINEAR" : "NEAREST"); break;
                case 3: snprintf(value, sizeof(value), "%s", m11_graphics_popup_aspect_name(config.gameAspectRatio[slot])); break;
                case 4: snprintf(value, sizeof(value), "%s", config.integerScaling ? "ON" : "OFF"); break;
                case 5: snprintf(value, sizeof(value), "%s", config.vsyncIndex ? "ON" : "OFF"); break;
                case 6: snprintf(value, sizeof(value), "%s", config.showFpsOverlay ? "ON" : "OFF"); break;
                case 7: { int w, h; M12_Resolution_Dimensions(config.gameResolution[slot], &w, &h); snprintf(value, sizeof(value), "%dX%d", w, h); } break;
                default: snprintf(value, sizeof(value), "%s", config.windowModeIndex == 0 ? "WINDOW" : config.windowModeIndex == 1 ? "MAXIMIZED" : "FULLSCREEN"); break;
            }
        } else if (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_CHEATS) {
            switch (i) {
                case 0: snprintf(value, sizeof(value), "%s", config.gameCheatsEnabled[slot] ? "ON" : "OFF"); break;
                default:
                    if (!config.gameCheatsEnabled[slot]) snprintf(value, sizeof(value), "LOCKED");
                    else if (config.gameSpeed[slot] == 0) snprintf(value, sizeof(value), "SLOWER");
                    else if (config.gameSpeed[slot] == 2) snprintf(value, sizeof(value), "FASTER");
                    else snprintf(value, sizeof(value), "NORMAL");
                    break;
            }
        } else if (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_FILTERS &&
                   state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
            static const char* const csbFilters[] = {
                "SCANLINE", "SCAN %", "PALETTE", "DITHER", "EPX", "BILINEAR"
            };
            switch (i) {
                case 0: snprintf(value, sizeof(value), "%s", config.csbV2CrtScanlinesEnabled ? "ON" : "OFF"); break;
                case 1: snprintf(value, sizeof(value), "%d%%", config.csbV2CrtScanlineStrength); break;
                case 2: snprintf(value, sizeof(value), "%s", config.csbV2PaletteCorrectionEnabled ? "ON" : "OFF"); break;
                case 3: snprintf(value, sizeof(value), "%s", config.csbV2DitherCleanupEnabled ? "ON" : "OFF"); break;
                case 4: snprintf(value, sizeof(value), "%dX", config.csbV2ScalePercent / 100); break;
                default: snprintf(value, sizeof(value), "%s", config.csbV2BilinearEnabled ? "ON" : "OFF"); break;
            }
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          M11_GRAPHICS_POPUP_X + 7, y, csbFilters[i], &line);
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          M11_GRAPHICS_POPUP_X + 82, y, value, &line);
            continue;
        } else if (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_FILTERS &&
                   state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02) {
            static const char* const theronFilters[] = {
                "SCANLINE", "SCAN %", "PALETTE", "DITHER", "EPX", "BILINEAR"
            };
            switch (i) {
                case 0: snprintf(value, sizeof(value), "%s", config.theronV2CrtScanlinesEnabled ? "ON" : "OFF"); break;
                case 1: snprintf(value, sizeof(value), "%d%%", config.theronV2CrtScanlineStrength); break;
                case 2: snprintf(value, sizeof(value), "%s", config.theronV2PaletteCorrectionEnabled ? "ON" : "OFF"); break;
                case 3: snprintf(value, sizeof(value), "%s", config.theronV2DitherCleanupEnabled ? "ON" : "OFF"); break;
                case 4: snprintf(value, sizeof(value), "%dX", config.theronV2ScalePercent / 100); break;
                default: snprintf(value, sizeof(value), "%s", config.theronV2BilinearEnabled ? "ON" : "OFF"); break;
            }
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          M11_GRAPHICS_POPUP_X + 7, y, theronFilters[i], &line);
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          M11_GRAPHICS_POPUP_X + 82, y, value, &line);
            continue;
        } else if ((state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_FILTERS ||
                    state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_EFFECTS) &&
                   state->sourceKind != M11_GAME_SOURCE_BUILTIN_CATALOG &&
                   state->sourceKind != M11_GAME_SOURCE_CSB_BOOT &&
                   state->sourceKind != M11_GAME_SOURCE_THERON_TRACK02) {
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          M11_GRAPHICS_POPUP_X + 7, y, "SOURCE LOCKED", &line);
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          M11_GRAPHICS_POPUP_X + 82, y, "REAL CHAIN NEEDED", &line);
            continue;
        } else if (state->graphicsPopupPage == M11_GRAPHICS_POPUP_PAGE_FILTERS) {
            switch (i) {
                case 0: snprintf(value, sizeof(value), "%s", config.dm1V2CrtScanlinesEnabled ? "ON" : "OFF"); break;
                case 1: snprintf(value, sizeof(value), "%d%%", config.dm1V2CrtScanlineStrength); break;
                case 2: snprintf(value, sizeof(value), "%s", config.dm1V2PaletteCorrectionEnabled ? "ON 100%%" : "OFF"); break;
                case 3: snprintf(value, sizeof(value), "%d", config.dm1V2PaletteGamma); break;
                case 4: snprintf(value, sizeof(value), "%d", config.dm1V2PaletteBrightness); break;
                case 5: snprintf(value, sizeof(value), "%d", config.dm1V2PaletteContrast); break;
                case 6: snprintf(value, sizeof(value), "%s", config.dm1V2DitherCleanupEnabled ? "ON" : "OFF"); break;
                case 7: snprintf(value, sizeof(value), "%s", config.dm1V2SharpeningEnabled ? "ON" : "OFF"); break;
                case 8: snprintf(value, sizeof(value), "%d%%", config.dm1V2SharpeningStrength); break;
                case 9: snprintf(value, sizeof(value), "%d", config.dm1V2ColorPreset); break;
                default: snprintf(value, sizeof(value), "%s", config.dm1V2SmoothingEnabled ? "ON" : "OFF"); break;
            }
        } else {
            switch (i) {
                case 0: snprintf(value, sizeof(value), "%s", config.dm1V2PhosphorPersistenceEnabled ? "ON" : "OFF"); break;
                case 1: snprintf(value, sizeof(value), "%d%%", config.dm1V2PhosphorDecay); break;
                case 2: snprintf(value, sizeof(value), "%s", config.dm1V2PixelGridEnabled ? "ON" : "OFF"); break;
                case 3: snprintf(value, sizeof(value), "%d%%", config.dm1V2PixelGridIntensity); break;
                case 4: snprintf(value, sizeof(value), "%s", config.dm1V2MotionBlurEnabled ? "ON" : "OFF"); break;
                case 5: snprintf(value, sizeof(value), "%d%%", config.dm1V2MotionBlurStrength); break;
                case 6: snprintf(value, sizeof(value), "%s", config.dm1V2DynamicLightingEnabled ? "ON" : "OFF"); break;
                default: snprintf(value, sizeof(value), "%s", config.dm1V2SmoothTurnPanEnabled ? "ON" : "OFF"); break;
            }
        }
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      M11_GRAPHICS_POPUP_X + 7, y, rows[i], &line);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      M11_GRAPHICS_POPUP_X + 82, y, value, &line);
    }
}

void M11_GameView_RecordPresentedFrame(M11_GameViewState* state,
                                       uint64_t nowMs)
{
    uint64_t elapsed;
    if (!state || !state->fpsOverlayEnabled) {
        return;
    }
    if (state->fpsOverlaySampleStartedMs == 0U) {
        state->fpsOverlaySampleStartedMs = nowMs;
        state->fpsOverlayFrameCount = 0U;
        return;
    }
    ++state->fpsOverlayFrameCount;
    elapsed = nowMs - state->fpsOverlaySampleStartedMs;
    if (elapsed >= 500U) {
        state->fpsOverlayValue = (unsigned int)((state->fpsOverlayFrameCount * 1000U + elapsed / 2U) / elapsed);
        state->fpsOverlayFrameCount = 0U;
        state->fpsOverlaySampleStartedMs = nowMs;
    }
}

void M11_GameView_DrawFpsOverlay(const M11_GameViewState* state,
                                 unsigned char* framebuffer,
                                 int framebufferWidth,
                                 int framebufferHeight)
{
    char text[20];
    M11_TextStyle style = g_text_small;
    if (!state || !state->fpsOverlayEnabled || !framebuffer ||
        framebufferWidth <= 0 || framebufferHeight <= 0) {
        return;
    }
    style.color = M11_COLOR_YELLOW;
    snprintf(text, sizeof(text), "FPS %u", state->fpsOverlayValue);
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  4, 4, 48, 11, M11_COLOR_BLACK);
    m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                  4, 4, 48, 11, M11_COLOR_LIGHT_BLUE);
    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                  7, 6, text, &style);
}

static int m11_draw_dm2_source_inventory_panel(
    const M11_GameViewState *state,
    unsigned char *framebuffer,
    int framebuffer_width,
    int framebuffer_height)
{
    const DM2_V1_BootProfile *profile;
    const DM2_V1_AssetLoader *loader;
    DM2_V1_QueryGdatSummaryImageReceipt summary;
    DM2_V1_GdatGfxRawMaterialReceipt material;
    DM2_V1_GdatRaw4BlitPlacement placement;
    uint8_t *pixels = NULL;
    int width = 0;
    int height = 0;
    DM2_ImageFormat format = DM2_IMG_FMT_UNKNOWN;
    int row;
    int is_fmtowns;
    int is_amiga;
    int is_mac;
    uint16_t required_colors;

    is_fmtowns = state && m11_dm2_is_fmtowns_profile(
        (const DM2_V1_BootProfile *)state->dm2BootProfile);
    is_amiga = state && m11_dm2_is_amiga_profile(
        (const DM2_V1_BootProfile *)state->dm2BootProfile);
    is_mac = state && m11_dm2_is_mac_profile(
        (const DM2_V1_BootProfile *)state->dm2BootProfile);
    required_colors = (is_amiga || is_mac) ? 16u : 255u;
    if (!state || !framebuffer || framebuffer_width <= 0 ||
        framebuffer_height <= 0 ||
        (!is_fmtowns && !is_amiga && !is_mac)) {
        return 0;
    }
    profile = (const DM2_V1_BootProfile *)state->dm2BootProfile;
    loader = dm2_v1_boot_asset_loader(profile);
    memset(&summary, 0, sizeof(summary));
    memset(&material, 0, sizeof(material));
    memset(&placement, 0, sizeof(placement));
    if (!loader ||
        !dm2_v1_query_gdat_summary_image_receipt(
            loader, DM2_GDAT_CATEGORY_INTERFACE_CHARSHEET, 0, 1,
            &summary) ||
        !summary.accepted || summary.colors != required_colors ||
        !dm2_v1_gdat_image_raw_material_receipt(
            loader, DM2_GDAT_CATEGORY_INTERFACE_CHARSHEET, 0, 1,
            &material) ||
        !material.accepted || !material.source_hash ||
        !material.receipt_hash ||
        !(pixels = dm2_v1_asset_load_image_field(
              loader, DM2_GDAT_CATEGORY_INTERFACE_CHARSHEET, 0, 1,
              &width, &height, &format)) ||
        width <= 0 || height <= 0 ||
        (is_fmtowns && format != DM2_IMG_FMT_IMG3 &&
         format != DM2_IMG_FMT_U4) ||
        (is_amiga && format != DM2_IMG_FMT_IMG3 &&
         format != DM2_IMG_FMT_U4) ||
        (is_mac && format != DM2_IMG_FMT_IMG3 &&
         format != DM2_IMG_FMT_U4) ||
        !dm2_v1_gdat_door_overlay_query_raw4_blit_placement(
            loader, DM2_V1_INVENTORY_SURVEY_PREVIEW_RECT, width, height,
            &placement) ||
        placement.source_x < 0 || placement.source_y < 0 ||
        placement.destination.x < 0 || placement.destination.y < 0 ||
        placement.destination.w <= 0 || placement.destination.h <= 0 ||
        placement.source_x + placement.destination.w > width ||
        placement.source_y + placement.destination.h > height ||
        placement.destination.x + placement.destination.w > framebuffer_width ||
        placement.destination.y + placement.destination.h > framebuffer_height) {
        dm2_v1_asset_free_pixels(pixels);
        return 0;
    }
    if (summary.colors == 16u) {
        DM2_V1_InventoryPanelSurveyFrameReceipt survey;
        memset(&survey, 0, sizeof(survey));
        if (!dm2_v1_inventory_panel_survey_frame_receipt(loader, &survey) ||
            !survey.valid || survey.decoded_width != (uint16_t)width ||
            survey.decoded_height != (uint16_t)height) {
            dm2_v1_asset_free_pixels(pixels);
            return 0;
        }
        /* The original Amiga RAW4 rectangle clips the 121x72 CHARSHEET
         * source to its 119x70 destination.  The generic inventory helper
         * intentionally accepts only whole-image blits, so use the verified
         * RAW4 source offset here instead of rejecting the authentic frame
         * (or replacing it with a host panel).  `survey` binds the exact
         * GDAT image, palette and decoded identity before any pixels reach
         * the framebuffer. */
        for (row = 0; row < placement.destination.h; ++row) {
            int column;
            for (column = 0; column < placement.destination.w; ++column) {
                uint8_t pixel = pixels[(size_t)(placement.source_y + row) *
                                       (size_t)width +
                                       (size_t)(placement.source_x + column)];
                if (pixel >= 16u) {
                    dm2_v1_asset_free_pixels(pixels);
                    return 0;
                }
                framebuffer[(size_t)(placement.destination.y + row) *
                            (size_t)framebuffer_width +
                            (size_t)(placement.destination.x + column)] =
                    survey.palette16[pixel];
            }
        }
        dm2_v1_asset_free_pixels(pixels);
        return 1;
    }
    for (row = 0; row < placement.destination.h; ++row) {
        memcpy(framebuffer + (size_t)(placement.destination.y + row) *
                   (size_t)framebuffer_width +
                   (size_t)placement.destination.x,
               pixels + (size_t)(placement.source_y + row) *
                   (size_t)width + (size_t)placement.source_x,
               (size_t)placement.destination.w);
    }
    dm2_v1_asset_free_pixels(pixels);
    return 1;
}

void M11_GameView_Draw(M11_GameViewState* state,
                       unsigned char* framebuffer,
                       int framebufferWidth,
                       int framebufferHeight) {
    char line[96];
    char line2[96];
    char line3[96];
    char focusAction[96];
    char focusHint[96];
    unsigned short firstThing = THING_ENDOFLIST;
    int squareThingCount = 0;
    M11_ViewportCell currentCell;
    M11_ViewportCell aheadCell;
    const struct DungeonMapDesc_Compat* mapDesc = NULL;
    int avgFood = 0;
    int avgWater = 0;
    char champion[24];
    if (!framebuffer || framebufferWidth <= 0 || framebufferHeight <= 0) {
        return;
    }
    if (state && state->active &&
        state->sourceKind == M11_GAME_SOURCE_CSB_HINT_ORACLE) {
        const CSB_HintOracleAtariRuntime *runtime =
            (const CSB_HintOracleAtariRuntime *)state->csbHintOracleRuntime;
        uint8_t rgb6[256][3];
        int color;
        if (!runtime || csb_hint_oracle_atari_runtime_render_frame(
                            runtime, framebuffer,
                            (size_t)framebufferWidth * (size_t)framebufferHeight) !=
                            CSB_HINT_ORACLE_ATARI_RUNTIME_OK) {
            memset(framebuffer, 0,
                   (size_t)framebufferWidth * (size_t)framebufferHeight);
            return;
        }
        for (color = 0; color < 256; ++color) {
            rgb6[color][0] = (uint8_t)(runtime->graphics.rgb4[(color & 15) * 3] * 4u);
            rgb6[color][1] = (uint8_t)(runtime->graphics.rgb4[(color & 15) * 3 + 1] * 4u);
            rgb6[color][2] = (uint8_t)(runtime->graphics.rgb4[(color & 15) * 3 + 2] * 4u);
        }
        (void)M11_Render_SetIndexedPaletteRgb6(rgb6);
        return;
    }
    /* The receipt is frame-local evidence from F0115's completed floor-item
     * blit. Do not let a prior frame authorize a later projectile-only view. */
    memset(&s_m11_dm1_floor_item_host_presentation_receipt, 0,
           sizeof(s_m11_dm1_floor_item_host_presentation_receipt));
    memset(s_m11_dm1_rendered_pile_targets, 0,
           sizeof(s_m11_dm1_rendered_pile_targets));
    s_m11_dm1_rendered_pile_target_count = 0;
    memset(&s_m11_dm1_alcove_item_host_presentation_receipt, 0,
           sizeof(s_m11_dm1_alcove_item_host_presentation_receipt));
    memset(&s_m11_dm1_creature_host_presentation_receipt, 0,
           sizeof(s_m11_dm1_creature_host_presentation_receipt));
    memset(&s_m11_dm1_projectile_host_presentation_receipt, 0,
           sizeof(s_m11_dm1_projectile_host_presentation_receipt));
    memset(&s_m11_dm1_door_host_presentation_receipt, 0,
           sizeof(s_m11_dm1_door_host_presentation_receipt));
    memset(&s_m11_dm1_wall_ornament_host_presentation_receipt, 0,
           sizeof(s_m11_dm1_wall_ornament_host_presentation_receipt));
    memset(&s_m11_dm1_hoc_mirror_host_presentation_receipt, 0,
           sizeof(s_m11_dm1_hoc_mirror_host_presentation_receipt));
    memset(&s_m11_dm1_hoc_mirror_viewport_material_frame_receipt, 0,
           sizeof(s_m11_dm1_hoc_mirror_viewport_material_frame_receipt));
    memset(&s_m11_dm1_hoc_presented_frame_consumer_receipt, 0,
           sizeof(s_m11_dm1_hoc_presented_frame_consumer_receipt));
    /* ReDMCSB DUNVIEW.C F0128:8318-8616 rebuilds a full viewport from the
     * current party tuple. A side/depth F0107 inscription publishes only
     * its original-ornament receipt, so invalidate both M648 surfaces before
     * the new tuple is composed rather than retaining either across a turn. */
    m11_dm1_invalidate_wall_inscription_material();
    /* F0128 rebuilds its per-square scheduler plan from the live view every
     * frame (DUNVIEW.C:8318-8616); never retain a prior frame's plan. */
    memset(&s_m11_dm1_f0128_per_square_scheduler_receipt, 0,
           sizeof(s_m11_dm1_f0128_per_square_scheduler_receipt));
    if (state && state->sourceKind == M11_GAME_SOURCE_DM2_BOOT &&
        state->dm2BootProfile) {
        DM2_V1_InterfacePalette palette;
        /* skproject/SKWIN/SkWinCore.cpp SkWinCore::INIT lines 55606-55615
         * loads INTERFACE_GENERAL/0 dtPalIRGB+dtPalette16 field 0xFE before
         * SHOW_MENU_SCREEN.  MapGraphicsStyle selects GRAPHICSSET scene art;
         * it must not replace this global display IRGB table. */
        if (dm2_v1_boot_interface_palette(
                (DM2_V1_BootProfile *)state->dm2BootProfile, &palette)) {
            (void)M11_Render_SetIndexedPaletteRgb6(palette.rgb6);
        } else {
            M11_Render_ClearIndexedPaletteRgb6();
        }
    } else if (state && state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
               state->csbBootProfile) {
        const CSB_V1_BootProfile *csb_profile =
            (const CSB_V1_BootProfile *)state->csbBootProfile;
        uint8_t rgb6[256][3];
        int color;
        if (m11_csb_is_fmtowns_profile(csb_profile) &&
            state->csbState.startup_entrance_active &&
            state->csbFmtownsEntrancePaletteValid) {
            /* ENTRANCE.C F0806 owns C28 only through the C004 transition. */
            for (color = 0; color < 256; ++color) {
                rgb6[color][0] =
                    state->csbFmtownsEntrancePaletteRgb6[color & 15][0];
                rgb6[color][1] =
                    state->csbFmtownsEntrancePaletteRgb6[color & 15][1];
                rgb6[color][2] =
                    state->csbFmtownsEntrancePaletteRgb6[color & 15][2];
            }
            (void)M11_Render_SetIndexedPaletteRgb6(rgb6);
            csb_v22_inplace_draw_clear_indexed_palette();
        } else if (m11_csb_is_fmtowns_profile(csb_profile) &&
                   state->csbFmtownsDungeonPalettesValid) {
            int palette_level = m11_compute_dungeon_palette_index(state);
            if (palette_level < 0) palette_level = 0;
            if (palette_level > 5) palette_level = 5;
            /* PALETTE.C F0390 selects C00_LIGHT0..C05_LIGHT5. F31 stores
             * dungeon colours at DAC indices 16..31, while M11's decoded
             * four-bit raster carries their low source nibble. */
            for (color = 0; color < 256; ++color) {
                rgb6[color][0] = state->csbFmtownsDungeonPaletteRgb6
                    [palette_level][color & 15][0];
                rgb6[color][1] = state->csbFmtownsDungeonPaletteRgb6
                    [palette_level][color & 15][1];
                rgb6[color][2] = state->csbFmtownsDungeonPaletteRgb6
                    [palette_level][color & 15][2];
            }
            (void)M11_Render_SetIndexedPaletteRgb6(rgb6);
            csb_v22_inplace_draw_clear_indexed_palette();
        } else if (csb_profile->variant_id == CSB_V1_VARIANT_ST20_EN ||
            csb_profile->variant_id == CSB_V1_VARIANT_ST21_EN) {
            /* CSBWin starts from Palette552[0], then
             * SelectPaletteForLightLevel chooses a source row whenever the
             * loaded save/runtime supplies its exact light facts. A missing
             * receipt remains on the documented boot palette, never a PC3.4
             * brightness approximation. */
            if (m11_csb_atari_st_runtime_palette_rgb6(csb_profile, rgb6) ||
                m11_csb_atari_st_initial_palette_rgb6(csb_profile, rgb6)) {
                (void)M11_Render_SetIndexedPaletteRgb6(rgb6);
            } else {
                M11_Render_ClearIndexedPaletteRgb6();
            }
            csb_v22_inplace_draw_clear_indexed_palette();
        } else {
        /* CSB's PC3.4 IMG3 decoder emits original four-bit VGA indices.
         * F0128 runs after this common renderer setup, which previously
         * cleared any indexed palette and made its source pixels appear as
         * grayscale/default colours.  ReDMCSB DATA.C/VIDEODRV.C owns the
         * six brightness rows; select the current dungeon level once and
         * expand every possible raw byte by its low source colour nibble. */
        int palette_level = m11_compute_dungeon_palette_index(state);
        if (palette_level < 0) palette_level = 0;
        if (palette_level >= M11_PALETTE_LEVELS) {
            palette_level = M11_PALETTE_LEVELS - 1;
        }
        for (color = 0; color < 256; ++color) {
            const unsigned char *rgb =
                G9010_auc_VgaPaletteAll_Compat[palette_level][color & 0x0f];
            rgb6[color][0] = (uint8_t)(rgb[0] >> 2);
            rgb6[color][1] = (uint8_t)(rgb[1] >> 2);
            rgb6[color][2] = (uint8_t)(rgb[2] >> 2);
        }
        (void)M11_Render_SetIndexedPaletteRgb6(rgb6);
        /* V2.2 swaps are still composed into the source-owned indexed F0128
         * page.  Give the compositor the exact palette just admitted above;
         * otherwise its RGBA cache would quantize against a generic EGA cube
         * and visibly change authentic CSB colours. */
        (void)csb_v22_inplace_draw_set_indexed_palette_rgb6(rgb6);
        }
    } else {
        M11_Render_ClearIndexedPaletteRgb6();
        csb_v22_inplace_draw_clear_indexed_palette();
    }
    /* Set file-scope draw state for asset-backed rendering helpers */
    g_drawState = state;
    /* Activate original DM1 font for this render pass */
    g_activeOriginalFont = state->originalFontAvailable
        ? &state->originalFont : NULL;
    /* Accessibility: propagate fontScale from game state to file-scope
     * text renderer.  0 means "use M11_TextStyle scale directly". */
    g_m11_font_scale_override = state->fontScale;
    /* Base background is BLACK (DM PC VGA slot 0). The pre-correction
     * base was NAVY (slot 14, pure blue), which produced the bright-blue
     * outermost frame strip the player saw around the whole game view.
     * Classic DM1 renders the area outside the HUD chrome as solid
     * black; only the HUD frame itself carries stone/bronze shading. CSB
     * preserves its current host page until its source-owned receipt commits. */
    if (!state || state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      0, 0, framebufferWidth, framebufferHeight,
                      M11_COLOR_BLACK);
    }
    if (!state || !state->active) {
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      18, 18, "NO GAME VIEW", &g_text_title);
        m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                            framebufferHeight);
        g_drawState = NULL;
        g_activeOriginalFont = NULL;
        g_m11_font_scale_override = 0;
        return;
    }
    m11_dm1_runtime_capture_frame_begin(state);
    if (m11_is_dm1_source_kind(state->sourceKind)) {
        const int c13Required =
            s_m11_dm1_c13_visible_runtime_handoff.owner == state;
        const int c13Accepted =
            m11_dm1_c13_visible_runtime_handoff_consume_transition(state);
        if (c13Required) {
            m11_dm1_runtime_capture_route_evidence(
                state, M11_DM1_RUNTIME_CAPTURE_C13, c13Accepted,
                c13Accepted, c13Accepted,
                s_m11_dm1_c13_visible_runtime_handoff.gameTick,
                s_m11_dm1_c13_visible_runtime_handoff.queueGameTick,
                s_m11_dm1_c13_visible_runtime_handoff.fingerprint);
        }
        if (!c13Accepted) {
        /* C13's next-tick fence expired or was never source-certified. The
         * visible transition owns no replacement pixels, so keep the page
         * cleared instead of letting a prior viewport leak through. */
        memset(framebuffer, 0,
               (size_t)framebufferWidth * (size_t)framebufferHeight);
        m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                            framebufferHeight);
        g_drawState = NULL;
        g_activeOriginalFont = NULL;
        g_m11_font_scale_override = 0;
        return;
        }
    }
    if (state->sourceKind == M11_GAME_SOURCE_THERON_TRACK02) {
        Theron_V1_World* world = (Theron_V1_World*)state->theronWorld;
        Theron_V1_Viewport* viewport =
            (Theron_V1_Viewport*)state->theronViewport;
        TrAssetBundle* assets = (TrAssetBundle*)state->theronAssets;
        if (state->theronState.dungeon_capture_required) {
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          18, 18, "TRACK02 CAPTURE REQUIRED", &g_text_title);
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        if (state->theronState.startup_phase != THERON_STARTUP_PHASE_IN_DUNGEON ||
            !state->theronState.level_loaded) {
            m11_theron_draw_startup_screen(state,
                                           world,
                                           framebuffer,
                                           framebufferWidth,
                                           framebufferHeight);
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        /* The authenticated VDC/VCE replay is indexed all the way through
         * the viewport presenter.  Install its real VCE colors before M11
         * converts that indexed surface to the user-visible screenshot;
         * otherwise a valid capture is presented through the cleared host
         * palette and becomes an apparently black frame. */
        (void)m11_theron_install_authenticated_vce_palette(viewport);
        if (!theron_v1_boot_runtime_render_frame(
                world,
                viewport,
                assets,
                state->presentationMode != M12_PRESENTATION_V1_ORIGINAL,
                state->hudLaunchMode,
                framebuffer,
                framebufferWidth,
                framebufferHeight)) {
            /* The runtime refused to draw (verified Track 02 with no bound
             * graphics bank, or missing viewport/world). Fail closed to a
             * black page rather than leaving stale pixels or a zero-pixel
             * source-owned surface visible. */
            memset(framebuffer, 0,
                   (size_t)framebufferWidth * (size_t)framebufferHeight);
        }
        m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                            framebufferHeight);
        g_drawState = NULL;
        g_activeOriginalFont = NULL;
        g_m11_font_scale_override = 0;
        return;
    }

    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT) {
        /* C040 clear consumption records a one-shot source receipt.  The
         * public draw API is const for ordinary renderers; a live game view
         * is nevertheless mutable here and owns this CSB-only transaction. */
        M11_GameViewState *csb_state = (M11_GameViewState *)state;
        if ((state->csbState.startup_title_active ||
             state->csbFmtownsEndingActive) &&
            (m11_csb_present_fmtowns_utility(csb_state, framebuffer,
                                             framebufferWidth, framebufferHeight) ||
             m11_csb_present_fmtowns_switch(csb_state, framebuffer,
                                            framebufferWidth, framebufferHeight) ||
             m11_csb_present_fmtowns_title(csb_state, framebuffer,
                                           framebufferWidth, framebufferHeight))) {
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        if (state->csbState.startup_title_active &&
            m11_csb_present_amiga_titl_startup(csb_state, framebuffer,
                                               framebufferWidth,
                                               framebufferHeight)) {
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        if (m11_csb_present_amiga_entrance_credits(
                state, framebuffer, framebufferWidth, framebufferHeight)) {
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        if (m11_csb_present_amiga_entrance(csb_state, framebuffer,
                                           framebufferWidth, framebufferHeight)) {
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        if (state->csbState.startup_title_active &&
            m11_csb_present_atari_st_startup(csb_state, framebuffer,
                                              framebufferWidth,
                                              framebufferHeight)) {
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        if (m11_csb_boot_startup_active_from_capture(state)) {
            m11_draw_csb_startup_entrance(csb_state,
                                          framebuffer,
                                          framebufferWidth,
                                          framebufferHeight);
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        /* Standard CSBWin/Atari has its own C232 HUD layout rather than the
         * PC3.4 C017/C040 terminal session.  Once ANIM.C has yielded to the
         * game, consume that real source layer directly. */
        if (m11_csb_present_atari_st_runtime_viewport(
                csb_state, framebuffer, framebufferWidth, framebufferHeight) &&
            m11_csb_present_atari_st_runtime_hud(csb_state, framebuffer,
                                                 framebufferWidth,
                                                 framebufferHeight)) {
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        if (m11_csb_present_amiga_runtime_surface(
                state, framebuffer, framebufferWidth, framebufferHeight)) {
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }
        /* ENTRANCE.C F0806 releases C002-C005 before DUNVIEW.C F0128 draws
         * the first live dungeon page. The previous C004 opening raster is
         * not a runtime backing store: begin each post-entrance source pass
         * from a cleared page so no host-retained entrance pixels survive
         * outside the authenticated viewport/HUD consumers. */
        memset(framebuffer, 0,
               (size_t)framebufferWidth * (size_t)framebufferHeight);
        /* PANEL.C F0346/F0347 validates a pending C040 -> C017 clear before
         * DUNVIEW draws the next page.  Keep that ordering in M11: a stale
         * terminal generation must not reveal a newly drawn viewport before
         * the session transaction rejects it. */
        if (!m11_csb_live_hud_session_ready(state) ||
            (!((const CSB_V1_StartupRuntimeAssetSession_PC34 *)
                   csb_state->csbStartupRuntimeAssetSession)
                  ->direct_resume_loaded &&
             !m11_csb_consume_c040_clear_session(csb_state)) ||
            !m11_render_csb_boot_viewport(csb_state, framebuffer,
                                          framebufferWidth,
                                          framebufferHeight)) {
            /* A verified CSB launch must not exchange missing source
             * material for a replacement host page or retain a stale page. */
            memset(framebuffer, 0,
                   (size_t)framebufferWidth * (size_t)framebufferHeight);
        } else {
            /* V2.0/V2.1 alter presentation only. ReDMCSB PANEL.C C017/C040
             * remains the authoritative CSB HUD; a procedural overlay would
             * replace genuine palette-indexed data. V2.2 stays unavailable
             * until a reviewed material gate can own replacement chrome. */
            if (state->inventoryPanelActive &&
                !m11_draw_csb_v1_inventory_surface(
                    csb_state, framebuffer, framebufferWidth,
                    framebufferHeight)) {
                /* The C017/C040 pair did not form one complete terminal
                 * session surface. Do not retain the preceding viewport
                 * as a substitute presentation. */
                memset(framebuffer, 0,
                       (size_t)framebufferWidth *
                           (size_t)framebufferHeight);
            } else if (!state->inventoryPanelActive) {
                /* CSB PC 3.4 viewport aperture sits at (48,33) in the 320x200
                 * page. Draw the HUD first, then save and restore the viewport
                 * rectangle so DM1-layout HUD panels (x=224+) that overlap the
                 * CSB viewport area (x=48..271) do not corrupt it. */
                unsigned char vp_save[224 * 136];
                int vpy;
                for (vpy = 0; vpy < 136; ++vpy) {
                    memcpy(vp_save + vpy * 224,
                           framebuffer + (33 + vpy) * framebufferWidth + 48,
                           224);
                }
                m11_draw_csb_v1_runtime_hud(state, framebuffer,
                                            framebufferWidth,
                                            framebufferHeight);
                for (vpy = 0; vpy < 136; ++vpy) {
                    memcpy(framebuffer + (33 + vpy) * framebufferWidth + 48,
                           vp_save + vpy * 224,
                           224);
                }
            }
        }
        m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                            framebufferHeight);
        g_drawState = NULL;
        g_activeOriginalFont = NULL;
        g_m11_font_scale_override = 0;
        return;
    }

    if (state->sourceKind == M11_GAME_SOURCE_NEXUS_DGN) {
        Nexus_Framebuffer nexusFb;
        int y;
        int copyW = framebufferWidth < NEXUS_FB_W ? framebufferWidth : NEXUS_FB_W;
        int copyH = framebufferHeight < NEXUS_FB_H ? framebufferHeight : NEXUS_FB_H;
        int directDraw = 0;
        nexus_fb_init(&nexusFb);
        if (state->nexusState.title_active ||
            state->nexusState.startup_save_select_active ||
            (state->nexusState.champion_select_active &&
             state->nexusEngine)) {
            Nexus_V1_LauncherRuntimeStartupSnapshot snapshot;
            Nexus_V1_LauncherRuntimeReceipt runtime_receipt;
            Nexus_V1_StartupHostCallerReceipt host_caller_receipt;
            Nexus_V1_StartupTitleTransitionCaptureReceipt transition_capture;
            Nexus_V1_StartupDrawCommand commands[80];
            Nexus_V1_DgnRenderCommand dgn_commands[NEXUS_V1_DGN_VIEW_RENDER_MAX_COMMANDS];
            int command_count;
            int host_caller_ready = 0;
            directDraw = 1;
            nexus_v1_launcher_startup_title_transition_capture_receipt_clear(
                &transition_capture);
            m11_nexus_runtime_startup_snapshot(state, &snapshot);
            memset(&runtime_receipt, 0, sizeof(runtime_receipt));
            (void)m11_nexus_runtime_receipt_from_state(state,
                                                       &runtime_receipt);
            if (nexus_v1_launcher_startup_host_caller_receipt_from_snapshot(
                    &runtime_receipt,
                    &snapshot,
                    M12_MENU_INPUT_NONE,
                    m11_nexus_startup_load_save_callback,
                    (void *)state,
                    commands,
                    (int)(sizeof(commands) / sizeof(commands[0])),
                    dgn_commands,
                    (int)(sizeof(dgn_commands) / sizeof(dgn_commands[0])),
                    &host_caller_receipt)) {
                host_caller_ready = host_caller_receipt.host_caller_ready ? 1 : 0;
                command_count =
                    host_caller_receipt.host_execute_startup_draws
                        ? host_caller_receipt.copied_startup_command_count
                        : 0;
                if (state->nexusState.title_active && command_count > 0 &&
                    !nexus_v1_launcher_startup_title_transition_capture_receipt_from_host(
                        &host_caller_receipt,
                        state->nexusState.title_frame,
                        commands,
                        command_count,
                        &transition_capture)) {
                    command_count = 0;
                }
                if (host_caller_receipt.host_execute_dgn_draws &&
                    host_caller_receipt.copied_dgn_command_count > 0 &&
                    m11_draw_nexus_dgn_host_plan(state,
                                                 framebuffer,
                                                 framebufferWidth,
                                                 framebufferHeight)) {
                    return;
                }
            } else {
                command_count = 0;
            }
            /* A blocked real-asset route owns this frame too. Clear it so
             * callers never retain a stale title/menu image as a fallback. */
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          0, 0, framebufferWidth, framebufferHeight,
                          M11_COLOR_BLACK);
            if (host_caller_ready && command_count > 0) {
                m11_draw_nexus_startup_commands(state,
                                                framebuffer,
                                                framebufferWidth,
                                                framebufferHeight,
                                                &host_caller_receipt.ownership
                                                     .startup_bundle.package,
                                                state->nexusState.title_active
                                                    ? &transition_capture
                                                    : NULL,
                                                commands,
                                                command_count);
            } else if (state->nexusState.title_active) {
                /* TITLE.CG is decoded and retained as a source receipt, but
                 * its Saturn VDP1/VDP2 destination is not authenticated. */
            } else if (host_caller_ready) {
                /* The startup receipt owns the blocked-route diagnostic;
                 * this framebuffer remains source pixels or no-draw. */
            }
        } else if (state->nexusEngine) {
            directDraw = 1;
            if (!m11_draw_nexus_dgn_host_plan(state,
                                               framebuffer,
                                               framebufferWidth,
                                               framebufferHeight) &&
                !state->nexusState.startup_suppress_fallback_visuals) {
                /* A blocked Saturn material route must remain a no-draw
                 * result. Human-readable diagnostics live in receipts/logs,
                 * never in host-generated viewport pixels. */
            }
        }
        if (!directDraw) {
            for (y = 0; y < copyH; ++y) {
                memcpy(&framebuffer[y * framebufferWidth],
                       &nexusFb.color_buffer[y * NEXUS_FB_W],
                       (size_t)copyW);
            }
        }
        /* Keep the framebuffer untouched when the source runtime is absent;
         * launcher/status receipts own the human-readable error. */
        m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                            framebufferHeight);
        g_drawState = NULL;
        g_activeOriginalFont = NULL;
        g_m11_font_scale_override = 0;
        return;
    }

    /* DM2 M11 render hand-off.  The DM2 runtime renders into the
     * same indexed framebuffer layout M11 presents for DM1/CSB, so direct
     * launcher starts can show the actual DM2 viewport boundary instead of
     * a text placeholder. Source: dm2_v1_runtime_render_frame(),
     * SKULL.ASM T560/T600 render split. */
    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
        int rendered = -1;
        int runtime_frame_accepted = 0;
        DM2_V1_ViewportM11FrameReceipt runtime_frame_receipt;
        DM2_V1_BootStartupHostViewReceipt startup_host_receipt;
        DM2_V1_BootStartupRenderOwnershipReceipt startup_ownership_receipt;
        DM2_V1_BootStartupRealVisualCaptureReceipt startup_visual_receipt;
        DM2_V1_BootRuntimeRenderReceipt runtime_render_receipt;
        int startup_menu_drawn = 0;
        memset(&startup_host_receipt, 0, sizeof(startup_host_receipt));
        memset(&startup_ownership_receipt, 0, sizeof(startup_ownership_receipt));
        memset(&startup_visual_receipt, 0, sizeof(startup_visual_receipt));
        memset(&runtime_render_receipt, 0, sizeof(runtime_render_receipt));
        memset(&runtime_frame_receipt, 0, sizeof(runtime_frame_receipt));

        /* skproject/SKWIN/SkWinCore.cpp::INIT (55639-55645) loops through
         * SHOW_MENU_SCREEN() until GAME_LOAD() accepts a user action.
         * SHOW_MENU_SCREEN() (55182-55235) owns TITLE/0/dt07/4 and its menu
         * input loop.  Do not render a live dungeon underneath or instead of
         * that source-owned surface: missing title GDAT must fail closed. */
        if (state->dm2State.startup_menu_active) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          0, 0, framebufferWidth, framebufferHeight,
                          M11_COLOR_BLACK);
            if (m11_dm2_preselection_input_active((M11_GameViewState *)state) &&
                m11_dm2_render_preselection_view(
                    (M11_GameViewState *)state, framebuffer,
                    framebufferWidth, framebufferHeight)) {
                /* Source GAME_LOAD preselection owns the viewport while the
                 * mirror/c_hero event is still private. */
                startup_menu_drawn = 1;
            } else if (((M11_GameViewState *)state)->dm2MacMovieActive) {
                /* Macintosh SHOW_MENU_SCREEN is preceded by the authentic
                 * Title.MooV.  Its decoded frame owns the surface until the
                 * movie reaches EOF; the static SKULL menu cannot appear
                 * early. */
                startup_menu_drawn = m11_dm2_present_mac_movie(
                    (M11_GameViewState *)state, framebuffer,
                    framebufferWidth, framebufferHeight);
            } else if (((M11_GameViewState *)state)->dm2MacMovieRejected) {
                /* Missing QuickTime decoder or a malformed source stream is
                 * a black, fail-closed Mac launch, never a PC title fallback. */
            } else if (((M11_GameViewState *)state)->dm2DosMveIntroActive) {
                /* IBMIOP's PC-DOS MVE is earlier than SHOW_MENU_SCREEN.
                 * While it owns the screen, do not evaluate any GDAT title,
                 * credits or host overlay route.  The presenter advances at
                 * most one exact source frame per Draw call, even when the
                 * host has missed several deadlines. */
                (void)m11_dm2_present_dos_intro((M11_GameViewState *)state,
                                                framebuffer, framebufferWidth,
                                                framebufferHeight);
            } else if (((const M11_GameViewState *)state)->dm2DosMveIntroRejected) {
                /* A verified MVE that cannot retain strict source order must
                 * fail black.  Showing SKULL's menu here would falsely claim
                 * that IBMIOP completed. */
            } else if (state->dm2FmtownsTitleRejected) {
                /* Fail closed: selected FM Towns media cannot claim PC
                 * GDAT's static startup page as an alternate TITLE. */
            } else if (state->dm2FmtownsTitleBound) {
                startup_menu_drawn = m11_dm2_present_fmtowns_title(
                    state, framebuffer, framebufferWidth, framebufferHeight);
            } else if (state->dm2State.startup_credits_active) {
                /* DM2_SHOW_CREDITS has its own image and palette transaction.
                 * It temporarily replaces SHOW_MENU_SCREEN after TITLE has
                 * handed off to SKULL, so it must precede the static FM Towns
                 * menu branch here. Source: SKULLWIN/startend.cpp::
                 * DM2_SHOW_CREDITS. */
                startup_menu_drawn = m11_draw_dm2_startup_credits(
                    state, framebuffer, framebufferWidth, framebufferHeight);
            } else if (m11_dm2_is_fmtowns_profile(
                           (const DM2_V1_BootProfile *)state->dm2BootProfile) &&
                       state->dm2FmtownsTitleFinished) {
                startup_menu_drawn = m11_dm2_present_fmtowns_skull_menu(
                    state, framebuffer, framebufferWidth, framebufferHeight);
            } else if (m11_dm2_is_amiga_profile(
                           (const DM2_V1_BootProfile *)state->dm2BootProfile) &&
                       state->dm2FmtownsTitleFinished) {
                startup_menu_drawn = m11_dm2_present_amiga_startup_menu(
                    state, framebuffer, framebufferWidth, framebufferHeight);
            } else {
                startup_menu_drawn = m11_draw_dm2_startup_menu(
                    state,
                    framebuffer,
                    framebufferWidth,
                    framebufferHeight,
                    &startup_host_receipt,
                    &startup_ownership_receipt,
                    &startup_visual_receipt);
            }
            /* SHOW_MENU_SCREEN and DM2_SHOW_CREDITS own pixels, input and
             * music, not an M11 status line.  A missing source image stays
             * black/fails closed; a decoded one is presented directly. */
            (void)startup_menu_drawn;
            m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                                framebufferHeight);
            g_drawState = NULL;
            g_activeOriginalFont = NULL;
            g_m11_font_scale_override = 0;
            return;
        }

        if (state->dm2World) {
            /* The mounted DM2 V1 profile already owns the exact G1 pose and
             * GDAT material transaction.  Do not let the optional V2
             * procedural viewport claim this source-backed frame; V2 may
             * still consume its own decoded GDAT HUD after this handoff. */
            (void)dm2_v1_boot_runtime_render_frame(
                (DM2_V1_BootProfile *)state->dm2BootProfile,
                framebuffer,
                framebufferWidth,
                framebufferWidth,
                framebufferHeight,
                NULL,
                NULL,
                &runtime_render_receipt);
            rendered = runtime_render_receipt.render_result;
        }
        if (rendered == 0) {
            (void)dm2_v1_runtime_last_m11_frame_receipt(
                &runtime_frame_receipt);
            runtime_frame_accepted = M11_Dm2RuntimeFrameReceipt_ShouldPresent(
                &runtime_render_receipt, &runtime_frame_receipt);
            {
                M11_GameViewState *mutable_state = (M11_GameViewState *)state;
                mutable_state->dm2LastRuntimeFrameAccepted =
                    runtime_frame_accepted ? 1 : 0;
                mutable_state->dm2LastRuntimeRealAssetsReady =
                    runtime_render_receipt.runtime_render_real_asset_ready ? 1 : 0;
                mutable_state->dm2LastRuntimeNoCoreFallbacks =
                    runtime_render_receipt.runtime_render_no_core_fallbacks ? 1 : 0;
                mutable_state->dm2LastRuntimeFallbackDrawCount =
                    runtime_render_receipt.runtime_render_fallback_floor_ceiling_count +
                    runtime_render_receipt.runtime_render_fallback_wall_count +
                    runtime_render_receipt.runtime_render_fallback_door_count +
                    runtime_render_receipt.runtime_render_fallback_creature_count +
                    runtime_render_receipt.runtime_render_fallback_item_count +
                    runtime_render_receipt.runtime_render_fallback_creature_possession_item_count +
                    runtime_render_receipt.runtime_render_fallback_carried_item_count +
                    runtime_render_receipt.runtime_render_fallback_projectile_count;
            }
            if (!runtime_frame_accepted) {
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              0, 0, framebufferWidth, framebufferHeight,
                              M11_COLOR_BLACK);
                rendered = -1;
            }
        }
        if (rendered == -1) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          0, 0, framebufferWidth, framebufferHeight,
                          M11_COLOR_BLACK);
        }
        if (state->inventoryPanelActive) {
            /* DM2 CHANGE_VIEWPORT_TO_INVENTORY replaces the dungeon page
             * with the source CHARSHEET frame.  Consume only the
             * authenticated platform palette/format, RECT_1EE material and
             * RAW4 placement; a missing frame must not leave the live dungeon
             * visible behind an asserted inventory state. */
            if (!m11_draw_dm2_source_inventory_panel(
                    state, framebuffer, framebufferWidth, framebufferHeight)) {
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              0, 0, framebufferWidth, framebufferHeight,
                              M11_COLOR_BLACK);
            }
        }
        /* The accepted V1 runtime frame is the only HUD owner.  SKProject
         * drives interface images from live GUI/session state (not a static
         * post-frame list), including per-champion and active-command state.
         * Do not replay a second compatibility HUD pass here: no complete
         * live-GUI receipt exists yet, so even authentic GDAT pixels could
         * overwrite a source-owned state transition.  Source: SKProject
         * SKWIN/SkWinCore.cpp DRAW_CHAMPION_PICTURE (12866+) and
         * SKWINSPX/src/v5/skguidrw.cpp UI command paths. */
        if (runtime_frame_accepted) {
            m11_draw_v1_leader_hand_object_name(state, framebuffer,
                                                framebufferWidth,
                                                framebufferHeight);
            (void)m11_draw_dm2_save_dialogue_panel(state, framebuffer,
                                                   framebufferWidth,
                                                   framebufferHeight);
        }
        m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                            framebufferHeight);
        g_drawState = NULL;
        g_activeOriginalFont = NULL;
        g_m11_font_scale_override = 0;
        return;
    }
    memset(&currentCell, 0, sizeof(currentCell));
    memset(&aheadCell, 0, sizeof(aheadCell));
    if (state->world.dungeon && state->world.party.mapIndex >= 0 &&
        state->world.party.mapIndex < (int)state->world.dungeon->header.mapCount) {
        mapDesc = &state->world.dungeon->maps[state->world.party.mapIndex];
    }
    if (state->showDebugHUD) {
        firstThing = m11_square_chain_head(&state->world,
                                           state->world.party.mapIndex,
                                           state->world.party.mapX,
                                           state->world.party.mapY);
        squareThingCount = m11_count_square_things(&state->world,
                                                   state->world.party.mapIndex,
                                                   state->world.party.mapX,
                                                   state->world.party.mapY);
        (void)m11_sample_viewport_cell(state, 0, 0, &currentCell);
        (void)m11_sample_viewport_cell(state, 1, 0, &aheadCell);
        m11_get_food_water_average(&state->world.party, &avgFood, &avgWater);
        m11_get_active_champion_label(state, champion, sizeof(champion));
        m11_format_front_cell_prompt(state,
                                     &aheadCell,
                                     focusAction,
                                     sizeof(focusAction),
                                     focusHint,
                                     sizeof(focusHint));
    }

    /* ── V1 screen layout ──
     * Three major zones (DM-like composition):
     *   1. Top bar:     thin title strip (dungeon name only)
     *   2. Middle:      viewport (left) + right status column
     *   3. Bottom:      party panel + single message line
     *
     * Debug/helper elements are only drawn when showDebugHUD is set. */

    if (state->showDebugHUD) {
        /* Debug-only HUD chrome background.  The normal V1 screen starts
         * from the source black clear (ReDMCSB DEFS.H M518_FillScreenBlack
         * -> C002_ZONE_SCREEN / C00_COLOR_BLACK) and then draws the exact
         * viewport, champion status boxes, right-column panels, and bottom
         * message area over it.  Keeping this broad slate rectangle in V1
         * left a visible prototype frame in the gaps between source panels
         * (especially y=29..32 above the viewport and the lower side-panel
         * gutters). */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      8, 8, framebufferWidth - 16, framebufferHeight - 16,
                      M11_COLOR_DARK_GRAY);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      8, 8, framebufferWidth - 16, framebufferHeight - 16,
                      M11_COLOR_DARK_GRAY);
    }

    if (state->showDebugHUD) {
        /* Top title/debug bar is diagnostic-only.  Normal V1 should not
         * advertise itself with Firestaff text chrome above the viewport;
         * DM1's in-game screen is asset panels + viewport, not a captioned
         * debug screenshot. */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      12, 12, framebufferWidth - 24, 12, M11_COLOR_BLACK);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      18, 13, state->title[0] != '\0' ? state->title : "DUNGEON MASTER", &g_text_shadow);
        snprintf(line, sizeof(line), "L%d %s %s%s",
                 state->world.party.mapIndex + 1,
                 m11_direction_name(state->world.party.direction),
                 state->lastAction,
                 state->resting ? " ZZZ" : "");
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      140, 13, line, &g_text_small);
        snprintf(line, sizeof(line), "G GRAB P DROP R REST 1-6 RUNE C CAST");
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      240, 13, line, &g_text_small);
    }

    /* Viewport zone — source-faithful DM1 rectangle. */
    m11_dm1_hoc_consume_presentation_receipt(state);
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  M11_VIEWPORT_X, M11_VIEWPORT_Y,
                  M11_VIEWPORT_W, M11_VIEWPORT_H, M11_COLOR_BLACK);
    m11_draw_viewport(state, framebuffer, framebufferWidth, framebufferHeight);
    /* Consume only the completed F0115 floor-object material from this
     * non-HoC viewport pass. Missing or stale GRAPHICS.DAT never retains a
     * prior receipt and prevents final runtime capture for this frame. */
    m11_dm1_f0115_floor_item_runtime_capture_consume(state);
    m11_dm1_f0115_c15_runtime_capture_consume(state);
    m11_dm1_f0115_c2900_runtime_capture_consume(state);
    m11_dm1_hoc_presented_frame_consumer_build(state);
    /* ReDMCSB has no procedural V2 particle, light or full-screen overlay
     * path. Keep the authenticated DM1 bitmap/palette renderer authoritative
     * until a real V2 asset corpus is available; synthetic effects must not
     * be injected after the source viewport draw. */

    /* Old Firestaff frame-strip assets are debug-only now; in normal
     * V1 they overdraw the source viewport/floor/ceiling composition. */
    if (state->showDebugHUD) {
        m11_draw_ui_frame_assets(state, framebuffer, framebufferWidth, framebufferHeight);
    }

    /* Right status column — align normal V1 to the original viewport
     * edge (x=224) so it does not erase the rightmost 10 px of the
     * 224-wide dungeon view. */
    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                  state->showDebugHUD ? 214 : 224,
                  state->showDebugHUD ? 24 : 33,
                  state->showDebugHUD ? 94 : 87,
                  state->showDebugHUD ? 120 : 136,
                  M11_COLOR_BLACK);
    m11_draw_utility_panel(state, framebuffer, framebufferWidth, framebufferHeight, mapDesc);

    if (state->showDebugHUD) {
        /* Map mini-panel, focus card, message log — debug only */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      218, 74, 86, 68, M11_COLOR_BLACK);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      218, 74, 86, 68, M11_COLOR_LIGHT_BLUE);
        m11_draw_map_panel(state, framebuffer, framebufferWidth, framebufferHeight);
        m11_draw_focus_card(framebuffer, framebufferWidth, framebufferHeight, state, &aheadCell);
        {
            int logI;
            int logY = 108;
            int logCount = state->messageLog.count;
            int logMax = 4;
            if (logCount > logMax) {
                logCount = logMax;
            }
            for (logI = 0; logI < logCount; ++logI) {
                const M11_LogEntry* entry = m11_log_entry_at(&state->messageLog, logI);
                if (entry && entry->text[0] != '\0') {
                    M11_TextStyle logStyle = g_text_small;
                    logStyle.color = entry->color;
                    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                                  222, logY + logI * 8, entry->text, &logStyle);
                }
            }
        }
    }

    /* Bottom zone — in normal V1 leave the source C015 message area
     * ownership to m11_draw_v1_message_area() below.  The old Firestaff
     * broad inset fill was a prompt-strip/debug band at y=169..191; it
     * visibly disagreed with TEXT.C's full-width message surface at
     * (0,173,320,27). */
    if (state->showDebugHUD || !m11_v1_chrome_mode_enabled(state)) {
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      12, state->showDebugHUD ? 146 : 169,
                      296, state->showDebugHUD ? 46 : 23,
                      M11_COLOR_BLACK);
    }

    if (state->showDebugHUD) {
        /* Diagnostic square summary lines — debug only */
        m11_format_square_summary(&currentCell, line, sizeof(line));
        m11_format_square_things(firstThing, squareThingCount, line3, sizeof(line3));
        snprintf(line2, sizeof(line2), "HERE  %s", line);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight, 16, 149, line2, &g_text_small);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight, 122, 149, line3, &g_text_small);
        snprintf(line, sizeof(line), "TICK %u", (unsigned int)state->world.gameTick);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight, 240, 149, line, &g_text_small);

        m11_format_square_summary(&aheadCell, line, sizeof(line));
        snprintf(line2, sizeof(line2), "AHEAD %s", line);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight, 16, 157, line2, &g_text_small);
        snprintf(line, sizeof(line), "%s F%03d W%03d",
                 champion,
                 avgFood,
                 avgWater);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight, 154, 157, line, &g_text_small);

        /* Prompt strip and focus helpers — debug only */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      M11_PROMPT_STRIP_X, M11_PROMPT_STRIP_Y,
                      M11_PROMPT_STRIP_W, M11_PROMPT_STRIP_H, M11_COLOR_BLACK);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      M11_PROMPT_STRIP_X, M11_PROMPT_STRIP_Y,
                      M11_PROMPT_STRIP_W, M11_PROMPT_STRIP_H, m11_focus_color(&aheadCell));
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      108, 168, focusAction, &g_text_small);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      197, 168, focusHint, &g_text_small);

        m11_draw_feedback_strip(framebuffer, framebufferWidth, framebufferHeight,
                                state, &aheadCell);
    }

    /* Normal V1 presentation intentionally renders no rolling event/debug
     * text in the party panel.  DM1 does show a few modal/story messages,
     * but Firestaff's messageLog is mostly synthetic telemetry (movement,
     * projectiles, tick status, etc.), so drawing it here makes the game
     * look like a debug build.  Keep all of that behind showDebugHUD until
     * each real DM1 message surface is source-bound. */
    if (state->showDebugHUD && !m11_v1_chrome_mode_enabled(state)) {
        m11_draw_control_strip(framebuffer, framebufferWidth,
                               framebufferHeight, &aheadCell, state);
    }
    m11_draw_party_panel(state, framebuffer, framebufferWidth, framebufferHeight);
    if (!m11_dm1_v1_top_row_receipt_required(state)) {
        m11_draw_v1_champion_icons(state, framebuffer, framebufferWidth,
                                   framebufferHeight);
    }

    /* The procedural workbench is not a DM1 spell renderer. Classic V1 uses
     * the late CASTER.C/MENUDRAW.C C009/C011/C013 route below, gated by real
     * GRAPHICS.DAT assets and the original font. */
    /* DM1 owns spell presentation through CASTER.C/MENUDRAW.C's late
     * C009/C011 route. The older workbench below is a host UI for other
     * sessions and is never a DM1 missing-asset fallback. */
    /* The legacy workbench belongs only to non-DM1, non-CSB tooling. CSB
     * spell presentation is CASTER.C/CSBWin-owned; when that material is not
     * admitted, disabling the DM1 chrome option must not paint a host panel
     * across the F0128 viewport. */
    if (state->spellPanelOpen && !m11_v1_chrome_mode_enabled(state) &&
        !m11_is_dm1_source_kind(state->sourceKind) &&
        state->sourceKind != M11_GAME_SOURCE_CSB_BOOT) {
        /* ── P4+P6 V1 Presentation: DM1-style rune-dominant spell panel
         * with GRAPHICS.DAT-backed spell area grid ── */
        int spI;
        int pnlX = 24, pnlY = 36, pnlW = 180, pnlH = 110;
        int row = state->spellRuneRow < 4 ? state->spellRuneRow : 3;
        const char* rowNames[4] = { "POWER", "ELEMENT", "FORM", "CLASS" };

        /* Panel background — DM1-style double-bordered rectangle.
         * The original spell panel is drawn on top of the action area, not
         * using graphic 20 (C020_GRAPHIC_PANEL_EMPTY) which is the inventory
         * panel background and has a different layout.  The spell casting UI
         * in the original uses the game's default panel region with the
         * spell area background (graphic 9) as a sub-region for the rune
         * buttons.  We preserve the procedural panel frame here. */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      pnlX, pnlY, pnlW, pnlH, M11_COLOR_BLACK);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      pnlX, pnlY, pnlW, pnlH, M11_COLOR_BROWN);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      pnlX + 2, pnlY + 2, pnlW - 4, pnlH - 4, M11_COLOR_BROWN);

        /* ── Selected rune sequence (pass 44: C011 rune-label cells) ── */
        {
            int bI;
            int seqCellY = pnlY + 7;
            int seqCellGap = 2;
            int seqCellX = pnlX + ((pnlW - ((4 * M11_SPELL_LABEL_CELL_W) +
                                            (3 * seqCellGap))) / 2);
            int drewCells = 0;
            for (bI = 0; bI < 4; ++bI) {
                int cellX = seqCellX + bI * (M11_SPELL_LABEL_CELL_W + seqCellGap);
                if (bI < state->spellBuffer.runeCount) {
                    int rv = state->spellBuffer.runes[bI];
                    int rr = (rv - 0x60) / 6;
                    int rc = (rv - 0x60) % 6;
                    char abbrev[3];
                    M11_TextStyle seqStyle = g_text_small;
                    if (!m11_blit_spell_label_cell(state,
                                                   framebuffer,
                                                   framebufferWidth,
                                                   framebufferHeight,
                                                   cellX,
                                                   seqCellY,
                                                   1)) {
                        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                      cellX, seqCellY,
                                      M11_SPELL_LABEL_CELL_W,
                                      M11_SPELL_LABEL_CELL_H,
                                      M11_COLOR_NAVY);
                        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                                      cellX, seqCellY,
                                      M11_SPELL_LABEL_CELL_W,
                                      M11_SPELL_LABEL_CELL_H,
                                      M11_COLOR_LIGHT_BLUE);
                    } else {
                        drewCells = 1;
                    }
                    m11_get_rune_abbrev(rr, rc, abbrev);
                    seqStyle.color = M11_COLOR_LIGHT_GREEN;
                    m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                                  cellX + 1, seqCellY + 3, abbrev, &seqStyle);
                } else {
                    m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  cellX, seqCellY,
                                  M11_SPELL_LABEL_CELL_W,
                                  M11_SPELL_LABEL_CELL_H,
                                  M11_COLOR_DARK_GRAY);
                }
            }
            if (!drewCells && state->spellBuffer.runeCount == 0) {
                M11_TextStyle dimStyle = g_text_small;
                dimStyle.color = M11_COLOR_DARK_GRAY;
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              pnlX + 8, seqCellY + 2, "- - - -", &dimStyle);
            }
        }

        /* ── Separator line below rune sequence ── */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      pnlX + 6, pnlY + 22, pnlW - 12, 1, M11_COLOR_BROWN);

        /* ── Active rune row: category label + pass-44 C011 cell blits ── */
        if (state->spellBuffer.runeCount < 4) {
            int runeGap = 2;
            int rowWidth = 6 * M11_SPELL_LABEL_CELL_W + 5 * runeGap;
            int rowStartX = pnlX + ((pnlW - rowWidth) / 2);
            int runeY = pnlY + 38;
            M11_TextStyle catStyle = g_text_small;
            catStyle.color = M11_COLOR_YELLOW;
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          pnlX + 8, pnlY + 26, rowNames[row], &catStyle);

            for (spI = 0; spI < 6; ++spI) {
                int bx = rowStartX + spI * (M11_SPELL_LABEL_CELL_W + runeGap);
                char abbrev[3];
                M11_TextStyle runeStyle = g_text_small;
                if (!m11_blit_spell_label_cell(state,
                                               framebuffer,
                                               framebufferWidth,
                                               framebufferHeight,
                                               bx,
                                               runeY,
                                               0)) {
                    m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  bx, runeY,
                                  M11_SPELL_LABEL_CELL_W,
                                  M11_SPELL_LABEL_CELL_H,
                                  M11_COLOR_NAVY);
                    m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                                  bx, runeY,
                                  M11_SPELL_LABEL_CELL_W,
                                  M11_SPELL_LABEL_CELL_H,
                                  M11_COLOR_LIGHT_BLUE);
                }
                m11_get_rune_abbrev(row, spI, abbrev);
                runeStyle.color = M11_COLOR_WHITE;
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              bx + 1, runeY + 3, abbrev, &runeStyle);
            }
        } else {
            /* All 4 runes selected — show cast-ready state */
            M11_TextStyle readyStyle = g_text_title;
            readyStyle.color = M11_COLOR_LIGHT_GREEN;
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          pnlX + 40, pnlY + 42, "CAST", &readyStyle);
        }

        /* ── Mana indicator (compact bar + value) ── */
        if (state->world.party.activeChampionIndex >= 0 &&
            state->world.party.activeChampionIndex < CHAMPION_MAX_PARTY) {
            const struct ChampionState_Compat* sc =
                &state->world.party.champions[state->world.party.activeChampionIndex];
            int barX = pnlX + 8, barY = pnlY + 64;
            int barW = pnlW - 16, barH = 6;
            int fillW;
            char manaStr[24];
            M11_TextStyle manaStyle = g_text_small;
            manaStyle.color = M11_COLOR_LIGHT_CYAN;
            /* Mana bar outline */
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          barX, barY, barW, barH, M11_COLOR_DARK_GRAY);
            /* Mana bar fill */
            fillW = (sc->mana.maximum > 0)
                ? (int)((long)sc->mana.current * (barW - 2) / sc->mana.maximum)
                : 0;
            if (fillW > barW - 2) fillW = barW - 2;
            if (fillW > 0) {
                m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                              barX + 1, barY + 1, fillW, barH - 2,
                              M11_COLOR_LIGHT_BLUE);
            }
            snprintf(manaStr, sizeof(manaStr), "%d/%d",
                     (int)sc->mana.current, (int)sc->mana.maximum);
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          barX, barY + barH + 2, manaStr, &manaStyle);
        }

        /* ── Remaining rune rows shown dimmed below active row ── */
        if (state->spellBuffer.runeCount < 4) {
            int futRow;
            int dimY = pnlY + 76;
            M11_TextStyle dimStyle = g_text_small;
            dimStyle.color = M11_COLOR_DARK_GRAY;
            for (futRow = row + 1; futRow < 4; ++futRow) {
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              pnlX + 8, dimY, rowNames[futRow], &dimStyle);
                dimY += 10;
            }
        }
    }

    /* Endgame victory overlay.
     * ReDMCSB ENDGAME.C F0446 lines 939-961 delays after victory text
     * before calling F0444_STARTEND_Endgame(C1_TRUE), so the final
     * presentation waits for the non-blocking F0446 handoff gate. */
    if (M11_GameView_GetEndgameFinalPresentationReady(state)) {
        if (m11_v1_chrome_mode_enabled(state) && state->assetsAvailable) {
            const M11_AssetSlot* theEnd = NULL;
            const M11_AssetSlot* mirror = NULL;
            const M11_AssetSlot* portraits = NULL;
            const M11_AssetSlot* credits = NULL;
            if (!m11_dm1_f0444_endgame_material_bound(state, &theEnd, &mirror,
                                                       &portraits, &credits)) {
                return;
            }
            if (state->endgameF0444PresentationPhase == 3) {
                /* I34E F0444 lines 654-687 expands authentic C005 to the
                 * complete 320x200 screen and selects the credits palette.
                 * The asset admission above proves C005 and that palette;
                 * never substitute a host credits surface. */
                if (credits && credits->loaded && credits->pixels &&
                    credits->width == 320u && credits->height == 200u) {
                    M11_AssetLoader_Blit(credits, framebuffer,
                                         framebufferWidth, framebufferHeight,
                                         0, 0, -1);
                }
                return;
            }
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          0, 0, framebufferWidth, framebufferHeight,
                          M11_COLOR_DARK_GRAY);
            if (state->endgameF0444PresentationPhase <= 1 &&
                mirror && mirror->loaded && mirror->pixels) {
                int i;
                for (i = 0; i < 4; ++i) {
                    int mirrorX, mirrorY;
                    DM1_V1_EndgameRectPc34 mirrorRect;
                    (void)dm1_v1_endgame_champion_mirror_rect_pc34(
                        i, &mirrorRect);
                    m11_copy_endgame_rect(&mirrorRect, &mirrorX, &mirrorY,
                                          NULL, NULL);
                    M11_AssetLoader_Blit(mirror, framebuffer, framebufferWidth,
                                         framebufferHeight, mirrorX, mirrorY, 10);
                    if (i < state->world.party.championCount &&
                        state->world.party.champions[i].present) {
                        if (portraits && portraits->loaded && portraits->pixels &&
                            portraits->width >= 256 && portraits->height >= 87) {
                            int pIdx = state->world.party.champions[i].portraitIndex & 0x1F;
                            int srcPX = (pIdx & 7) * M11_PORTRAIT_W;
                            int srcPY = (pIdx >> 3) * M11_PORTRAIT_H;
                            if (srcPX + M11_PORTRAIT_W <= (int)portraits->width &&
                                srcPY + M11_PORTRAIT_H <= (int)portraits->height) {
                                int portraitX, portraitY;
                                DM1_V1_EndgameRectPc34 portraitRect;
                                (void)dm1_v1_endgame_champion_portrait_rect_pc34(
                                    i, &portraitRect);
                                m11_copy_endgame_rect(&portraitRect,
                                                      &portraitX,
                                                      &portraitY,
                                                      NULL,
                                                      NULL);
                                M11_AssetLoader_BlitRegion(portraits,
                                    srcPX, srcPY,
                                    M11_PORTRAIT_W, M11_PORTRAIT_H,
                                    framebuffer, framebufferWidth, framebufferHeight,
                                    portraitX, portraitY, M11_COLOR_DARK_GRAY);
                            }
                        }
                    }
                }
            }
            if (state->endgameF0444PresentationPhase == 2 &&
                theEnd && theEnd->loaded && theEnd->pixels) {
                int theEndX, theEndY;
                DM1_V1_EndgameRectPc34 theEndRect;
                (void)dm1_v1_endgame_the_end_rect_pc34(&theEndRect);
                m11_copy_endgame_rect(&theEndRect, &theEndX, &theEndY,
                                      NULL, NULL);
                M11_AssetLoader_Blit(theEnd, framebuffer, framebufferWidth,
                                     framebufferHeight,
                                     theEndX,
                                     theEndY,
                                     -1);
            }
            /* F0444 owns the complete logical screen in all three phases.
             * Do not let the normal dungeon HUD repaint it afterward. */
            return;
        }
    }

    /* ReDMCSB STARTUP2.C:411-423 panel order: F0394 spell area, F0387
     * action area, then F0395 movement arrows.  These are deliberately
     * late in M11's normal V1 lane: the earlier party/utility and optional
     * spell-workbench passes must not repaint C011 line 2 or C093..C096.
     * Modal and fullscreen overlays remain later and therefore retain their
     * intentional ownership of the screen. */
    {
        const int actionSpellReceiptResult =
            m11_draw_dm1_v1_action_spell_receipt_frame(
                state, framebuffer, framebufferWidth, framebufferHeight);
        if (actionSpellReceiptResult < 0) {
            m11_dm1_runtime_capture_route_evidence(
                state, M11_DM1_RUNTIME_CAPTURE_ACTION_SPELL,
                0, 0, 0, 0u, 0u, 0u);
        }
        if (actionSpellReceiptResult == 0) {
            m11_draw_v1_spell_area_overlay(state, framebuffer, framebufferWidth,
                                           framebufferHeight);
            m11_draw_v1_action_area_overlay(state, framebuffer, framebufferWidth,
                                            framebufferHeight);
        }
    }
    m11_draw_v1_movement_arrows(state, framebuffer, framebufferWidth,
                                framebufferHeight);
    m11_draw_v1_message_area(state, framebuffer, framebufferWidth,
                             framebufferHeight);

    /* Dialog box overlay for text plaque inspection */
    if (state->dialogOverlayActive && state->dialogOverlayText[0] != '\0') {
        int dlgX = 30, dlgY = 50, dlgW = 260, dlgH = 80;
        int textY;
        int drewSourceBackdrop = 0;
        int drewReturnConfirmModal = 0;
        if (state->returnToMenuConfirmActive && !state->quitGuardActive) {
            M11_ReturnConfirmDialogLayout confirmLayout;
            /* Dim the current game content heavily — the actual game view
             * (dungeon, inventory, whatever was on screen) stays visible
             * but darkened, with the confirm dialog centered on top. */
            m11_dim_rect(framebuffer, framebufferWidth, framebufferHeight,
                         0, 0, framebufferWidth, framebufferHeight, 5);
            m11_return_confirm_dialog_layout_for(state, framebufferWidth,
                                                 framebufferHeight,
                                                 &confirmLayout);
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          confirmLayout.boxX, confirmLayout.boxY,
                          confirmLayout.boxW, confirmLayout.boxH,
                          M11_COLOR_BLACK);
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          confirmLayout.boxX, confirmLayout.boxY,
                          confirmLayout.boxW, confirmLayout.boxH,
                          M11_COLOR_LIGHT_GRAY);
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          confirmLayout.boxX + 1, confirmLayout.boxY + 1,
                          confirmLayout.boxW - 2, confirmLayout.boxH - 2,
                          M11_COLOR_DARK_GRAY);
            dlgX = confirmLayout.boxX;
            dlgY = confirmLayout.boxY;
            dlgW = confirmLayout.boxW;
            dlgH = confirmLayout.boxH;
            drewSourceBackdrop = 0;
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          confirmLayout.promptX, confirmLayout.promptY,
                          confirmLayout.prompt, &g_text_shadow);
            /* Always draw YES/NO choices for return-to-menu confirm.
             * Choices are stored in dialogChoices[0..dialogChoiceCount-1].
             * ReDMCSB CLIKVIEW.C F0378/F0379/F0380: bottom row button clicks. */
            if (state->dialogChoiceCount > 0) {
                int i;
                for (i = 0; i < state->dialogChoiceCount && i < 4; ++i) {
                    const char* label =
                        (i == 0) ? confirmLayout.choice0 :
                        (i == 1) ? confirmLayout.choice1 :
                                   state->dialogChoices[i];
                    m11_draw_text_centered_in_rect(framebuffer,
                        framebufferWidth, framebufferHeight,
                        confirmLayout.boxX + i * confirmLayout.choiceW,
                        confirmLayout.choiceY,
                        confirmLayout.choiceW,
                        label, &g_text_small);
                }
            }
            drewReturnConfirmModal = 1;
        } else if (m11_v1_chrome_mode_enabled(state)) {
            drewSourceBackdrop = m11_draw_dm_dialog_backdrop(
                state, framebuffer, framebufferWidth, framebufferHeight);
        }
        /* The generic plaque frame is Firestaff UI, not a ReDMCSB dialog
         * surface. CSB may draw only the admitted source backdrop; a missing
         * C000-like source surface remains no-draw even when the optional
         * DM1 chrome path is disabled. Return confirmations are host UI and
         * keep their separate explicit branch above. */
        if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
            !drewSourceBackdrop && !state->returnToMenuConfirmActive) {
            return;
        }
        if (!drewSourceBackdrop && !state->returnToMenuConfirmActive) {
            m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                          dlgX, dlgY, dlgW, dlgH, M11_COLOR_BLACK);
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          dlgX, dlgY, dlgW, dlgH, M11_COLOR_YELLOW);
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          dlgX + 2, dlgY + 2, dlgW - 4, dlgH - 4, M11_COLOR_BROWN);
        }
        if (state->showDebugHUD) {
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          dlgX + 8, dlgY + 8, "TEXT PLAQUE", &g_text_title);
        }
        if (drewSourceBackdrop) {
            m11_apply_dm_dialog_choice_patch(state, framebuffer,
                                             framebufferWidth, framebufferHeight);
            M11_TextStyle versionStyle = g_text_small;
            versionStyle.color = M11_COLOR_LIGHT_GRAY;
            versionStyle.shadowColor = M11_COLOR_DARK_GRAY;
            /* ReDMCSB DIALOG.C:F0427 prints "V3.4" into
             * C450_ZONE_DIALOG_VERSION after expanding the source
             * C000 dialog-box graphic.  ZONES.H reconstruction gives
             * type 4 / parent 4 / d1=192 / d2=7; parent zone 4 is the
             * 224×136 viewport, so screen origin is viewport + d1/d2. */
            int versionX, versionY;
            (void)dm1_v1_dialog_version_text_origin_pc34(&versionX,
                                                         &versionY);
            m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                          versionX,
                          versionY,
                          "V3.4", &versionStyle);
        }
        /* Word-wrap the dialog text into the box.  Source-dialog mode uses the
         * C469 zone width decision instead of the old fixed 40-character cut. */
        if (drewReturnConfirmModal) {
            /* The scale-aware return modal draws its own prompt and choices
             * above; skip the generic plaque/choice renderer so the text
             * does not double-paint or reuse the fixed 40-character split. */
        } else if (drewSourceBackdrop) {
            char line1[80], line2[128];
            int lineCount = m11_dialog_source_split_two_lines(
                state->dialogOverlayText, line1, sizeof(line1), line2, sizeof(line2),
                m11_dialog_source_message_width_for_choices(state->dialogChoiceCount));
            DM1_V1_DialogRectPc34 msgRect;
            int msgX = 0, msgW = M11_VIEWPORT_W;
            int msgLeft;
            textY = (state->dialogChoiceCount > 1)
                        ? dm1_v1_dialog_multi_choice_message_text_y_pc34(lineCount)
                        : dm1_v1_dialog_single_choice_message_text_y_pc34(lineCount);
            if (dm1_v1_dialog_message_rect_pc34(state->dialogChoiceCount,
                                                &msgRect)) {
                msgX = msgRect.x;
                msgW = msgRect.w;
            }
            /* COORD.C layout-696 records C469/C471 as a centered type-0
             * text zone: d1 is the center x, not a left edge. */
            msgLeft = M11_VIEWPORT_X + msgX - (msgW / 2);
            m11_draw_text_centered_in_rect(framebuffer,
                                           framebufferWidth,
                                           framebufferHeight,
                                           msgLeft,
                                           textY,
                                           msgW,
                                           line1,
                                           &g_text_shadow);
            if (lineCount > 1 && line2[0] != '\0') {
                m11_draw_text_centered_in_rect(framebuffer,
                                               framebufferWidth,
                                               framebufferHeight,
                                               msgLeft,
                                               textY + 8,
                                               msgW,
                                               line2,
                                               &g_text_shadow);
            }
        } else {
            textY = dlgY + ((state->showDebugHUD || !m11_v1_chrome_mode_enabled(state)) ? 28 : 18);
            if (strlen(state->dialogOverlayText) <= 40) {
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              dlgX + 12, textY, state->dialogOverlayText,
                              &g_text_shadow);
            } else {
                /* Split at nearest space before character 40 */
                char line1[48], line2[80];
                int splitPos = 40;
                while (splitPos > 0 && state->dialogOverlayText[splitPos] != ' ') {
                    --splitPos;
                }
                if (splitPos == 0) splitPos = 40;
                memcpy(line1, state->dialogOverlayText, (size_t)splitPos);
                line1[splitPos] = '\0';
                snprintf(line2, sizeof(line2), "%s",
                         state->dialogOverlayText + splitPos + (state->dialogOverlayText[splitPos] == ' ' ? 1 : 0));
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              dlgX + 12, textY, line1, &g_text_shadow);
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              dlgX + 12, textY + 14, line2, &g_text_shadow);
            }
        }
        if (!drewReturnConfirmModal &&
            (state->showDebugHUD || !m11_v1_chrome_mode_enabled(state))) {
            if (state->dialogChoiceCount > 0) {
                int i;
                int choiceY = dlgY + dlgH - 18;
                int choiceW = dlgW / state->dialogChoiceCount;
                for (i = 0; i < state->dialogChoiceCount && i < 4; ++i) {
                    m11_draw_text_centered_in_rect(framebuffer,
                                                   framebufferWidth,
                                                   framebufferHeight,
                                                   dlgX + i * choiceW,
                                                   choiceY,
                                                   choiceW,
                                                   state->dialogChoices[i],
                                                   &g_text_small);
                }
            } else {
                m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                              dlgX + 50, dlgY + dlgH - 16,
                              m11_translate_for_state(
                                  state, "PRESS ANY KEY TO DISMISS"),
                              &g_text_small);
            }
        }
        if (drewSourceBackdrop) {
            m11_draw_dialog_choices_source(state, framebuffer,
                                           framebufferWidth, framebufferHeight);
        }
    }

    /* ── Session-timer runtime overlay (in-game UX boundary) ────────
     * Draw the reminder banner + forced-pause confirm dialog on top of
     * the gameplay viewport.  See include/session_timer_runtime.h +
     * src/shared/session_timer_runtime.c + the M11_TickSessionTimer
     * branch in src/engine/main_loop_m11.c for the runtime state
     * machine that drives these latches. */
    if (state->sessionTimerReminderOverlayActive &&
        !state->sessionTimerForcedPauseDialogActive &&
        !state->dialogOverlayActive) {
        char reminderLine[64];
        M11_TextStyle remindStyle = g_text_small;
        enum {
            TIMER_REMINDER_X = 4,
            TIMER_REMINDER_Y = 4,
            TIMER_REMINDER_W = 312,
            TIMER_REMINDER_H = 28,
            TIMER_REMINDER_TEXT_INSET = 8,
            TIMER_REMINDER_TEXT_Y = 8
        };
        m11_format_session_timer_reminder_line(
            state, reminderLine, sizeof(reminderLine));
        /* Firestaff-specific overlay: keep all reminder pixels in the
         * y=4..31 top strip so the source-owned DM1 dungeon viewport
         * at y=33..168 remains untouched even when fontScale is 3. */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      TIMER_REMINDER_X, TIMER_REMINDER_Y,
                      TIMER_REMINDER_W, TIMER_REMINDER_H,
                      M11_COLOR_BLACK);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      TIMER_REMINDER_X, TIMER_REMINDER_Y,
                      TIMER_REMINDER_W, TIMER_REMINDER_H,
                      M11_COLOR_YELLOW);
        remindStyle.color = M11_COLOR_YELLOW;
        remindStyle.shadowColor = M11_COLOR_DARK_GRAY;
        m11_draw_text_centered_in_rect(
            framebuffer, framebufferWidth, framebufferHeight,
            TIMER_REMINDER_X + TIMER_REMINDER_TEXT_INSET,
            TIMER_REMINDER_TEXT_Y,
            TIMER_REMINDER_W - (2 * TIMER_REMINDER_TEXT_INSET),
            reminderLine,
            &remindStyle);
    }
    if (state->sessionTimerForcedPauseDialogActive &&
        !state->dialogOverlayActive &&
        !state->returnToMenuConfirmActive) {
        M11_ForcedPauseDialogLayout pauseLayout;
        M11_TextStyle pauseStyle = g_text_small;
        m11_forced_pause_dialog_layout_for(state, framebufferWidth,
                                           framebufferHeight, &pauseLayout);
        m11_dim_rect(framebuffer, framebufferWidth, framebufferHeight,
                     0, 0, framebufferWidth, framebufferHeight, 5);
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      pauseLayout.boxX, pauseLayout.boxY,
                      pauseLayout.boxW, pauseLayout.boxH,
                      M11_COLOR_BLACK);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      pauseLayout.boxX, pauseLayout.boxY,
                      pauseLayout.boxW, pauseLayout.boxH,
                      M11_COLOR_LIGHT_GRAY);
        if (pauseLayout.boxW >= 4 && pauseLayout.boxH >= 4) {
            m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                          pauseLayout.boxX + 1, pauseLayout.boxY + 1,
                          pauseLayout.boxW - 2, pauseLayout.boxH - 2,
                          M11_COLOR_DARK_GRAY);
        }
        pauseStyle.color = M11_COLOR_WHITE;
        pauseStyle.shadowColor = M11_COLOR_DARK_GRAY;
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      pauseLayout.titleX, pauseLayout.titleY,
                      pauseLayout.title, &pauseStyle);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      pauseLayout.line1X, pauseLayout.line1Y,
                      pauseLayout.line1, &pauseStyle);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      pauseLayout.line2X, pauseLayout.line2Y,
                      pauseLayout.line2, &pauseStyle);
    }

    /* Rest / death overlay */
    if (state->partyDead) {
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      60, 70, 200, 60, M11_COLOR_BLACK);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      60, 70, 200, 60, M11_COLOR_LIGHT_RED);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      80, 80, m11_translate_for_state(state, "GAME OVER"),
                      &g_text_title);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      72, 108,
                      m11_translate_for_state(
                          state, "LOAD SAVE OR ESC TO MENU"),
                      &g_text_shadow);
    } else if (state->resting) {
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      100, 70, 120, 30, M11_COLOR_BLACK);
        m11_draw_rect(framebuffer, framebufferWidth, framebufferHeight,
                      100, 70, 120, 30, M11_COLOR_LIGHT_BLUE);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      112, 78,
                      m11_translate_for_state(state, "RESTING..."),
                      &g_text_shadow);
        m11_draw_text(framebuffer, framebufferWidth, framebufferHeight,
                      112, 88,
                      m11_translate_for_state(state, "R TO WAKE"),
                      &g_text_small);
    }

    /* ReDMCSB has no host-drawn damage border in the authenticated DM1
     * viewport.  The original damage feedback is carried by the source
     * C015/C016 champion-panel redraw and the source audio route.  Keep the
     * old red frame only for the non-authenticated diagnostic renderer; it
     * must never contaminate a real PC34 frame as a synthetic visual. */
    if (state->damageFlashTimer > 0 &&
        !m11_dm1_authenticated_viewport_source_active()) {
        int vx = 12, vy = 24, vw = 196, vh = 118;
        int thickness = 2;
        /* Top border */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      vx, vy, vw, thickness, M11_COLOR_LIGHT_RED);
        /* Bottom border */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      vx, vy + vh - thickness, vw, thickness, M11_COLOR_LIGHT_RED);
        /* Left border */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      vx, vy, thickness, vh, M11_COLOR_LIGHT_RED);
        /* Right border */
        m11_fill_rect(framebuffer, framebufferWidth, framebufferHeight,
                      vx + vw - thickness, vy, thickness, vh, M11_COLOR_LIGHT_RED);
    }

    /* ReDMCSB has no yellow host-drawn attack-X here.  Creature attacks are
     * represented by the authenticated C014/C015/C016 surfaces and audio;
     * keep attackCueTimer as timing state only for existing receipts. */

    /* ── Creature-hit overlay: GRAPHICS.DAT graphic 14 on viewport ── */
    /* In the original DM1, when the party deals melee damage to a
     * creature, the "damage to creature" graphic (C014, 88×45) is
     * drawn centered in the viewport's action-result zone with the
     * damage number overlaid.  Size scales with damage magnitude:
     * >40 = full (88×45), 15-40 = medium (64×37), <15 = small (42×37).
     * Ref: ReDMCSB MELEE.C, G2093-G2096. */
    if (state->creatureHitOverlayTimer > 0) {
        DM1_V1_ActionSpellHudPresentationReceiptPc34 hudReceipt;
        DM1_V1_F0661DamageMaterialReceiptPc34 damageMaterial;
        const DM1_V1_LiveActionEffectPc34* liveDamage = NULL;
        int vCX = 110, vCY = 78; /* viewport center */
        int i;
        memset(&hudReceipt, 0, sizeof(hudReceipt));
        for (i = 0; i < state->dm1LiveActionEffects.count; ++i) {
            const DM1_V1_LiveActionEffectPc34* entry =
                &state->dm1LiveActionEffects.entries[i];
            if (entry->kind == DM1_V1_LIVE_ACTION_EFFECT_DAMAGE_PC34 &&
                entry->damage == state->creatureHitDamageAmount &&
                dm1_v1_live_action_effect_hud_presentation_pc34(
                    entry, &hudReceipt) &&
                hudReceipt.valid &&
                hudReceipt.presentationKind ==
                    DM1_V1_ACTION_HUD_PRESENTATION_DAMAGE_PC34 &&
                hudReceipt.layoutKind ==
                    DM1_V1_ACTION_HUD_LAYOUT_CREATURE_DAMAGE_PC34) {
                liveDamage = entry;
                break;
            }
        }
        memset(&damageMaterial, 0, sizeof(damageMaterial));
        if (liveDamage && m11_dm1_v1_f0661_damage_material_ready(
                              state, &damageMaterial)) {
            const M11_AssetSlot* dmg14 = M11_AssetLoader_Load(
                (M11_AssetLoader*)&state->assetLoader,
                (unsigned int)dm1_v1_graphic_creature_damage_pc34());
            if (dmg14 && dmg14->loaded && dmg14->pixels &&
                (int)dmg14->graphicIndex == damageMaterial.damageGraphicIndex &&
                (int)dmg14->width == damageMaterial.sourceWidth &&
                (int)dmg14->height == damageMaterial.sourceHeight) {
                int blitW, blitH;
                if (state->creatureHitDamageAmount > 40) {
                    blitW = damageMaterial.sourceWidth;
                    blitH = damageMaterial.sourceHeight;
                } else if (state->creatureHitDamageAmount > 15) {
                    blitW = damageMaterial.mediumWidth;
                    blitH = damageMaterial.mediumHeight;
                } else {
                    blitW = damageMaterial.smallWidth;
                    blitH = damageMaterial.smallHeight;
                }
                M11_AssetLoader_BlitScaled(dmg14, framebuffer,
                    framebufferWidth, framebufferHeight,
                    vCX - blitW / 2, vCY - blitH / 2,
                    blitW, blitH, 0);
                /* The number is deliberately printed only through the
                 * original PC34 HUD font.  Missing M653 or missing C014 is
                 * a no-draw source failure, not permission to substitute
                 * a host rectangle/font over the viewport. */
                {
                    char hitNum[8];
                    snprintf(hitNum, sizeof(hitNum), "%d",
                             state->creatureHitDamageAmount);
                    m11_draw_v1_damage_number_text(
                        framebuffer, framebufferWidth, framebufferHeight,
                        vCX - 6, vCY - 3, hitNum);
                }
            }
        }
    }

    /* ── Full-screen overlay panels (drawn last, on top of everything) ── */
    if (state->mapOverlayActive &&
        !m11_dm1_v1_blocks_host_map_overlay(state)) {
        m11_draw_fullscreen_map(state, framebuffer, framebufferWidth, framebufferHeight);
    }
    if (state->inventoryPanelActive) {
        DM1_V1_HocCandidateRuntimeFrameAdmissionReceiptPc34 hocAdmission;
        DM1_V1_HocLiveFinalRuntimeCaptureReceiptPc34 hocCapture;
        const int hocRequired = state->candidateMirrorPanelActive &&
            !state->candidateMirrorRenameActive;
        int hocAccepted;
        memset(&hocAdmission, 0, sizeof(hocAdmission));
        memset(&hocCapture, 0, sizeof(hocCapture));
        hocAccepted = m11_dm1_hoc_runtime_frame_admission_current(
                state, &hocAdmission) &&
            m11_dm1_hoc_final_runtime_capture_current(
                state, &hocAdmission, &hocCapture);
        if (hocRequired) {
            unsigned int materialFNV1a = hocCapture.c040.sourceHash;
            materialFNV1a ^= hocCapture.c026.sourceHash;
            materialFNV1a *= 16777619u;
            m11_dm1_runtime_capture_route_evidence(
                state, M11_DM1_RUNTIME_CAPTURE_HOC, hocAccepted,
                hocAccepted, hocAccepted,
                (unsigned int)hocCapture.runtimeTick,
                hocCapture.sensorGeneration ^ hocCapture.panelGeneration,
                materialFNV1a);
        }
        if (hocRequired && !hocAccepted) {
            /* The stale/missing C040/C026 admission must not erase the
             * source-owned HoC page. Only its two source-owned zones are
             * cleared, with no host panel or portrait substitute. Ordinary
             * inventory, including F0344/F0345, has no HoC receipt. */
            m11_clear_dm1_hoc_runtime_frame_zones(
                framebuffer, framebufferWidth, framebufferHeight,
                s_m11_dm1_hoc_runtime_frame_admission.owner == state
                    ? &s_m11_dm1_hoc_runtime_frame_admission.admission
                    : NULL);
        } else {
            m11_draw_inventory_panel(state, framebuffer, framebufferWidth,
                                     framebufferHeight);
        }
    }

    /* Capture only the final indexed DM1 page and only after C13, HoC,
     * champion top-row, and active action/spell receipts have independently
     * admitted this tick. Accessibility and RetroAchievements are host
     * overlays and deliberately do not become source-frame material. */
    m11_dm1_runtime_capture_publish(state, framebuffer, framebufferWidth,
                                    framebufferHeight);

    /* Accessibility manifest: emit UI zones for Peekaboo / automation
     * tools.  Routed through m11_screen_reader_update_ex() so the
     * gameplay-side and launcher-side manifests share one writer
     * (fs_ax_*) and one config knob (FS_ACCESSIBILITY=1).  The full
     * zone set: always-on viewport / movement / spell / HUD /
     * control strip plus per-overlay inventory / map / dialog /
     * candidate mirror / endgame zones lives in
     * src/engine/m11_game_view_a11y.c.
     *
     * Source-lock: see m11_game_view_a11y.c header for the
     * ReDMCSB layout-696 / PANEL.C / ENDGAME.C citations. */
    m11_screen_reader_update_ex(state, framebufferWidth, framebufferHeight);

    m11_draw_ra_overlay(state, framebuffer, framebufferWidth,
                        framebufferHeight);
    g_drawState = NULL;
    g_activeOriginalFont = NULL;
    g_m11_font_scale_override = 0;
}

/* ── Creature animation implementation ── */

void M11_GameView_TickAnimation(M11_GameViewState* state) {
    if (!state) return;
    state->animTick++;
    if (state->damageFlashTimer > 0) state->damageFlashTimer--;
    if (state->attackCueTimer > 0)   state->attackCueTimer--;
    if (state->creatureHitOverlayTimer > 0) state->creatureHitOverlayTimer--;
    if (state->v1MovementArrowVisualTicks > 0) {
        state->v1MovementArrowVisualTicks--;
        if (state->v1MovementArrowVisualTicks <= 0) {
            state->v1MovementArrowVisualMask = 0;
        }
    }
    if (state->sourceKind == M11_GAME_SOURCE_CSB_BOOT &&
        state->presentationMode != M12_PRESENTATION_V1_ORIGINAL &&
        csb_v2_runtime_is_bound()) {
        /* M11 animation ticks run once per presented frame. Feed the V2
         * renderer its display cadence independently of the 55ms V1 tick. */
        csb_v2_runtime_render_frame(state->animTick * 16u);
    }
    { int ci; for (ci = 0; ci < 4; ++ci) {
        if (state->championDamageTimer[ci] > 0) state->championDamageTimer[ci]--;
    }}
    if (m11_is_dm1_source_kind(state->sourceKind)) {
        dm1_v1_text_set_game_time(&state->dm1V1TextMessage,
                                  (long)state->world.gameTick);
        dm1_v1_text_clear_expired_rows(&state->dm1V1TextMessage);
    }
}

void M11_GameView_NotifyDamageFlash(M11_GameViewState* state,
                                    int creatureType) {
    if (!state) return;
    state->damageFlashTimer = M11_DAMAGE_FLASH_DURATION;
    state->attackCueTimer   = M11_ATTACK_CUE_DURATION;
    state->attackCueCreatureType = creatureType;
}

int M11_GameView_GetDamageFlashTimer(const M11_GameViewState* state) {
    return state ? state->damageFlashTimer : 0;
}

int M11_GameView_GetAttackCueTimer(const M11_GameViewState* state) {
    return state ? state->attackCueTimer : 0;
}

void M11_GameView_NotifyChampionDamage(M11_GameViewState* state,
                                       int championSlot,
                                       int damageAmount) {
    if (!state || championSlot < 0 || championSlot >= 4) return;
    state->championDamageTimer[championSlot] = M11_CHAMPION_DAMAGE_OVERLAY_DURATION;
    state->championDamageAmount[championSlot] = damageAmount;
}

uint32_t M11_GameView_GetAnimTick(const M11_GameViewState* state) {
    return state ? state->animTick : 0;
}

void M11_GameView_NotifyCreatureHit(M11_GameViewState* state,
                                    int damageAmount) {
    if (!state) return;
    state->creatureHitOverlayTimer = M11_CREATURE_HIT_OVERLAY_DURATION;
    state->creatureHitDamageAmount = damageAmount;
}

int M11_GameView_GetCreatureHitOverlayTimer(const M11_GameViewState* state) {
    return state ? state->creatureHitOverlayTimer : 0;
}

int M11_GameView_CreatureAnimFrame(const M11_GameViewState* state,
                                   int creatureType) {
    /* Stagger animation per creature type so groups don't all
     * move in lockstep.  Returns 0 or 1. */
    uint32_t phase;
    if (!state) return 0;
    phase = state->animTick + (uint32_t)creatureType * 3;
    return (int)((phase / M11_CREATURE_ANIM_PERIOD) & 1);
}

int M11_GameView_GetAttackCueCreatureType(const M11_GameViewState* state) {
    return state ? state->attackCueCreatureType : -1;
}

/* ── Full-screen map overlay API ── */

int M11_GameView_ToggleMapOverlay(M11_GameViewState* state) {
    if (!state) return 0;
    if (m11_dm1_v1_blocks_host_map_overlay(state)) {
        /* The full-screen map is a Firestaff convenience/debug surface,
         * not a source-owned DM1 V1 command or display.  HandleInput
         * already rejects its keyboard route in this mode. Clear a retained
         * diagnostic value as well as rejecting direct activation. */
        state->mapOverlayActive = 0;
        return 0;
    }
    if (state->candidateMirrorPanelActive) {
        /* ReDMCSB: COMMAND.C F0380 gates the normal command surfaces
         * around G0299_ui_CandidateChampionOrdinal while the C040
         * resurrect/reincarnate panel owns input.  The Firestaff map
         * overlay is not a source DM1 surface, so the direct helper must
         * not make it active behind that panel. */
        return 0;
    }
    state->mapOverlayActive = !state->mapOverlayActive;
    return state->mapOverlayActive;
}

int M11_GameView_IsMapOverlayActive(const M11_GameViewState* state) {
    return state ? state->mapOverlayActive : 0;
}

/* ── Full inventory panel API ── */

int M11_GameView_ToggleInventoryPanel(M11_GameViewState* state) {
    if (!state) return 0;
    if (state->sourceKind == M11_GAME_SOURCE_DM2_BOOT) {
        /* SKProject CHANGE_VIEWPORT_TO_INVENTORY renders the DM2 inventory
         * from CHAMPIONS/INTERFACE_GENERAL GDAT and its own click table. The
         * generic M11 panel consumes DM1 GRAPHICS.DAT geometry, therefore a
         * DM2 caller must fail closed until that source route is bound. */
        state->inventoryPanelActive = 0;
        return 0;
    }
    if (state->candidateMirrorPanelActive) {
        /* ReDMCSB COMMAND.C lines 2177-2183 gates C007..C011
         * inventory toggles with !G0299_ui_CandidateChampionOrdinal while
         * the C040 resurrect/reincarnate panel owns input.  Keep the direct
         * M11 inventory helper on the same boundary as keyboard/pointer
         * routing so callers cannot bypass the source command contract. */
        return 0;
    }
    state->inventoryPanelActive = !state->inventoryPanelActive;
    m11_clear_v1_mouth_visual(state);
    state->v1FoodWaterPanelActive = 0;
    if (state->inventoryPanelActive) {
        state->inventorySelectedSlot = 0;
    }
    return state->inventoryPanelActive;
}

int M11_GameView_IsInventoryPanelActive(const M11_GameViewState* state) {
    return state ? state->inventoryPanelActive : 0;
}

int M11_GameView_GetInventorySelectedSlot(const M11_GameViewState* state) {
    return state ? state->inventorySelectedSlot : -1;
}

