int M11_GameView_DismissDialogOverlay(M11_GameViewState* state) {
    if (!state || !state->dialogOverlayActive) return 0;
    state->dialogOverlayActive = 0;
    state->returnToMenuConfirmActive = 0;
    state->quitGuardActive = 0;
    state->dm1SaveDiskMenuStage = 0;
    state->csbDiskMenuActive = 0;
    state->csbDiskMenuSelectedChoice = 0;
    state->csbDiskMenuStage = M11_CSB_SAVE_DISK_MENU_NONE;
    state->dm2MacOpenGameActive = 0;
    state->dm2MacOpenGamePage = 0;
    state->dialogOverlayText[0] = '\0';
    state->dialogChoiceCount = 0;
    memset(state->dialogChoices, 0, sizeof(state->dialogChoices));
    state->v1ObjectDescriptionPanelActive = 0;
    state->v1ObjectDescriptionThing = THING_NONE;
    state->v1ObjectDescriptionIconIndex = -1;
    state->v1ObjectDescriptionSourceMaterialValid = 0;
    state->v1ObjectDescriptionSourceGraphicIndex = -1;
    state->v1ObjectDescriptionName[0] = '\0';
    state->v1ScrollPanelActive = 0;
    state->v1ScrollPanelThing = THING_NONE;
    state->v1ChampionStatsPanelActive = 0;
    state->v1FoodWaterPanelActive = 0;
    return 1;
}

int M11_GameView_ShowDialogOverlay(M11_GameViewState* state,
                                   const char* text) {
    return M11_GameView_ShowDialogOverlayChoices(state, text, "OK", NULL, NULL, NULL);
}

int M11_GameView_ShowDialogOverlayChoices(M11_GameViewState* state,
                                          const char* text,
                                          const char* choice1,
                                          const char* choice2,
                                          const char* choice3,
                                          const char* choice4) {
    const char* choices[4];
    int i;
    if (!state || !text) return 0;
    state->dialogOverlayActive = 1;
    state->returnToMenuConfirmActive = 0;
    state->dialogSelectedChoice = 0;
    snprintf(state->dialogOverlayText, sizeof(state->dialogOverlayText),
             "%s", m11_translate_for_state(state, text));
    state->dialogChoiceCount = 0;
    memset(state->dialogChoices, 0, sizeof(state->dialogChoices));
    choices[0] = choice1;
    choices[1] = choice2;
    choices[2] = choice3;
    choices[3] = choice4;
    for (i = 0; i < 4; ++i) {
        if (choices[i] && choices[i][0] != '\0') {
            snprintf(state->dialogChoices[state->dialogChoiceCount],
                     sizeof(state->dialogChoices[state->dialogChoiceCount]),
                     "%s", m11_translate_for_state(state, choices[i]));
            ++state->dialogChoiceCount;
        }
    }
    return 1;
}

